def _search_ordering_reward(row: Mapping[str, Any]) -> float:
    if "search_reward" not in row:
        raise ValueError(
            "search ordering requires train-only portfolio search_reward; "
            "legacy pair_reward state cannot seed a fresh campaign"
        )
    reward = float(row["search_reward"])
    if not math.isfinite(reward):
        raise ValueError("search_reward must be finite")
    authority = str(row.get("search_reward_authority", ""))
    if authority != SEARCH_REWARD_AUTHORITY:
        raise ValueError(
            "search_reward authority changed; legacy reward state cannot seed "
            "a fresh campaign"
        )
    return reward


@dataclass(slots=True)
class BehaviorArchive:
    rows: list[dict[str, Any]] = field(default_factory=list)
    champion_by_family: dict[str, int] = field(default_factory=dict)
    family_counts: Counter[str] = field(default_factory=Counter)
    duplicate_replacements: int = 0
    transition_productivity: dict[str, dict[str, int]] = field(default_factory=dict)
    blocked_transition_keys: set[str] = field(default_factory=set)
    blocked_transition_skips: int = 0

    def observe(
        self,
        *,
        candidate: CandidateSpec,
        evaluation: Mapping[str, Any],
        arm: str,
        seed: int,
        completion_ordinal: int,
        checkpoint_index: int,
    ) -> tuple[dict[str, Any], bool]:
        behavior = dict(evaluation.get("behavior") or {})
        family_id = str(behavior.get("behavior_family_id", ""))
        if not family_id:
            raise ValueError("strict candidate lacks a behavior family identity")
        new_family = family_id not in self.champion_by_family
        row = {
            "exact_expression_id": candidate.candidate_id,
            "canonical_expression_id": candidate.expression.expression_id,
            "behavior_family_id": family_id,
            "arm": arm,
            "seed": int(seed),
            "completion_ordinal": int(completion_ordinal),
            "checkpoint_index": int(checkpoint_index),
            "search_reward": _search_ordering_reward(evaluation),
            "search_reward_authority": str(
                evaluation.get("search_reward_authority", "")
            ),
            "pair_reward": float(evaluation["pair_reward"]),
            "matched_positive": bool(evaluation["matched_positive"]),
            "gross_mean_annotation": evaluation["incremental"].get("gross_mean"),
            "net_mean_annotation": evaluation["incremental"].get("net_mean"),
            "cost_mean_annotation": evaluation["incremental"].get("cost_mean"),
            "is_family_champion": False,
            **behavior,
        }
        new_index = len(self.rows)
        self.rows.append(row)
        self.family_counts[family_id] += 1
        old_index = self.champion_by_family.get(family_id)
        replace = old_index is None
        if old_index is not None:
            old = self.rows[old_index]
            replace = (
                _search_ordering_reward(row) > _search_ordering_reward(old)
                or (
                    _search_ordering_reward(row) == _search_ordering_reward(old)
                    and str(row["exact_expression_id"])
                    < str(old["exact_expression_id"])
                )
            )
        if replace:
            if old_index is not None:
                self.rows[old_index]["is_family_champion"] = False
                self.duplicate_replacements += 1
            self.rows[new_index]["is_family_champion"] = True
            self.champion_by_family[family_id] = new_index
        return self.rows[new_index], new_family

    def summary_rows(self) -> list[dict[str, Any]]:
        output = []
        for family_id, index in sorted(self.champion_by_family.items()):
            champion = self.rows[index]
            output.append(
                {
                    "behavior_family_id": family_id,
                    "members": int(self.family_counts[family_id]),
                    "champion_exact_expression_id": champion["exact_expression_id"],
                    "champion_arm": champion["arm"],
                    "champion_search_reward": champion["search_reward"],
                    "champion_pair_reward": champion["pair_reward"],
                    "champion_matched_positive": champion["matched_positive"],
                }
            )
        return output

    def observe_transition(
        self,
        *,
        transition_key: str,
        new_family: bool,
        block_after_collisions: int,
    ) -> None:
        if not transition_key:
            raise ValueError("campaign transition observation lacks a key")
        stats = self.transition_productivity.setdefault(
            str(transition_key),
            {"trials": 0, "new_families": 0, "collisions": 0},
        )
        stats["trials"] += 1
        stats["new_families"] += int(bool(new_family))
        stats["collisions"] += int(not new_family)
        if int(stats["collisions"]) >= int(block_after_collisions):
            self.blocked_transition_keys.add(str(transition_key))

    def transition_state(self) -> dict[str, Any]:
        return {
            "transition_productivity": {
                key: dict(stats)
                for key, stats in sorted(self.transition_productivity.items())
            },
            "blocked_transition_keys": sorted(self.blocked_transition_keys),
            "blocked_transition_skips": int(self.blocked_transition_skips),
        }

    def restore_transition_state(self, state: Mapping[str, Any]) -> None:
        self.transition_productivity = {
            str(key): {
                "trials": int(stats.get("trials", 0)),
                "new_families": int(stats.get("new_families", 0)),
                "collisions": int(stats.get("collisions", 0)),
            }
            for key, stats in state.get("transition_productivity", {}).items()
        }
        self.blocked_transition_keys = set(
            str(value) for value in state.get("blocked_transition_keys", ())
        )
        self.blocked_transition_skips = int(
            state.get("blocked_transition_skips", 0)
        )

    def state_hash(self) -> str:
        payload = {
            "families": self.summary_rows(),
            "rows": len(self.rows),
            "duplicate_replacements": self.duplicate_replacements,
        }
        if (
            self.transition_productivity
            or self.blocked_transition_keys
            or self.blocked_transition_skips
        ):
            payload["transition_state"] = self.transition_state()
        return _payload_sha(payload)

    @classmethod
    def from_rows(cls, rows: Sequence[Mapping[str, Any]]) -> "BehaviorArchive":
        archive = cls(rows=[dict(row) for row in rows])
        for index, row in enumerate(archive.rows):
            _search_ordering_reward(row)
            family_id = str(row["behavior_family_id"])
            archive.family_counts[family_id] += 1
            if bool(row["is_family_champion"]):
                if family_id in archive.champion_by_family:
                    raise ValueError("behavior archive has multiple family champions")
                archive.champion_by_family[family_id] = index
        if len(archive.champion_by_family) != len(archive.family_counts):
            raise ValueError("behavior archive family lacks a champion")
        return archive


@dataclass(slots=True)
class HierarchicalTypedCEMV2:
    seed: int
    registry: TypedExpressionRegistry
    parameters: Mapping[str, Any] = field(
        default_factory=lambda: dict(V2_PARAMETERS["hierarchical_typed_cem_v2"])
    )
    rng: random.Random = field(init=False)
    roles: dict[str, list[str]] = field(init=False)
    compatible_skeleton_ids: tuple[str, ...] = field(init=False)
    seen: set[str] = field(default_factory=set)
    tables: dict[str, dict[str, dict[str, Any]]] = field(
        default_factory=lambda: defaultdict(dict)
    )
    update_count: int = 0
    step: int = 0
    last_elite_family_count: int = 0
    last_elite_mechanism_count: int = 0
    last_elite_skeleton_count: int = 0

    def __post_init__(self) -> None:
        self.parameters = dict(self.parameters)
        self.rng = random.Random(int(self.seed))
        surface = field_role_surface(tuple(self.registry.fields.values()))
        self.roles = {
            str(key): [str(value) for value in values]
            for key, values in surface["roles"].items()
        }
        self.compatible_skeleton_ids = tuple(surface["compatible_skeleton_ids"])
        if not self.compatible_skeleton_ids:
            raise ValueError("CEM V2 carrier has no compatible skeleton")
        if not 0.0 < float(self.parameters["smoothing"]) <= 1.0:
            raise ValueError("CEM V2 smoothing is invalid")
        if int(self.parameters["minimum_observation_count"]) < 1:
            raise ValueError("CEM V2 minimum observation count is invalid")
        if not 0.0 <= float(self.parameters["entropy_floor_ratio"]) <= 1.0:
            raise ValueError("CEM V2 entropy floor is invalid")

    @staticmethod
    def _entropy(probabilities: Sequence[float]) -> float:
        return float(
            -sum(value * math.log(value) for value in probabilities if value > 0.0)
        )

    def _regularized(
        self, values: Sequence[Any], weights: Mapping[str, float]
    ) -> dict[str, float]:
        ordered = tuple(sorted(values, key=lambda value: str(value)))
        if not ordered:
            raise ValueError("CEM V2 received an empty legal domain")
        if len(ordered) == 1:
            return {str(ordered[0]): 1.0}
        floor = float(self.parameters["minimum_probability"])
        if floor * len(ordered) >= 1.0:
            raise ValueError("CEM V2 minimum probability exceeds the legal support")
        raw = np.asarray(
            [max(0.0, float(weights.get(str(value), 0.0))) for value in ordered],
            dtype=float,
        )
        if not np.any(raw > 0.0):
            raw = np.ones(len(ordered), dtype=float)
        raw /= float(raw.sum())
        probabilities = floor + (1.0 - floor * len(ordered)) * raw
        entropy_floor = float(self.parameters["entropy_floor_ratio"]) * math.log(
            len(ordered)
        )
        uniform = np.full(len(ordered), 1.0 / len(ordered), dtype=float)
        if self._entropy(probabilities.tolist()) < entropy_floor:
            for index in range(1, 51):
                mixture = index / 50.0
                candidate = (1.0 - mixture) * probabilities + mixture * uniform
                if self._entropy(candidate.tolist()) >= entropy_floor:
                    probabilities = candidate
                    break
        return {
            str(value): float(probability)
            for value, probability in zip(ordered, probabilities.tolist())
        }

    def _table_weights(
        self, axis: str, context: str, legal_values: Sequence[Any]
    ) -> dict[str, float] | None:
        table = self.tables.get(axis, {}).get(context)
        if table is None or int(table.get("observations", 0)) < int(
            self.parameters["minimum_observation_count"]
        ):
            return None
        return self._regularized(legal_values, table.get("probabilities", {}))

    def _choice(
        self,
        axis: str,
        legal_values: Sequence[Any],
        contexts: Sequence[str],
        *,
        role_family_contexts: Mapping[Any, str] | None = None,
    ) -> Any:
        ordered = tuple(sorted(legal_values, key=lambda value: str(value)))
        probabilities: dict[str, float] | None = None
        if contexts:
            probabilities = self._table_weights(axis, contexts[0], ordered)
        if probabilities is None and role_family_contexts:
            counts: dict[str, float] = {}
            observations = 0
            for value in ordered:
                table = self.tables.get(axis, {}).get(
                    role_family_contexts.get(value, "")
                )
                if table is None:
                    continue
                count = int(table.get("observations", 0))
                if count:
                    counts[str(value)] = float(count)
                    observations += count
            if observations >= int(self.parameters["minimum_observation_count"]):
                probabilities = self._regularized(ordered, counts)
        if probabilities is None:
            for context in contexts[1:]:
                probabilities = self._table_weights(axis, context, ordered)
                if probabilities is not None:
                    break
        if probabilities is None:
            probabilities = self._regularized(
                ordered, {str(value): 1.0 for value in ordered}
            )
        return self.rng.choices(
            ordered,
            weights=[probabilities[str(value)] for value in ordered],
            k=1,
        )[0]

    def _sample_candidate(self) -> CandidateSpec:
        compatible = tuple(
            item
            for item in skeleton_registry()
            if item.skeleton_id in self.compatible_skeleton_ids
        )
        mechanisms = tuple(sorted({item.mechanism_family for item in compatible}))
        mechanism = str(self._choice("mechanism_family", mechanisms, ("G",)))
        skeleton_ids = tuple(
            item.skeleton_id
            for item in compatible
            if item.mechanism_family == mechanism
        )
        skeleton = _skeleton_by_id(
            str(
                self._choice(
                    "skeleton_variant",
                    skeleton_ids,
                    (f"E|{mechanism}", "G"),
                )
            )
        )
        left_role, right_role = skeleton.field_roles

        selected: dict[str, Any] = {}
        for side, role in (("left", left_role), ("right", right_role)):
            families = _family_fields(self.roles, role)
            family = str(
                self._choice(
                    "field_family",
                    tuple(families),
                    (
                        f"E|{role}|{skeleton.skeleton_id}",
                        f"S|{skeleton.skeleton_id}",
                        f"M|{mechanism}",
                        f"G|{role}",
                    ),
                    role_family_contexts={
                        value: f"RF|{role}|{value}" for value in families
                    },
                )
            )
            fields = list(families[family])
            if side == "right" and selected.get("left_field") in fields and len(fields) > 1:
                fields.remove(selected["left_field"])
            selected[f"{side}_field"] = str(
                self._choice(
                    "field_token",
                    fields,
                    (
                        f"E|{role}|{family}|{skeleton.skeleton_id}",
                        f"RF|{role}|{family}",
                        f"S|{skeleton.skeleton_id}",
                        f"M|{mechanism}",
                        f"G|{role}|{family}",
                    ),
                )
            )
            field_id = str(selected[f"{side}_field"])
            window_contexts = (
                f"E|{role}|{family}|{skeleton.skeleton_id}",
                f"RF|{role}|{family}",
                f"S|{skeleton.skeleton_id}",
                f"M|{mechanism}",
                "G",
            )
            selected[f"{side}_window"] = int(
                WINDOWS[0]
                if side == "right"
                and infer_family(field_id) == "listing_age_context"
                else self._choice(
                    "window",
                    _legal_windows(field_id, role),
                    window_contexts,
                )
            )
            operator = skeleton.to_dict()["operator_DAG"]
            right_normalizer_inactive = side == "right" and (
                skeleton.mechanism_family == "STATE_REGIME_MODULATION"
                or operator == "StateModulation"
            )
            selected[f"{side}_normalizer"] = str(
                "RollingZScore"
                if right_normalizer_inactive
                else self._choice(
                    "normalizer",
                    _legal_normalizers(field_id, role),
                    window_contexts,
                )
            )
        selected["beta"] = float(
            self._choice(
                "beta",
                BETAS,
                (f"S|{skeleton.skeleton_id}", f"M|{mechanism}", "G"),
            )
            if skeleton.to_dict()["operator_DAG"] == "Residual"
            else 0.5
        )
        selected["horizon_hours"] = int(
            self._choice(
                "horizon",
                HORIZONS,
                (
                    f"E|{mechanism}|{skeleton.skeleton_id}",
                    f"S|{skeleton.skeleton_id}",
                    f"M|{mechanism}",
                    "G",
                ),
            )
        )
        return candidate_from_genes(
            self.registry, skeleton=skeleton, genes=selected, roles=self.roles
        )

    def propose(self) -> tuple[CandidateSpec, dict[str, Any]]:
        before = self.state_hash()
        limit = int(self.parameters["duplicate_resample_limit"])
        candidate: CandidateSpec | None = None
        for duplicate_resamples in range(limit + 1):
            candidate = self._sample_candidate()
            if candidate.candidate_id not in self.seen:
                break
        assert candidate is not None
        if candidate.candidate_id in self.seen:
            raise _ProposalGenerationFailure(
                "CEM V2 duplicate resample limit exhausted",
                raw_attempts=limit + 1,
            )
        self.seen.add(candidate.candidate_id)
        self.step += 1
        return candidate, {
            "policy_state_hash_before": before,
            "operation": "HIERARCHICAL_TYPED_CEM_SAMPLE",
            "parent_ids": [],
            "receipt": None,
            "receipt_verified": None,
            "raw_attempts": duplicate_resamples + 1,
            "operator_diagnostic": candidate.operator_path,
            "interaction_diagnostic": candidate.skeleton_id,
        }

    def _accumulate(
        self,
        accumulator: dict[str, dict[str, Counter[str]]],
        axis: str,
        contexts: Iterable[str],
        value: Any,
    ) -> None:
        for context in contexts:
            accumulator[axis][str(context)][str(value)] += 1

    @staticmethod
    def _elite_sort_key(row: Mapping[str, Any]) -> tuple[Any, ...]:
        return (
            -_search_ordering_reward(row),
            int(row.get("policy_local_family_count_at_completion", 1)),
            str(row["candidate_id"]),
        )

    def _select_elites(
        self, rows: Sequence[Mapping[str, Any]]
    ) -> list[Mapping[str, Any]]:
        elite_count = max(
            1,
            int(math.ceil(len(rows) * float(self.parameters["elite_fraction"]))),
        )
        ordered = sorted(rows, key=self._elite_sort_key)
        if bool(self.parameters.get("behavior_family_champion_elites", False)):
            champions: list[Mapping[str, Any]] = []
            seen_families: set[str] = set()
            for row in ordered:
                family_id = str(
                    row.get("behavior_family_id") or row["candidate_id"]
                )
                if family_id in seen_families:
                    continue
                seen_families.add(family_id)
                champions.append(row)
        else:
            champions = ordered
        if bool(
            self.parameters.get("mechanism_stratified_elites", False)
            or self.parameters.get("skeleton_stratified_elites", False)
        ):
            candidate_by_id = {
                str(row["candidate_id"]): CandidateSpec.from_dict(
                    json.loads(str(row["candidate_spec_json"]))
                )
                for row in champions
            }
            selected: list[Mapping[str, Any]] = []
            selected_ids: set[str] = set()
            if bool(
                self.parameters.get("mechanism_stratified_elites", False)
            ):
                best_by_mechanism: dict[str, Mapping[str, Any]] = {}
                for row in champions:
                    candidate = candidate_by_id[str(row["candidate_id"])]
                    best_by_mechanism.setdefault(
                        candidate.mechanism_family, row
                    )
                selected.extend(
                    sorted(
                        best_by_mechanism.values(),
                        key=self._elite_sort_key,
                    )[:elite_count]
                )
                selected_ids.update(
                    str(row["candidate_id"]) for row in selected
                )
            best_by_skeleton: dict[str, Mapping[str, Any]] = {}
            if bool(
                self.parameters.get("skeleton_stratified_elites", False)
            ):
                for row in champions:
                    candidate = candidate_by_id[str(row["candidate_id"])]
                    best_by_skeleton.setdefault(candidate.skeleton_id, row)
                for row in sorted(
                    best_by_skeleton.values(), key=self._elite_sort_key
                ):
                    if len(selected) >= elite_count:
                        break
                    if str(row["candidate_id"]) in selected_ids:
                        continue
                    selected.append(row)
                    selected_ids.add(str(row["candidate_id"]))
            for row in champions:
                if len(selected) >= elite_count:
                    break
                if str(row["candidate_id"]) in selected_ids:
                    continue
                selected.append(row)
                selected_ids.add(str(row["candidate_id"]))
            elites = sorted(selected, key=self._elite_sort_key)
        else:
            elites = champions[:elite_count]
        self.last_elite_family_count = len(
            {
                str(row.get("behavior_family_id") or row["candidate_id"])
                for row in elites
            }
        )
        self.last_elite_mechanism_count = len(
            {
                CandidateSpec.from_dict(
                    json.loads(str(row["candidate_spec_json"]))
                ).mechanism_family
                for row in elites
            }
        )
        self.last_elite_skeleton_count = len(
            {
                CandidateSpec.from_dict(
                    json.loads(str(row["candidate_spec_json"]))
                ).skeleton_id
                for row in elites
            }
        )
        return elites

    def update(self, rows: Sequence[Mapping[str, Any]]) -> None:
        if not rows:
            return
        elites = self._select_elites(rows)
        accumulator: dict[str, dict[str, Counter[str]]] = defaultdict(
            lambda: defaultdict(Counter)
        )
        for row in elites:
            candidate = CandidateSpec.from_dict(json.loads(str(row["candidate_spec_json"])))
            skeleton = _skeleton_by_id(candidate.skeleton_id)
            mechanism = candidate.mechanism_family
            genes = candidate.generation_genes
            self._accumulate(accumulator, "mechanism_family", ("G",), mechanism)
            self._accumulate(
                accumulator,
                "skeleton_variant",
                (f"E|{mechanism}", "G"),
                skeleton.skeleton_id,
            )
            for side, role in zip(("left", "right"), skeleton.field_roles):
                field_id = str(genes[f"{side}_field"])
                family = infer_family(field_id)
                self._accumulate(
                    accumulator,
                    "field_family",
                    (
                        f"E|{role}|{skeleton.skeleton_id}",
                        f"RF|{role}|{family}",
                        f"S|{skeleton.skeleton_id}",
                        f"M|{mechanism}",
                        f"G|{role}",
                    ),
                    family,
                )
                common = (
                    f"E|{role}|{family}|{skeleton.skeleton_id}",
                    f"RF|{role}|{family}",
                    f"S|{skeleton.skeleton_id}",
                    f"M|{mechanism}",
                    f"G|{role}|{family}",
                )
                self._accumulate(accumulator, "field_token", common, field_id)
                effective = _effective_generation_gene_names(skeleton, genes)
                if f"{side}_window" in effective:
                    self._accumulate(
                        accumulator,
                        "window",
                        (*common[:-1], "G"),
                        genes[f"{side}_window"],
                    )
                if f"{side}_normalizer" in effective:
                    self._accumulate(
                        accumulator,
                        "normalizer",
                        (*common[:-1], "G"),
                        genes[f"{side}_normalizer"],
                    )
            if "beta" in _effective_generation_gene_names(skeleton, genes):
                self._accumulate(
                    accumulator,
                    "beta",
                    (f"S|{skeleton.skeleton_id}", f"M|{mechanism}", "G"),
                    genes["beta"],
                )
            self._accumulate(
                accumulator,
                "horizon",
                (
                    f"E|{mechanism}|{skeleton.skeleton_id}",
                    f"S|{skeleton.skeleton_id}",
                    f"M|{mechanism}",
                    "G",
                ),
                genes["horizon_hours"],
            )

        smoothing = float(self.parameters["smoothing"])
        pseudocount = float(self.parameters["count_pseudocount"])
        for axis, contexts in accumulator.items():
            for context, additions in contexts.items():
                table = self.tables[axis].setdefault(
                    context,
                    {"observations": 0, "counts": {}, "probabilities": {}},
                )
                # The probability table is the sole cross-checkpoint memory.
                # Keeping cumulative elite counts as well would replay old
                # observations a second time through the smoothing update.
                current_observations = Counter(
                    {str(key): int(value) for key, value in additions.items()}
                )
                diagnostic_counts = Counter(
                    {
                        str(key): int(value)
                        for key, value in table["counts"].items()
                    }
                )
                diagnostic_counts.update(current_observations)
                table["counts"] = dict(sorted(diagnostic_counts.items()))
                # Admission uses current-checkpoint observations. Historical
                # counts remain diagnostic and never feed the EMA again.
                table["observations"] = int(sum(current_observations.values()))
                prior = table.get("probabilities", {})
                values = tuple(sorted(set(prior) | set(additions)))
                current_total = int(sum(additions.values()))
                empirical = {
                    value: (additions[value] + pseudocount)
                    / (current_total + pseudocount * len(values))
                    for value in values
                }
                blended = {
                    value: (1.0 - smoothing)
                    * float(prior.get(value, 1.0 / len(values)))
                    + smoothing * float(empirical[value])
                    for value in values
                }
                table["probabilities"] = self._regularized(values, blended)
        self.update_count += 1

    def entropy_summary(self) -> dict[str, float]:
        output: dict[str, float] = {}
        for axis, contexts in sorted(self.tables.items()):
            entropies = [
                self._entropy(list(table.get("probabilities", {}).values()))
                for table in contexts.values()
                if table.get("probabilities")
            ]
            output[axis] = float(np.mean(entropies)) if entropies else 0.0
        return output

    def export_state(self) -> dict[str, Any]:
        return {
            "kind": "hierarchical_typed_cem_v2",
            "seed": int(self.seed),
            "parameters": dict(self.parameters),
            "rng_state": _json_rng_state(self.rng.getstate()),
            "seen": sorted(self.seen),
            "tables": {
                axis: {context: dict(table) for context, table in sorted(contexts.items())}
                for axis, contexts in sorted(self.tables.items())
            },
            "update_count": int(self.update_count),
            "step": int(self.step),
            "last_elite_family_count": int(self.last_elite_family_count),
            "last_elite_mechanism_count": int(
                self.last_elite_mechanism_count
            ),
            "last_elite_skeleton_count": int(self.last_elite_skeleton_count),
        }

    def state_hash(self) -> str:
        return _payload_sha(self.export_state())

    @classmethod
    def from_state(
        cls, registry: TypedExpressionRegistry, state: Mapping[str, Any]
    ) -> "HierarchicalTypedCEMV2":
        policy = cls(int(state["seed"]), registry, dict(state["parameters"]))
        policy.rng.setstate(_tuple_rng_state(state["rng_state"]))
        policy.seen = set(str(value) for value in state["seen"])
        policy.tables = defaultdict(
            dict,
            {
                str(axis): {
                    str(context): dict(table)
                    for context, table in contexts.items()
                }
                for axis, contexts in state["tables"].items()
            },
        )
        policy.update_count = int(state["update_count"])
        policy.step = int(state["step"])
        policy.last_elite_family_count = int(
            state.get("last_elite_family_count", 0)
        )
        policy.last_elite_mechanism_count = int(
            state.get("last_elite_mechanism_count", 0)
        )
        policy.last_elite_skeleton_count = int(
            state.get("last_elite_skeleton_count", 0)
        )
        return policy


@dataclass(slots=True)
class TypedEvolutionV2:
    seed: int
    registry: TypedExpressionRegistry
    parameters: Mapping[str, Any] = field(
        default_factory=lambda: dict(V2_PARAMETERS["typed_evolution_v2"])
    )
    rng: random.Random = field(init=False)
    roles: dict[str, list[str]] = field(init=False)
    compatible_skeleton_ids: tuple[str, ...] = field(init=False)
    seen: set[str] = field(default_factory=set)
    population: dict[str, dict[str, Any]] = field(default_factory=dict)
    family_counts: Counter[str] = field(default_factory=Counter)
    step: int = 0
    verified_mutations: int = 0
    verified_skeleton_mutations: int = 0
    verified_crossovers: int = 0
    duplicate_replacements: int = 0
    operation_probabilities: dict[str, float] = field(init=False)
    operator_productivity: dict[str, dict[str, int]] = field(
        default_factory=lambda: {
            operation: {"trials": 0, "new_families": 0}
            for operation in EVOLUTION_OPERATIONS
        }
    )
    operator_update_count: int = 0
    blocked_transition_skips: int = 0
    transition_productivity: dict[str, dict[str, int]] = field(default_factory=dict)
    blocked_transition_keys: set[str] = field(default_factory=set)

    def __post_init__(self) -> None:
        self.parameters = dict(self.parameters)
        self.rng = random.Random(int(self.seed))
        surface = field_role_surface(tuple(self.registry.fields.values()))
        self.roles = {
            str(key): [str(value) for value in values]
            for key, values in surface["roles"].items()
        }
        self.compatible_skeleton_ids = tuple(surface["compatible_skeleton_ids"])
        if not self.compatible_skeleton_ids:
            raise ValueError("Evolution V2 carrier has no compatible skeleton")
        probabilities = sum(
            float(self.parameters[name])
            for name in (
                "gene_mutation_probability",
                "skeleton_variant_mutation_probability",
                "homologous_crossover_probability",
            )
        )
        if not math.isclose(probabilities, 1.0, rel_tol=0.0, abs_tol=1.0e-12):
            raise ValueError("Evolution V2 operation probabilities must sum to one")
        if int(self.parameters["population_limit"]) < int(
            self.parameters["tournament_size"]
        ):
            raise ValueError("Evolution V2 population is smaller than its tournament")
        if not 1 <= int(self.parameters["mechanism_cell_limit"]) <= int(
            self.parameters["population_limit"]
        ):
            raise ValueError("Evolution V2 mechanism cell limit is invalid")
        skeleton_cell_limit = int(
            self.parameters.get(
                "skeleton_cell_limit", self.parameters["population_limit"]
            )
        )
        if not 1 <= skeleton_cell_limit <= int(
            self.parameters["population_limit"]
        ):
            raise ValueError("Evolution V2 skeleton cell limit is invalid")
        floor = float(self.parameters.get("operator_productivity_floor", 0.0))
        if bool(self.parameters.get("operator_productivity_adaptation", False)):
            if not 0.0 <= floor < 1.0 / len(EVOLUTION_OPERATIONS):
                raise ValueError(
                    "Evolution V2 operator productivity floor is invalid"
                )
        if bool(
            self.parameters.get(
                "campaign_local_transition_collision_control", False
            )
        ) and int(self.parameters.get("transition_block_after_collisions", 0)) < 1:
            raise ValueError("Evolution V2 transition collision gate is invalid")
        self.operation_probabilities = {
            "EFFECTIVE_GENE_MUTATION_1_TO_3": float(
                self.parameters["gene_mutation_probability"]
            ),
            "COMPATIBLE_SKELETON_VARIANT_MUTATION": float(
                self.parameters["skeleton_variant_mutation_probability"]
            ),
            "ONE_POINT_HOMOLOGOUS_GENE_BUNDLE_CROSSOVER": float(
                self.parameters["homologous_crossover_probability"]
            ),
        }

    def _candidate(self, record: Mapping[str, Any]) -> CandidateSpec:
        return CandidateSpec.from_dict(record["candidate"])

    def _parent(
        self,
        *,
        eligible: Sequence[str] | None = None,
    ) -> CandidateSpec:
        ids = sorted(eligible or self.population)
        size = min(int(self.parameters["tournament_size"]), len(ids))
        if size == 0:
            raise RuntimeError("Evolution V2 has no eligible parent")
        participants = self.rng.sample(ids, size)
        parent_id = max(
            participants,
            key=lambda candidate_id: (
                float(self.population[candidate_id]["search_reward"]),
                -int(
                    self.family_counts[
                        str(self.population[candidate_id]["behavior_family_id"])
                    ]
                ),
                candidate_id,
            ),
        )
        return self._candidate(self.population[parent_id])

    def _receipt(
        self,
        *,
        operation: str,
        parents: Sequence[CandidateSpec],
        child: CandidateSpec,
        details: Mapping[str, Any],
    ) -> dict[str, Any]:
        core = {
            "schema_version": "BROAD_TYPED_EVOLUTION_RECEIPT_V2",
            "operation": operation,
            "parent_ids": [parent.candidate_id for parent in parents],
            "child_id": child.candidate_id,
            "parent_skeleton_ids": [parent.skeleton_id for parent in parents],
            "child_skeleton_id": child.skeleton_id,
            "parent_genome_sha256": [
                _payload_sha(parent.generation_genes) for parent in parents
            ],
            "child_genome_sha256": _payload_sha(child.generation_genes),
            "parent_expression_sha256": [
                _payload_sha(parent.expression.canonical_dict()) for parent in parents
            ],
            "child_expression_sha256": _payload_sha(
                child.expression.canonical_dict()
            ),
            "child_control_expression_sha256": _payload_sha(
                child.control.canonical_dict()
            ),
            "child_raw_fields": list(child.raw_fields),
            **dict(details),
        }
        return {**core, "receipt_sha256": _payload_sha(core)}

    def update_operator_productivity(
        self, rows: Sequence[Mapping[str, Any]]
    ) -> None:
        if not bool(
            self.parameters.get("operator_productivity_adaptation", False)
        ):
            return
        checkpoint_productivity = {
            operation: Counter(trials=0, new_families=0)
            for operation in EVOLUTION_OPERATIONS
        }
        for row in rows:
            operation = str(row.get("operation", ""))
            if operation not in checkpoint_productivity:
                continue
            stats = checkpoint_productivity[operation]
            stats["trials"] += 1
            stats["new_families"] += int(
                bool(
                    row.get(
                        "new_policy_local_behavior_family_at_completion",
                        False,
                    )
                )
            )
        self.operator_productivity = checkpoint_productivity
        prior_successes = int(
            self.parameters["operator_productivity_prior_successes"]
        )
        prior_trials = int(
            self.parameters["operator_productivity_prior_trials"]
        )
        scores = {
            operation: (
                int(stats["new_families"]) + prior_successes
            )
            / (int(stats["trials"]) + prior_trials)
            for operation, stats in sorted(self.operator_productivity.items())
        }
        total = float(sum(scores.values()))
        floor = float(self.parameters["operator_productivity_floor"])
        remaining = 1.0 - floor * len(EVOLUTION_OPERATIONS)
        self.operation_probabilities = {
            operation: floor + remaining * float(scores[operation]) / total
            for operation in EVOLUTION_OPERATIONS
        }
        self.operator_update_count += 1

    def _mutate_genes(
        self, parent: CandidateSpec
    ) -> tuple[CandidateSpec, dict[str, Any]]:
        skeleton = _skeleton_by_id(parent.skeleton_id)
        maximum = int(self.parameters["maximum_mutated_genes"])
        minimum = int(self.parameters["minimum_mutated_genes"])
        compiled_attempts = 0
        for internal_attempt in range(
            1, int(self.parameters["duplicate_resample_limit"]) + 2
        ):
            genome = dict(parent.generation_genes)
            effective = sorted(_effective_generation_gene_names(skeleton, genome))
            target_count = self.rng.randint(minimum, min(maximum, len(effective)))
            selected = self.rng.sample(effective, target_count)
            for name in selected:
                domains = _mutable_gene_domains(
                    skeleton, genes=genome, roles=self.roles
                )
                if name not in domains:
                    break
                genome[name] = self.rng.choice(domains[name])
            else:
                child = candidate_from_genes(
                    self.registry,
                    skeleton=skeleton,
                    genes=genome,
                    roles=self.roles,
                )
                compiled_attempts += 1
                changed = sorted(
                    name
                    for name in GENE_ORDER
                    if child.generation_genes[name] != parent.generation_genes[name]
                )
                if minimum <= len(changed) <= maximum and child.candidate_id != parent.candidate_id:
                    return child, self._receipt(
                        operation="EFFECTIVE_GENE_MUTATION_1_TO_3",
                        parents=(parent,),
                        child=child,
                        details={
                            "changed_genes": changed,
                            "internal_generation_attempts": internal_attempt,
                            "compile_valid_attempts": compiled_attempts,
                        },
                    )
        raise _ProposalGenerationFailure(
            "Evolution V2 could not produce an effective 1-3 gene mutation",
            raw_attempts=int(self.parameters["duplicate_resample_limit"]) + 1,
            compile_valid_attempts=compiled_attempts,
        )

    @staticmethod
    def _skeleton_transition_key(
        *,
        parent_behavior_family_id: str,
        source_skeleton_id: str,
        target_skeleton_id: str,
        remapped_genome_sha256: str,
    ) -> str:
        return _payload_sha(
            {
                "operation": "COMPATIBLE_SKELETON_VARIANT_MUTATION",
                "parent_behavior_family_id": str(parent_behavior_family_id),
                "source_skeleton_id": str(source_skeleton_id),
                "target_skeleton_id": str(target_skeleton_id),
                "remapped_genome_sha256": str(remapped_genome_sha256),
            }
        )

    def _mutate_skeleton_with_transition(
        self,
        parent: CandidateSpec,
        *,
        parent_behavior_family_id: str,
        blocked_transition_keys: set[str] | None = None,
    ) -> tuple[CandidateSpec, dict[str, Any], str]:
        source = _skeleton_by_id(parent.skeleton_id)
        targets = [
            item
            for item in skeleton_registry()
            if item.skeleton_id in self.compatible_skeleton_ids
            and item.mechanism_family == source.mechanism_family
            and item.skeleton_id != source.skeleton_id
            and item.field_roles == source.field_roles
        ]
        self.rng.shuffle(targets)
        blocked = blocked_transition_keys or set()
        for internal_attempt, target in enumerate(targets, start=1):
            child = candidate_from_genes(
                self.registry,
                skeleton=target,
                genes=dict(parent.generation_genes),
                roles=self.roles,
            )
            transition_key = self._skeleton_transition_key(
                parent_behavior_family_id=parent_behavior_family_id,
                source_skeleton_id=source.skeleton_id,
                target_skeleton_id=target.skeleton_id,
                remapped_genome_sha256=_payload_sha(
                    child.generation_genes
                ),
            )
            if transition_key in blocked:
                self.blocked_transition_skips += 1
                continue
            if child.candidate_id != parent.candidate_id:
                return (
                    child,
                    self._receipt(
                        operation="COMPATIBLE_SKELETON_VARIANT_MUTATION",
                        parents=(parent,),
                        child=child,
                        details={
                            "source_variant": int(source.variant),
                            "target_variant": int(target.variant),
                            "deterministic_gene_remapping": dict(
                                child.generation_genes
                            ),
                            "internal_generation_attempts": internal_attempt,
                            "compile_valid_attempts": internal_attempt,
                        },
                    ),
                    transition_key,
                )
        raise _ProposalGenerationFailure(
            "Evolution V2 has no compatible skeleton variant mutation",
            raw_attempts=max(1, len(targets)),
            compile_valid_attempts=len(targets),
        )

    def _mutate_skeleton(
        self, parent: CandidateSpec
    ) -> tuple[CandidateSpec, dict[str, Any]]:
        child, receipt, _ = self._mutate_skeleton_with_transition(
            parent,
            parent_behavior_family_id="RECEIPT_ONLY_NO_COLLISION_MEMORY",
            blocked_transition_keys=set(),
        )
        return child, receipt

    def _crossover(
        self, first: CandidateSpec, second: CandidateSpec
    ) -> tuple[CandidateSpec, dict[str, Any]]:
        first_skeleton = _skeleton_by_id(first.skeleton_id)
        second_skeleton = _skeleton_by_id(second.skeleton_id)
        if first_skeleton.field_roles != second_skeleton.field_roles:
            raise ValueError("crossover parents have incompatible typed roles")
        gene_order = [
            name
            for name in GENE_ORDER
            if name
            in (
                _effective_generation_gene_names(
                    first_skeleton, first.generation_genes
                )
                & _effective_generation_gene_names(
                    second_skeleton, second.generation_genes
                )
            )
        ]
        points = list(range(1, len(gene_order)))
        self.rng.shuffle(points)
        compiled_attempts = 0
        for internal_attempt, point in enumerate(points, start=1):
            genome = dict(first.generation_genes)
            for index, name in enumerate(gene_order):
                if index >= point:
                    genome[name] = second.generation_genes[name]
            try:
                child = candidate_from_genes(
                    self.registry,
                    skeleton=first_skeleton,
                    genes=genome,
                    roles=self.roles,
                )
            except ValueError:
                continue
            compiled_attempts += 1
            if child.candidate_id in {first.candidate_id, second.candidate_id}:
                continue
            return child, self._receipt(
                operation="ONE_POINT_HOMOLOGOUS_GENE_BUNDLE_CROSSOVER",
                parents=(first, second),
                child=child,
                details={
                    "crossover_point": int(point),
                    "gene_order": gene_order,
                    "output_type": "NUMERIC_ASSET_TIME",
                    "internal_generation_attempts": internal_attempt,
                    "compile_valid_attempts": compiled_attempts,
                },
            )
        raise _ProposalGenerationFailure(
            "Evolution V2 could not produce a compatible crossover",
            raw_attempts=max(1, len(points)),
            compile_valid_attempts=compiled_attempts,
        )

    def verify_receipt(
        self,
        parents: Sequence[CandidateSpec],
        child: CandidateSpec,
        receipt: Mapping[str, Any],
    ) -> bool:
        try:
            core = {
                key: value for key, value in receipt.items() if key != "receipt_sha256"
            }
            if (
                receipt.get("schema_version")
                != "BROAD_TYPED_EVOLUTION_RECEIPT_V2"
                or receipt.get("parent_ids")
                != [parent.candidate_id for parent in parents]
                or receipt.get("child_id") != child.candidate_id
                or receipt.get("parent_skeleton_ids")
                != [parent.skeleton_id for parent in parents]
                or receipt.get("child_skeleton_id") != child.skeleton_id
                or receipt.get("parent_genome_sha256")
                != [_payload_sha(parent.generation_genes) for parent in parents]
                or receipt.get("child_genome_sha256")
                != _payload_sha(child.generation_genes)
                or receipt.get("parent_expression_sha256")
                != [
                    _payload_sha(parent.expression.canonical_dict())
                    for parent in parents
                ]
                or receipt.get("child_expression_sha256")
                != _payload_sha(child.expression.canonical_dict())
                or receipt.get("child_control_expression_sha256")
                != _payload_sha(child.control.canonical_dict())
                or receipt.get("child_raw_fields") != list(child.raw_fields)
                or receipt.get("receipt_sha256") != _payload_sha(core)
                or not _candidate_rebuild_verified(self.registry, child, self.roles)
            ):
                return False
            operation = str(receipt["operation"])
            if operation == "EFFECTIVE_GENE_MUTATION_1_TO_3":
                if len(parents) != 1 or child.skeleton_id != parents[0].skeleton_id:
                    return False
                changed = sorted(
                    name
                    for name in GENE_ORDER
                    if child.generation_genes[name]
                    != parents[0].generation_genes[name]
                )
                return changed == receipt.get("changed_genes") and 1 <= len(changed) <= 3
            if operation == "COMPATIBLE_SKELETON_VARIANT_MUTATION":
                if len(parents) != 1:
                    return False
                source = _skeleton_by_id(parents[0].skeleton_id)
                target = _skeleton_by_id(child.skeleton_id)
                rebuilt = candidate_from_genes(
                    self.registry,
                    skeleton=target,
                    genes=dict(parents[0].generation_genes),
                    roles=self.roles,
                )
                return bool(
                    source.mechanism_family == target.mechanism_family
                    and source.field_roles == target.field_roles
                    and source.skeleton_id != target.skeleton_id
                    and rebuilt.candidate_id == child.candidate_id
                    and receipt.get("deterministic_gene_remapping")
                    == child.generation_genes
                )
            if operation == "ONE_POINT_HOMOLOGOUS_GENE_BUNDLE_CROSSOVER":
                if len(parents) != 2:
                    return False
                if (
                    _skeleton_by_id(parents[0].skeleton_id).field_roles
                    != _skeleton_by_id(parents[1].skeleton_id).field_roles
                ):
                    return False
                first_skeleton = _skeleton_by_id(parents[0].skeleton_id)
                second_skeleton = _skeleton_by_id(parents[1].skeleton_id)
                gene_order = [
                    name
                    for name in GENE_ORDER
                    if name
                    in (
                        _effective_generation_gene_names(
                            first_skeleton, parents[0].generation_genes
                        )
                        & _effective_generation_gene_names(
                            second_skeleton, parents[1].generation_genes
                        )
                    )
                ]
                if receipt.get("gene_order") != gene_order:
                    return False
                point = int(receipt["crossover_point"])
                if not 1 <= point < len(gene_order):
                    return False
                genome = dict(parents[0].generation_genes)
                for index, name in enumerate(gene_order):
                    if index >= point:
                        genome[name] = parents[1].generation_genes[name]
                rebuilt = candidate_from_genes(
                    self.registry,
                    skeleton=first_skeleton,
                    genes=genome,
                    roles=self.roles,
                )
                return rebuilt.candidate_id == child.candidate_id
            return False
        except (KeyError, TypeError, ValueError, StopIteration):
            return False

    def propose(
        self, archive: BehaviorArchive | None = None
    ) -> tuple[CandidateSpec, dict[str, Any]]:
        del archive  # reporting archive is never an adaptive-policy input
        before = self.state_hash()
        limit = int(self.parameters["duplicate_resample_limit"])
        candidate: CandidateSpec | None = None
        receipt: dict[str, Any] | None = None
        parents: tuple[CandidateSpec, ...] = ()
        operation = "TYPED_RANDOM_WARMUP"
        transition_key: str | None = None
        compile_attempts = 0
        compile_valid_attempts = 0

        def run_child_operation(operation_factory: Callable[[], Any]) -> Any:
            try:
                return operation_factory()
            except _ProposalGenerationFailure as failure:
                raise _ProposalGenerationFailure(
                    str(failure),
                    raw_attempts=(
                        compile_attempts + failure.raw_attempts - 1
                    ),
                    compile_valid_attempts=(
                        compile_valid_attempts
                        + failure.compile_valid_attempts
                    ),
                ) from failure

        for duplicate_resamples in range(limit + 1):
            transition_key = None
            compile_attempts += 1
            if len(self.population) < int(self.parameters["warmup"]):
                skeletons = tuple(
                    item
                    for item in skeleton_registry()
                    if item.skeleton_id in self.compatible_skeleton_ids
                )
                skeleton = skeletons[(self.step + self.seed + duplicate_resamples) % len(skeletons)]
                candidate = generate_effective_candidate(
                    self.registry, skeleton=skeleton, rng=self.rng, roles=self.roles
                )
                receipt = None
                parents = ()
                operation = "TYPED_RANDOM_WARMUP"
                compile_valid_attempts += 1
            else:
                draw = self.rng.random()
                gene_probability = float(
                    self.operation_probabilities[
                        "EFFECTIVE_GENE_MUTATION_1_TO_3"
                    ]
                )
                skeleton_probability = float(
                    self.operation_probabilities[
                        "COMPATIBLE_SKELETON_VARIANT_MUTATION"
                    ]
                )
                first = self._parent()
                if draw < gene_probability:
                    candidate, receipt = run_child_operation(
                        lambda: self._mutate_genes(first)
                    )
                    parents = (first,)
                    operation = str(receipt["operation"])
                elif draw < gene_probability + skeleton_probability:
                    if bool(
                        self.parameters.get(
                            "campaign_local_transition_collision_control",
                            False,
                        )
                    ):
                        parent_family_id = str(
                            self.population[first.candidate_id][
                                "behavior_family_id"
                            ]
                        )
                        (
                            candidate,
                            receipt,
                            transition_key,
                        ) = run_child_operation(
                            lambda: self._mutate_skeleton_with_transition(
                                first,
                                parent_behavior_family_id=parent_family_id,
                                blocked_transition_keys=self.blocked_transition_keys,
                            )
                        )
                    else:
                        candidate, receipt = run_child_operation(
                            lambda: self._mutate_skeleton(first)
                        )
                    parents = (first,)
                    operation = str(receipt["operation"])
                else:
                    first_roles = _skeleton_by_id(first.skeleton_id).field_roles
                    compatible = [
                        candidate_id
                        for candidate_id, record in self.population.items()
                        if candidate_id != first.candidate_id
                        and _skeleton_by_id(
                            str(record["candidate"]["skeleton_id"])
                        ).field_roles
                        == first_roles
                    ]
                    if bool(
                        self.parameters.get(
                            "prefer_cross_skeleton_crossover", False
                        )
                    ):
                        cross_skeleton = [
                            candidate_id
                            for candidate_id in compatible
                            if str(
                                self.population[candidate_id]["candidate"][
                                    "skeleton_id"
                                ]
                            )
                            != first.skeleton_id
                        ]
                        if cross_skeleton:
                            compatible = cross_skeleton
                    if not compatible:
                        candidate, receipt = run_child_operation(
                            lambda: self._mutate_genes(first)
                        )
                        parents = (first,)
                    else:
                        second = self._parent(eligible=compatible)
                        candidate, receipt = run_child_operation(
                            lambda: self._crossover(first, second)
                        )
                        parents = (first, second)
                    operation = str(receipt["operation"])
                compile_attempts += int(
                    receipt.get("internal_generation_attempts", 1)
                ) - 1
                compile_valid_attempts += int(
                    receipt.get("compile_valid_attempts", 1)
                )
            if candidate.candidate_id not in self.seen:
                break
        assert candidate is not None
        if candidate.candidate_id in self.seen:
            raise _ProposalGenerationFailure(
                "Evolution V2 duplicate resample limit exhausted",
                raw_attempts=compile_attempts,
                compile_valid_attempts=compile_valid_attempts,
            )
        verified = (
            self.verify_receipt(parents, candidate, receipt)
            if receipt is not None
            else _candidate_rebuild_verified(self.registry, candidate, self.roles)
        )
        if not verified:
            raise RuntimeError("Evolution V2 receipt or expression verification failed")
        self.seen.add(candidate.candidate_id)
        self.step += 1
        return candidate, {
            "policy_state_hash_before": before,
            "operation": operation,
            "parent_ids": [parent.candidate_id for parent in parents],
            "receipt": receipt,
            "receipt_verified": bool(verified) if receipt is not None else None,
            "raw_attempts": compile_attempts,
            "compile_valid_attempts": compile_valid_attempts,
            "transition_key": transition_key,
        }

    def observe(
        self,
        candidate: CandidateSpec,
        archive_row: Mapping[str, Any],
    ) -> None:
        family_id = str(archive_row["behavior_family_id"])
        self.family_counts[family_id] += 1
        parent_ids = [str(value) for value in archive_row.get("parent_ids", [])]
        root_lineage_ids = sorted(
            {
                root_id
                for parent_id in parent_ids
                for root_id in self.population.get(parent_id, {}).get(
                    "root_lineage_ids", [parent_id]
                )
            }
            or {candidate.candidate_id}
        )
        candidate_record = {
            "candidate": candidate.to_dict(),
            "search_reward": _search_ordering_reward(archive_row),
            "pair_reward": float(archive_row["pair_reward"]),
            "behavior_family_id": family_id,
            "mechanism_family": candidate.mechanism_family,
            "skeleton_id": candidate.skeleton_id,
            "root_lineage_ids": root_lineage_ids,
        }
        family_members = [
            candidate_id
            for candidate_id, record in self.population.items()
            if str(record["behavior_family_id"]) == family_id
        ]
        keep_new = True
        for candidate_id in family_members:
            old = self.population[candidate_id]
            if (
                float(old["search_reward"])
                > float(candidate_record["search_reward"])
                or (
                    float(old["search_reward"])
                    == float(candidate_record["search_reward"])
                    and candidate_id < candidate.candidate_id
                )
            ):
                keep_new = False
            else:
                del self.population[candidate_id]
                self.duplicate_replacements += 1
        if keep_new:
            self.population[candidate.candidate_id] = candidate_record
        limit = int(self.parameters["population_limit"])
        if len(self.population) > limit or (
            "skeleton_cell_limit" in self.parameters and self.population
        ):
            ordered = sorted(
                self.population,
                key=lambda candidate_id: (
                    -float(self.population[candidate_id]["search_reward"]),
                    candidate_id,
                ),
            )
            cell_limit = int(self.parameters["mechanism_cell_limit"])
            skeleton_cell_limit = int(
                self.parameters.get("skeleton_cell_limit", limit)
            )
            mechanism_counts: Counter[str] = Counter()
            skeleton_counts: Counter[str] = Counter()
            retained: list[str] = []
            for candidate_id in ordered:
                mechanism = str(
                    self.population[candidate_id]["mechanism_family"]
                )
                skeleton_id = str(
                    self.population[candidate_id].get(
                        "skeleton_id",
                        self.population[candidate_id]["candidate"]["skeleton_id"],
                    )
                )
                if (
                    mechanism_counts[mechanism] >= cell_limit
                    or skeleton_counts[skeleton_id] >= skeleton_cell_limit
                ):
                    continue
                retained.append(candidate_id)
                mechanism_counts[mechanism] += 1
                skeleton_counts[skeleton_id] += 1
                if len(retained) == limit:
                    break
            self.population = {
                candidate_id: self.population[candidate_id]
                for candidate_id in retained
            }
        operation = str(archive_row.get("operation", ""))
        if operation == "EFFECTIVE_GENE_MUTATION_1_TO_3":
            self.verified_mutations += 1
        elif operation == "COMPATIBLE_SKELETON_VARIANT_MUTATION":
            self.verified_skeleton_mutations += 1
        elif operation == "ONE_POINT_HOMOLOGOUS_GENE_BUNDLE_CROSSOVER":
            self.verified_crossovers += 1

    def observe_transition(
        self,
        *,
        transition_key: str,
        new_family: bool,
        block_after_collisions: int,
    ) -> None:
        if not transition_key:
            raise ValueError("policy-local transition observation lacks a key")
        stats = self.transition_productivity.setdefault(
            str(transition_key),
            {"trials": 0, "new_families": 0, "collisions": 0},
        )
        stats["trials"] += 1
        stats["new_families"] += int(bool(new_family))
        stats["collisions"] += int(not new_family)
        if int(stats["collisions"]) >= int(block_after_collisions):
            self.blocked_transition_keys.add(str(transition_key))

    def population_diagnostics(self) -> dict[str, Any]:
        mechanism_occupancy = Counter(
            str(record.get("mechanism_family", ""))
            for record in self.population.values()
        )
        skeleton_occupancy = Counter(
            str(
                record.get(
                    "skeleton_id", record["candidate"]["skeleton_id"]
                )
            )
            for record in self.population.values()
        )
        family_occupancy = Counter(
            str(record.get("behavior_family_id", ""))
            for record in self.population.values()
        )
        root_counts: Counter[str] = Counter()
        for record in self.population.values():
            roots = tuple(record.get("root_lineage_ids", ()))
            weight = 1.0 / max(1, len(roots))
            for root_id in roots:
                root_counts[str(root_id)] += weight
        total_root_weight = float(sum(root_counts.values()))
        probabilities = [
            float(count) / total_root_weight
            for count in root_counts.values()
            if total_root_weight > 0.0 and count > 0.0
        ]
        return {
            "effective_parent_count": len(self.population),
            "lineage_entropy": float(
                -sum(value * math.log(value) for value in probabilities)
            ),
            "top_root_lineage_share": (
                max(root_counts.values(), default=0.0)
                / max(total_root_weight, 1.0)
            ),
            "mechanism_occupancy": dict(sorted(mechanism_occupancy.items())),
            "skeleton_occupancy": dict(sorted(skeleton_occupancy.items())),
            "behavior_family_count": len(family_occupancy),
            "duplicate_family_slots": int(
                sum(max(0, count - 1) for count in family_occupancy.values())
            ),
            "operation_probabilities": dict(
                sorted(self.operation_probabilities.items())
            ),
            "operator_productivity": {
                operation: dict(stats)
                for operation, stats in sorted(
                    self.operator_productivity.items()
                )
            },
            "operator_update_count": int(self.operator_update_count),
            "blocked_transition_skips": int(self.blocked_transition_skips),
            "transition_productivity": {
                key: dict(value)
                for key, value in sorted(self.transition_productivity.items())
            },
            "blocked_transition_keys": sorted(self.blocked_transition_keys),
        }

    def export_state(self) -> dict[str, Any]:
        state = {
            "kind": "typed_evolution_v2",
            "seed": int(self.seed),
            "parameters": dict(self.parameters),
            "rng_state": _json_rng_state(self.rng.getstate()),
            "seen": sorted(self.seen),
            "population": {
                candidate_id: dict(record)
                for candidate_id, record in sorted(self.population.items())
            },
            "family_counts": dict(sorted(self.family_counts.items())),
            "step": int(self.step),
            "verified_mutations": int(self.verified_mutations),
            "verified_skeleton_mutations": int(self.verified_skeleton_mutations),
            "verified_crossovers": int(self.verified_crossovers),
            "duplicate_replacements": int(self.duplicate_replacements),
            "operation_probabilities": dict(
                sorted(self.operation_probabilities.items())
            ),
            "operator_productivity": {
                operation: dict(stats)
                for operation, stats in sorted(
                    self.operator_productivity.items()
                )
            },
            "operator_update_count": int(self.operator_update_count),
        }
        if bool(
            self.parameters.get(
                "campaign_local_transition_collision_control", False
            )
        ):
            state["blocked_transition_skips"] = int(
                self.blocked_transition_skips
            )
            state["transition_productivity"] = {
                key: dict(value)
                for key, value in sorted(self.transition_productivity.items())
            }
            state["blocked_transition_keys"] = sorted(
                self.blocked_transition_keys
            )
        return state

    def state_hash(self) -> str:
        return _payload_sha(self.export_state())

    @classmethod
    def from_state(
        cls, registry: TypedExpressionRegistry, state: Mapping[str, Any]
    ) -> "TypedEvolutionV2":
        policy = cls(int(state["seed"]), registry, dict(state["parameters"]))
        policy.rng.setstate(_tuple_rng_state(state["rng_state"]))
        policy.seen = set(str(value) for value in state["seen"])
        policy.population = {
            str(candidate_id): dict(record)
            for candidate_id, record in state["population"].items()
        }
        policy.family_counts = Counter(
            {
                str(family_id): int(count)
                for family_id, count in state.get("family_counts", {}).items()
            }
        )
        policy.step = int(state["step"])
        policy.verified_mutations = int(state["verified_mutations"])
        policy.verified_skeleton_mutations = int(
            state["verified_skeleton_mutations"]
        )
        policy.verified_crossovers = int(state["verified_crossovers"])
        policy.duplicate_replacements = int(state["duplicate_replacements"])
        policy.operation_probabilities = {
            str(operation): float(probability)
            for operation, probability in state.get(
                "operation_probabilities",
                policy.operation_probabilities,
            ).items()
        }
        policy.operator_productivity = {
            operation: {
                "trials": int(
                    state.get("operator_productivity", {})
                    .get(operation, {})
                    .get("trials", 0)
                ),
                "new_families": int(
                    state.get("operator_productivity", {})
                    .get(operation, {})
                    .get("new_families", 0)
                ),
            }
            for operation in EVOLUTION_OPERATIONS
        }
        policy.operator_update_count = int(
            state.get("operator_update_count", 0)
        )
        policy.blocked_transition_skips = int(
            state.get("blocked_transition_skips", 0)
        )
        policy.transition_productivity = {
            str(key): {
                "trials": int(value.get("trials", 0)),
                "new_families": int(value.get("new_families", 0)),
                "collisions": int(value.get("collisions", 0)),
            }
            for key, value in state.get("transition_productivity", {}).items()
        }
        policy.blocked_transition_keys = set(
            str(value) for value in state.get("blocked_transition_keys", ())
        )
        return policy


def _mechanism_catalog_sha(catalog: Sequence[MechanismSpec]) -> str:
    return _payload_sha([item.to_dict() for item in catalog])


def _weighted_key_choice(
    rng: random.Random, probabilities: Mapping[str, float]
) -> str:
    ordered = tuple(sorted((str(key), float(value)) for key, value in probabilities.items()))
    draw = rng.random() * sum(value for _, value in ordered)
    cumulative = 0.0
    for key, value in ordered:
        cumulative += value
        if draw <= cumulative:
            return key
    return ordered[-1][0]


def _regularized_mechanism_probabilities(
    *,
    previous: Mapping[str, float],
    counts: Mapping[str, float],
    smoothing: float,
    minimum_probability: float,
    entropy_floor_ratio: float,
    pseudocount: float,
) -> dict[str, float]:
    domain = tuple(sorted(str(value) for value in previous))
    if not domain:
        raise ValueError("mechanism probability domain is empty")
    raw = {key: float(counts.get(key, 0.0)) + pseudocount for key in domain}
    raw_total = sum(raw.values())
    target = {key: raw[key] / raw_total for key in domain}
    blended = {
        key: (1.0 - smoothing) * float(previous[key]) + smoothing * target[key]
        for key in domain
    }
    floor_total = minimum_probability * len(domain)
    if floor_total >= 1.0:
        raise ValueError("mechanism minimum probability exhausts the simplex")
    residual = sum(max(0.0, value - minimum_probability) for value in blended.values())
    if residual <= 0.0:
        regularized = {key: 1.0 / len(domain) for key in domain}
    else:
        regularized = {
            key: minimum_probability
            + (1.0 - floor_total)
            * max(0.0, blended[key] - minimum_probability)
            / residual
            for key in domain
        }
    entropy_floor = entropy_floor_ratio * math.log(len(domain)) if len(domain) > 1 else 0.0

    def entropy(values: Mapping[str, float]) -> float:
        return -sum(value * math.log(value) for value in values.values() if value > 0.0)

    if entropy(regularized) + 1.0e-15 < entropy_floor:
        uniform = 1.0 / len(domain)
        low, high = 0.0, 1.0
        for _ in range(60):
            mix = (low + high) / 2.0
            trial = {
                key: (1.0 - mix) * regularized[key] + mix * uniform
                for key in domain
            }
            if entropy(trial) >= entropy_floor:
                high = mix
            else:
                low = mix
        regularized = {
            key: (1.0 - high) * regularized[key] + high * uniform
            for key in domain
        }
    total = sum(regularized.values())
    return {key: regularized[key] / total for key in domain}


@dataclass
class MechanismRandomV2:
    seed: int
    registry: TypedExpressionRegistry
    catalog: tuple[MechanismSpec, ...]
    parameters: dict[str, Any] = field(
        default_factory=lambda: {"duplicate_resample_limit": 64}
    )
    rng: random.Random = field(init=False)
    domains: dict[str, tuple[Any, ...]] = field(init=False)
    program_specs_by_id: dict[str, Any] = field(init=False, default_factory=dict)
    seen: set[str] = field(default_factory=set)
    step: int = 0

    def __post_init__(self) -> None:
        if not self.catalog or len({item.mechanism_id for item in self.catalog}) != len(
            self.catalog
        ):
            raise ValueError("mechanism policy catalog must be non-empty and unique")
        stream_id = str(self.parameters.get("rng_stream_id") or "")
        effective_seed = (
            int.from_bytes(
                hashlib.sha256(
                    f"{int(self.seed)}|{stream_id}".encode("utf-8")
                ).digest()[:8],
                "big",
            )
            if stream_id
            else int(self.seed)
        )
        self.rng = random.Random(effective_seed)
        self.domains = mechanism_role_domains(tuple(self.registry.fields.values()))
        if self.parameters.get("candidate_builder") == "TEMPORAL_MECHANISM_PROGRAM_V1":
            from alphafactory_crypto.broad_search.temporal_program_v1 import (
                TemporalProgramSpec,
            )

            parsed = [
                TemporalProgramSpec.from_dict(row)
                for row in tuple(self.parameters.get("temporal_program_specs") or ())
            ]
            self.program_specs_by_id = {value.program_id: value for value in parsed}
            expected_program_ids = {str(item.program_id) for item in self.catalog}
            if (
                None in {item.program_id for item in self.catalog}
                or set(self.program_specs_by_id) != expected_program_ids
            ):
                raise ValueError("temporal program policy catalog is incomplete")
        if "allowed_horizons" in self.parameters:
            allowed_horizons = tuple(
                int(value) for value in self.parameters["allowed_horizons"]
            )
            if not allowed_horizons or any(value not in HORIZONS for value in allowed_horizons):
                raise ValueError("mechanism policy allowed_horizons changed")
            self.domains["__HORIZONS__"] = allowed_horizons

    def _select_spec(self) -> MechanismSpec:
        if bool(self.parameters.get("balanced_template_sampling", False)):
            templates = tuple(sorted({item.template_id for item in self.catalog}))
            template = self.rng.choice(templates)
            choices = tuple(
                item for item in self.catalog if item.template_id == template
            )
            return self.rng.choice(choices)
        return self.catalog[self.rng.randrange(len(self.catalog))]

    def _program_spec(self, spec: MechanismSpec) -> Any:
        if self.parameters.get("candidate_builder") != "TEMPORAL_MECHANISM_PROGRAM_V1":
            return None
        try:
            return self.program_specs_by_id[str(spec.program_id)]
        except KeyError as error:
            raise ValueError(
                "temporal program policy catalog binding changed"
            ) from error

    def _sample_candidate(self, spec: MechanismSpec) -> CandidateSpec:
        if self.parameters.get("candidate_builder") == "TEMPORAL_MECHANISM_PROGRAM_V1":
            from alphafactory_crypto.broad_search.temporal_program_v1 import (
                sample_temporal_program_candidate,
            )

            return sample_temporal_program_candidate(
                registry=self.registry,
                mechanism=spec,
                program=self._program_spec(spec),
                domains=self.domains,
                scale_contract=dict(self.parameters["time_scale_authority"]),
                rng=self.rng,
            )
        return sample_mechanism_candidate(
            registry=self.registry,
            spec=spec,
            domains=self.domains,
            rng=self.rng,
        )

    def _build_candidate(self, genes: Mapping[str, Any]) -> CandidateSpec:
        if self.parameters.get("candidate_builder") == "TEMPORAL_MECHANISM_PROGRAM_V1":
            from alphafactory_crypto.broad_search.temporal_program_v1 import (
                temporal_program_candidate_from_genes,
            )

            return temporal_program_candidate_from_genes(
                self.registry, genes=genes, domains=self.domains
            )
        return mechanism_candidate_from_genes(
            self.registry, genes=genes, domains=self.domains
        )

    def propose(self) -> tuple[CandidateSpec, dict[str, Any]]:
        before = self.state_hash()
        limit = int(self.parameters.get("duplicate_resample_limit", 64))
        for attempt in range(1, limit + 2):
            spec = self._select_spec()
            candidate = self._sample_candidate(spec)
            if candidate.candidate_id in self.seen:
                continue
            self.seen.add(candidate.candidate_id)
            self.step += 1
            metadata = {
                "policy_state_hash_before": before,
                "operation": "EXTENSIBLE_MECHANISM_TYPED_RANDOM",
                "parent_ids": [],
                "receipt": None,
                "receipt_verified": None,
                "raw_attempts": attempt,
                "compile_valid_attempts": attempt,
            }
            metadata["policy_state_hash_after_proposal"] = self.state_hash()
            return candidate, metadata
        raise _ProposalGenerationFailure(
            "Mechanism random duplicate resample limit exhausted",
            raw_attempts=limit + 1,
            compile_valid_attempts=limit + 1,
        )

    def export_state(self) -> dict[str, Any]:
        return {
            "kind": "mechanism_random_v2",
            "seed": int(self.seed),
            "parameters": dict(self.parameters),
            "catalog": [item.to_dict() for item in self.catalog],
            "catalog_sha256": _mechanism_catalog_sha(self.catalog),
            "rng_state": _json_rng_state(self.rng.getstate()),
            "seen": sorted(self.seen),
            "step": int(self.step),
        }

    def state_hash(self) -> str:
        return _payload_sha(self.export_state())

    @classmethod
    def from_state(
        cls, registry: TypedExpressionRegistry, state: Mapping[str, Any]
    ) -> "MechanismRandomV2":
        catalog = tuple(MechanismSpec.from_dict(row) for row in state["catalog"])
        if _mechanism_catalog_sha(catalog) != str(state["catalog_sha256"]):
            raise ValueError("mechanism catalog checkpoint identity changed")
        policy = cls(
            int(state["seed"]), registry, catalog, dict(state["parameters"])
        )
        policy.rng.setstate(_tuple_rng_state(state["rng_state"]))
        policy.seen = set(str(value) for value in state["seen"])
        policy.step = int(state["step"])
        return policy


@dataclass
class MechanismCEMV2(MechanismRandomV2):
    template_probabilities: dict[str, float] = field(init=False)
    mechanism_probabilities: dict[str, dict[str, float]] = field(init=False)
    update_count: int = 0

    def __post_init__(self) -> None:
        super().__post_init__()
        templates = sorted({item.template_id for item in self.catalog})
        self.template_probabilities = {
            template: 1.0 / len(templates) for template in templates
        }
        self.mechanism_probabilities = {}
        for template in templates:
            ids = sorted(
                item.mechanism_id
                for item in self.catalog
                if item.template_id == template
            )
            self.mechanism_probabilities[template] = {
                mechanism_id: 1.0 / len(ids) for mechanism_id in ids
            }

    def _select_spec(self) -> MechanismSpec:
        template = _weighted_key_choice(self.rng, self.template_probabilities)
        mechanism_id = _weighted_key_choice(
            self.rng, self.mechanism_probabilities[template]
        )
        return next(item for item in self.catalog if item.mechanism_id == mechanism_id)

    def propose(self) -> tuple[CandidateSpec, dict[str, Any]]:
        candidate, metadata = super().propose()
        metadata["operation"] = "MECHANISM_LEVEL_CEM_V2_SAMPLE"
        return candidate, metadata

    def update(self, rows: Sequence[Mapping[str, Any]]) -> None:
        minimum = int(self.parameters.get("minimum_observation_count", 8))
        if len(rows) < minimum:
            return
        champions: dict[str, Mapping[str, Any]] = {}
        for row in rows:
            family_id = str(row.get("behavior_family_id", row.get("candidate_id", "")))
            previous = champions.get(family_id)
            if previous is None or (
                -float(row["search_reward"]), str(row["candidate_id"])
            ) < (-float(previous["search_reward"]), str(previous["candidate_id"])):
                champions[family_id] = row
        ordered = sorted(
            champions.values(),
            key=lambda row: (-float(row["search_reward"]), str(row["candidate_id"])),
        )
        elite_count = max(
            1,
            int(math.ceil(float(self.parameters.get("elite_fraction", 0.20)) * len(ordered))),
        )
        elites = ordered[:elite_count]
        template_counts: Counter[str] = Counter()
        mechanism_counts: dict[str, Counter[str]] = defaultdict(Counter)
        for row in elites:
            payload = row.get("candidate_spec_json")
            candidate = (
                CandidateSpec.from_dict(json.loads(str(payload)))
                if not isinstance(payload, Mapping)
                else CandidateSpec.from_dict(payload)
            )
            spec = MechanismSpec.from_dict(candidate.generation_genes["mechanism_spec"])
            template_counts[spec.template_id] += 1
            mechanism_counts[spec.template_id][spec.mechanism_id] += 1
        common = {
            "smoothing": float(self.parameters.get("smoothing", 0.35)),
            "minimum_probability": float(
                self.parameters.get("minimum_probability", 0.002)
            ),
            "entropy_floor_ratio": float(
                self.parameters.get("entropy_floor_ratio", 0.60)
            ),
            "pseudocount": float(self.parameters.get("count_pseudocount", 0.50)),
        }
        self.template_probabilities = _regularized_mechanism_probabilities(
            previous=self.template_probabilities,
            counts=template_counts,
            **common,
        )
        for template, previous in sorted(self.mechanism_probabilities.items()):
            self.mechanism_probabilities[template] = (
                _regularized_mechanism_probabilities(
                    previous=previous,
                    counts=mechanism_counts.get(template, {}),
                    **common,
                )
            )
        self.update_count += 1

    def entropy_summary(self) -> dict[str, float]:
        template_entropy = -sum(
            value * math.log(value)
            for value in self.template_probabilities.values()
            if value > 0.0
        )
        conditional = []
        for values in self.mechanism_probabilities.values():
            conditional.append(
                -sum(value * math.log(value) for value in values.values() if value > 0.0)
            )
        return {
            "template_entropy": float(template_entropy),
            "mean_conditional_mechanism_entropy": float(np.mean(conditional)),
        }

    def export_state(self) -> dict[str, Any]:
        state = super().export_state()
        state.update(
            {
                "kind": "mechanism_cem_v2",
                "template_probabilities": dict(sorted(self.template_probabilities.items())),
                "mechanism_probabilities": {
                    key: dict(sorted(values.items()))
                    for key, values in sorted(self.mechanism_probabilities.items())
                },
                "update_count": int(self.update_count),
            }
        )
        return state

    @classmethod
    def from_state(
        cls, registry: TypedExpressionRegistry, state: Mapping[str, Any]
    ) -> "MechanismCEMV2":
        catalog = tuple(MechanismSpec.from_dict(row) for row in state["catalog"])
        if _mechanism_catalog_sha(catalog) != str(state["catalog_sha256"]):
            raise ValueError("mechanism CEM catalog checkpoint identity changed")
        policy = cls(
            int(state["seed"]), registry, catalog, dict(state["parameters"])
        )
        policy.rng.setstate(_tuple_rng_state(state["rng_state"]))
        policy.seen = set(str(value) for value in state["seen"])
        policy.step = int(state["step"])
        policy.template_probabilities = {
            str(key): float(value)
            for key, value in state["template_probabilities"].items()
        }
        policy.mechanism_probabilities = {
            str(key): {str(inner): float(value) for inner, value in values.items()}
            for key, values in state["mechanism_probabilities"].items()
        }
        policy.update_count = int(state["update_count"])
        return policy


MECHANISM_EVOLUTION_OPERATIONS = (
    "MECHANISM_PARAMETER_GROUP_MUTATION_1_TO_3",
    "COMPATIBLE_MECHANISM_SPEC_MUTATION",
    "ONE_POINT_TYPED_MECHANISM_CROSSOVER",
)


@dataclass
class MechanismEvolutionV2(MechanismRandomV2):
    population: dict[str, dict[str, Any]] = field(default_factory=dict)
    verified_parameter_mutations: int = 0
    verified_mechanism_mutations: int = 0
    verified_crossovers: int = 0
    targeted_parent_pool_payload: dict[str, Any] | None = None
    targeted_basin_order: tuple[str, ...] = ()
    targeted_member_order: dict[str, tuple[str, ...]] = field(default_factory=dict)
    targeted_basin_cursor: int = 0
    targeted_parent_cursors: dict[str, int] = field(default_factory=dict)

    def _candidate(self, record: Mapping[str, Any]) -> CandidateSpec:
        return CandidateSpec.from_dict(record["candidate"])

    def configure_targeted_parent_pool(self, payload: Mapping[str, Any]) -> None:
        """Freeze a train-only economic-basin parent source for local exploration.

        This is optional and leaves every historical/non-targeted policy path
        unchanged.  Current-run children may still be observed for diagnostics,
        but targeted proposals never promote them into the frozen parent source.
        """

        value = json.loads(json.dumps(dict(payload)))
        observed_sha = str(value.get("target_parent_pool_sha256") or "")
        core = {
            key: item
            for key, item in value.items()
            if key != "target_parent_pool_sha256"
        }
        if (
            not observed_sha
            or observed_sha != _payload_sha(core)
            or value.get("status")
            != "FROZEN_TRAIN_ONLY_ECONOMIC_BASIN_PARENT_POOL"
            or int(value.get("validation_reads", -1)) != 0
            or int(value.get("oos_reads", -1)) != 0
            or int(value.get("sealed_reads", -1)) != 0
            or int(value.get("market_arrays_read", -1)) != 0
            or int(value.get("candidate_evaluations", -1)) != 0
        ):
            raise ValueError("targeted frozen parent pool identity changed")
        parent_records = dict(value.get("parent_records") or {})
        basins = list(value.get("target_basins") or ())
        if (
            not parent_records
            or not basins
            or int(value.get("frozen_parent_candidate_count", -1))
            != len(parent_records)
            or int(value.get("target_basin_count", -1)) != len(basins)
        ):
            raise ValueError("targeted frozen parent pool is empty or inconsistent")
        members_by_basin: dict[str, tuple[str, ...]] = {}
        seen_members: set[str] = set()
        for basin in basins:
            basin_id = str(basin.get("economic_similarity_cluster_id") or "")
            members = tuple(str(item) for item in basin.get("member_candidate_ids", ()))
            if not basin_id or not members or len(set(members)) != len(members):
                raise ValueError("targeted frozen basin membership changed")
            for candidate_id in members:
                record = dict(parent_records.get(candidate_id) or {})
                if (
                    str(record.get("candidate_id") or "") != candidate_id
                    or str(record.get("economic_similarity_cluster_id") or "")
                    != basin_id
                ):
                    raise ValueError("targeted frozen parent record changed")
                candidate = self._candidate(record)
                if candidate.candidate_id != candidate_id:
                    raise ValueError("targeted frozen parent CandidateSpec changed")
                if not _candidate_rebuild_verified(self.registry, candidate, {}):
                    raise ValueError("targeted frozen parent replay failed")
                family = str(
                    candidate.generation_genes.get("program_spec", {}).get(
                        "family_id", ""
                    )
                )
                if family != str(record.get("program_family_id") or ""):
                    raise ValueError("targeted frozen parent family changed")
                seen_members.add(candidate_id)
            members_by_basin[basin_id] = members
        if seen_members != set(parent_records):
            raise ValueError("targeted frozen parent coverage changed")
        self.targeted_parent_pool_payload = value
        self.targeted_basin_order = tuple(
            sorted(
                members_by_basin,
                key=lambda basin_id: _payload_sha(
                    {"seed": int(self.seed), "basin_id": basin_id}
                ),
            )
        )
        self.targeted_member_order = {
            basin_id: tuple(
                sorted(
                    members,
                    key=lambda candidate_id: _payload_sha(
                        {
                            "seed": int(self.seed),
                            "basin_id": basin_id,
                            "candidate_id": candidate_id,
                        }
                    ),
                )
            )
            for basin_id, members in members_by_basin.items()
        }
        self.targeted_basin_cursor = 0
        self.targeted_parent_cursors = {
            basin_id: 0 for basin_id in self.targeted_basin_order
        }
        # Baseline parents are source material, never valid child proposals.
        self.seen.update(parent_records)

    def _targeted_parent_record(self, candidate_id: str) -> dict[str, Any]:
        if self.targeted_parent_pool_payload is None:
            raise RuntimeError("targeted parent source is not configured")
        return dict(
            dict(self.targeted_parent_pool_payload["parent_records"])[candidate_id]
        )

    def _next_targeted_basin(self) -> str:
        if not self.targeted_basin_order:
            raise RuntimeError("targeted parent source has no basin")
        basin_id = self.targeted_basin_order[
            self.targeted_basin_cursor % len(self.targeted_basin_order)
        ]
        self.targeted_basin_cursor += 1
        return basin_id

    def _next_targeted_parent(self, basin_id: str) -> CandidateSpec:
        members = self.targeted_member_order[basin_id]
        cursor = int(self.targeted_parent_cursors.get(basin_id, 0))
        candidate_id = members[cursor % len(members)]
        self.targeted_parent_cursors[basin_id] = cursor + 1
        return self._candidate(self._targeted_parent_record(candidate_id))

    def _targeted_crossover_parent(
        self, basin_id: str, first: CandidateSpec
    ) -> CandidateSpec | None:
        members = self.targeted_member_order[basin_id]
        first_record = self._targeted_parent_record(first.candidate_id)
        first_realization = str(first_record.get("concrete_realization_id") or "")
        first_spec = self._spec(first)
        compatible: list[tuple[bool, int, CandidateSpec]] = []
        start = int(self.targeted_parent_cursors.get(basin_id, 0))
        for offset in range(len(members)):
            candidate_id = members[(start + offset) % len(members)]
            if candidate_id == first.candidate_id:
                continue
            record = self._targeted_parent_record(candidate_id)
            candidate = self._candidate(record)
            if not self._compatible(first_spec, self._spec(candidate)):
                continue
            different_realization = (
                str(record.get("concrete_realization_id") or "")
                != first_realization
            )
            compatible.append((not different_realization, offset, candidate))
        if not compatible:
            return None
        compatible.sort(key=lambda row: (row[0], row[1], row[2].candidate_id))
        second = compatible[0][2]
        self.targeted_parent_cursors[basin_id] = start + compatible[0][1] + 1
        return second

    def _bind_targeted_receipt(
        self,
        receipt: Mapping[str, Any],
        *,
        basin_id: str,
        parents: Sequence[CandidateSpec],
    ) -> dict[str, Any]:
        if self.targeted_parent_pool_payload is None:
            raise RuntimeError("targeted parent source is not configured")
        core = {key: value for key, value in receipt.items() if key != "receipt_sha256"}
        core.update(
            {
                "targeted_parent_source": "FROZEN_TRAIN_ONLY_BASELINE",
                "targeted_economic_basin_id": basin_id,
                "targeted_parent_pool_sha256": str(
                    self.targeted_parent_pool_payload["target_parent_pool_sha256"]
                ),
                "targeted_parent_realization_ids": [
                    str(
                        self._targeted_parent_record(parent.candidate_id).get(
                            "concrete_realization_id"
                        )
                        or ""
                    )
                    for parent in parents
                ],
            }
        )
        return {**core, "receipt_sha256": _payload_sha(core)}

    def _selection_key(
        self,
        candidate_id: str,
        record: Mapping[str, Any],
        *,
        include_family_count: bool,
    ) -> tuple[Any, ...]:
        if self.parameters.get("selection_authority") != (
            "DEVELOPMENT_THREE_BLOCK_ROBUST_ORDERING_V1"
        ):
            base: tuple[Any, ...] = (-float(record["search_reward"]),)
        else:
            ordering = dict(record.get("block_robust_ordering") or {})
            if ordering.get("authority") != (
                "DEVELOPMENT_THREE_BLOCK_ROBUST_ORDERING_V1"
            ):
                raise ValueError("block-robust Evolution observation is unbound")
            base = (
                -int(ordering["replicated_positive_block_count"]),
                -float(ordering["worst_block_min_matched_net_mean"]),
                -float(ordering["median_block_joint_search_reward"]),
                float(ordering["max_required_mean_one_way_turnover"]),
                -float(ordering["min_required_support"]),
            )
        if include_family_count:
            base = (*base, int(record.get("family_count", 1)))
        return (*base, str(candidate_id))

    def _parent(self, eligible: Sequence[str] | None = None) -> CandidateSpec:
        ids = sorted(eligible or self.population)
        size = min(int(self.parameters.get("tournament_size", 4)), len(ids))
        sampled = self.rng.sample(ids, size)
        selected = min(
            sampled,
            key=lambda candidate_id: self._selection_key(
                candidate_id,
                self.population[candidate_id],
                include_family_count=True,
            ),
        )
        return self._candidate(self.population[selected])

    @staticmethod
    def _spec(candidate: CandidateSpec) -> MechanismSpec:
        return MechanismSpec.from_dict(candidate.generation_genes["mechanism_spec"])

    @staticmethod
    def _compatible(first: MechanismSpec, second: MechanismSpec) -> bool:
        return (
            first.left_role,
            first.right_role,
            first.condition_role,
        ) == (
            second.left_role,
            second.right_role,
            second.condition_role,
        )

    def _receipt(
        self,
        *,
        operation: str,
        parents: Sequence[CandidateSpec],
        child: CandidateSpec,
        details: Mapping[str, Any],
    ) -> dict[str, Any]:
        core = {
            "schema_version": "MECHANISM_EVOLUTION_RECEIPT_V2",
            "operation": operation,
            "parent_ids": [value.candidate_id for value in parents],
            "parent_mechanism_ids": [self._spec(value).mechanism_id for value in parents],
            "child_id": child.candidate_id,
            "child_mechanism_id": self._spec(child).mechanism_id,
            "parent_expression_sha256": [
                _payload_sha(value.expression.canonical_dict()) for value in parents
            ],
            "child_expression_sha256": _payload_sha(child.expression.canonical_dict()),
            "child_control_sha256": _payload_sha(child.control.canonical_dict()),
            "child_genome_sha256": _payload_sha(child.generation_genes),
            **dict(details),
        }
        return {**core, "receipt_sha256": _payload_sha(core)}

    @staticmethod
    def _gene_groups(candidate: CandidateSpec) -> tuple[tuple[str, ...], ...]:
        if "program_spec" in candidate.generation_genes:
            from alphafactory_crypto.broad_search.temporal_program_v1 import (
                program_gene_groups,
            )

            return program_gene_groups(candidate)
        spec = MechanismEvolutionV2._spec(candidate)
        groups: list[tuple[str, ...]] = [
            ("left_field", "left_auxiliary_field"),
            ("right_field", "right_auxiliary_field"),
            ("left_window", "left_normalizer"),
            ("right_window", "right_normalizer"),
            ("horizon_hours",),
        ]
        if spec.condition_role:
            groups.extend(
                [
                    ("condition_field", "condition_auxiliary_field"),
                    ("condition_window", "condition_normalizer"),
                ]
            )
        if spec.payload_operator == "Residual":
            groups.append(("beta",))
        return tuple(groups)

    def _mutate_parameters(
        self, parent: CandidateSpec
    ) -> tuple[CandidateSpec, dict[str, Any]]:
        spec = self._spec(parent)
        limit = int(self.parameters.get("duplicate_resample_limit", 64))
        for attempt in range(1, limit + 2):
            donor = self._sample_candidate(spec)
            genome = dict(parent.generation_genes)
            groups = list(self._gene_groups(parent))
            count = self.rng.randint(1, min(3, len(groups)))
            selected = self.rng.sample(groups, count)
            for group in selected:
                for name in group:
                    genome[name] = donor.generation_genes[name]
            child = self._build_candidate(genome)
            if child.candidate_id == parent.candidate_id:
                continue
            return child, self._receipt(
                operation=MECHANISM_EVOLUTION_OPERATIONS[0],
                parents=(parent,),
                child=child,
                details={
                    "changed_gene_groups": [list(value) for value in selected],
                    "internal_generation_attempts": attempt,
                    "compile_valid_attempts": attempt,
                },
            )
        raise _ProposalGenerationFailure(
            "mechanism parameter mutation exhausted",
            raw_attempts=limit + 1,
            compile_valid_attempts=limit + 1,
        )

    def _mutate_mechanism(
        self, parent: CandidateSpec
    ) -> tuple[CandidateSpec, dict[str, Any]]:
        source = self._spec(parent)
        targets = [
            item
            for item in self.catalog
            if item.mechanism_id != source.mechanism_id
            and self._compatible(source, item)
        ]
        self.rng.shuffle(targets)
        for attempt, target in enumerate(targets, start=1):
            genome = dict(parent.generation_genes)
            genome.update(
                {
                    "mechanism_id": target.mechanism_id,
                    "mechanism_spec": target.to_dict(),
                    "matched_control_schema": target.matched_control_schema,
                }
            )
            if target.payload_operator != "Residual":
                genome["beta"] = 0.5
            if "program_spec" in genome:
                donor = self._sample_candidate(target)
                for name in (
                    "program_id",
                    "program_spec",
                    "left_window",
                    "left_long_window",
                    "left_threshold",
                    "left_outer_window",
                    "left_outer_threshold",
                    "right_window",
                    "right_long_window",
                    "right_threshold",
                    "outer_threshold",
                    "beta",
                ):
                    genome[name] = donor.generation_genes[name]
            try:
                child = self._build_candidate(genome)
            except ValueError:
                continue
            if child.candidate_id == parent.candidate_id:
                continue
            remap_domain = (
                (
                    "program_id",
                    "program_spec",
                    "left_window",
                    "left_long_window",
                    "left_threshold",
                    "left_outer_window",
                    "left_outer_threshold",
                    "right_window",
                    "right_long_window",
                    "right_threshold",
                    "outer_threshold",
                    "beta",
                )
                if "program_spec" in child.generation_genes
                else ("beta",)
            )
            remapped_gene_names = sorted(
                name
                for name in remap_domain
                if child.generation_genes.get(name)
                != parent.generation_genes.get(name)
            )
            return child, self._receipt(
                operation=MECHANISM_EVOLUTION_OPERATIONS[1],
                parents=(parent,),
                child=child,
                details={
                    "source_mechanism_id": source.mechanism_id,
                    "target_mechanism_id": target.mechanism_id,
                    "deterministic_gene_remapping": True,
                    "remapped_gene_names": remapped_gene_names,
                    "internal_generation_attempts": attempt,
                    "compile_valid_attempts": attempt,
                },
            )
        raise _ProposalGenerationFailure(
            "compatible mechanism mutation exhausted",
            raw_attempts=max(1, len(targets)),
            compile_valid_attempts=len(targets),
        )

    def _crossover(
        self, first: CandidateSpec, second: CandidateSpec
    ) -> tuple[CandidateSpec, dict[str, Any]]:
        if not self._compatible(self._spec(first), self._spec(second)):
            raise ValueError("mechanism crossover roles are incompatible")
        groups = list(self._gene_groups(first))
        points = list(range(1, len(groups)))
        self.rng.shuffle(points)
        for attempt, point in enumerate(points, start=1):
            genome = dict(first.generation_genes)
            for group in groups[point:]:
                for name in group:
                    genome[name] = second.generation_genes[name]
            try:
                child = self._build_candidate(genome)
            except ValueError:
                continue
            if child.candidate_id in {first.candidate_id, second.candidate_id}:
                continue
            return child, self._receipt(
                operation=MECHANISM_EVOLUTION_OPERATIONS[2],
                parents=(first, second),
                child=child,
                details={
                    "crossover_point": point,
                    "gene_groups": [list(value) for value in groups],
                    "output_type": "NUMERIC_ASSET_TIME",
                    "internal_generation_attempts": attempt,
                    "compile_valid_attempts": attempt,
                },
            )
        raise _ProposalGenerationFailure(
            "typed mechanism crossover exhausted",
            raw_attempts=max(1, len(points)),
            compile_valid_attempts=len(points),
        )

    def verify_receipt(
        self,
        parents: Sequence[CandidateSpec],
        child: CandidateSpec,
        receipt: Mapping[str, Any],
    ) -> bool:
        try:
            core = {key: value for key, value in receipt.items() if key != "receipt_sha256"}
            operation = str(receipt["operation"])
            parent_ids = [value.candidate_id for value in parents]
            parent_mechanism_ids = [
                self._spec(value).mechanism_id for value in parents
            ]
            parent_hashes = [
                _payload_sha(value.expression.canonical_dict()) for value in parents
            ]
            operation_verified = False
            if operation == MECHANISM_EVOLUTION_OPERATIONS[0] and len(parents) == 1:
                groups = tuple(
                    tuple(str(name) for name in group)
                    for group in receipt.get("changed_gene_groups", ())
                )
                legal_groups = set(self._gene_groups(parents[0]))
                selected_keys = {name for group in groups for name in group}
                all_keys = set(parents[0].generation_genes) | set(
                    child.generation_genes
                )
                operation_verified = bool(
                    1 <= len(groups) <= 3
                    and len(set(groups)) == len(groups)
                    and set(groups).issubset(legal_groups)
                    and self._spec(child).mechanism_id
                    == self._spec(parents[0]).mechanism_id
                    and any(
                        child.generation_genes.get(key)
                        != parents[0].generation_genes.get(key)
                        for key in selected_keys
                    )
                    and all(
                        child.generation_genes.get(key)
                        == parents[0].generation_genes.get(key)
                        for key in all_keys - selected_keys
                    )
                )
            elif operation == MECHANISM_EVOLUTION_OPERATIONS[1] and len(parents) == 1:
                source = self._spec(parents[0])
                target = self._spec(child)
                remap_domain = (
                    (
                        "program_id",
                        "program_spec",
                        "left_window",
                        "left_long_window",
                        "left_threshold",
                        "left_outer_window",
                        "left_outer_threshold",
                        "right_window",
                        "right_long_window",
                        "right_threshold",
                        "outer_threshold",
                        "beta",
                    )
                    if "program_spec" in child.generation_genes
                    else ("beta",)
                )
                expected_remapped = sorted(
                    name
                    for name in remap_domain
                    if child.generation_genes.get(name)
                    != parents[0].generation_genes.get(name)
                )
                allowed = {
                    "mechanism_id",
                    "mechanism_spec",
                    "matched_control_schema",
                    *expected_remapped,
                }
                all_keys = set(parents[0].generation_genes) | set(
                    child.generation_genes
                )
                operation_verified = bool(
                    source.mechanism_id
                    == str(receipt.get("source_mechanism_id"))
                    and target.mechanism_id
                    == str(receipt.get("target_mechanism_id"))
                    and source.mechanism_id != target.mechanism_id
                    and self._compatible(source, target)
                    and receipt.get("deterministic_gene_remapping") is True
                    and receipt.get("remapped_gene_names") == expected_remapped
                    and all(
                        child.generation_genes.get(key)
                        == parents[0].generation_genes.get(key)
                        for key in all_keys - allowed
                    )
                )
            elif operation == MECHANISM_EVOLUTION_OPERATIONS[2] and len(parents) == 2:
                groups = tuple(
                    tuple(str(name) for name in group)
                    for group in receipt.get("gene_groups", ())
                )
                point = int(receipt.get("crossover_point", -1))
                expected_groups = self._gene_groups(parents[0])
                grouped_keys = {name for group in groups for name in group}
                all_keys = set(parents[0].generation_genes) | set(
                    child.generation_genes
                )
                operation_verified = bool(
                    groups == expected_groups
                    and 0 < point < len(groups)
                    and self._compatible(self._spec(parents[0]), self._spec(parents[1]))
                    and self._spec(child).mechanism_id
                    == self._spec(parents[0]).mechanism_id
                    and all(
                        child.generation_genes.get(name)
                        == parents[0].generation_genes.get(name)
                        for group in groups[:point]
                        for name in group
                    )
                    and all(
                        child.generation_genes.get(name)
                        == parents[1].generation_genes.get(name)
                        for group in groups[point:]
                        for name in group
                    )
                    and all(
                        child.generation_genes.get(key)
                        == parents[0].generation_genes.get(key)
                        for key in all_keys - grouped_keys
                    )
                    and receipt.get("output_type") == "NUMERIC_ASSET_TIME"
                )
            targeted_verified = True
            if receipt.get("targeted_parent_source") is not None:
                basin_id = str(receipt.get("targeted_economic_basin_id") or "")
                members = set(self.targeted_member_order.get(basin_id, ()))
                targeted_verified = bool(
                    self.targeted_parent_pool_payload is not None
                    and receipt.get("targeted_parent_source")
                    == "FROZEN_TRAIN_ONLY_BASELINE"
                    and str(receipt.get("targeted_parent_pool_sha256") or "")
                    == str(
                        self.targeted_parent_pool_payload.get(
                            "target_parent_pool_sha256", ""
                        )
                    )
                    and members
                    and set(parent_ids).issubset(members)
                    and receipt.get("targeted_parent_realization_ids")
                    == [
                        str(
                            self._targeted_parent_record(parent.candidate_id).get(
                                "concrete_realization_id"
                            )
                            or ""
                        )
                        for parent in parents
                    ]
                )
            return bool(
                targeted_verified
                and receipt.get("schema_version") == "MECHANISM_EVOLUTION_RECEIPT_V2"
                and operation in MECHANISM_EVOLUTION_OPERATIONS
                and operation_verified
                and receipt.get("parent_ids") == parent_ids
                and receipt.get("parent_mechanism_ids") == parent_mechanism_ids
                and receipt.get("parent_expression_sha256") == parent_hashes
                and receipt.get("child_id") == child.candidate_id
                and receipt.get("child_mechanism_id") == self._spec(child).mechanism_id
                and receipt.get("child_expression_sha256")
                == _payload_sha(child.expression.canonical_dict())
                and receipt.get("child_control_sha256")
                == _payload_sha(child.control.canonical_dict())
                and receipt.get("child_genome_sha256")
                == _payload_sha(child.generation_genes)
                and receipt.get("receipt_sha256") == _payload_sha(core)
                and _candidate_rebuild_verified(self.registry, child, {})
            )
        except (KeyError, TypeError, ValueError):
            return False

    def _propose_targeted(self) -> tuple[CandidateSpec, dict[str, Any]]:
        before = self.state_hash()
        limit = int(self.parameters.get("duplicate_resample_limit", 64))
        for duplicate_attempt in range(1, limit + 2):
            basin_id = self._next_targeted_basin()
            first = self._next_targeted_parent(basin_id)
            draw = self.rng.random()
            parameter_probability = float(
                self.parameters.get("parameter_mutation_probability", 0.50)
            )
            mechanism_probability = float(
                self.parameters.get("mechanism_mutation_probability", 0.30)
            )
            if draw < parameter_probability:
                child, receipt = self._mutate_parameters(first)
                parents = (first,)
            elif draw < parameter_probability + mechanism_probability:
                child, receipt = self._mutate_mechanism(first)
                parents = (first,)
            else:
                second = self._targeted_crossover_parent(basin_id, first)
                if second is None:
                    child, receipt = self._mutate_parameters(first)
                    parents = (first,)
                else:
                    try:
                        child, receipt = self._crossover(first, second)
                        parents = (first, second)
                    except _ProposalGenerationFailure:
                        child, receipt = self._mutate_parameters(first)
                        parents = (first,)
            receipt = self._bind_targeted_receipt(
                receipt, basin_id=basin_id, parents=parents
            )
            if child.candidate_id in self.seen:
                continue
            if not self.verify_receipt(parents, child, receipt):
                raise RuntimeError("targeted mechanism evolution receipt verification failed")
            self.seen.add(child.candidate_id)
            self.step += 1
            return child, {
                "policy_state_hash_before": before,
                "operation": str(receipt["operation"]),
                "parent_ids": [value.candidate_id for value in parents],
                "receipt": receipt,
                "receipt_verified": True,
                "raw_attempts": duplicate_attempt
                + int(receipt.get("internal_generation_attempts", 1))
                - 1,
                "compile_valid_attempts": int(
                    receipt.get("compile_valid_attempts", 1)
                ),
                "targeted_economic_basin_id": basin_id,
                "targeted_parent_pool_sha256": str(
                    self.targeted_parent_pool_payload["target_parent_pool_sha256"]
                ),
            }
        raise _ProposalGenerationFailure(
            "targeted mechanism evolution duplicate resample limit exhausted",
            raw_attempts=limit + 1,
        )

    def propose(self) -> tuple[CandidateSpec, dict[str, Any]]:
        if self.targeted_parent_pool_payload is not None:
            return self._propose_targeted()
        if len(self.population) < int(self.parameters.get("warmup", 32)):
            candidate, metadata = super().propose()
            metadata["operation"] = "MECHANISM_EVOLUTION_TYPED_RANDOM_WARMUP"
            return candidate, metadata
        before = self.state_hash()
        limit = int(self.parameters.get("duplicate_resample_limit", 64))
        for duplicate_attempt in range(1, limit + 2):
            first = self._parent()
            draw = self.rng.random()
            if draw < float(self.parameters.get("parameter_mutation_probability", 0.50)):
                child, receipt = self._mutate_parameters(first)
                parents = (first,)
            elif draw < float(
                self.parameters.get("parameter_mutation_probability", 0.50)
            ) + float(self.parameters.get("mechanism_mutation_probability", 0.30)):
                child, receipt = self._mutate_mechanism(first)
                parents = (first,)
            else:
                first_spec = self._spec(first)
                compatible = [
                    candidate_id
                    for candidate_id, record in self.population.items()
                    if candidate_id != first.candidate_id
                    and self._compatible(first_spec, self._spec(self._candidate(record)))
                ]
                if compatible:
                    second = self._parent(compatible)
                    child, receipt = self._crossover(first, second)
                    parents = (first, second)
                else:
                    child, receipt = self._mutate_parameters(first)
                    parents = (first,)
            if child.candidate_id in self.seen:
                continue
            if not self.verify_receipt(parents, child, receipt):
                raise RuntimeError("mechanism evolution receipt verification failed")
            self.seen.add(child.candidate_id)
            self.step += 1
            return child, {
                "policy_state_hash_before": before,
                "operation": str(receipt["operation"]),
                "parent_ids": [value.candidate_id for value in parents],
                "receipt": receipt,
                "receipt_verified": True,
                "raw_attempts": duplicate_attempt
                + int(receipt.get("internal_generation_attempts", 1))
                - 1,
                "compile_valid_attempts": int(
                    receipt.get("compile_valid_attempts", 1)
                ),
            }
        raise _ProposalGenerationFailure(
            "mechanism evolution duplicate resample limit exhausted",
            raw_attempts=limit + 1,
        )

    def observe(
        self, candidate: CandidateSpec, archive_row: Mapping[str, Any]
    ) -> None:
        family_id = str(archive_row["behavior_family_id"])
        record = {
            "candidate": candidate.to_dict(),
            "search_reward": _search_ordering_reward(archive_row),
            "block_robust_ordering": (
                dict(archive_row["block_robust_ordering"])
                if isinstance(archive_row.get("block_robust_ordering"), Mapping)
                else None
            ),
            "behavior_family_id": family_id,
            "family_count": int(
                archive_row.get("policy_local_family_count_at_completion", 1)
            ),
        }
        for candidate_id in [
            key
            for key, value in self.population.items()
            if str(value["behavior_family_id"]) == family_id
        ]:
            old = self.population[candidate_id]
            if self._selection_key(
                candidate_id, old, include_family_count=False
            ) < self._selection_key(
                candidate.candidate_id, record, include_family_count=False
            ):
                return
            del self.population[candidate_id]
        self.population[candidate.candidate_id] = record
        operation = str(archive_row.get("operation", ""))
        if operation == MECHANISM_EVOLUTION_OPERATIONS[0]:
            self.verified_parameter_mutations += 1
        elif operation == MECHANISM_EVOLUTION_OPERATIONS[1]:
            self.verified_mechanism_mutations += 1
        elif operation == MECHANISM_EVOLUTION_OPERATIONS[2]:
            self.verified_crossovers += 1
        limit = int(self.parameters.get("population_limit", 256))
        if len(self.population) > limit:
            retained = sorted(
                self.population,
                key=lambda candidate_id: self._selection_key(
                    candidate_id,
                    self.population[candidate_id],
                    include_family_count=False,
                ),
            )[:limit]
            self.population = {
                candidate_id: self.population[candidate_id]
                for candidate_id in retained
            }

    def population_diagnostics(self) -> dict[str, Any]:
        mechanism_occupancy = Counter(
            self._spec(self._candidate(record)).mechanism_id
            for record in self.population.values()
        )
        template_occupancy = Counter(
            self._spec(self._candidate(record)).template_id
            for record in self.population.values()
        )
        count = len(self.population)
        return {
            "effective_parent_count": count,
            "lineage_entropy": math.log(count) if count else 0.0,
            "top_root_lineage_share": 1.0 / count if count else 0.0,
            "mechanism_occupancy": dict(sorted(template_occupancy.items())),
            "skeleton_occupancy": dict(sorted(mechanism_occupancy.items())),
            "operation_probabilities": {
                MECHANISM_EVOLUTION_OPERATIONS[0]: float(
                    self.parameters.get("parameter_mutation_probability", 0.50)
                ),
                MECHANISM_EVOLUTION_OPERATIONS[1]: float(
                    self.parameters.get("mechanism_mutation_probability", 0.30)
                ),
                MECHANISM_EVOLUTION_OPERATIONS[2]: float(
                    self.parameters.get("crossover_probability", 0.20)
                ),
            },
            "operator_productivity": {},
            "operator_update_count": 0,
        }

    def export_state(self) -> dict[str, Any]:
        state = super().export_state()
        state.update(
            {
                "kind": "mechanism_evolution_v2",
                "population": {
                    key: dict(value) for key, value in sorted(self.population.items())
                },
                "verified_parameter_mutations": int(self.verified_parameter_mutations),
                "verified_mechanism_mutations": int(self.verified_mechanism_mutations),
                "verified_crossovers": int(self.verified_crossovers),
                "targeted_parent_pool_payload": self.targeted_parent_pool_payload,
                "targeted_basin_cursor": int(self.targeted_basin_cursor),
                "targeted_parent_cursors": dict(
                    sorted(self.targeted_parent_cursors.items())
                ),
            }
        )
        return state

    @classmethod
    def from_state(
        cls, registry: TypedExpressionRegistry, state: Mapping[str, Any]
    ) -> "MechanismEvolutionV2":
        catalog = tuple(MechanismSpec.from_dict(row) for row in state["catalog"])
        if _mechanism_catalog_sha(catalog) != str(state["catalog_sha256"]):
            raise ValueError("mechanism evolution catalog checkpoint identity changed")
        policy = cls(
            int(state["seed"]), registry, catalog, dict(state["parameters"])
        )
        policy.rng.setstate(_tuple_rng_state(state["rng_state"]))
        policy.seen = set(str(value) for value in state["seen"])
        policy.step = int(state["step"])
        policy.population = {
            str(key): dict(value) for key, value in state["population"].items()
        }
        policy.verified_parameter_mutations = int(
            state["verified_parameter_mutations"]
        )
        policy.verified_mechanism_mutations = int(
            state["verified_mechanism_mutations"]
        )
        policy.verified_crossovers = int(state["verified_crossovers"])
        targeted_payload = state.get("targeted_parent_pool_payload")
        if isinstance(targeted_payload, Mapping):
            policy.configure_targeted_parent_pool(targeted_payload)
            policy.targeted_basin_cursor = int(
                state.get("targeted_basin_cursor", 0)
            )
            restored_cursors = dict(state.get("targeted_parent_cursors") or {})
            if set(restored_cursors) != set(policy.targeted_parent_cursors):
                raise ValueError("targeted parent cursor identity changed")
            policy.targeted_parent_cursors = {
                str(key): int(value) for key, value in restored_cursors.items()
            }
        return policy


PolicyType = (
    LanePolicy
    | HierarchicalTypedCEMV2
    | TypedEvolutionV2
    | MechanismRandomV2
    | MechanismCEMV2
    | MechanismEvolutionV2
)


def _export_lane_policy(policy: LanePolicy) -> dict[str, Any]:
    return {
        "kind": "lane_policy_v1",
        "policy": policy.policy,
        "seed": int(policy.seed),
        "parameters": dict(policy.parameters),
        "rng_state": _json_rng_state(policy.rng.getstate()),
        "seen": sorted(policy.seen),
        "rewards": dict(sorted(policy.rewards.items())),
        "candidates": {
            candidate_id: candidate.to_dict()
            for candidate_id, candidate in sorted(policy.candidates.items())
        },
        "skeleton_visits": dict(sorted(policy.skeleton_visits.items())),
        "skeleton_rewards": {
            key: list(values) for key, values in sorted(policy.skeleton_rewards.items())
        },
        "proposal_order": list(policy.proposal_order),
        "cem_probabilities": {
            axis: dict(sorted(values.items()))
            for axis, values in sorted(policy.cem_probabilities.items())
        },
        "cem_update_count": int(policy.cem_update_count),
        "step": int(policy.step),
    }


def _restore_lane_policy(
    registry: TypedExpressionRegistry, state: Mapping[str, Any]
) -> LanePolicy:
    policy = LanePolicy(
        str(state["policy"]),
        int(state["seed"]),
        registry,
        dict(state["parameters"]),
    )
    policy.rng.setstate(_tuple_rng_state(state["rng_state"]))
    policy.seen = set(str(value) for value in state["seen"])
    policy.rewards = {
        str(key): float(value) for key, value in state["rewards"].items()
    }
    policy.candidates = {
        str(candidate_id): CandidateSpec.from_dict(payload)
        for candidate_id, payload in state["candidates"].items()
    }
    policy.skeleton_visits = Counter(
        {str(key): int(value) for key, value in state["skeleton_visits"].items()}
    )
    policy.skeleton_rewards = defaultdict(
        list,
        {
            str(key): [float(value) for value in values]
            for key, values in state["skeleton_rewards"].items()
        },
    )
    policy.proposal_order = [str(value) for value in state["proposal_order"]]
    policy.cem_probabilities = {
        str(axis): {str(key): float(value) for key, value in values.items()}
        for axis, values in state["cem_probabilities"].items()
    }
    policy.cem_update_count = int(state["cem_update_count"])
    policy.step = int(state["step"])
    return policy


def _export_policy(policy: PolicyType) -> dict[str, Any]:
    if isinstance(policy, LanePolicy):
        return _export_lane_policy(policy)
    return policy.export_state()


def _restore_policy(
    registry: TypedExpressionRegistry, state: Mapping[str, Any]
) -> PolicyType:
    kind = str(state["kind"])
    if kind == "lane_policy_v1":
        return _restore_lane_policy(registry, state)
    if kind == "hierarchical_typed_cem_v2":
        return HierarchicalTypedCEMV2.from_state(registry, state)
    if kind == "typed_evolution_v2":
        return TypedEvolutionV2.from_state(registry, state)
    if kind == "mechanism_random_v2":
        return MechanismRandomV2.from_state(registry, state)
    if kind == "mechanism_cem_v2":
        return MechanismCEMV2.from_state(registry, state)
    if kind == "mechanism_evolution_v2":
        return MechanismEvolutionV2.from_state(registry, state)
    raise ValueError(f"unsupported checkpoint policy kind: {kind}")


def _policy_key(arm: str, seed: int) -> str:
    return f"{arm}|{int(seed)}"


def _policy_inflight_limit(
    *,
    campaign: str,
    policy: PolicyType,
    workers: int,
    active_lane_count: int,
) -> int:
    """Return the semantics-preserving proposal lookahead for one policy lane.

    V2.1 random policies have no reward-dependent state, so consecutive asks
    from the same RNG lane can safely fill otherwise idle evaluator slots.  An
    adaptive policy remains one-in-flight: its next parent selection must see
    the preceding candidate's reward and behavior-family observation.
    """

    if campaign in {
        MECHANISM_SEARCH_V21_CAMPAIGN,
        MECHANISM_SEARCH_V22_CAMPAIGN,
        MECHANISM_SEARCH_V23_CAMPAIGN,
        *SEARCH_EVIDENCE_CAMPAIGNS,
    } and type(policy) is MechanismRandomV2:
        return max(1, int(math.ceil(int(workers) / max(1, int(active_lane_count)))))
    return 1


def _load_mechanism_v2_contract(
    repo_root: Path,
) -> tuple[dict[str, Any], tuple[MechanismSpec, ...]]:
    config = _read_json(repo_root / MECHANISM_SEARCH_V2_CONFIG)
    if config.get("authorization") != (
        "ONE_FRESH_STATE_12000_STRICT_MECHANISM_CAMPAIGN"
    ):
        raise PermissionError("Mechanism V2 authorization changed")
    if any(bool(value) for value in config.get("fresh_state", {}).values()):
        raise PermissionError("Mechanism V2 imported prior adaptive state")
    search = dict(config["search"])
    expected = {
        "strict_evaluated_target": MECHANISM_SEARCH_V2_STRICT_TARGET,
        "checkpoint_size": MECHANISM_SEARCH_V2_CHECKPOINT_SIZE,
        "checkpoint_count": MECHANISM_SEARCH_V2_CHECKPOINT_COUNT,
        "raw_generation_attempts_maximum": MECHANISM_SEARCH_V2_RAW_ATTEMPT_LIMIT,
        "wall_time_seconds_maximum": MECHANISM_SEARCH_V2_WALL_TIME_LIMIT_SECONDS,
    }
    if any(int(search.get(key, -1)) != value for key, value in expected.items()):
        raise ValueError("Mechanism V2 search budget changed")
    stages = list(config.get("stages") or ())
    checkpoint_owners: dict[int, str] = {}
    stage_strict_total = 0
    for stage in stages:
        indexes = tuple(int(value) for value in stage["checkpoint_indexes"])
        allocation = {
            str(arm): int(count)
            for arm, count in stage["allocation_per_checkpoint"].items()
        }
        if (
            not indexes
            or set(allocation) != set(MECHANISM_SEARCH_V2_ARMS)
            or sum(allocation.values()) != MECHANISM_SEARCH_V2_CHECKPOINT_SIZE
            or int(stage["strict_count"])
            != len(indexes) * MECHANISM_SEARCH_V2_CHECKPOINT_SIZE
        ):
            raise ValueError("Mechanism V2 stage allocation changed")
        for checkpoint_index in indexes:
            if checkpoint_index in checkpoint_owners:
                raise ValueError("Mechanism V2 checkpoint belongs to multiple stages")
            checkpoint_owners[checkpoint_index] = str(stage["stage_id"])
        stage_strict_total += int(stage["strict_count"])
    if set(checkpoint_owners) != set(range(MECHANISM_SEARCH_V2_CHECKPOINT_COUNT)) or (
        stage_strict_total != MECHANISM_SEARCH_V2_STRICT_TARGET
    ):
        raise ValueError("Mechanism V2 stages do not cover the frozen campaign")
    evolution_parameters = dict(
        dict(config["policy_parameters"])["mechanism_evolution_v2"]
    )
    if not math.isclose(
        sum(
            float(evolution_parameters[key])
            for key in (
                "parameter_mutation_probability",
                "mechanism_mutation_probability",
                "crossover_probability",
            )
        ),
        1.0,
        rel_tol=0.0,
        abs_tol=1.0e-15,
    ):
        raise ValueError("Mechanism V2 evolution operation probabilities changed")
    persistence = dict(config["persistent_mechanism_knowledge"])
    if any(
        bool(persistence.get(key))
        for key in ("individual_candidate_reward", "population", "cem_distribution", "rng_state")
    ):
        raise PermissionError("Mechanism V2 persistence crossed the campaign boundary")
    boundaries = dict(config["boundaries"])
    if any(
        bool(boundaries.get(key))
        for key in (
            "oos",
            "challenge",
            "recent",
            "may_stress",
            "forward",
            "promotion",
            "cross_sprint_adaptive_memory",
            "latent_priority",
            "relational_training",
        )
    ):
        raise PermissionError("Mechanism V2 crossed a frozen research boundary")
    catalog_path = repo_root / str(config["catalog_path"])
    if catalog_path != repo_root / MECHANISM_SEARCH_V2_CATALOG:
        raise ValueError("Mechanism V2 catalog path changed")
    catalog = compile_mechanism_catalog(_read_json(catalog_path))
    if len(catalog) <= len(skeleton_registry()):
        raise ValueError("Mechanism V2 catalog did not expand the legacy box")
    return config, catalog


def _load_mechanism_v21_contract(
    repo_root: Path,
) -> tuple[
    dict[str, Any],
    tuple[MechanismSpec, ...],
    tuple[MechanismSpec, ...],
    dict[str, Any],
]:
    """Load the fresh V2.1 campaign without importing V2 adaptive state."""

    config = _read_json(repo_root / MECHANISM_SEARCH_V21_CONFIG)
    if config.get("authorization") != (
        "ONE_FRESH_STATE_10000_STRICT_MECHANISM_BASIS_CAMPAIGN"
    ):
        raise PermissionError("Mechanism V2.1 authorization changed")
    if any(bool(value) for value in config.get("fresh_state", {}).values()):
        raise PermissionError("Mechanism V2.1 imported prior adaptive state")
    search = dict(config["search"])
    expected = {
        "strict_evaluated_target": MECHANISM_SEARCH_V21_STRICT_TARGET,
        "checkpoint_size": MECHANISM_SEARCH_V21_CHECKPOINT_SIZE,
        "checkpoint_count": MECHANISM_SEARCH_V21_CHECKPOINT_COUNT,
        "raw_generation_attempts_maximum": MECHANISM_SEARCH_V21_RAW_ATTEMPT_LIMIT,
        "wall_time_seconds_maximum": MECHANISM_SEARCH_V21_WALL_TIME_LIMIT_SECONDS,
    }
    if any(int(search.get(key, -1)) != value for key, value in expected.items()):
        raise ValueError("Mechanism V2.1 search budget changed")
    if search.get("workers_12_forbidden") is not True:
        raise PermissionError("Mechanism V2.1 worker boundary changed")

    checkpoint_owners: dict[int, str] = {}
    strict_total = 0
    for stage in config.get("stages") or ():
        indexes = tuple(int(value) for value in stage["checkpoint_indexes"])
        allocation = {
            str(arm): int(count)
            for arm, count in stage["allocation_per_checkpoint"].items()
        }
        if (
            not indexes
            or set(allocation) != set(MECHANISM_SEARCH_V21_ARMS)
            or sum(allocation.values()) != MECHANISM_SEARCH_V21_CHECKPOINT_SIZE
            or int(stage["strict_count"])
            != len(indexes) * MECHANISM_SEARCH_V21_CHECKPOINT_SIZE
        ):
            raise ValueError("Mechanism V2.1 stage allocation changed")
        for checkpoint_index in indexes:
            if checkpoint_index in checkpoint_owners:
                raise ValueError("Mechanism V2.1 checkpoint has two owners")
            checkpoint_owners[checkpoint_index] = str(stage["stage_id"])
        strict_total += int(stage["strict_count"])
    if (
        set(checkpoint_owners) != set(range(MECHANISM_SEARCH_V21_CHECKPOINT_COUNT))
        or strict_total != MECHANISM_SEARCH_V21_STRICT_TARGET
    ):
        raise ValueError("Mechanism V2.1 stages do not cover the campaign")

    evolution = dict(config["policy_parameters"]["mechanism_evolution_v2_1"])
    if not math.isclose(
        sum(
            float(evolution[key])
            for key in (
                "parameter_mutation_probability",
                "mechanism_mutation_probability",
                "crossover_probability",
            )
        ),
        1.0,
        rel_tol=0.0,
        abs_tol=1.0e-15,
    ):
        raise ValueError("Mechanism V2.1 evolution probabilities changed")
    persistence = dict(config["persistent_mechanism_knowledge"])
    if any(
        bool(persistence.get(key))
        for key in (
            "individual_candidate_reward",
            "population",
            "cem_distribution",
            "rng_state",
        )
    ):
        raise PermissionError("Mechanism V2.1 crossed campaign-local memory")
    if any(
        bool(config["boundaries"].get(key))
        for key in (
            "oos",
            "challenge",
            "recent",
            "may_stress",
            "forward",
            "promotion",
            "cross_sprint_adaptive_memory",
            "latent_priority",
            "relational_training",
        )
    ):
        raise PermissionError("Mechanism V2.1 crossed a research boundary")

    legacy_path = repo_root / str(config["legacy_catalog_path"])
    expanded_path = repo_root / str(config["catalog_path"])
    knowledge_path = repo_root / str(config["aggregate_knowledge_path"])
    if legacy_path != repo_root / MECHANISM_SEARCH_V2_CATALOG:
        raise ValueError("Mechanism V2.1 legacy catalog changed")
    if expanded_path != repo_root / MECHANISM_SEARCH_V21_CATALOG:
        raise ValueError("Mechanism V2.1 expanded catalog changed")
    if knowledge_path != repo_root / MECHANISM_SEARCH_V21_KNOWLEDGE:
        raise ValueError("Mechanism V2.1 aggregate knowledge path changed")
    legacy_catalog = compile_mechanism_catalog(_read_json(legacy_path))
    expanded_catalog = compile_mechanism_catalog(_read_json(expanded_path))
    if len(expanded_catalog) <= len(legacy_catalog):
        raise ValueError("Mechanism V2.1 did not expand the mechanism basis")
    knowledge = _read_json(knowledge_path)
    usage = dict(knowledge.get("usage_contract") or {})
    if (
        usage.get("catalog_design_and_lifecycle_only") is not True
        or any(
            bool(usage.get(key))
            for key in (
                "sampling_probability_prior",
                "candidate_or_reward_import",
                "population_or_distribution_import",
                "rng_or_policy_state_import",
                "individual_candidate_identity_persisted",
            )
        )
    ):
        raise PermissionError("Mechanism V2 aggregate knowledge crossed its boundary")
    source_manifest = _read_json(
        repo_root / "runtime/crypto_search_mechanism_v2_20260801/run_manifest.json"
    )
    source_ledger_path = str(knowledge["source_candidate_ledger"])
    source_records = [
        row
        for row in source_manifest.get("artifacts") or ()
        if str(row.get("path")) == source_ledger_path
    ]
    if (
        len(source_records) != 1
        or str(source_records[0].get("sha256"))
        != str(knowledge["source_candidate_ledger_sha256"])
    ):
        raise ValueError("Mechanism V2 aggregate knowledge source identity changed")
    return config, legacy_catalog, expanded_catalog, knowledge


