def _report_text(decision: Mapping[str, Any]) -> str:
    answers = decision["success_questions"]
    qualified = ", ".join(decision["future_new_data_arena_qualified_arms"]) or "none"
    title = str(decision.get("report_title") or "Crypto Search Engine V1")
    surface = str(
        decision.get("surface_description")
        or "Broad 39 spent-development only; Core3 excluded"
    )
    return f"""# {title}

- Status: `{decision['status']}`
- Producer source: `{decision['producer_source_sha']}`
- Surface: {surface}; sealed reads `0`.
- Strict completed: `{decision['strict_evaluated_count']:,}` from `{decision['generation_attempts']:,}` raw attempts.
- Checkpoints: `{decision['checkpoint_count']}/10`, all atomic and restore-verified.
- Behavior families: `{decision['behavior_family_count']:,}`; duplicate rate `{decision['behavior_duplicate_rate']:.2%}`.

## Required answers

1. CEM V2 compute density: **{answers['cem_v2_compute_density']}**.
2. Evolution V2 repair and behavior discovery: **{answers['evolution_v2_repair_and_behavior_discovery']}**.
3. Behavior Archive duplicate reduction: **{answers['behavior_archive_duplicate_reduction']}**.
4. Continuous checkpoint/resume: **{answers['continuous_checkpoint_resume']}**.
5. Future new-data Arena qualification: **{qualified}**.

No Alpha, fresh economic, OOS, challenge, recent, May-stress, forward, relational,
latent-priority, promotion, or cross-sprint-memory conclusion is created by this run.
"""


def _top_decile_mean(values: Sequence[float]) -> float | None:
    finite = [float(value) for value in values if math.isfinite(float(value))]
    if not finite:
        return None
    count = max(1, int(math.ceil(0.10 * len(finite))))
    return float(np.mean(sorted(finite, reverse=True)[:count]))


def _validation_blocked_decision(
    *,
    source_sha: str,
    state: Mapping[str, Any],
    ledger: Sequence[Mapping[str, Any]],
    archive: BehaviorArchive,
    checkpoint: Path,
    failure: Mapping[str, Any],
    campaign: str,
    closure_source_sha: str | None = None,
) -> dict[str, Any]:
    economic_config = _economic_campaign_config(campaign)
    strict_count = len(ledger)
    family_count = len(archive.champion_by_family)
    return {
        "schema_version": 1,
        "status": "ENGINE_VALIDATION_BLOCKED",
        "reason": str(failure["reason"]),
        "producer_source_sha": str(source_sha),
        "closure_source_sha": str(closure_source_sha or source_sha),
        "epoch_id": economic_config["epoch_id"],
        "report_title": economic_config["report_title"],
        "search_campaign": campaign,
        "surface_description": (
            "existing 115-field OI/mark x aggTrades aligned carrier; "
            "receipt-bound Binance USD-M target"
        ),
        "strict_evaluated_count": strict_count,
        "generation_attempts": int(state["generation_attempts"]),
        "active_wall_seconds": float(
            state.get("wall_elapsed_seconds", 0.0)
        ),
        "checkpoint_count": int(state.get("next_checkpoint_index", 0)),
        "checkpoint": checkpoint.name,
        "checkpoint_restore_verified": True,
        "behavior_family_count": family_count,
        "behavior_duplicate_rate": (
            1.0 - family_count / strict_count if strict_count else 0.0
        ),
        "validation_stage": {
            "status": "BLOCKED_BEFORE_COMPLETE_EQUAL_COUNT",
            **dict(failure),
            "candidate_generation_performed": False,
            "optimizer_feedback_written": False,
            "policy_memory_written": False,
            "holdout_read": False,
        },
        "research_decision": "HOLD_ENGINE_VALIDATION_BLOCKED",
        "future_new_data_arena_qualified_arms": [],
        "alpha_claim": False,
        "oos": False,
        "promotion": False,
        "next_arena_started": False,
        "parameters_changed": False,
        "seed_changed": False,
        "rescue_rerun_started": False,
        "sealed_reads": 0,
    }


def _block_robust_gate_summary(
    *,
    ledger: pd.DataFrame,
    state: Mapping[str, Any],
    config: Mapping[str, Any],
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    if len(ledger) != BLOCK_ROBUST_GATE_STRICT_TARGET:
        raise RuntimeError("block-robust gate strict count is incomplete")
    frame = ledger.copy()
    if frame["block_robust_ordering_json"].isna().any():
        raise RuntimeError("block-robust ordering provenance is incomplete")
    frame["mechanism_template"] = frame["candidate_spec_json"].map(
        lambda payload: str(
            CandidateSpec.from_dict(json.loads(str(payload))).generation_genes[
                "mechanism_spec"
            ]["template_id"]
        )
    )
    arm_rows: dict[str, dict[str, Any]] = {}
    for arm in BLOCK_ROBUST_GATE_ARMS:
        local = frame.loc[frame["arm"].astype(str) == arm]
        counter = dict(state["arm_counters"][arm])
        process_cpu_seconds = float(counter["cpu_seconds"])
        attempts = int(counter["generation_attempts"])
        replicated = int(local["replicated_candidate"].fillna(False).astype(bool).sum())
        arm_rows[arm] = {
            "strict_evaluated_count": int(len(local)),
            "generation_attempts": attempts,
            "strict_raw_reachability": float(len(local) / max(1, attempts)),
            "behavior_family_count": int(
                local["behavior_family_id"].astype(str).nunique()
            ),
            "replicated_candidate_count": replicated,
            "all_three_blocks_positive_count": int(
                local["all_three_blocks_positive"].fillna(False).astype(bool).sum()
            ),
            "replicated_candidate_rate": float(replicated / max(1, len(local))),
            "total_process_cpu_seconds": process_cpu_seconds,
            "replicated_candidates_per_process_cpu_hour": float(
                replicated * 3600.0 / max(process_cpu_seconds, 1.0e-12)
            ),
        }

    template_rows: list[dict[str, Any]] = []
    for template in sorted(frame["mechanism_template"].unique()):
        for arm in BLOCK_ROBUST_GATE_ARMS:
            local = frame.loc[
                frame["arm"].astype(str).eq(arm)
                & frame["mechanism_template"].eq(template)
            ]
            replicated = int(
                local["replicated_candidate"].fillna(False).astype(bool).sum()
            )
            template_rows.append(
                {
                    "mechanism_template": str(template),
                    "arm": arm,
                    "strict_evaluated_count": int(len(local)),
                    "replicated_candidate_count": replicated,
                    "replicated_candidate_rate": float(
                        replicated / max(1, len(local))
                    ),
                }
            )
    template_frame = pd.DataFrame(template_rows)
    current_arm = BLOCK_ROBUST_GATE_ARMS[1]
    robust_arm = BLOCK_ROBUST_GATE_ARMS[2]
    minimum = int(config["qualification"]["minimum_candidates_per_arm_template"])
    supported_positive: list[str] = []
    for template in sorted(frame["mechanism_template"].unique()):
        current = template_frame.loc[
            template_frame["mechanism_template"].eq(template)
            & template_frame["arm"].eq(current_arm)
        ].iloc[0]
        robust = template_frame.loc[
            template_frame["mechanism_template"].eq(template)
            & template_frame["arm"].eq(robust_arm)
        ].iloc[0]
        if (
            int(current["strict_evaluated_count"]) >= minimum
            and int(robust["strict_evaluated_count"]) >= minimum
            and float(robust["replicated_candidate_rate"])
            > float(current["replicated_candidate_rate"])
        ):
            supported_positive.append(str(template))
    robust_template = template_frame.loc[template_frame["arm"].eq(robust_arm)]
    best_template = str(
        robust_template.sort_values(
            ["replicated_candidate_count", "mechanism_template"],
            ascending=[False, True],
            kind="mergesort",
        ).iloc[0]["mechanism_template"]
    )

    def leave_out_rate(arm: str) -> float:
        local = frame.loc[
            frame["arm"].astype(str).eq(arm)
            & ~frame["mechanism_template"].eq(best_template)
        ]
        return float(
            local["replicated_candidate"].fillna(False).astype(bool).sum()
            / max(1, len(local))
        )

    current = arm_rows[current_arm]
    robust = arm_rows[robust_arm]
    gate_checks = {
        "equal_strict_count": (
            int(current["strict_evaluated_count"])
            == int(robust["strict_evaluated_count"])
            == 512
        ),
        "replicated_count_strictly_above_current": int(
            robust["replicated_candidate_count"]
        )
        > int(current["replicated_candidate_count"]),
        "replicated_cpu_productivity_strictly_above_current": float(
            robust["replicated_candidates_per_process_cpu_hour"]
        )
        > float(current["replicated_candidates_per_process_cpu_hour"]),
        "behavior_family_floor": int(robust["behavior_family_count"])
        >= 0.9 * int(current["behavior_family_count"]),
        "strict_raw_reachability_floor": float(robust["strict_raw_reachability"])
        >= 0.9 * float(current["strict_raw_reachability"]),
        "template_breadth": len(supported_positive) >= 2,
        "leave_best_template_out_delta_positive": leave_out_rate(robust_arm)
        > leave_out_rate(current_arm),
    }
    qualified = all(gate_checks.values())
    summary = {
        "schema_version": 1,
        "status": (
            "QUALIFIED_FOR_SEPARATELY_AUTHORIZED_SMALL_DEVELOPMENT_VALIDATION"
            if qualified
            else "NOT_QUALIFIED_FOR_VALIDATION"
        ),
        "authority": "CRYPTO_REPLICATION_AWARE_SEARCH_GATE_V1",
        "development_only": True,
        "validation_read": False,
        "oos_read": False,
        "arms": arm_rows,
        "gate_checks": gate_checks,
        "supported_templates_with_positive_delta": supported_positive,
        "best_robust_template_removed": best_template,
        "leave_best_template_out_rates": {
            current_arm: leave_out_rate(current_arm),
            robust_arm: leave_out_rate(robust_arm),
        },
        "automatic_continuation": False,
        "alpha_claim": False,
    }
    return {**summary, "summary_sha256": _payload_sha(summary)}, template_rows


def _write_search_evidence_v1_artifacts(
    *,
    runtime_root: Path,
    ledger: Sequence[Mapping[str, Any]],
    state: Mapping[str, Any],
    economic_receipt: Mapping[str, Any],
    config: Mapping[str, Any],
    campaign: str = SEARCH_EVIDENCE_V1_CAMPAIGN,
) -> dict[str, Any]:
    """Join existing run facts into one passive, run-local evidence table."""

    failures = [dict(row) for row in state.get("search_failure_evidence", [])]
    evidence_rows: list[dict[str, Any]] = []
    for row in ledger:
        evidence_rows.append(
            {
                **dict(row),
                "proposal_status": "STRICT_EVALUATED",
                "failure_reason": None,
            }
        )
    for row in failures:
        evidence_rows.append(
            {
                **dict(row),
                "proposal_status": "CONTROL_DEGENERATE",
                "search_reward": None,
                "pair_reward": None,
                "behavior_family_id": None,
                "new_behavior_family_at_completion": False,
            }
        )
    if not evidence_rows:
        raise RuntimeError("SEARCH_EVIDENCE_V1_HAS_NO_OBSERVED_CANDIDATES")
    evidence = pd.DataFrame(evidence_rows)
    evidence = evidence.sort_values(
        ["generation_attempt_ordinal", "candidate_id"], kind="mergesort"
    ).reset_index(drop=True)
    _write_parquet(runtime_root / "search_run_evidence.parquet", evidence_rows)

    minimum = int(
        dict(config.get("evidence_contract") or {}).get(
            "minimum_comparable_candidates_per_reported_stratum", 30
        )
    )
    exposure_rows: list[dict[str, Any]] = []
    for dimensions in (
        ("arm",),
        ("arm", "mechanism_family"),
        ("arm", "declared_axis_count"),
        ("arm", "mapping_family"),
        ("arm", "horizon_hours"),
        ("arm", "operation"),
    ):
        for keys, local in evidence.groupby(list(dimensions), dropna=False):
            if not isinstance(keys, tuple):
                keys = (keys,)
            successful = local.loc[local["strict_evaluated"].fillna(False).astype(bool)]
            positives = (
                int(successful["matched_positive"].fillna(False).astype(bool).sum())
                if "matched_positive" in successful
                else 0
            )
            families = (
                int(successful["behavior_family_id"].dropna().astype(str).nunique())
                if "behavior_family_id" in successful
                else 0
            )
            exposure_rows.append(
                {
                    "slice_dimensions": "+".join(dimensions),
                    "slice_key": "|".join(str(value) for value in keys),
                    "observed_candidate_count": int(len(local)),
                    "strict_evaluated_count": int(len(successful)),
                    "control_degenerate_count": int(
                        (local["proposal_status"] == "CONTROL_DEGENERATE").sum()
                    ),
                    "behavior_family_count": families,
                    "matched_positive_count": positives,
                    "inference_status": (
                        "OBSERVED_SUFFICIENTLY"
                        if len(local) >= minimum
                        else "NOT_OBSERVED_SUFFICIENTLY"
                    ),
                    "minimum_comparable_count": minimum,
                }
            )
    _write_parquet(runtime_root / "search_exposure_strata.parquet", exposure_rows)

    arm_funnel: dict[str, Any] = {}
    campaign_meta = _economic_campaign_config(campaign)
    for arm in tuple(campaign_meta["arms"]):
        local = evidence.loc[evidence["arm"].astype(str) == arm]
        successful = local.loc[local["strict_evaluated"].fillna(False).astype(bool)]
        counter = dict(state["arm_counters"][arm])
        arm_funnel[arm] = {
            "generation_attempts": int(counter["generation_attempts"]),
            "compile_valid": int(counter["compile_valid"]),
            "exact_unique": int(counter["exact_unique"]),
            "behavior_attributed": int(len(local)),
            "control_non_degenerate": int(len(successful)),
            "strict_evaluated": int(len(successful)),
            "behavior_family_count": int(
                successful["behavior_family_id"].dropna().astype(str).nunique()
            ),
            "matched_positive": int(
                successful["matched_positive"].fillna(False).astype(bool).sum()
            ),
            "mean_search_reward": (
                float(pd.to_numeric(successful["search_reward"]).mean())
                if len(successful)
                else None
            ),
            "control_degenerate": int(
                (local["proposal_status"] == "CONTROL_DEGENERATE").sum()
            ),
        }

    successful = evidence.loc[evidence["strict_evaluated"].fillna(False).astype(bool)]
    realization_counts = {
        str(key): int(value)
        for key, value in evidence["mechanism_realization_status"]
        .fillna("NOT_OBSERVED")
        .value_counts()
        .sort_index()
        .items()
    }
    failure_stage_counts: Counter[str] = Counter()
    comparison_for_reason = {
        "CONTROL_BEHAVIOR_EQUALS_PRIMARY": "primary_vs_left_control",
        "RIGHT_AXIS_CONTROL_BEHAVIOR_EQUALS_PRIMARY": "primary_vs_right_control",
        "INTERACTION_LEFT_CONTROL_BEHAVIOR_EQUALS_AB": (
            "ab_vs_interaction_left_control"
        ),
    }
    for row in failures:
        reason = str(row.get("failure_reason") or "UNKNOWN")
        stage = "UNKNOWN"
        try:
            provenance = json.loads(str(row["control_degeneracy_provenance_json"]))
            comparison = dict(provenance["comparisons"])[comparison_for_reason[reason]]
            stage = str(comparison.get("first_equal_stage") or "UNKNOWN")
        except (KeyError, TypeError, ValueError, json.JSONDecodeError):
            pass
        failure_stage_counts[f"{reason}:{stage}"] += 1

    summary = {
        "schema_version": 1,
        "status": "PASS_SEARCH_RUN_EVIDENCE_V1_NONEMPTY",
        "contract_id": dict(config.get("evidence_contract") or {}).get(
            "contract_id"
        ),
        "target_and_execution_contract": {
            "status": "PASS_RECEIPT_BOUND",
            "venue": economic_receipt["execution"]["venue"],
            "instrument_type": economic_receipt["execution"]["instrument_type"],
            "target_cache_identity_sha256": economic_receipt["execution"][
                "target_cache_identity_sha256"
            ],
            "cost_bps": economic_receipt["cost"]["cost_bps"],
            "validation": "NOT_AUTHORIZED",
            "oos": "NOT_AUTHORIZED",
        },
        "strict_evaluated_count": int(len(ledger)),
        "joined_strict_provenance_count": int(len(successful)),
        "behavior_attributed_proposal_count": int(len(evidence)),
        "control_degenerate_count": int(len(failures)),
        "arm_funnel": arm_funnel,
        "mechanism_realization_status_counts": realization_counts,
        "control_degeneracy_stage_counts": dict(sorted(failure_stage_counts.items())),
        "economic_waterfall": {
            "primary_gross_positive": int(
                (pd.to_numeric(successful["primary_gross_mean"], errors="coerce") > 0).sum()
            ),
            "primary_net_positive": int(
                (pd.to_numeric(successful["primary_net_mean"], errors="coerce") > 0).sum()
            ),
            "left_increment_gross_positive": int(
                (pd.to_numeric(successful["gross_mean"], errors="coerce") > 0).sum()
            ),
            "left_increment_net_positive": int(
                (pd.to_numeric(successful["net_mean"], errors="coerce") > 0).sum()
            ),
            "gross_positive_cost_sign_killed": int(
                successful["gross_positive_cost_sign_killed"]
                .fillna(False)
                .astype(bool)
                .sum()
            ),
            "turnover_killed": int(
                successful["turnover_killed"].fillna(False).astype(bool).sum()
            ),
            "matched_positive": int(
                successful["matched_positive"].fillna(False).astype(bool).sum()
            ),
        },
        "exposure_stratum_count": len(exposure_rows),
        "minimum_comparable_candidates_per_reported_stratum": minimum,
        "diagnostics_used_by_optimizer": (
            "BLOCK_ROBUST_EVOLUTION_ARM_ONLY"
            if campaign == BLOCK_ROBUST_GATE_CAMPAIGN
            else False
        ),
        "diagnostics_used_by_reward": False,
        "diagnostics_used_by_archive_identity": False,
        "historical_inference_performed": False,
        "question_scope": dict(config.get("question_scope") or {}),
        "sealed_reads": 0,
    }
    if campaign == BLOCK_ROBUST_GATE_CAMPAIGN:
        block_summary, template_rows = _block_robust_gate_summary(
            ledger=pd.DataFrame(ledger),
            state=state,
            config=config,
        )
        _write_json(runtime_root / "block_robust_gate_summary.json", block_summary)
        _write_parquet(runtime_root / "block_robust_template_metrics.parquet", template_rows)
        summary["block_robust_gate"] = block_summary
    _write_json(runtime_root / "search_run_evidence_summary.json", summary)
    return summary


def _validation_blocked_report_text(decision: Mapping[str, Any]) -> str:
    failure = dict(decision["validation_stage"])
    if failure.get("failure_stage") == "ARM_AGGREGATION":
        failure_description = (
            f"arm `{failure['arm']}` reached validation arm aggregation, but "
            f"the producer raised `{failure['exception_message']}`."
        )
    else:
        failure_description = (
            f"candidate `{failure['candidate_id']}` from arm `{failure['arm']}` "
            f"at {failure['horizon_hours']}h produced `{failure['reason']}` on "
            "the validation block."
        )
    return f"""# {decision['report_title']}

- Status: `ENGINE_VALIDATION_BLOCKED` (`{decision['reason']}`)
- Producer source: `{decision['producer_source_sha']}`
- Closure source: `{decision['closure_source_sha']}`
- Strict train candidates retained: `{decision['strict_evaluated_count']:,}` from `{decision['generation_attempts']:,}` raw attempts.
- Exact checkpoint: `{decision['checkpoint']}`; restore verified: `{decision['checkpoint_restore_verified']}`.
- Behavior families: `{decision['behavior_family_count']:,}`; duplicate rate `{decision['behavior_duplicate_rate']:.2%}`.

The frozen validation stage stopped before complete equal-count aggregation:
{failure_description} This is an engine validation-aggregation defect, not an Alpha or
carrier-information conclusion. No adaptive continuation,
seed/parameter change, rescue rerun, holdout/OOS/challenge read, promotion, or
next Arena occurred.
"""


def _validation_control_arm_stopped_report_text(
    decision: Mapping[str, Any],
) -> str:
    control = dict(
        dict(decision["validation_arm_decisions"])["canonical_typed_random"]
    )
    failed_conditions = sorted(
        key
        for key, value in dict(control.get("conditions") or {}).items()
        if value is not True
    )
    return f"""# {decision['report_title']}

- Status: `ENGINE_VALIDATION_BLOCKED` (`{decision['reason']}`)
- Producer source: `{decision['producer_source_sha']}`
- Strict train candidates retained: `{decision['strict_evaluated_count']:,}` from `{decision['generation_attempts']:,}` raw attempts.
- Exact checkpoint: `{decision['checkpoint']}`; restore verified: `{decision['checkpoint_restore_verified']}`.
- Failed typed-random conditions: `{', '.join(failed_conditions)}`.

The frozen equal-count validation stage completed, but its typed-random control
arm failed the pre-authorized economic kill-line.  Without a surviving control
arm, later adaptive-arm comparisons are undefined, so the remaining campaign
budget was not allocated.  No parameter/seed change, rescue rerun,
holdout/OOS/challenge read, promotion, or next Arena occurred.
"""


def _budget_exhausted_decision(
    *,
    decision: Mapping[str, Any],
    source_sha: str,
    state: Mapping[str, Any],
    ledger: Sequence[Mapping[str, Any]] | pd.DataFrame,
    archive: BehaviorArchive | pd.DataFrame,
    checkpoint_restore_verified: bool,
    closure_source_sha: str,
    campaign: str = ECONOMIC_SEARCH_CAMPAIGN,
) -> dict[str, Any]:
    economic_config = _economic_campaign_config(campaign)
    frame = (
        ledger.copy()
        if isinstance(ledger, pd.DataFrame)
        else pd.DataFrame(list(ledger))
    )
    archive_frame = (
        archive.copy()
        if isinstance(archive, pd.DataFrame)
        else pd.DataFrame(list(archive.rows))
    )
    counters = {
        str(arm): dict(values)
        for arm, values in dict(state.get("arm_counters") or {}).items()
    }
    arm_summaries: dict[str, dict[str, Any]] = {}
    for arm, counter in sorted(counters.items()):
        local = (
            frame[frame["arm"].eq(arm)].copy()
            if not frame.empty and "arm" in frame
            else pd.DataFrame()
        )
        search_rewards = (
            pd.to_numeric(local["search_reward"], errors="coerce")
            .dropna()
            .astype(float)
            .tolist()
            if "search_reward" in local
            else []
        )
        pair_rewards = (
            pd.to_numeric(local["pair_reward"], errors="coerce")
            .dropna()
            .astype(float)
            .tolist()
            if "pair_reward" in local
            else []
        )
        strict_count = int(counter.get("strict_evaluated", len(local)))
        cpu_seconds = float(counter.get("cpu_seconds", 0.0))
        family_count = (
            int(local["behavior_family_id"].nunique())
            if "behavior_family_id" in local
            else 0
        )
        operations = (
            {
                str(key): int(value)
                for key, value in local["operation"].value_counts().items()
            }
            if "operation" in local
            else {}
        )
        arm_summaries[arm] = {
            **{
                key: int(counter.get(key, 0))
                for key in (
                    "generation_attempts",
                    "compile_valid",
                    "exact_unique",
                    "matched_control_valid",
                    "strict_evaluated",
                )
            },
            "cpu_seconds": cpu_seconds,
            "compile_valid_rate": (
                float(counter.get("compile_valid", 0))
                / max(1, int(counter.get("generation_attempts", 0)))
            ),
            "strict_per_cpu_hour": (
                strict_count * 3600.0 / cpu_seconds if cpu_seconds > 0.0 else 0.0
            ),
            "behavior_family_count": family_count,
            "new_behavior_families_per_1k_evaluations": (
                family_count * 1000.0 / strict_count if strict_count else 0.0
            ),
            "behavior_duplicate_rate": (
                1.0 - family_count / strict_count if strict_count else 0.0
            ),
            "mean_search_reward": (
                float(np.mean(search_rewards)) if search_rewards else None
            ),
            "top_decile_search_reward": _top_decile_mean(search_rewards),
            "positive_search_reward_count": sum(
                value > 0.0 for value in search_rewards
            ),
            "mean_pair_reward": (
                float(np.mean(pair_rewards)) if pair_rewards else None
            ),
            "top_decile_pair_reward": _top_decile_mean(pair_rewards),
            "positive_pair_reward_count": sum(value > 0.0 for value in pair_rewards),
            "positive_matched_discovery_count": (
                int(local["matched_positive"].fillna(False).astype(bool).sum())
                if "matched_positive" in local
                else 0
            ),
            "cost_killed_count": (
                int(local["cost_killed"].fillna(False).astype(bool).sum())
                if "cost_killed" in local
                else 0
            ),
            "turnover_killed_count": (
                int(local["turnover_killed"].fillna(False).astype(bool).sum())
                if "turnover_killed" in local
                else 0
            ),
            "verified_operations": operations,
        }
    family_count = (
        int(archive_frame["behavior_family_id"].nunique())
        if "behavior_family_id" in archive_frame
        else 0
    )
    strict_count = len(frame)
    legacy_v1_failure = {
        "status": "PROPOSAL_LAYER_INCOMPATIBLE_ROLE_RESOLUTION",
        "observed_exception": (
            "admitted field registry cannot satisfy skeleton role: oi_change"
        ),
        "candidate_evaluations_consumed_by_diagnostic": 0,
        "remedy": (
            "reuse the already-frozen partial role map for compatible "
            "skeleton proposal and mutation"
        ),
    }
    validation_stage = dict(state.get("validation_stage") or {})
    if not validation_stage:
        validation_stage = {
            "status": "NOT_RUN_BUDGET_EXHAUSTED_BEFORE_CHECKPOINT_000",
            "candidate_generation_performed": False,
            "holdout_read": False,
        }
    terminal_diagnosis = (
        "The two fresh-state V1 controls consumed almost the entire raw-attempt "
        "budget before compilation. Their legacy proposal path re-required a "
        "complete Broad role surface after a compatible carrier-specific "
        "skeleton subset had already been frozen, and failed on the absent "
        "`oi_change` role. This is a proposal-layer defect, not evidence that "
        "the carrier lacks economic information."
        if campaign == ECONOMIC_SEARCH_CAMPAIGN
        else (
            "The independent V2 campaign reached a frozen hard budget. "
            "Completed candidates and the exact checkpoint are retained; "
            "partial arm evidence is diagnostic only and does not qualify an "
            "arm or support an Alpha claim."
        )
    )
    return {
        **dict(decision),
        "producer_source_sha": source_sha,
        "closure_source_sha": closure_source_sha,
        "epoch_id": economic_config["epoch_id"],
        "report_title": economic_config["report_title"],
        "surface_description": (
            "existing 115-field OI/mark x aggTrades aligned carrier; "
            "receipt-bound Binance USD-M target"
        ),
        "search_campaign": campaign,
        "strict_evaluated_count": strict_count,
        "checkpoint_count": int(state.get("next_checkpoint_index", 0)),
        "emergency_checkpoint_restore_verified": bool(
            checkpoint_restore_verified
        ),
        "behavior_family_count": family_count,
        "behavior_duplicate_rate": (
            1.0 - family_count / strict_count if strict_count else 0.0
        ),
        "archive_duplicate_replacements": int(
            state.get("archive_duplicate_replacements", 0)
        ),
        "positive_search_reward_count": sum(
            int(values["positive_search_reward_count"])
            for values in arm_summaries.values()
        ),
        "positive_pair_reward_count": sum(
            int(values["positive_pair_reward_count"])
            for values in arm_summaries.values()
        ),
        "positive_matched_discovery_count": sum(
            int(values["positive_matched_discovery_count"])
            for values in arm_summaries.values()
        ),
        "arm_summaries": arm_summaries,
        "failure_counts": dict(state.get("failure_counts") or {}),
        "v1_control_failure": (
            legacy_v1_failure
            if campaign == ECONOMIC_SEARCH_CAMPAIGN
            else {
                "status": "NOT_OBSERVED_AFTER_PROPOSAL_LIVENESS_REPAIR",
                "candidate_evaluations_consumed_by_diagnostic": 0,
            }
        ),
        "validation_stage": validation_stage,
        "terminal_diagnosis": terminal_diagnosis,
        "research_decision": "HOLD_INCOMPLETE_IMBALANCED_CAMPAIGN",
        "future_new_data_arena_qualified_arms": [],
        "success_questions": {
            "cem_v2_compute_density": (
                "NO_ON_PARTIAL_EQUAL_COUNT_EVIDENCE"
            ),
            "evolution_v2_repair_and_behavior_discovery": (
                "NO_BEHAVIOR_DISCOVERY_GAIN_ON_PARTIAL_EQUAL_COUNT_EVIDENCE"
            ),
            "behavior_archive_duplicate_reduction": (
                "PARTIAL_DEDUPLICATION_OBSERVED_NO_ROLLING_LEARNING_EVIDENCE"
            ),
            "continuous_checkpoint_resume": (
                "NO_2K_CHECKPOINT_REACHED_EMERGENCY_RESTORE_ONLY"
            ),
        },
        "alpha_claim": False,
        "oos": False,
        "promotion": False,
        "next_arena_started": False,
        "parameters_changed": False,
        "seed_changed": False,
        "rescue_rerun_started": False,
        "sealed_reads": 0,
    }


def _budget_exhausted_report_text(decision: Mapping[str, Any]) -> str:
    summaries = decision["arm_summaries"]
    rows = []
    for arm, values in summaries.items():
        mean_search = values["mean_search_reward"]
        top_search = values["top_decile_search_reward"]
        mean_pair = values["mean_pair_reward"]
        top_pair = values["top_decile_pair_reward"]
        rows.append(
            "| {arm} | {attempts:,} | {compiled:,} | {strict:,} | "
            "{families:,} | {search_mean} | {search_top} | "
            "{pair_mean} | {pair_top} |".format(
                arm=arm,
                attempts=values["generation_attempts"],
                compiled=values["compile_valid"],
                strict=values["strict_evaluated"],
                families=values["behavior_family_count"],
                search_mean=(
                    f"{mean_search:.6f}" if mean_search is not None else "n/a"
                ),
                search_top=(
                    f"{top_search:.6f}" if top_search is not None else "n/a"
                ),
                pair_mean=f"{mean_pair:.6f}" if mean_pair is not None else "n/a",
                pair_top=f"{top_pair:.6f}" if top_pair is not None else "n/a",
            )
        )
    return f"""# {decision['report_title']}

- Status: `{decision['status']}` (`{decision['reason']}`)
- Producer source: `{decision['producer_source_sha']}`
- Closure source: `{decision['closure_source_sha']}`
- Surface: {decision['surface_description']}; frozen cost assumption `5 bps`.
- Strict completed: `{decision['strict_evaluated_count']:,}` from `{decision['generation_attempts']:,}` raw attempts.
- Behavior families: `{decision['behavior_family_count']:,}`; duplicate rate `{decision['behavior_duplicate_rate']:.2%}`.
- Emergency checkpoint restore verified: `{decision['emergency_checkpoint_restore_verified']}`.

## Arm evidence

| Arm | Raw attempts | Compile-valid | Strict | Families | Mean search reward | Top-decile search reward | Mean pair reward | Top-decile pair reward |
|---|---:|---:|---:|---:|---:|---:|---:|---:|
{chr(10).join(rows)}

Strict `pair_reward` positives: `{decision['positive_pair_reward_count']}`;
matched-positive discoveries: `{decision['positive_matched_discovery_count']}`;
positive joint search rewards: `{decision['positive_search_reward_count']}`.
Joint search-reward positives are partial train diagnostics and do not override
the strict matched authority.

## Terminal diagnosis

{decision['terminal_diagnosis']}

Completed rolling checkpoints: `{decision['checkpoint_count']}`. OOS, promotion,
challenge, and any next Arena remain unstarted.
No seed, parameter, or rescue rerun was used.
"""


def _final_decision(
    *,
    source_sha: str,
    state: Mapping[str, Any],
    ledger: Sequence[Mapping[str, Any]],
    archive: BehaviorArchive,
    metrics: Sequence[Mapping[str, Any]],
    runtime_root: Path,
    seeds: Sequence[int] = SEEDS,
) -> dict[str, Any]:
    final_rows = {
        str(row["arm"]): row
        for row in metrics
        if int(row["checkpoint_index"]) == CHECKPOINT_COUNT - 1
    }
    random_metrics = final_rows["canonical_typed_random"]
    cem = final_rows.get("hierarchical_typed_cem_v2")
    evolution = final_rows.get("typed_evolution_v2")
    cem_density = bool(
        cem
        and float(cem["valid_exact_unique_per_cpu_hour"])
        > float(random_metrics["valid_exact_unique_per_cpu_hour"])
    )
    evolution_behavior = bool(
        evolution
        and float(evolution["new_behavior_families_per_1k_evaluations"])
        > float(random_metrics["new_behavior_families_per_1k_evaluations"])
    )
    evolution_repairs = sum(
        str(row["arm"]) == "typed_evolution_v2"
        and str(row["operation"])
        in {
            "EFFECTIVE_GENE_MUTATION_1_TO_3",
            "COMPATIBLE_SKELETON_VARIANT_MUTATION",
            "ONE_POINT_HOMOLOGOUS_GENE_BUNDLE_CROSSOVER",
        }
        and bool(row["receipt_verified"])
        for row in ledger
    )
    archive_reduced = bool(
        archive.duplicate_replacements > 0
        and sum(
            policy_record
            for policy_record in (
                1
                for row in ledger
                if str(row["arm"]) == "typed_evolution_v2"
                and int(row["family_member_count_at_completion"]) > 1
            )
        )
        > 0
    )
    checkpoints = sorted((runtime_root / "checkpoints").glob("checkpoint_[0-9][0-9][0-9]"))
    restore_verified = len(checkpoints) == CHECKPOINT_COUNT and all(
        bool(_read_json(path / "manifest.json").get("restore_verified"))
        for path in checkpoints
    )
    def not_worse(value: Any, baseline: Any) -> bool:
        return float(value) >= float(baseline) - QUALIFICATION_TOLERANCE

    def clearly_better(value: Any, baseline: Any) -> bool:
        return float(value) > float(baseline) + QUALIFICATION_TOLERANCE

    metric_by_checkpoint_arm = {
        (int(row["checkpoint_index"]), str(row["arm"])): row
        for row in metrics
        if str(row["arm"]) != "__campaign__"
    }
    qualification_evidence: dict[str, Any] = {}
    qualified = ["canonical_typed_random"]
    for arm, arm_metrics in (
        ("hierarchical_typed_cem_v2", cem),
        ("typed_evolution_v2", evolution),
    ):
        if arm_metrics is None or state["arm_states"].get(arm) != "ACTIVE":
            continue
        checkpoint_gates: list[dict[str, Any]] = []
        for checkpoint_index in range(
            max(1, CHECKPOINT_COUNT - 2), CHECKPOINT_COUNT
        ):
            local = metric_by_checkpoint_arm.get((checkpoint_index, arm))
            random_local = metric_by_checkpoint_arm.get(
                (checkpoint_index, "canonical_typed_random")
            )
            if local is None or random_local is None:
                continue
            reward_not_worse = all(
                not_worse(local[name], random_local[name])
                for name in (
                    "mean_search_reward_at_matched_count",
                    "top_decile_search_reward_at_matched_count",
                )
            )
            productivity_better = any(
                clearly_better(local[name], random_local[name])
                for name in (
                    "valid_exact_unique_per_cpu_hour",
                    "new_behavior_families_per_1k_evaluations",
                )
            )
            checkpoint_gates.append(
                {
                    "checkpoint_index": checkpoint_index,
                    "reward_not_worse": reward_not_worse,
                    "productivity_better": productivity_better,
                    "pass": reward_not_worse and productivity_better,
                }
            )

        seed_gates: dict[str, Any] = {}
        for seed in seeds:
            arm_rows = [
                row
                for row in ledger
                if str(row["arm"]) == arm and int(row["seed"]) == seed
            ]
            random_rows = [
                row
                for row in ledger
                if str(row["arm"]) == "canonical_typed_random"
                and int(row["seed"]) == seed
            ]
            matched_count = min(len(arm_rows), len(random_rows))
            arm_mean, arm_top = _reward_at_equal_count(
                arm_rows,
                matched_count,
                reward_field="search_reward",
            )
            random_mean, random_top = _reward_at_equal_count(
                random_rows,
                matched_count,
                reward_field="search_reward",
            )
            seed_pass = bool(
                matched_count > 0
                and arm_mean is not None
                and arm_top is not None
                and random_mean is not None
                and random_top is not None
                and not_worse(arm_mean, random_mean)
                and not_worse(arm_top, random_top)
            )
            seed_gates[str(seed)] = {
                "matched_count": matched_count,
                "mean_search_reward_not_worse": (
                    seed_pass
                    if arm_mean is None or random_mean is None
                    else not_worse(arm_mean, random_mean)
                ),
                "top_decile_search_reward_not_worse": (
                    seed_pass
                    if arm_top is None or random_top is None
                    else not_worse(arm_top, random_top)
                ),
                "pass": seed_pass,
            }

        duplicate_gate = (
            float(arm_metrics["behavior_duplicate_rate"])
            <= QUALIFICATION_DUPLICATE_RATE_MAXIMUM + QUALIFICATION_TOLERANCE
        )
        consecutive_gate = (
            len(checkpoint_gates) == 2
            and all(bool(row["pass"]) for row in checkpoint_gates)
        )
        cross_seed_gate = len(seed_gates) == len(seeds) and all(
            bool(row["pass"]) for row in seed_gates.values()
        )
        arm_pass = duplicate_gate and consecutive_gate and cross_seed_gate
        qualification_evidence[arm] = {
            "engineering_execution_qualified": True,
            "search_strategy_qualified": arm_pass,
            "frozen_tolerance": QUALIFICATION_TOLERANCE,
            "behavior_duplicate_rate_maximum": QUALIFICATION_DUPLICATE_RATE_MAXIMUM,
            "behavior_duplicate_rate_pass": duplicate_gate,
            "checkpoint_gates": checkpoint_gates,
            "seed_gates": seed_gates,
        }
        if arm_pass:
            qualified.append(arm)
    duplicate_rate = 1.0 - len(archive.champion_by_family) / max(1, len(ledger))
    archive_qualified = bool(
        archive_reduced
        and restore_verified
        and duplicate_rate
        <= QUALIFICATION_DUPLICATE_RATE_MAXIMUM + QUALIFICATION_TOLERANCE
    )
    return {
        "schema_version": 1,
        "epoch_id": EPOCH_ID,
        "status": "PASS" if len(ledger) == STRICT_TARGET else "HOLD_RESEARCH",
        "producer_source_sha": source_sha,
        "strict_evaluated_count": len(ledger),
        "generation_attempts": int(state["generation_attempts"]),
        "raw_attempt_limit": RAW_ATTEMPT_LIMIT,
        "active_wall_seconds": float(state["wall_elapsed_seconds"]),
        "wall_time_limit_seconds": WALL_TIME_LIMIT_SECONDS,
        "checkpoint_count": len(checkpoints),
        "behavior_family_count": len(archive.champion_by_family),
        "behavior_duplicate_rate": duplicate_rate,
        "archive_duplicate_replacements": archive.duplicate_replacements,
        "arm_states": dict(state["arm_states"]),
        "engineering_execution_qualified_arms": list(ROLLING_ARMS),
        "search_strategy_qualification_evidence": qualification_evidence,
        "per_run_behavior_archive_engineering_qualified": archive_qualified,
        "future_new_data_arena_qualified_arms": qualified,
        "future_new_data_arena_qualified_components": [
            *qualified,
            *(["per_run_behavior_archive"] if archive_qualified else []),
        ],
        "success_questions": {
            "cem_v2_compute_density": (
                "YES" if cem_density else "NO_NOT_DEMONSTRATED"
            ),
            "evolution_v2_repair_and_behavior_discovery": (
                "YES"
                if evolution_repairs > 0 and evolution_behavior
                else "PARTIAL_REPAIRS_VERIFIED_DISCOVERY_INCREMENT_NOT_DEMONSTRATED"
                if evolution_repairs > 0
                else "NO_NOT_DEMONSTRATED"
            ),
            "behavior_archive_duplicate_reduction": (
                "YES" if archive_reduced else "NO_DUPLICATE_REDUCTION_NOT_DEMONSTRATED"
            ),
            "continuous_checkpoint_resume": (
                "YES_EXACT_RESTORE_VERIFIED"
                if restore_verified
                else "NO_RESTORE_PROOF_INCOMPLETE"
            ),
        },
        "latent_status": "LATENT_SEARCH_PRIORITY_MODEL_DEFERRED_TO_V1_1",
        "relational_status": "STAGE1_CLOSED",
        "sealed_reads": 0,
        "promotion": "FORBIDDEN",
        "next_arena_started": False,
        "cannot_conclude": [
            "new or fresh economic increment",
            "Alpha discovery",
            "OOS validity",
            "challenge, recent, May-stress, or forward evidence",
            "promotion readiness",
            "latent or relational search priority",
        ],
    }


def _mechanism_v21_train_gate(
    *,
    repo_root: Path,
    ledger: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    config, _, _, _ = _load_mechanism_v21_contract(repo_root)
    contract = dict(config["train_gate"])

    def ordered(arm: str) -> list[Mapping[str, Any]]:
        return sorted(
            (row for row in ledger if str(row["arm"]) == arm),
            key=lambda row: (
                int(row["arm_completion_ordinal"]),
                str(row["candidate_id"]),
            ),
        )

    count = int(contract["same_matched_evaluated_count"])
    random_rows = ordered("expanded_mechanism_random_v2_1")[:count]
    evolution_rows = ordered("mechanism_evolution_v2_1")[:count]
    if len(random_rows) != count or len(evolution_rows) != count:
        raise ValueError("Mechanism V2.1 train gate lacks equal-count rows")

    def metrics(rows: Sequence[Mapping[str, Any]]) -> dict[str, Any]:
        rewards = [float(row["search_reward"]) for row in rows]
        families = {str(row["behavior_family_id"]) for row in rows}
        positive_count = sum(value > 0.0 for value in rewards)
        yield_rate = len(families) / len(rows)
        return {
            "matched_evaluated_count": len(rows),
            "mean_search_reward": float(np.mean(rewards)),
            "top_decile_search_reward": _top_decile_mean(rewards),
            "positive_search_reward_count": positive_count,
            "positive_search_reward_rate": positive_count / len(rows),
            "behavior_family_count": len(families),
            "behavior_family_yield": yield_rate,
            "behavior_duplicate_rate": 1.0 - yield_rate,
        }

    random_metrics = metrics(random_rows)
    evolution_metrics = metrics(evolution_rows)
    checks = {
        "expanded_positive_count": (
            random_metrics["positive_search_reward_count"]
            >= int(contract["minimum_expanded_positive_search_reward_count"])
        ),
        "expanded_positive_rate": (
            random_metrics["positive_search_reward_rate"]
            >= float(contract["minimum_expanded_positive_search_reward_rate"])
        ),
        "evolution_mean_reward_increment": (
            evolution_metrics["mean_search_reward"]
            > random_metrics["mean_search_reward"]
        ),
        "evolution_top_decile_increment": (
            evolution_metrics["top_decile_search_reward"]
            > random_metrics["top_decile_search_reward"]
        ),
        "evolution_positive_rate_increment": (
            evolution_metrics["positive_search_reward_rate"]
            > random_metrics["positive_search_reward_rate"]
        ),
        "evolution_behavior_family_yield": (
            evolution_metrics["behavior_family_yield"]
            >= float(contract["minimum_evolution_behavior_family_yield"])
        ),
        "evolution_duplicate_rate": (
            evolution_metrics["behavior_duplicate_rate"]
            <= float(contract["maximum_evolution_behavior_duplicate_rate"])
        ),
    }
    return {
        "schema_version": 1,
        "status": "PASS" if all(checks.values()) else "TRAIN_GATE_NEGATIVE",
        "contract": contract,
        "expanded_random": random_metrics,
        "evolution": evolution_metrics,
        "checks": checks,
        "validation_authorized_by_gate": all(checks.values()),
        "threshold_tuning_performed": False,
        "candidate_generation_performed": False,
        "sealed_reads": 0,
    }


def _mechanism_v22_train_gate(
    *,
    repo_root: Path,
    ledger: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    config, _, _ = _load_mechanism_v22_contract(repo_root)
    contract = dict(config["train_gate"])

    def ordered(arm: str) -> list[Mapping[str, Any]]:
        return sorted(
            (row for row in ledger if str(row["arm"]) == arm),
            key=lambda row: (
                int(row["arm_completion_ordinal"]),
                str(row["candidate_id"]),
            ),
        )

    count = int(contract["same_matched_evaluated_count"])
    random_rows = ordered("expanded_mechanism_random_v2_2")[:count]
    evolution_rows = ordered("mechanism_evolution_v2_2")[:count]
    if len(random_rows) != count or len(evolution_rows) != count:
        raise ValueError("Mechanism V2.2 train gate lacks equal-count rows")

    def metrics(rows: Sequence[Mapping[str, Any]]) -> dict[str, Any]:
        rewards = [float(row["search_reward"]) for row in rows]
        families = {str(row["behavior_family_id"]) for row in rows}
        positive_count = sum(value > 0.0 for value in rewards)
        yield_rate = len(families) / len(rows)
        return {
            "matched_evaluated_count": len(rows),
            "mean_search_reward": float(np.mean(rewards)),
            "top_decile_search_reward": _top_decile_mean(rewards),
            "positive_search_reward_count": positive_count,
            "positive_search_reward_rate": positive_count / len(rows),
            "behavior_family_count": len(families),
            "behavior_family_yield": yield_rate,
            "behavior_duplicate_rate": 1.0 - yield_rate,
        }

    random_metrics = metrics(random_rows)
    evolution_metrics = metrics(evolution_rows)
    checks = {
        "evolution_positive_count": (
            evolution_metrics["positive_search_reward_count"]
            >= int(contract["minimum_evolution_positive_search_reward_count"])
        ),
        "evolution_positive_rate": (
            evolution_metrics["positive_search_reward_rate"]
            >= float(contract["minimum_evolution_positive_search_reward_rate"])
        ),
        "evolution_mean_reward_increment": (
            evolution_metrics["mean_search_reward"]
            > random_metrics["mean_search_reward"]
        ),
        "evolution_top_decile_increment": (
            evolution_metrics["top_decile_search_reward"]
            > random_metrics["top_decile_search_reward"]
        ),
        "evolution_positive_rate_increment": (
            evolution_metrics["positive_search_reward_rate"]
            > random_metrics["positive_search_reward_rate"]
        ),
        "evolution_behavior_family_yield": (
            evolution_metrics["behavior_family_yield"]
            >= float(contract["minimum_evolution_behavior_family_yield"])
        ),
        "evolution_duplicate_rate": (
            evolution_metrics["behavior_duplicate_rate"]
            <= float(contract["maximum_evolution_behavior_duplicate_rate"])
        ),
    }
    passed = all(checks.values())
    return {
        "schema_version": 1,
        "status": "PASS" if passed else "TRAIN_GATE_NEGATIVE",
        "contract": contract,
        "expanded_random": random_metrics,
        "evolution": evolution_metrics,
        "checks": checks,
        "absolute_floor_applies_to": "mechanism_evolution_v2_2",
        "random_role": "EQUAL_COUNT_COMPARATOR",
        "validation_authorized_by_gate": passed,
        "threshold_tuning_performed": False,
        "candidate_generation_performed": False,
        "sealed_reads": 0,
    }


def _mechanism_v22_validation_allows_expansion(
    validation_result: Mapping[str, Any],
) -> bool:
    if validation_result.get("status") != "VALIDATION_STAGE_COMPLETE":
        return False
    decisions = dict(validation_result.get("arm_decisions") or {})
    return all(
        bool(dict(decisions.get(arm) or {}).get("passed"))
        for arm in MECHANISM_SEARCH_V22_ARMS
    )


def _mechanism_v21_final_decision(
    *,
    repo_root: Path,
    source_sha: str,
    state: Mapping[str, Any],
    ledger: Sequence[Mapping[str, Any]],
    archive: BehaviorArchive,
    metrics: Sequence[Mapping[str, Any]],
    runtime_root: Path,
    validation_result: Mapping[str, Any],
) -> dict[str, Any]:
    config, legacy_catalog, expanded_catalog, _ = _load_mechanism_v21_contract(
        repo_root
    )
    checkpoints = sorted(
        (runtime_root / "checkpoints").glob("checkpoint_[0-9][0-9][0-9]")
    )
    restore_verified = (
        len(checkpoints) == MECHANISM_SEARCH_V21_CHECKPOINT_COUNT
        and all(
            bool(_read_json(path / "manifest.json").get("restore_verified"))
            for path in checkpoints
        )
    )
    by_arm = {
        arm: sorted(
            (row for row in ledger if str(row["arm"]) == arm),
            key=lambda row: (
                int(row["arm_completion_ordinal"]),
                str(row["candidate_id"]),
            ),
        )
        for arm in MECHANISM_SEARCH_V21_ARMS
    }

    def summary(arm: str) -> dict[str, Any]:
        rows = by_arm[arm]
        rewards = [float(row["search_reward"]) for row in rows]
        pair_rewards = [float(row["pair_reward"]) for row in rows]
        families = {str(row["behavior_family_id"]) for row in rows}
        counter = state["arm_counters"][arm]
        cpu_hours = float(counter["cpu_seconds"]) / 3600.0
        positive = sum(value > 0.0 for value in rewards)
        return {
            "generation_attempts": int(counter["generation_attempts"]),
            "strict_evaluated": len(rows),
            "valid_exact_unique_per_cpu_hour": int(counter["exact_unique"])
            / max(cpu_hours, 1.0e-12),
            "behavior_family_count": len(families),
            "behavior_family_yield": len(families) / max(1, len(rows)),
            "behavior_duplicate_rate": 1.0 - len(families) / max(1, len(rows)),
            "mean_search_reward": float(np.mean(rewards)) if rewards else None,
            "top_decile_search_reward": _top_decile_mean(rewards),
            "positive_search_reward_count": positive,
            "positive_search_reward_rate": positive / max(1, len(rows)),
            "mean_pair_reward": float(np.mean(pair_rewards)) if pair_rewards else None,
            "top_decile_pair_reward": _top_decile_mean(pair_rewards),
            "cost_killed_rate": sum(bool(row["cost_killed"]) for row in rows)
            / max(1, len(rows)),
            "turnover_killed_rate": sum(
                bool(row["turnover_killed"]) for row in rows
            )
            / max(1, len(rows)),
            "verified_parameter_mutations": sum(
                str(row["operation"]) == MECHANISM_EVOLUTION_OPERATIONS[0]
                and bool(row["receipt_verified"])
                for row in rows
            ),
            "verified_mechanism_mutations": sum(
                str(row["operation"]) == MECHANISM_EVOLUTION_OPERATIONS[1]
                and bool(row["receipt_verified"])
                for row in rows
            ),
            "verified_crossovers": sum(
                str(row["operation"]) == MECHANISM_EVOLUTION_OPERATIONS[2]
                and bool(row["receipt_verified"])
                for row in rows
            ),
        }

    arm_summaries = {arm: summary(arm) for arm in MECHANISM_SEARCH_V21_ARMS}

    def comparison(arm: str, baseline: str, count: int) -> dict[str, Any]:
        local = by_arm[arm][:count]
        control = by_arm[baseline][:count]
        local_rewards = [float(row["search_reward"]) for row in local]
        control_rewards = [float(row["search_reward"]) for row in control]
        return {
            "baseline_arm": baseline,
            "matched_evaluated_count": min(len(local), len(control)),
            "mean_search_reward_delta": float(np.mean(local_rewards))
            - float(np.mean(control_rewards)),
            "top_decile_search_reward_delta": _top_decile_mean(local_rewards)
            - _top_decile_mean(control_rewards),
            "positive_search_reward_rate_delta": sum(
                value > 0.0 for value in local_rewards
            )
            / len(local_rewards)
            - sum(value > 0.0 for value in control_rewards) / len(control_rewards),
            "behavior_family_yield_delta": (
                len({str(row["behavior_family_id"]) for row in local}) / len(local)
                - len({str(row["behavior_family_id"]) for row in control})
                / len(control)
            ),
        }

    train_gate = _read_json(runtime_root / "train_gate.json")
    validation_decisions = dict(validation_result.get("arm_decisions") or {})
    qualified = sorted(
        arm
        for arm, row in validation_decisions.items()
        if bool(dict(row).get("passed"))
    )
    return {
        "schema_version": 1,
        "epoch_id": MECHANISM_SEARCH_V21_EPOCH_ID,
        "status": (
            "PASS_SEARCH_ENGINE_V2_1_COMPLETED"
            if train_gate["validation_authorized_by_gate"]
            else "PASS_SEARCH_ENGINE_V2_1_TRAIN_GATE_NEGATIVE"
        ),
        "producer_source_sha": source_sha,
        "strict_evaluated_count": len(ledger),
        "generation_attempts": int(state["generation_attempts"]),
        "raw_attempt_limit": MECHANISM_SEARCH_V21_RAW_ATTEMPT_LIMIT,
        "active_wall_seconds": float(state["wall_elapsed_seconds"]),
        "wall_time_limit_seconds": MECHANISM_SEARCH_V21_WALL_TIME_LIMIT_SECONDS,
        "checkpoint_count": len(checkpoints),
        "checkpoint_restore_verified": restore_verified,
        "legacy_compiled_mechanism_count": len(legacy_catalog),
        "expanded_compiled_mechanism_count": len(expanded_catalog),
        "template_count": len({item.template_id for item in expanded_catalog}),
        "stage_contract": list(config["stages"]),
        "behavior_family_count": len(archive.champion_by_family),
        "behavior_duplicate_rate": 1.0
        - len(archive.champion_by_family) / max(1, len(ledger)),
        "archive_duplicate_replacements": archive.duplicate_replacements,
        "arm_summaries": arm_summaries,
        "equal_count_comparisons": {
            "expanded_basis_random_vs_old_grammar_random": comparison(
                "expanded_mechanism_random_v2_1",
                "legacy_mechanism_random_v2",
                2_000,
            ),
            "evolution_vs_expanded_basis_random": comparison(
                "mechanism_evolution_v2_1",
                "expanded_mechanism_random_v2_1",
                4_000,
            ),
        },
        "train_gate": train_gate,
        "validation_status": validation_result.get("status"),
        "future_development_data_arena_qualified_arms": qualified,
        "future_new_data_arena_qualified_arms": qualified,
        "research_decision": "HOLD_DEVELOPMENT_ONLY_NO_PROMOTION",
        "alpha_claim": False,
        "oos": False,
        "promotion": "FORBIDDEN",
        "next_arena_started": False,
        "parameters_changed": False,
        "seed_changed": False,
        "rescue_rerun_started": False,
        "sealed_reads": 0,
    }


def _mechanism_v21_report_text(decision: Mapping[str, Any]) -> str:
    arm_rows = []
    for arm, values in decision["arm_summaries"].items():
        arm_rows.append(
            "| {arm} | {strict:,} | {families:,} | {duplicate:.2%} | "
            "{mean:.6f} | {top:.6f} | {positive:.2%} |".format(
                arm=arm,
                strict=int(values["strict_evaluated"]),
                families=int(values["behavior_family_count"]),
                duplicate=float(values["behavior_duplicate_rate"]),
                mean=float(values["mean_search_reward"]),
                top=float(values["top_decile_search_reward"]),
                positive=float(values["positive_search_reward_rate"]),
            )
        )
    qualified = ", ".join(
        decision["future_development_data_arena_qualified_arms"]
    ) or "none"
    return f"""# Crypto Search Engine V2.1 Mechanism Basis

- Status: `{decision['status']}`; development-only; sealed reads `0`.
- Producer source: `{decision['producer_source_sha']}`.
- Strict completed: `{decision['strict_evaluated_count']:,}` from `{decision['generation_attempts']:,}` raw attempts.
- Catalog: `{decision['legacy_compiled_mechanism_count']}` legacy and `{decision['expanded_compiled_mechanism_count']}` expanded mechanisms through the existing AST/compiler/evaluator.
- Checkpoints: `{decision['checkpoint_count']}/5`; exact restore: `{decision['checkpoint_restore_verified']}`.
- Train gate: `{decision['train_gate']['status']}`; terminal validation: `{decision['validation_status']}`.

| Arm | Strict | Families | Duplicate | Mean search reward | Top-decile | Positive search reward |
|---|---:|---:|---:|---:|---:|---:|
{chr(10).join(arm_rows)}

Validation-qualified arms: **{qualified}**. This run does not create an Alpha,
OOS, challenge, recent, May-stress, forward, or promotion claim and starts no
subsequent Arena.
"""


def _mechanism_v23_final_decision(
    *,
    repo_root: Path,
    source_sha: str,
    state: Mapping[str, Any],
    ledger: Sequence[Mapping[str, Any]],
    archive: BehaviorArchive,
    runtime_root: Path,
    validation_result: Mapping[str, Any],
) -> dict[str, Any]:
    config, catalog, _ = _load_mechanism_v23_contract(repo_root)
    checkpoints = sorted(
        (runtime_root / "checkpoints").glob("checkpoint_[0-9][0-9][0-9]")
    )
    restore_verified = all(
        bool(_read_json(path / "manifest.json").get("restore_verified"))
        for path in checkpoints
    )
    full_policy_pass = bool(validation_result.get("full_evolution_policy_pass"))
    if full_policy_pass and len(ledger) == MECHANISM_SEARCH_V23_STRICT_TARGET:
        status = (
            "PASS_SEARCH_ENGINE_V2_3_POLICY_ATTRIBUTION_AND_"
            "CONTINUATION_COMPLETE"
        )
        reason = "FULL_POLICY_GATE_PASSED_AND_FROZEN_CONTINUATION_COMPLETE"
    elif not full_policy_pass and len(ledger) == (
        MECHANISM_SEARCH_V23_QUALIFICATION_STRICT_COUNT
    ):
        status = "PASS_SEARCH_ENGINE_V2_3_POLICY_ATTRIBUTION_GATE_NEGATIVE"
        reason = "FULL_POLICY_ATTRIBUTION_GATE_NEGATIVE"
    else:
        raise RuntimeError("Mechanism V2.3 terminal state is incomplete")
    by_arm = {
        arm: [row for row in ledger if str(row["arm"]) == arm]
        for arm in MECHANISM_SEARCH_V23_ARMS
    }

    def summary(arm: str) -> dict[str, Any]:
        rows = by_arm[arm]
        rewards = [float(row["search_reward"]) for row in rows]
        families = {str(row["behavior_family_id"]) for row in rows}
        counter = state["arm_counters"][arm]
        cpu_hours = float(counter["cpu_seconds"]) / 3600.0
        return {
            "generation_attempts": int(counter["generation_attempts"]),
            "strict_evaluated": len(rows),
            "valid_exact_unique_per_cpu_hour": int(counter["exact_unique"])
            / max(cpu_hours, 1.0e-12),
            "behavior_family_count": len(families),
            "behavior_family_yield": len(families) / max(1, len(rows)),
            "behavior_duplicate_rate": 1.0 - len(families) / max(1, len(rows)),
            "mean_search_reward": float(np.mean(rewards)) if rewards else None,
            "top_decile_search_reward": _top_decile_mean(rewards),
            "positive_search_reward_count": sum(value > 0.0 for value in rewards),
            "positive_search_reward_rate": sum(value > 0.0 for value in rewards)
            / max(1, len(rows)),
        }

    component_pass = dict(validation_result.get("component_pass") or {})
    qualified = ["mechanism_evolution_v2_3"] if full_policy_pass else []
    return {
        "schema_version": 1,
        "epoch_id": MECHANISM_SEARCH_V23_EPOCH_ID,
        "status": status,
        "reason": reason,
        "producer_source_sha": source_sha,
        "strict_evaluated_count": len(ledger),
        "generation_attempts": int(state["generation_attempts"]),
        "raw_attempt_limit": MECHANISM_SEARCH_V23_RAW_ATTEMPT_LIMIT,
        "active_wall_seconds": float(state["wall_elapsed_seconds"]),
        "wall_time_limit_seconds": MECHANISM_SEARCH_V23_WALL_TIME_LIMIT_SECONDS,
        "checkpoint_count": len(checkpoints),
        "checkpoint_restore_verified": restore_verified,
        "compiled_mechanism_count": len(catalog),
        "template_count": len({item.template_id for item in catalog}),
        "stage_contract": list(config["stages"]),
        "behavior_family_count": len(archive.champion_by_family),
        "behavior_duplicate_rate": 1.0
        - len(archive.champion_by_family) / max(1, len(ledger)),
        "archive_duplicate_replacements": archive.duplicate_replacements,
        "arm_summaries": {arm: summary(arm) for arm in MECHANISM_SEARCH_V23_ARMS},
        "validation_status": validation_result.get("status"),
        "validation_candidate_cohort_evaluated_count": validation_result.get(
            "strict_candidate_cohort_evaluated_count"
        ),
        "proposal_distribution_qualified": bool(
            component_pass.get("proposal_distribution")
        ),
        "train_ranker_qualified": bool(component_pass.get("train_ranker")),
        "total_policy_relative_qualified": bool(
            component_pass.get("total_policy")
        ),
        "absolute_evolution_top_passed": bool(
            validation_result.get("absolute_evolution_top_passed")
        ),
        "full_evolution_policy_pass": full_policy_pass,
        "validation_allows_continuous_expansion": full_policy_pass,
        "future_development_data_arena_qualified_arms": qualified,
        "future_new_data_arena_qualified_arms": qualified,
        "research_decision": "HOLD_DEVELOPMENT_ONLY_NO_PROMOTION",
        "alpha_claim": False,
        "oos": False,
        "promotion": "FORBIDDEN",
        "next_arena_started": False,
        "parameters_changed": False,
        "seed_changed": False,
        "rescue_rerun_started": False,
        "sealed_reads": 0,
    }


def _search_evidence_v1_final_decision(
    *,
    repo_root: Path,
    source_sha: str,
    state: Mapping[str, Any],
    ledger: Sequence[Mapping[str, Any]],
    archive: BehaviorArchive,
    runtime_root: Path,
    evidence_summary: Mapping[str, Any],
    campaign: str = SEARCH_EVIDENCE_V1_CAMPAIGN,
) -> dict[str, Any]:
    campaign_meta = _economic_campaign_config(campaign)
    config, catalog, _ = _load_search_evidence_v1_contract(
        repo_root, campaign=campaign
    )
    checkpoints = sorted(
        (runtime_root / "checkpoints").glob("checkpoint_[0-9][0-9][0-9]")
    )
    if len(ledger) != int(campaign_meta["strict_target"]):
        raise RuntimeError("Search Evidence V1 terminal strict count is incomplete")
    joined_strict_count = int(
        evidence_summary.get("joined_strict_provenance_count", -1)
    )
    if (
        campaign in {SEARCH_EVIDENCE_V11_CAMPAIGN, BLOCK_ROBUST_GATE_CAMPAIGN}
        and joined_strict_count != len(ledger)
    ):
        raise RuntimeError(
            "Search Evidence V1.1 strict provenance join is incomplete"
        )
    block_gate = dict(evidence_summary.get("block_robust_gate") or {})
    block_qualified = block_gate.get("status") == (
        "QUALIFIED_FOR_SEPARATELY_AUTHORIZED_SMALL_DEVELOPMENT_VALIDATION"
    )
    return {
        "schema_version": 1,
        "epoch_id": campaign_meta["epoch_id"],
        "status": campaign_meta["decision_status"],
        "reason": (
            "FRESH_DEVELOPMENT_BLOCK_ROBUST_POLICY_COMPARISON_COMPLETE"
            if campaign == BLOCK_ROBUST_GATE_CAMPAIGN
            else "FRESH_DEVELOPMENT_SEARCH_AND_PASSIVE_EVIDENCE_JOIN_COMPLETE"
        ),
        "producer_source_sha": source_sha,
        "strict_evaluated_count": len(ledger),
        "joined_strict_provenance_count": joined_strict_count,
        "generation_attempts": int(state["generation_attempts"]),
        "raw_attempt_limit": int(campaign_meta["raw_attempt_limit"]),
        "active_wall_seconds": float(state["wall_elapsed_seconds"]),
        "wall_time_limit_seconds": int(campaign_meta["wall_time_limit_seconds"]),
        "checkpoint_count": len(checkpoints),
        "checkpoint_restore_verified": all(
            bool(_read_json(path / "manifest.json").get("restore_verified"))
            for path in checkpoints
        ),
        "compiled_mechanism_count": len(catalog),
        "template_count": len({item.template_id for item in catalog}),
        "stage_contract": list(config["stages"]),
        "behavior_family_count": len(archive.champion_by_family),
        "behavior_duplicate_rate": 1.0
        - len(archive.champion_by_family) / max(1, len(ledger)),
        "arm_summaries": dict(evidence_summary["arm_funnel"]),
        "evidence_summary": dict(evidence_summary),
        "validation_status": "NOT_AUTHORIZED",
        "future_development_data_arena_qualified_arms": (
            [BLOCK_ROBUST_GATE_ARMS[2]] if block_qualified else []
        ),
        "future_new_data_arena_qualified_arms": [],
        "research_decision": (
            block_gate.get("status")
            if campaign == BLOCK_ROBUST_GATE_CAMPAIGN
            else "EVIDENCE_COLLECTED_NO_AUTOMATIC_POLICY_CHANGE"
        ),
        "alpha_claim": False,
        "oos": False,
        "promotion": "FORBIDDEN",
        "next_arena_started": False,
        "parameters_changed": False,
        "seed_changed": False,
        "rescue_rerun_started": False,
        "sealed_reads": 0,
    }


def _search_evidence_v1_report_text(decision: Mapping[str, Any]) -> str:
    if decision.get("epoch_id") == BLOCK_ROBUST_GATE_EPOCH_ID:
        gate = dict(decision["evidence_summary"]["block_robust_gate"])
        arm_lines = []
        for arm, values in gate["arms"].items():
            arm_lines.append(
                "| {arm} | {strict:,} | {attempts:,} | {families:,} | "
                "{replicated:,} | {all_three:,} | {per_cpu:.3f} |".format(
                    arm=arm,
                    strict=int(values["strict_evaluated_count"]),
                    attempts=int(values["generation_attempts"]),
                    families=int(values["behavior_family_count"]),
                    replicated=int(values["replicated_candidate_count"]),
                    all_three=int(values["all_three_blocks_positive_count"]),
                    per_cpu=float(
                        values["replicated_candidates_per_process_cpu_hour"]
                    ),
                )
            )
        failed = [name for name, passed in gate["gate_checks"].items() if not passed]
        return f"""# Crypto Replication-Aware Search Gate V1

- Engineering status: `{decision['status']}`; research gate: `{gate['status']}`.
- Producer source: `{decision['producer_source_sha']}`.
- Development-only strict evaluations: `{decision['strict_evaluated_count']:,}` from `{decision['generation_attempts']:,}` attempts; sealed reads `0`.
- Scope: existing 115-field aligned carrier, 4h binary mechanisms, Binance USD-M target, existing mapping, matched controls and frozen 5 bps cost.
- Checkpoints: `{decision['checkpoint_count']}/3`; exact restore: `{decision['checkpoint_restore_verified']}`.
- Validation/OOS/promotion: `NOT_AUTHORIZED` / `NOT_AUTHORIZED` / `FORBIDDEN`.

| Arm | Strict | Attempts | Families | Replicated 2/3+ | Replicated 3/3 | Replicated / CPU-hour |
|---|---:|---:|---:|---:|---:|---:|
{chr(10).join(arm_lines)}

Gate checks that failed: `{', '.join(failed) if failed else 'none'}`.
Supported templates with positive robust-minus-current delta: `{', '.join(gate['supported_templates_with_positive_delta']) or 'none'}`.

The robust arm changes only development parent ordering. It does not change the
reward formula, target, mapping, cost, mechanism catalog, compiler, AST, or
evaluator. Passing this gate authorizes nothing automatically; any development
validation requires a separate instruction and frozen cohort.
"""
    summary = dict(decision["evidence_summary"])
    waterfall = dict(summary["economic_waterfall"])
    arm_rows = []
    for arm, values in decision["arm_summaries"].items():
        arm_rows.append(
            "| {arm} | {attempts:,} | {attributed:,} | {strict:,} | "
            "{degenerate:,} | {families:,} | {positive:,} |".format(
                arm=arm,
                attempts=int(values["generation_attempts"]),
                attributed=int(values["behavior_attributed"]),
                strict=int(values["strict_evaluated"]),
                degenerate=int(values["control_degenerate"]),
                families=int(values["behavior_family_count"]),
                positive=int(values["matched_positive"]),
            )
        )
    return f"""# {decision.get('report_title', 'Crypto Search Run Evidence Contract V1')}

- Status: `{decision['status']}`; development-only; sealed reads `0`.
- Producer source: `{decision['producer_source_sha']}`.
- Strict evaluated: `{decision['strict_evaluated_count']:,}` from `{decision['generation_attempts']:,}` raw attempts.
- Behavior-attributed proposals: `{summary['behavior_attributed_proposal_count']:,}`; control-degenerate: `{summary['control_degenerate_count']:,}`.
- Checkpoints: `{decision['checkpoint_count']}/{sum(len(stage['checkpoint_indexes']) for stage in decision['stage_contract'])}`; exact restore: `{decision['checkpoint_restore_verified']}`.
- Validation/OOS/promotion: `NOT_AUTHORIZED` / `NOT_AUTHORIZED` / `FORBIDDEN`.

| Arm | Raw attempts | Behavior attributed | Strict | Control-degenerate | Families | Matched positive |
|---|---:|---:|---:|---:|---:|---:|
{chr(10).join(arm_rows)}

## Economic waterfall

- Primary gross/net positive: `{waterfall['primary_gross_positive']}` / `{waterfall['primary_net_positive']}`.
- Left matched increment gross/net positive: `{waterfall['left_increment_gross_positive']}` / `{waterfall['left_increment_net_positive']}`.
- Cost-sign-killed / turnover-killed / strict matched-positive: `{waterfall['gross_positive_cost_sign_killed']}` / `{waterfall['turnover_killed']}` / `{waterfall['matched_positive']}`.

The evidence tables connect actual exposure, unchanged optimizer productivity,
outcome-free mechanism realization, matched increment behavior, executable
behavior, and economics. Diagnostics were not used by proposal policy, reward,
or archive identity. This run creates no Alpha, OOS, promotion, challenge,
recent, May-stress, forward, or automatic next-Arena claim.
"""


def _mechanism_v23_report_text(decision: Mapping[str, Any]) -> str:
    rows = []
    for arm, values in decision["arm_summaries"].items():
        rows.append(
            "| {arm} | {strict:,} | {families:,} | {duplicate:.2%} | "
            "{mean:.6f} | {top:.6f} | {positive:.2%} |".format(
                arm=arm,
                strict=int(values["strict_evaluated"]),
                families=int(values["behavior_family_count"]),
                duplicate=float(values["behavior_duplicate_rate"]),
                mean=float(values["mean_search_reward"]),
                top=float(values["top_decile_search_reward"]),
                positive=float(values["positive_search_reward_rate"]),
            )
        )
    return f"""# Crypto Search Engine V2.3 Policy Attribution

- Status: `{decision['status']}` (`{decision['reason']}`); development-only.
- Producer source: `{decision['producer_source_sha']}`.
- Strict train/continuation: `{decision['strict_evaluated_count']:,}` from `{decision['generation_attempts']:,}` attempts; validation candidate-cohort evaluations: `{decision['validation_candidate_cohort_evaluated_count']}`.
- Catalog: `{decision['compiled_mechanism_count']}` unchanged mechanisms; no new data, AST, compiler, evaluator, target, or cost.
- Checkpoints: `{decision['checkpoint_count']}`; exact restore: `{decision['checkpoint_restore_verified']}`.

| Arm | Strict | Families | Duplicate | Mean search reward | Top-decile | Positive search reward |
|---|---:|---:|---:|---:|---:|---:|
{chr(10).join(rows)}

Proposal distribution qualified: **{decision['proposal_distribution_qualified']}**.
Train ranker qualified: **{decision['train_ranker_qualified']}**.
Total policy relative effect qualified: **{decision['total_policy_relative_qualified']}**.
Evolution train-top absolute kill-line passed: **{decision['absolute_evolution_top_passed']}**.
Full replicated Evolution policy passed: **{decision['full_evolution_policy_pass']}**.

Random is comparator-only and has no profitability survival requirement. This
run creates no Alpha, OOS, challenge, recent, stress, forward, or promotion
claim and starts no subsequent Arena.
"""


def _mechanism_v22_final_decision(
    *,
    repo_root: Path,
    source_sha: str,
    state: Mapping[str, Any],
    ledger: Sequence[Mapping[str, Any]],
    archive: BehaviorArchive,
    runtime_root: Path,
    validation_result: Mapping[str, Any],
) -> dict[str, Any]:
    config, catalog, _ = _load_mechanism_v22_contract(repo_root)
    checkpoints = sorted(
        (runtime_root / "checkpoints").glob("checkpoint_[0-9][0-9][0-9]")
    )
    restore_verified = all(
        bool(_read_json(path / "manifest.json").get("restore_verified"))
        for path in checkpoints
    )
    train_gate = _read_json(runtime_root / "train_gate.json")
    validation_passed = _mechanism_v22_validation_allows_expansion(
        validation_result
    )
    if train_gate["validation_authorized_by_gate"] is not True:
        status = "PASS_SEARCH_ENGINE_V2_2_TRAIN_GATE_NEGATIVE"
        reason = "TRAIN_GATE_NEGATIVE"
    elif not validation_passed:
        status = "PASS_SEARCH_ENGINE_V2_2_VALIDATION_GATE_NEGATIVE"
        reason = "VALIDATION_GATE_NEGATIVE"
    elif len(ledger) == MECHANISM_SEARCH_V22_STRICT_TARGET:
        status = "PASS_SEARCH_ENGINE_V2_2_CONTINUOUS_EXPANSION_COMPLETE"
        reason = "FROZEN_STAGE_C_COMPLETE"
    else:
        raise RuntimeError("Mechanism V2.2 terminal state is incomplete")

    by_arm = {
        arm: sorted(
            (row for row in ledger if str(row["arm"]) == arm),
            key=lambda row: (
                int(row["arm_completion_ordinal"]),
                str(row["candidate_id"]),
            ),
        )
        for arm in MECHANISM_SEARCH_V22_ARMS
    }

    def summary(arm: str) -> dict[str, Any]:
        rows = by_arm[arm]
        rewards = [float(row["search_reward"]) for row in rows]
        pair_rewards = [float(row["pair_reward"]) for row in rows]
        families = {str(row["behavior_family_id"]) for row in rows}
        counter = state["arm_counters"][arm]
        cpu_hours = float(counter["cpu_seconds"]) / 3600.0
        positive = sum(value > 0.0 for value in rewards)
        return {
            "generation_attempts": int(counter["generation_attempts"]),
            "strict_evaluated": len(rows),
            "valid_exact_unique_per_cpu_hour": int(counter["exact_unique"])
            / max(cpu_hours, 1.0e-12),
            "behavior_family_count": len(families),
            "behavior_family_yield": len(families) / max(1, len(rows)),
            "behavior_duplicate_rate": 1.0 - len(families) / max(1, len(rows)),
            "mean_search_reward": float(np.mean(rewards)) if rewards else None,
            "top_decile_search_reward": _top_decile_mean(rewards),
            "positive_search_reward_count": positive,
            "positive_search_reward_rate": positive / max(1, len(rows)),
            "mean_pair_reward": float(np.mean(pair_rewards)) if pair_rewards else None,
            "top_decile_pair_reward": _top_decile_mean(pair_rewards),
            "cost_killed_rate": sum(bool(row["cost_killed"]) for row in rows)
            / max(1, len(rows)),
            "turnover_killed_rate": sum(
                bool(row["turnover_killed"]) for row in rows
            )
            / max(1, len(rows)),
            "verified_parameter_mutations": sum(
                str(row["operation"]) == MECHANISM_EVOLUTION_OPERATIONS[0]
                and bool(row["receipt_verified"])
                for row in rows
            ),
            "verified_mechanism_mutations": sum(
                str(row["operation"]) == MECHANISM_EVOLUTION_OPERATIONS[1]
                and bool(row["receipt_verified"])
                for row in rows
            ),
            "verified_crossovers": sum(
                str(row["operation"]) == MECHANISM_EVOLUTION_OPERATIONS[2]
                and bool(row["receipt_verified"])
                for row in rows
            ),
        }

    qualified = ["mechanism_evolution_v2_2"] if validation_passed else []
    return {
        "schema_version": 1,
        "epoch_id": MECHANISM_SEARCH_V22_EPOCH_ID,
        "status": status,
        "reason": reason,
        "producer_source_sha": source_sha,
        "strict_evaluated_count": len(ledger),
        "generation_attempts": int(state["generation_attempts"]),
        "raw_attempt_limit": MECHANISM_SEARCH_V22_RAW_ATTEMPT_LIMIT,
        "active_wall_seconds": float(state["wall_elapsed_seconds"]),
        "wall_time_limit_seconds": MECHANISM_SEARCH_V22_WALL_TIME_LIMIT_SECONDS,
        "checkpoint_count": len(checkpoints),
        "checkpoint_restore_verified": restore_verified,
        "compiled_mechanism_count": len(catalog),
        "template_count": len({item.template_id for item in catalog}),
        "stage_contract": list(config["stages"]),
        "behavior_family_count": len(archive.champion_by_family),
        "behavior_duplicate_rate": 1.0
        - len(archive.champion_by_family) / max(1, len(ledger)),
        "archive_duplicate_replacements": archive.duplicate_replacements,
        "arm_summaries": {
            arm: summary(arm) for arm in MECHANISM_SEARCH_V22_ARMS
        },
        "train_gate": train_gate,
        "validation_status": validation_result.get("status"),
        "validation_allows_continuous_expansion": validation_passed,
        "future_development_data_arena_qualified_arms": qualified,
        "future_new_data_arena_qualified_arms": qualified,
        "research_decision": "HOLD_DEVELOPMENT_ONLY_NO_PROMOTION",
        "alpha_claim": False,
        "oos": False,
        "promotion": "FORBIDDEN",
        "next_arena_started": False,
        "parameters_changed": False,
        "seed_changed": False,
        "rescue_rerun_started": False,
        "sealed_reads": 0,
    }


def _mechanism_v22_report_text(decision: Mapping[str, Any]) -> str:
    rows = []
    for arm, values in decision["arm_summaries"].items():
        rows.append(
            "| {arm} | {strict:,} | {families:,} | {duplicate:.2%} | "
            "{mean:.6f} | {top:.6f} | {positive:.2%} |".format(
                arm=arm,
                strict=int(values["strict_evaluated"]),
                families=int(values["behavior_family_count"]),
                duplicate=float(values["behavior_duplicate_rate"]),
                mean=float(values["mean_search_reward"]),
                top=float(values["top_decile_search_reward"]),
                positive=float(values["positive_search_reward_rate"]),
            )
        )
    qualified = ", ".join(
        decision["future_development_data_arena_qualified_arms"]
    ) or "none"
    return f"""# Crypto Search Engine V2.2 Evolution Qualification

- Status: `{decision['status']}` (`{decision['reason']}`); development-only.
- Producer source: `{decision['producer_source_sha']}`.
- Strict completed: `{decision['strict_evaluated_count']:,}` from `{decision['generation_attempts']:,}` raw attempts.
- Catalog: `{decision['compiled_mechanism_count']}` existing V2.1 mechanisms; no new AST/compiler/evaluator.
- Checkpoints: `{decision['checkpoint_count']}`; exact restore: `{decision['checkpoint_restore_verified']}`.
- Train gate: `{decision['train_gate']['status']}`; validation: `{decision['validation_status']}`.

| Arm | Strict | Families | Duplicate | Mean search reward | Top-decile | Positive search reward |
|---|---:|---:|---:|---:|---:|---:|
{chr(10).join(rows)}

Development-qualified policy arms: **{qualified}**. The random arm is the
receipt-bound validation control, not the policy being qualified. This run
creates no Alpha, OOS, challenge, recent, May-stress, forward, or promotion
claim and starts no subsequent Arena.
"""


def _mechanism_v2_final_decision(
    *,
    repo_root: Path,
    source_sha: str,
    state: Mapping[str, Any],
    ledger: Sequence[Mapping[str, Any]],
    archive: BehaviorArchive,
    metrics: Sequence[Mapping[str, Any]],
    runtime_root: Path,
    validation_result: Mapping[str, Any],
) -> dict[str, Any]:
    config, catalog = _load_mechanism_v2_contract(repo_root)
    checkpoints = sorted(
        (runtime_root / "checkpoints").glob("checkpoint_[0-9][0-9][0-9]")
    )
    restore_verified = len(checkpoints) == MECHANISM_SEARCH_V2_CHECKPOINT_COUNT and all(
        bool(_read_json(path / "manifest.json").get("restore_verified"))
        for path in checkpoints
    )
    by_arm = {
        arm: sorted(
            (row for row in ledger if str(row["arm"]) == arm),
            key=lambda row: (
                int(row["arm_completion_ordinal"]),
                str(row["candidate_id"]),
            ),
        )
        for arm in MECHANISM_SEARCH_V2_ARMS
    }
    latest_metrics: dict[str, Mapping[str, Any]] = {}
    for row in metrics:
        arm = str(row["arm"])
        if arm == "__campaign__":
            continue
        current = latest_metrics.get(arm)
        if current is None or int(row["checkpoint_index"]) > int(
            current["checkpoint_index"]
        ):
            latest_metrics[arm] = row

    def arm_summary(arm: str) -> dict[str, Any]:
        rows = by_arm[arm]
        rewards = [float(row["search_reward"]) for row in rows]
        pair_rewards = [float(row["pair_reward"]) for row in rows]
        families = {str(row["behavior_family_id"]) for row in rows}
        counter = state["arm_counters"][arm]
        cpu_hours = float(counter["cpu_seconds"]) / 3600.0
        return {
            "generation_attempts": int(counter["generation_attempts"]),
            "compile_valid": int(counter["compile_valid"]),
            "strict_evaluated": len(rows),
            "strict_per_raw_attempt": len(rows)
            / max(1, int(counter["generation_attempts"])),
            "valid_exact_unique_per_cpu_hour": int(counter["exact_unique"])
            / max(cpu_hours, 1.0e-12),
            "positive_matched_discoveries_per_cpu_hour": sum(
                bool(row["matched_positive"]) for row in rows
            )
            / max(cpu_hours, 1.0e-12),
            "new_behavior_families_per_cpu_hour": len(families)
            / max(cpu_hours, 1.0e-12),
            "new_behavior_families_per_1k_evaluations": 1000.0
            * len(families)
            / max(1, len(rows)),
            "behavior_family_count": len(families),
            "behavior_duplicate_rate": 1.0 - len(families) / max(1, len(rows)),
            "positive_matched_family_rate": len(
                {
                    str(row["behavior_family_id"])
                    for row in rows
                    if bool(row["matched_positive"])
                }
            )
            / max(1, len(families)),
            "mean_search_reward": float(np.mean(rewards)) if rewards else None,
            "top_decile_search_reward": _top_decile_mean(rewards),
            "mean_pair_reward": float(np.mean(pair_rewards)) if pair_rewards else None,
            "top_decile_pair_reward": _top_decile_mean(pair_rewards),
            "cost_killed_rate": sum(bool(row["cost_killed"]) for row in rows)
            / max(1, len(rows)),
            "turnover_killed_rate": sum(
                bool(row["turnover_killed"]) for row in rows
            )
            / max(1, len(rows)),
            "cem_entropy": json.loads(
                str(latest_metrics.get(arm, {}).get("cem_entropy_json") or "{}")
            ),
            "verified_parameter_mutations": sum(
                str(row["operation"]) == MECHANISM_EVOLUTION_OPERATIONS[0]
                and bool(row["receipt_verified"])
                for row in rows
            ),
            "verified_mechanism_mutations": sum(
                str(row["operation"]) == MECHANISM_EVOLUTION_OPERATIONS[1]
                and bool(row["receipt_verified"])
                for row in rows
            ),
            "verified_crossovers": sum(
                str(row["operation"]) == MECHANISM_EVOLUTION_OPERATIONS[2]
                and bool(row["receipt_verified"])
                for row in rows
            ),
        }

    arm_summaries = {arm: arm_summary(arm) for arm in MECHANISM_SEARCH_V2_ARMS}

    def comparison(
        arm: str, baseline: str, matched_count: int
    ) -> dict[str, Any]:
        local = by_arm[arm]
        control = by_arm[baseline]
        count = min(int(matched_count), len(local), len(control))
        local_mean, local_top = _reward_at_equal_count(
            local, count, reward_field="search_reward"
        )
        control_mean, control_top = _reward_at_equal_count(
            control, count, reward_field="search_reward"
        )
        local_pair_mean, local_pair_top = _reward_at_equal_count(
            local, count, reward_field="pair_reward"
        )
        control_pair_mean, control_pair_top = _reward_at_equal_count(
            control, count, reward_field="pair_reward"
        )
        return {
            "baseline_arm": baseline,
            "matched_evaluated_count": count,
            "mean_search_reward_delta": (
                float(local_mean) - float(control_mean)
                if local_mean is not None and control_mean is not None
                else None
            ),
            "top_decile_search_reward_delta": (
                float(local_top) - float(control_top)
                if local_top is not None and control_top is not None
                else None
            ),
            "mean_pair_reward_delta": (
                float(local_pair_mean) - float(control_pair_mean)
                if local_pair_mean is not None and control_pair_mean is not None
                else None
            ),
            "top_decile_pair_reward_delta": (
                float(local_pair_top) - float(control_pair_top)
                if local_pair_top is not None and control_pair_top is not None
                else None
            ),
            "valid_exact_unique_per_cpu_hour_delta": (
                arm_summaries[arm]["valid_exact_unique_per_cpu_hour"]
                - arm_summaries[baseline]["valid_exact_unique_per_cpu_hour"]
            ),
            "new_behavior_families_per_1k_delta": (
                arm_summaries[arm]["new_behavior_families_per_1k_evaluations"]
                - arm_summaries[baseline][
                    "new_behavior_families_per_1k_evaluations"
                ]
            ),
        }

    comparisons = {
        "expanded_random_vs_legacy_fixed_skeleton": comparison(
            "extensible_mechanism_random_v2", "canonical_typed_random", 2_000
        ),
        "mechanism_level_cem_v2_vs_expanded_random": comparison(
            "mechanism_level_cem_v2", "extensible_mechanism_random_v2", 3_000
        ),
        "mechanism_evolution_v2_vs_expanded_random": comparison(
            "mechanism_evolution_v2", "extensible_mechanism_random_v2", 3_000
        ),
    }
    validation_decisions = dict(validation_result.get("arm_decisions") or {})
    qualified_arms = sorted(
        arm
        for arm, decision in validation_decisions.items()
        if bool(dict(decision).get("passed"))
    )
    duplicate_rate = 1.0 - len(archive.champion_by_family) / max(1, len(ledger))
    return {
        "schema_version": 2,
        "epoch_id": MECHANISM_SEARCH_V2_EPOCH_ID,
        "status": (
            "PASS_SEARCH_ENGINE_V2_MECHANISM_CAMPAIGN_COMPLETED"
            if len(ledger) == MECHANISM_SEARCH_V2_STRICT_TARGET
            else "HOLD_RESEARCH"
        ),
        "producer_source_sha": source_sha,
        "strict_evaluated_count": len(ledger),
        "generation_attempts": int(state["generation_attempts"]),
        "raw_attempt_limit": MECHANISM_SEARCH_V2_RAW_ATTEMPT_LIMIT,
        "active_wall_seconds": float(state["wall_elapsed_seconds"]),
        "wall_time_limit_seconds": MECHANISM_SEARCH_V2_WALL_TIME_LIMIT_SECONDS,
        "checkpoint_count": len(checkpoints),
        "checkpoint_restore_verified": restore_verified,
        "compiled_mechanism_count": len(catalog),
        "template_count": len({item.template_id for item in catalog}),
        "mechanism_family_count": len(
            {item.template_id for item in catalog}
        ),
        "stage_contract": list(config["stages"]),
        "behavior_family_count": len(archive.champion_by_family),
        "behavior_duplicate_rate": duplicate_rate,
        "archive_duplicate_replacements": archive.duplicate_replacements,
        "arm_summaries": arm_summaries,
        "equal_count_comparisons": comparisons,
        "engineering_execution_qualified_arms": [
            arm for arm, rows in by_arm.items() if rows
        ],
        "future_development_data_arena_qualified_arms": qualified_arms,
        "future_new_data_arena_qualified_arms": qualified_arms,
        "success_questions": {
            "grammar_expansion": (
                "YES_EXISTING_TYPED_AST_EXPANDED_TO_"
                f"{len(catalog)}_DECLARATIVE_MECHANISMS"
            ),
            "expanded_random_vs_fixed_skeleton": comparisons[
                "expanded_random_vs_legacy_fixed_skeleton"
            ],
            "mechanism_cem_learnability": comparisons[
                "mechanism_level_cem_v2_vs_expanded_random"
            ],
            "mechanism_evolution_learnability": comparisons[
                "mechanism_evolution_v2_vs_expanded_random"
            ],
            "continuous_checkpoint_resume": (
                "YES_EXACT_RESTORE_VERIFIED"
                if restore_verified
                else "NO_RESTORE_PROOF_INCOMPLETE"
            ),
            "independent_validation_qualification": qualified_arms,
        },
        "research_decision": "HOLD_DEVELOPMENT_ONLY_NO_PROMOTION",
        "persistent_state_boundary": dict(
            config["persistent_mechanism_knowledge"]
        ),
        "alpha_claim": False,
        "oos": False,
        "promotion": "FORBIDDEN",
        "next_arena_started": False,
        "parameters_changed": False,
        "seed_changed": False,
        "rescue_rerun_started": False,
        "sealed_reads": 0,
    }


def _mechanism_v2_report_text(decision: Mapping[str, Any]) -> str:
    rows = []
    for arm, values in decision["arm_summaries"].items():
        rows.append(
            "| {arm} | {strict:,} | {attempts:,} | {families:,} | {dup:.2%} | "
            "{mean:.6f} | {top:.6f} | {positive:.2%} |".format(
                arm=arm,
                strict=int(values["strict_evaluated"]),
                attempts=int(values["generation_attempts"]),
                families=int(values["behavior_family_count"]),
                dup=float(values["behavior_duplicate_rate"]),
                mean=float(values["mean_search_reward"]),
                top=float(values["top_decile_search_reward"]),
                positive=float(values["positive_matched_family_rate"]),
            )
        )
    comparisons = decision["equal_count_comparisons"]
    comparison_rows = []
    for name, values in comparisons.items():
        comparison_rows.append(
            "| {name} | {count:,} | {mean:.6f} | {top:.6f} | {density:.2f} | "
            "{behavior:.2f} |".format(
                name=name,
                count=int(values["matched_evaluated_count"]),
                mean=float(values["mean_search_reward_delta"]),
                top=float(values["top_decile_search_reward_delta"]),
                density=float(values["valid_exact_unique_per_cpu_hour_delta"]),
                behavior=float(values["new_behavior_families_per_1k_delta"]),
            )
        )
    qualified = ", ".join(
        decision["future_development_data_arena_qualified_arms"]
    ) or "none"
    return f"""# Crypto Search Engine V2 Mechanism Grammar

- Status: `{decision['status']}`; development-only, sealed reads `0`.
- Producer source: `{decision['producer_source_sha']}`.
- Strict completed: `{decision['strict_evaluated_count']:,}` from `{decision['generation_attempts']:,}` raw attempts.
- Grammar: `{decision['template_count']}` templates, `{decision['compiled_mechanism_count']}` compiled typed mechanisms, reusing the existing AST/compiler/evaluator.
- Checkpoints: `{decision['checkpoint_count']}/6`; exact restore verified: `{decision['checkpoint_restore_verified']}`.
- Behavior families: `{decision['behavior_family_count']:,}`; duplicate rate `{decision['behavior_duplicate_rate']:.2%}`.

## Arm evidence

| Arm | Strict | Attempts | Families | Duplicate | Mean search reward | Top-decile | Positive family rate |
|---|---:|---:|---:|---:|---:|---:|---:|
{chr(10).join(rows)}

## Frozen comparisons

Reward deltas use the same first N completions per arm. Compute-density and
behavior-yield deltas use each arm's complete frozen allocation.

| Comparison | Equal count | Mean reward delta | Top-decile delta | Valid/CPU-hour delta | Families/1k delta |
|---|---:|---:|---:|---:|---:|
{chr(10).join(comparison_rows)}

## Decision

Independent final validation-qualified arms: **{qualified}**. Random-control
failure cannot veto another arm; each arm is judged by the same absolute frozen
kill-line. This is development qualification only, not Alpha, OOS, promotion,
challenge, recent, May-stress, or forward evidence. No next Arena was started.
"""


def _write_mechanism_v2_knowledge(
    *,
    repo_root: Path,
    runtime_root: Path,
    ledger: Sequence[Mapping[str, Any]],
    validation_result: Mapping[str, Any],
    campaign: str = MECHANISM_SEARCH_V2_CAMPAIGN,
) -> None:
    if campaign in SEARCH_EVIDENCE_CAMPAIGNS:
        _, catalog, _ = _load_search_evidence_v1_contract(
            repo_root, campaign=campaign
        )
    elif campaign == MECHANISM_SEARCH_V23_CAMPAIGN:
        _, catalog, _ = _load_mechanism_v23_contract(repo_root)
    elif campaign == MECHANISM_SEARCH_V22_CAMPAIGN:
        _, catalog, _ = _load_mechanism_v22_contract(repo_root)
    elif campaign == MECHANISM_SEARCH_V21_CAMPAIGN:
        _, _, catalog, _ = _load_mechanism_v21_contract(repo_root)
    elif campaign == MECHANISM_SEARCH_V2_CAMPAIGN:
        _, catalog = _load_mechanism_v2_contract(repo_root)
    else:
        raise ValueError("unsupported mechanism knowledge campaign")
    catalog_by_id = {item.mechanism_id: item for item in catalog}
    rows_by_mechanism: dict[str, list[Mapping[str, Any]]] = defaultdict(list)
    candidate_to_mechanism: dict[str, str] = {}
    candidate_to_arm: dict[str, str] = {}
    for row in ledger:
        candidate = CandidateSpec.from_dict(
            json.loads(str(row["candidate_spec_json"]))
        )
        spec_payload = candidate.generation_genes.get("mechanism_spec")
        if not isinstance(spec_payload, Mapping):
            continue
        mechanism_id = MechanismSpec.from_dict(spec_payload).mechanism_id
        rows_by_mechanism[mechanism_id].append(row)
        candidate_to_mechanism[str(row["candidate_id"])] = mechanism_id
        candidate_to_arm[str(row["candidate_id"])] = str(row["arm"])

    validation_by_mechanism: dict[str, list[Mapping[str, Any]]] = defaultdict(list)
    validation_path = runtime_root / "validation_candidate_ledger.parquet"
    if validation_path.is_file():
        for row in pd.read_parquet(validation_path).to_dict("records"):
            mechanism_id = candidate_to_mechanism.get(str(row["candidate_id"]))
            if mechanism_id is not None:
                validation_by_mechanism[mechanism_id].append(row)
    arm_decisions = dict(validation_result.get("arm_decisions") or {})

    knowledge_rows: list[dict[str, Any]] = []
    for mechanism_id, spec in sorted(catalog_by_id.items()):
        train_rows = rows_by_mechanism.get(mechanism_id, [])
        validation_rows = validation_by_mechanism.get(mechanism_id, [])
        evaluated_validation = [
            row
            for row in validation_rows
            if str(row.get("validation_status")) == "EVALUATED"
        ]
        rewards = [float(row["search_reward"]) for row in train_rows]
        pair_rewards = [float(row["pair_reward"]) for row in train_rows]
        arms = sorted({str(row["arm"]) for row in train_rows})
        qualified_arm_member = any(
            bool(dict(arm_decisions.get(arm) or {}).get("passed")) for arm in arms
        )
        lifecycle = (
            "TRAIN_OBSERVED_VALIDATION_OBSERVED"
            if evaluated_validation
            else "TRAIN_OBSERVED"
            if train_rows
            else "DECLARED_NOT_OBSERVED"
        )
        knowledge_rows.append(
            {
                **spec.to_dict(),
                "lifecycle_state": lifecycle,
                "train_strict_evaluated_count": len(train_rows),
                "train_behavior_family_count": len(
                    {str(row["behavior_family_id"]) for row in train_rows}
                ),
                "train_matched_positive_count": sum(
                    bool(row["matched_positive"]) for row in train_rows
                ),
                "train_mean_search_reward": (
                    float(np.mean(rewards)) if rewards else None
                ),
                "train_top_decile_search_reward": _top_decile_mean(rewards),
                "train_mean_pair_reward": (
                    float(np.mean(pair_rewards)) if pair_rewards else None
                ),
                "train_top_decile_pair_reward": _top_decile_mean(pair_rewards),
                "observed_arms_json": json.dumps(arms, separators=(",", ":")),
                "validation_evaluated_count": len(evaluated_validation),
                "validation_mean_net": (
                    float(
                        np.mean(
                            [
                                float(row["validation_primary_net_mean"])
                                for row in evaluated_validation
                            ]
                        )
                    )
                    if evaluated_validation
                    else None
                ),
                "validation_mean_matched_increment": (
                    float(
                        np.mean(
                            [
                                float(row["validation_matched_increment"])
                                for row in evaluated_validation
                            ]
                        )
                    )
                    if evaluated_validation
                    else None
                ),
                "member_of_validation_qualified_arm": qualified_arm_member,
                "individual_candidate_state_persisted": False,
                "evidence_role": "DEVELOPMENT_AGGREGATE_ONLY",
            }
        )
    _write_parquet(runtime_root / "mechanism_knowledge.parquet", knowledge_rows)
    _write_json(
        runtime_root / "mechanism_knowledge_summary.json",
        {
            "schema_version": 1,
            "catalog_sha256": _mechanism_catalog_sha(catalog),
            "declared_mechanism_count": len(catalog),
            "train_observed_mechanism_count": sum(
                int(row["train_strict_evaluated_count"] > 0)
                for row in knowledge_rows
            ),
            "validation_observed_mechanism_count": sum(
                int(row["validation_evaluated_count"] > 0)
                for row in knowledge_rows
            ),
            "individual_candidate_reward_persisted": False,
            "population_or_distribution_persisted": False,
            "knowledge_sha256": _payload_sha(knowledge_rows),
        },
    )


def _aggtrades_canary_final_decision(
    *,
    source_sha: str,
    state: Mapping[str, Any],
    ledger: Sequence[Mapping[str, Any]],
    archive: BehaviorArchive,
    metrics: Sequence[Mapping[str, Any]],
    runtime_root: Path,
) -> dict[str, Any]:
    final_rows = {
        str(row["arm"]): row
        for row in metrics
        if int(row["checkpoint_index"]) == AGGTRADES_CANARY_CHECKPOINT_COUNT - 1
    }
    random_metrics = final_rows["canonical_typed_random"]
    comparisons: dict[str, Any] = {}
    for arm in ("hierarchical_typed_cem_v2", "typed_evolution_v2"):
        local = final_rows[arm]
        comparisons[arm] = {
            "matched_evaluated_count": int(
                local["matched_reward_comparison_count"]
            ),
            "valid_exact_unique_per_cpu_hour_delta": float(
                local["valid_exact_unique_per_cpu_hour"]
            )
            - float(random_metrics["valid_exact_unique_per_cpu_hour"]),
            "new_behavior_families_per_1k_delta": float(
                local["new_behavior_families_per_1k_evaluations"]
            )
            - float(random_metrics["new_behavior_families_per_1k_evaluations"]),
            "mean_search_reward_delta": float(
                local["mean_search_reward_at_matched_count"]
            )
            - float(random_metrics["mean_search_reward_at_matched_count"]),
            "top_decile_search_reward_delta": float(
                local["top_decile_search_reward_at_matched_count"]
            )
            - float(
                random_metrics["top_decile_search_reward_at_matched_count"]
            ),
            "mean_pair_reward_delta": float(
                local["mean_pair_reward_at_matched_count"]
            )
            - float(random_metrics["mean_pair_reward_at_matched_count"]),
            "top_decile_pair_reward_delta": float(
                local["top_decile_pair_reward_at_matched_count"]
            )
            - float(random_metrics["top_decile_pair_reward_at_matched_count"]),
            "behavior_duplicate_rate_delta": float(
                local["behavior_duplicate_rate"]
            )
            - float(random_metrics["behavior_duplicate_rate"]),
        }
    checkpoints = sorted(
        (runtime_root / "checkpoints").glob("checkpoint_[0-9][0-9][0-9]")
    )
    restore_verified = (
        len(checkpoints) == AGGTRADES_CANARY_CHECKPOINT_COUNT
        and all(
            bool(_read_json(path / "manifest.json").get("restore_verified"))
            for path in checkpoints
        )
    )
    arm_counts = Counter(str(row["arm"]) for row in ledger)
    expected_arm_counts = {
        arm: count * AGGTRADES_CANARY_CHECKPOINT_COUNT
        for arm, count in AGGTRADES_CANARY_CHECKPOINT_ALLOCATION.items()
    }
    every_candidate_uses_aggtrades = all(
        bool(
            set(json.loads(str(row["raw_fields_json"])))
            & set(AGGTRADES_SYSTEM_CANARY_FIELDS)
        )
        for row in ledger
    )
    verified_operations = Counter(
        str(row["operation"])
        for row in ledger
        if str(row["arm"]) == "typed_evolution_v2"
        and bool(row.get("receipt_verified"))
    )
    engineering_pass = bool(
        len(ledger) == AGGTRADES_CANARY_STRICT_TARGET
        and dict(arm_counts) == expected_arm_counts
        and every_candidate_uses_aggtrades
        and restore_verified
    )
    return {
        "schema_version": 1,
        "epoch_id": AGGTRADES_CANARY_EPOCH_ID,
        "status": (
            "PASS_SYSTEM_CANARY_COMPLETED"
            if engineering_pass
            else "HOLD_SYSTEM_CANARY_INCOMPLETE"
        ),
        "research_decision": "HOLD_RESEARCH_FIXED_RETROSPECTIVE_COHORT",
        "producer_source_sha": source_sha,
        "strict_evaluated_count": len(ledger),
        "generation_attempts": int(state["generation_attempts"]),
        "raw_attempt_limit": AGGTRADES_CANARY_RAW_ATTEMPT_LIMIT,
        "active_wall_seconds": float(state["wall_elapsed_seconds"]),
        "wall_time_limit_seconds": AGGTRADES_CANARY_WALL_TIME_LIMIT_SECONDS,
        "checkpoint_count": len(checkpoints),
        "checkpoint_restore_verified": restore_verified,
        "arm_counts": dict(sorted(arm_counts.items())),
        "expected_arm_counts": expected_arm_counts,
        "every_candidate_uses_aggtrades": every_candidate_uses_aggtrades,
        "behavior_family_count": len(archive.champion_by_family),
        "behavior_duplicate_rate": 1.0
        - len(archive.champion_by_family) / max(1, len(ledger)),
        "archive_duplicate_replacements": archive.duplicate_replacements,
        "system_comparisons_vs_typed_random": comparisons,
        "verified_evolution_operations": dict(sorted(verified_operations.items())),
        "engineering_execution_qualified_arms": list(AGGTRADES_CANARY_ARMS),
        "future_new_data_arena_qualified_arms": [],
        "promotion": "FORBIDDEN",
        "sealed_reads": 0,
        "next_arena_started": False,
        "cannot_conclude": [
            "unbiased cross-sectional Alpha",
            "fresh economic increment",
            "OOS validity",
            "challenge, recent, May-stress, or forward evidence",
            "candidate or component promotion",
        ],
    }


def _aggtrades_canary_report_text(decision: Mapping[str, Any]) -> str:
    comparisons = decision["system_comparisons_vs_typed_random"]
    cem = comparisons["hierarchical_typed_cem_v2"]
    evolution = comparisons["typed_evolution_v2"]
    return f"""# Crypto aggTrades Search-System Canary V1

- Status: `{decision['status']}`
- Research decision: `{decision['research_decision']}`
- Producer source: `{decision['producer_source_sha']}`
- Strict completed: `{decision['strict_evaluated_count']:,}` from `{decision['generation_attempts']:,}` raw attempts.
- Checkpoints: `{decision['checkpoint_count']}/{AGGTRADES_CANARY_CHECKPOINT_COUNT}`, exact restore verified: `{decision['checkpoint_restore_verified']}`.
- Every candidate used at least one aggTrades field: `{decision['every_candidate_uses_aggtrades']}`.
- Behavior families: `{decision['behavior_family_count']:,}`; duplicate rate `{decision['behavior_duplicate_rate']:.2%}`.

## System comparison versus typed random

| Arm | valid exact-unique / CPU-hour delta | new families / 1k delta | mean search reward delta | top-decile search reward delta |
|---|---:|---:|---:|---:|
| Hierarchical Typed CEM V2 | {cem['valid_exact_unique_per_cpu_hour_delta']:.6f} | {cem['new_behavior_families_per_1k_delta']:.6f} | {cem['mean_search_reward_delta']:.8f} | {cem['top_decile_search_reward_delta']:.8f} |
| Typed Evolution V2 | {evolution['valid_exact_unique_per_cpu_hour_delta']:.6f} | {evolution['new_behavior_families_per_1k_delta']:.6f} | {evolution['mean_search_reward_delta']:.8f} | {evolution['top_decile_search_reward_delta']:.8f} |

This fixed-retrospective-cohort canary evaluates search-system behavior only.
It creates no Alpha, OOS, challenge, recent, May-stress, forward, promotion,
data-admission, latent-priority, or relational-training authority.
"""


def _v11_final_decision(
    *,
    source_sha: str,
    state: Mapping[str, Any],
    ledger: Sequence[Mapping[str, Any]],
    archive: BehaviorArchive,
    metrics: Sequence[Mapping[str, Any]],
    runtime_root: Path,
) -> dict[str, Any]:
    final_rows = {
        str(row["arm"]): row
        for row in metrics
        if int(row["checkpoint_index"]) == V11_CHECKPOINT_COUNT - 1
    }
    random_metrics = final_rows["canonical_typed_random"]
    comparisons: dict[str, Any] = {}
    for arm in V11_ARMS[1:]:
        local = final_rows[arm]
        comparisons[arm] = {
            "matched_evaluated_count": int(
                local["matched_reward_comparison_count"]
            ),
            "valid_exact_unique_per_cpu_hour": float(
                local["valid_exact_unique_per_cpu_hour"]
            ),
            "valid_exact_unique_per_cpu_hour_delta": float(
                local["valid_exact_unique_per_cpu_hour"]
            )
            - float(random_metrics["valid_exact_unique_per_cpu_hour"]),
            "new_behavior_families_per_1k_evaluations": float(
                local["new_behavior_families_per_1k_evaluations"]
            ),
            "new_behavior_families_per_1k_delta": float(
                local["new_behavior_families_per_1k_evaluations"]
            )
            - float(random_metrics["new_behavior_families_per_1k_evaluations"]),
            "mean_search_reward_at_matched_count": float(
                local["mean_search_reward_at_matched_count"]
            ),
            "mean_search_reward_delta": float(
                local["mean_search_reward_at_matched_count"]
            )
            - float(random_metrics["mean_search_reward_at_matched_count"]),
            "top_decile_search_reward_at_matched_count": float(
                local["top_decile_search_reward_at_matched_count"]
            ),
            "top_decile_search_reward_delta": float(
                local["top_decile_search_reward_at_matched_count"]
            )
            - float(
                random_metrics["top_decile_search_reward_at_matched_count"]
            ),
            "mean_pair_reward_at_matched_count": float(
                local["mean_pair_reward_at_matched_count"]
            ),
            "mean_pair_reward_delta": float(
                local["mean_pair_reward_at_matched_count"]
            )
            - float(random_metrics["mean_pair_reward_at_matched_count"]),
            "top_decile_pair_reward_at_matched_count": float(
                local["top_decile_pair_reward_at_matched_count"]
            ),
            "top_decile_pair_reward_delta": float(
                local["top_decile_pair_reward_at_matched_count"]
            )
            - float(random_metrics["top_decile_pair_reward_at_matched_count"]),
            "behavior_duplicate_rate": float(
                local["behavior_duplicate_rate"]
            ),
            "behavior_duplicate_rate_delta": float(
                local["behavior_duplicate_rate"]
            )
            - float(random_metrics["behavior_duplicate_rate"]),
        }
    checkpoints = sorted(
        (runtime_root / "checkpoints").glob("checkpoint_[0-9][0-9][0-9]")
    )
    restore_verified = (
        len(checkpoints) == V11_CHECKPOINT_COUNT
        and all(
            bool(_read_json(path / "manifest.json").get("restore_verified"))
            for path in checkpoints
        )
    )
    arm_counts = Counter(str(row["arm"]) for row in ledger)
    expected_arm_counts = {
        arm: count * V11_CHECKPOINT_COUNT
        for arm, count in V11_CHECKPOINT_ALLOCATION.items()
    }
    every_candidate_uses_aggtrades = all(
        bool(
            set(json.loads(str(row["raw_fields_json"])))
            & set(AGGTRADES_SYSTEM_CANARY_FIELDS)
        )
        for row in ledger
    )
    verified_operations = Counter(
        str(row["operation"])
        for row in ledger
        if str(row["arm"]) == "behavior_niched_evolution_v2_1"
        and bool(row.get("receipt_verified"))
    )
    positive_by_arm = {
        arm: sum(
            bool(row["matched_positive"])
            for row in ledger
            if str(row["arm"]) == arm
        )
        for arm in V11_ARMS
    }
    cem = comparisons["behavior_niched_cem_v2_1"]
    evolution = comparisons["behavior_niched_evolution_v2_1"]
    cem_pass = bool(
        cem["valid_exact_unique_per_cpu_hour_delta"] >= 0.0
        and (
            cem["new_behavior_families_per_1k_delta"] > 0.0
            or cem["mean_search_reward_delta"] > 0.0
            or cem["top_decile_search_reward_delta"] > 0.0
        )
    )
    evolution_pass = bool(
        evolution["new_behavior_families_per_1k_delta"] >= 0.0
        and evolution["mean_search_reward_delta"] >= 0.0
        and evolution["top_decile_search_reward_delta"] >= 0.0
        and evolution["behavior_duplicate_rate"] < 0.065
    )
    evolution_metrics = final_rows["behavior_niched_evolution_v2_1"]
    within_budget = bool(
        int(state["generation_attempts"]) <= V11_RAW_ATTEMPT_LIMIT
        and float(state["wall_elapsed_seconds"])
        <= V11_WALL_TIME_LIMIT_SECONDS
    )
    engineering_pass = bool(
        len(ledger) == V11_STRICT_TARGET
        and dict(arm_counts) == expected_arm_counts
        and every_candidate_uses_aggtrades
        and restore_verified
        and int(evolution_metrics["operator_update_count"]) > 0
        and within_budget
    )
    return {
        "schema_version": 1,
        "epoch_id": V11_EPOCH_ID,
        "status": (
            "PASS_SEARCH_ENGINE_V1_1_COMPLETED"
            if engineering_pass
            else "ENGINE_BUDGET_EXHAUSTED"
            if not within_budget
            else "HOLD_SEARCH_ENGINE_V1_1_INCOMPLETE"
        ),
        "research_decision": "HOLD_RESEARCH_SPENT_FIXED_RETROSPECTIVE_COHORT",
        "producer_source_sha": source_sha,
        "strict_evaluated_count": len(ledger),
        "generation_attempts": int(state["generation_attempts"]),
        "raw_attempt_limit": V11_RAW_ATTEMPT_LIMIT,
        "active_wall_seconds": float(state["wall_elapsed_seconds"]),
        "wall_time_limit_seconds": V11_WALL_TIME_LIMIT_SECONDS,
        "checkpoint_count": len(checkpoints),
        "checkpoint_restore_verified": restore_verified,
        "arm_counts": dict(sorted(arm_counts.items())),
        "expected_arm_counts": expected_arm_counts,
        "every_candidate_uses_aggtrades": every_candidate_uses_aggtrades,
        "behavior_family_count": len(archive.champion_by_family),
        "behavior_duplicate_rate": 1.0
        - len(archive.champion_by_family) / max(1, len(ledger)),
        "archive_duplicate_replacements": archive.duplicate_replacements,
        "system_comparisons_vs_typed_random": comparisons,
        "positive_matched_discoveries_by_arm": positive_by_arm,
        "verified_evolution_operations": dict(
            sorted(verified_operations.items())
        ),
        "final_evolution_operator_probabilities": json.loads(
            str(evolution_metrics["operator_probabilities_json"])
        ),
        "final_evolution_operator_productivity": json.loads(
            str(evolution_metrics["operator_productivity_json"])
        ),
        "search_iteration_decision": {
            "behavior_niched_cem_v2_1": (
                "RETAIN_ENGINEERING_SEARCH_INCREMENT"
                if cem_pass
                else "REJECT_INCREMENT_NOT_DEMONSTRATED"
            ),
            "behavior_niched_evolution_v2_1": (
                "RETAIN_ENGINEERING_SEARCH_INCREMENT"
                if evolution_pass
                else "REJECT_INCREMENT_NOT_DEMONSTRATED"
            ),
        },
        "engineering_execution_qualified_arms": list(V11_ARMS),
        "future_new_data_arena_qualified_arms": [],
        "promotion": "FORBIDDEN",
        "sealed_reads": 0,
        "next_arena_started": False,
        "cannot_conclude": [
            "unbiased cross-sectional Alpha",
            "fresh economic increment",
            "OOS validity",
            "challenge, recent, May-stress, or forward evidence",
            "candidate, arm, or component promotion",
        ],
    }


def _v12_final_decision(
    *,
    source_sha: str,
    state: Mapping[str, Any],
    ledger: Sequence[Mapping[str, Any]],
    archive: BehaviorArchive,
    metrics: Sequence[Mapping[str, Any]],
    runtime_root: Path,
) -> dict[str, Any]:
    final_rows = {
        str(row["arm"]): row
        for row in metrics
        if int(row["checkpoint_index"]) == V12_CHECKPOINT_COUNT - 1
    }
    random_metrics = final_rows["canonical_typed_random"]
    evolution_metrics = final_rows["collision_controlled_evolution_v2_2"]
    comparison = {
        "matched_evaluated_count": int(
            evolution_metrics["matched_reward_comparison_count"]
        ),
        "strict_per_raw_attempt": float(
            evolution_metrics["strict_per_raw_attempt"]
        ),
        "strict_per_raw_attempt_delta": float(
            evolution_metrics["strict_per_raw_attempt"]
        )
        - float(random_metrics["strict_per_raw_attempt"]),
        "balanced_valid_exact_unique_per_cpu_hour": float(
            evolution_metrics[
                "balanced_valid_exact_unique_per_cpu_hour"
            ]
        ),
        "balanced_valid_exact_unique_per_cpu_hour_delta": float(
            evolution_metrics[
                "balanced_valid_exact_unique_per_cpu_hour"
            ]
        )
        - float(
            random_metrics[
                "balanced_valid_exact_unique_per_cpu_hour"
            ]
        ),
        "new_behavior_families_per_cpu_hour": float(
            evolution_metrics["new_behavior_families_per_cpu_hour"]
        ),
        "new_behavior_families_per_cpu_hour_delta": float(
            evolution_metrics["new_behavior_families_per_cpu_hour"]
        )
        - float(random_metrics["new_behavior_families_per_cpu_hour"]),
        "new_behavior_families_per_1k_evaluations": float(
            evolution_metrics["new_behavior_families_per_1k_evaluations"]
        ),
        "new_behavior_families_per_1k_delta": float(
            evolution_metrics["new_behavior_families_per_1k_evaluations"]
        )
        - float(random_metrics["new_behavior_families_per_1k_evaluations"]),
        "mean_search_reward_at_matched_count": float(
            evolution_metrics["mean_search_reward_at_matched_count"]
        ),
        "mean_search_reward_delta": float(
            evolution_metrics["mean_search_reward_at_matched_count"]
        )
        - float(random_metrics["mean_search_reward_at_matched_count"]),
        "top_decile_search_reward_at_matched_count": float(
            evolution_metrics["top_decile_search_reward_at_matched_count"]
        ),
        "top_decile_search_reward_delta": float(
            evolution_metrics["top_decile_search_reward_at_matched_count"]
        )
        - float(random_metrics["top_decile_search_reward_at_matched_count"]),
        "mean_pair_reward_at_matched_count": float(
            evolution_metrics["mean_pair_reward_at_matched_count"]
        ),
        "mean_pair_reward_delta": float(
            evolution_metrics["mean_pair_reward_at_matched_count"]
        )
        - float(random_metrics["mean_pair_reward_at_matched_count"]),
        "top_decile_pair_reward_at_matched_count": float(
            evolution_metrics["top_decile_pair_reward_at_matched_count"]
        ),
        "top_decile_pair_reward_delta": float(
            evolution_metrics["top_decile_pair_reward_at_matched_count"]
        )
        - float(random_metrics["top_decile_pair_reward_at_matched_count"]),
        "behavior_duplicate_rate": float(
            evolution_metrics["behavior_duplicate_rate"]
        ),
        "behavior_duplicate_rate_delta": float(
            evolution_metrics["behavior_duplicate_rate"]
        )
        - float(random_metrics["behavior_duplicate_rate"]),
    }
    engineering_gate = {
        "strict_per_raw_attempt_above_random": (
            comparison["strict_per_raw_attempt_delta"] > 0.0
        ),
        "balanced_valid_exact_unique_per_cpu_hour_not_below_random": (
            comparison[
                "balanced_valid_exact_unique_per_cpu_hour_delta"
            ]
            >= 0.0
        ),
        "new_behavior_families_per_cpu_hour_not_below_random": (
            comparison["new_behavior_families_per_cpu_hour_delta"] >= 0.0
        ),
        "behavior_duplicate_rate_at_or_below_3pct": (
            comparison["behavior_duplicate_rate"] <= 0.03
        ),
        "mean_search_reward_not_below_random": (
            comparison["mean_search_reward_delta"] >= 0.0
        ),
        "top_decile_search_reward_not_below_random": (
            comparison["top_decile_search_reward_delta"] >= 0.0
        ),
    }
    increment_pass = all(engineering_gate.values())
    checkpoints = sorted(
        (runtime_root / "checkpoints").glob("checkpoint_[0-9][0-9][0-9]")
    )
    restore_verified = (
        len(checkpoints) == V12_CHECKPOINT_COUNT
        and all(
            bool(_read_json(path / "manifest.json").get("restore_verified"))
            for path in checkpoints
        )
    )
    arm_counts = Counter(str(row["arm"]) for row in ledger)
    expected_arm_counts = {
        arm: count * V12_CHECKPOINT_COUNT
        for arm, count in V12_CHECKPOINT_ALLOCATION.items()
    }
    batches: dict[int, list[Mapping[str, Any]]] = defaultdict(list)
    for row in ledger:
        if row.get("balanced_batch_index") is not None:
            batches[int(row["balanced_batch_index"])].append(row)
    balanced_batch_integrity = bool(
        len(batches) == V12_STRICT_TARGET // V12_BALANCED_BATCH_SIZE
        and all(
            len(rows) == V12_BALANCED_BATCH_SIZE
            and Counter(str(row["arm"]) for row in rows)
            == {
                "canonical_typed_random": len(SEEDS),
                "collision_controlled_evolution_v2_2": len(SEEDS),
            }
            and len(
                {
                    (str(row["arm"]), int(row["seed"]))
                    for row in rows
                }
            )
            == V12_BALANCED_BATCH_SIZE
            and sorted(int(row["balanced_batch_slot"]) for row in rows)
            == list(range(V12_BALANCED_BATCH_SIZE))
            for rows in batches.values()
        )
    )
    expected_lanes = {
        (arm, seed) for arm in V12_ARMS for seed in SEEDS
    }
    lanes_by_slot: dict[int, set[tuple[str, int]]] = defaultdict(set)
    for rows in batches.values():
        for row in rows:
            lanes_by_slot[int(row["balanced_batch_slot"])].add(
                (str(row["arm"]), int(row["seed"]))
            )
    rotating_submission_integrity = bool(
        balanced_batch_integrity
        and set(lanes_by_slot) == set(range(V12_BALANCED_BATCH_SIZE))
        and all(lanes == expected_lanes for lanes in lanes_by_slot.values())
    )
    every_candidate_uses_aggtrades = all(
        bool(
            set(json.loads(str(row["raw_fields_json"])))
            & set(AGGTRADES_SYSTEM_CANARY_FIELDS)
        )
        for row in ledger
    )
    verified_operations = Counter(
        str(row["operation"])
        for row in ledger
        if str(row["arm"]) == "collision_controlled_evolution_v2_2"
        and bool(row.get("receipt_verified"))
    )
    positive_by_arm = {
        arm: sum(
            bool(row["matched_positive"])
            for row in ledger
            if str(row["arm"]) == arm
        )
        for arm in V12_ARMS
    }
    within_budget = bool(
        int(state["generation_attempts"]) <= V12_RAW_ATTEMPT_LIMIT
        and float(state["wall_elapsed_seconds"])
        <= V12_WALL_TIME_LIMIT_SECONDS
    )
    engineering_pass = bool(
        len(ledger) == V12_STRICT_TARGET
        and dict(arm_counts) == expected_arm_counts
        and every_candidate_uses_aggtrades
        and balanced_batch_integrity
        and rotating_submission_integrity
        and restore_verified
        and int(evolution_metrics["operator_update_count"]) > 0
        and within_budget
    )
    return {
        "schema_version": 1,
        "epoch_id": V12_EPOCH_ID,
        "status": (
            "PASS_SEARCH_ENGINE_V1_2_COMPLETED"
            if engineering_pass
            else "ENGINE_BUDGET_EXHAUSTED"
            if not within_budget
            else "HOLD_SEARCH_ENGINE_V1_2_INCOMPLETE"
        ),
        "research_decision": "HOLD_RESEARCH_SPENT_FIXED_RETROSPECTIVE_COHORT",
        "producer_source_sha": source_sha,
        "strict_evaluated_count": len(ledger),
        "generation_attempts": int(state["generation_attempts"]),
        "raw_attempt_limit": V12_RAW_ATTEMPT_LIMIT,
        "active_wall_seconds": float(state["wall_elapsed_seconds"]),
        "wall_time_limit_seconds": V12_WALL_TIME_LIMIT_SECONDS,
        "checkpoint_count": len(checkpoints),
        "checkpoint_restore_verified": restore_verified,
        "arm_counts": dict(sorted(arm_counts.items())),
        "expected_arm_counts": expected_arm_counts,
        "balanced_batch_count": len(batches),
        "balanced_batch_integrity": balanced_batch_integrity,
        "rotating_submission_integrity": rotating_submission_integrity,
        "every_candidate_uses_aggtrades": every_candidate_uses_aggtrades,
        "behavior_family_count": len(archive.champion_by_family),
        "behavior_duplicate_rate": 1.0
        - len(archive.champion_by_family) / max(1, len(ledger)),
        "archive_duplicate_replacements": archive.duplicate_replacements,
        "system_comparison_vs_typed_random": comparison,
        "frozen_engineering_gate": engineering_gate,
        "verified_evolution_operations": dict(
            sorted(verified_operations.items())
        ),
        "final_evolution_operator_probabilities": json.loads(
            str(evolution_metrics["operator_probabilities_json"])
        ),
        "final_evolution_operator_productivity": json.loads(
            str(evolution_metrics["operator_productivity_json"])
        ),
        "transition_productivity": json.loads(
            str(evolution_metrics["transition_productivity_json"])
        ),
        "blocked_transition_count": int(
            evolution_metrics["blocked_transition_count"]
        ),
        "blocked_transition_skips": int(
            evolution_metrics["blocked_transition_skips"]
        ),
        "positive_matched_discoveries_by_arm": positive_by_arm,
        "search_iteration_decision": {
            "collision_controlled_evolution_v2_2": (
                "RETAIN_ENGINEERING_SEARCH_INCREMENT"
                if increment_pass
                else "REJECT_INCREMENT_NOT_DEMONSTRATED"
            )
        },
        "engineering_execution_qualified_arms": list(V12_ARMS),
        "future_new_data_arena_qualified_arms": [],
        "promotion": "FORBIDDEN",
        "sealed_reads": 0,
        "next_arena_started": False,
        "cannot_conclude": [
            "unbiased cross-sectional Alpha",
            "fresh economic increment",
            "OOS validity",
            "challenge, recent, May-stress, or forward evidence",
            "candidate, arm, or component promotion",
        ],
    }


def _v11_report_text(decision: Mapping[str, Any]) -> str:
    comparisons = decision["system_comparisons_vs_typed_random"]
    cem = comparisons["behavior_niched_cem_v2_1"]
    evolution = comparisons["behavior_niched_evolution_v2_1"]
    return f"""# Crypto Search Engine V1.1 Behavior-Niched Arena

- Status: `{decision['status']}`
- Research decision: `{decision['research_decision']}`
- Producer source: `{decision['producer_source_sha']}`
- Strict completed: `{decision['strict_evaluated_count']:,}` from `{decision['generation_attempts']:,}` raw attempts.
- Checkpoints: `{decision['checkpoint_count']}/{V11_CHECKPOINT_COUNT}`, exact restore verified: `{decision['checkpoint_restore_verified']}`.
- Behavior families: `{decision['behavior_family_count']:,}`; duplicate rate `{decision['behavior_duplicate_rate']:.2%}`.
- Positive matched discoveries by arm: `{json.dumps(decision['positive_matched_discoveries_by_arm'], sort_keys=True)}`.

## Equal-count system comparison versus typed random

| Arm | valid unique / CPU-hour delta | new families / 1k | delta | mean reward delta | top-decile delta | duplicate rate |
|---|---:|---:|---:|---:|---:|---:|
| Behavior-Niched CEM V2.1 | {cem['valid_exact_unique_per_cpu_hour_delta']:.6f} | {cem['new_behavior_families_per_1k_evaluations']:.3f} | {cem['new_behavior_families_per_1k_delta']:.3f} | {cem['mean_search_reward_delta']:.8f} | {cem['top_decile_search_reward_delta']:.8f} | {cem['behavior_duplicate_rate']:.2%} |
| Behavior-Niched Evolution V2.1 | {evolution['valid_exact_unique_per_cpu_hour_delta']:.6f} | {evolution['new_behavior_families_per_1k_evaluations']:.3f} | {evolution['new_behavior_families_per_1k_delta']:.3f} | {evolution['mean_search_reward_delta']:.8f} | {evolution['top_decile_search_reward_delta']:.8f} | {evolution['behavior_duplicate_rate']:.2%} |

## System decision

- CEM V2.1: `{decision['search_iteration_decision']['behavior_niched_cem_v2_1']}`
- Evolution V2.1: `{decision['search_iteration_decision']['behavior_niched_evolution_v2_1']}`
- Future new-data Arena arms: `[]`

This fixed, spent-development Arena evaluates search capability only. It
creates no Alpha, OOS, challenge, recent, May-stress, forward, promotion,
data-admission, latent-priority, relational-training, or future-Arena
    qualification authority.
"""


def _v12_report_text(decision: Mapping[str, Any]) -> str:
    comparison = decision["system_comparison_vs_typed_random"]
    gate = decision["frozen_engineering_gate"]
    return f"""# Crypto Search Engine V1.2

- Status: `{decision['status']}`
- Research decision: `{decision['research_decision']}`
- Producer source: `{decision['producer_source_sha']}`
- Strict completed: `{decision['strict_evaluated_count']:,}` from `{decision['generation_attempts']:,}` raw attempts.
- Checkpoints: `{decision['checkpoint_count']}/{V12_CHECKPOINT_COUNT}`, exact restore verified: `{decision['checkpoint_restore_verified']}`.
- Balanced batches: `{decision['balanced_batch_count']}`, integrity: `{decision['balanced_batch_integrity']}`, rotating submission: `{decision['rotating_submission_integrity']}`.
- Behavior families: `{decision['behavior_family_count']:,}`; global duplicate rate `{decision['behavior_duplicate_rate']:.2%}`.

## Evolution V2.2 versus typed random

| Metric | Delta / result |
|---|---:|
| strict per raw attempt | {comparison['strict_per_raw_attempt_delta']:+.8f} |
| balanced valid unique / CPU-hour | {comparison['balanced_valid_exact_unique_per_cpu_hour_delta']:+.6f} |
| new families / CPU-hour | {comparison['new_behavior_families_per_cpu_hour_delta']:+.6f} |
| new families / 1k | {comparison['new_behavior_families_per_1k_evaluations']:.3f} |
| mean search reward | {comparison['mean_search_reward_delta']:+.8f} |
| top-decile search reward | {comparison['top_decile_search_reward_delta']:+.8f} |
| behavior duplicate rate | {comparison['behavior_duplicate_rate']:.2%} |

## Collision control

- Blocked transitions: `{decision['blocked_transition_count']}`
- Pre-evaluation blocked-transition skips: `{decision['blocked_transition_skips']}`
- Frozen gates passed: `{sum(bool(value) for value in gate.values())}/{len(gate)}`
- Search decision: `{decision['search_iteration_decision']['collision_controlled_evolution_v2_2']}`
- Future new-data Arena arms: `[]`

This fixed, spent-development engineering Arena creates no Alpha, OOS,
challenge, recent, May-stress, forward, promotion, data-admission,
latent-priority, relational-training, or future-Arena qualification authority.
"""


def _final_manifest(
    *,
    repo_root: Path,
    runtime_root: Path,
    report_path: Path,
    source_sha: str,
    frozen_hash: str,
    identities: Mapping[str, Any],
    state: Mapping[str, Any],
    epoch_id: str = EPOCH_ID,
    base_sha: str = BASE_SHA,
    status: str = "COMPLETED",
    closure_source_sha: str | None = None,
    continuation: str = (
        "python -m alphafactory_crypto.broad_search.search_engine_v1 "
        "check --runtime-date 20260721"
    ),
) -> dict[str, Any]:
    paths = [
        runtime_root / "frozen_contract.json",
        runtime_root / "embedded_preflight.json",
        runtime_root / "candidate_ledger.parquet",
        runtime_root / "behavior_archive.parquet",
        runtime_root / "behavior_family_summary.json",
        runtime_root / "arm_checkpoint_metrics.parquet",
        runtime_root / "final_decision.json",
        report_path,
    ]
    if (runtime_root / "constructibility_canary.json").is_file():
        paths.append(runtime_root / "constructibility_canary.json")
    for name in (
        "mechanism_knowledge.parquet",
        "mechanism_knowledge_summary.json",
        "validation_candidate_ledger.parquet",
        "validation_arm_metrics.parquet",
        "validation_cohort_paths.parquet",
        "validation_decisions.json",
        "validation_failure.json",
        "validation_failure_stdout.log",
        "validation_failure_stderr.log",
        "search_failure_evidence.parquet",
        "search_run_evidence.parquet",
        "search_exposure_strata.parquet",
        "search_run_evidence_summary.json",
        "block_robust_gate_summary.json",
        "block_robust_template_metrics.parquet",
    ):
        path = runtime_root / name
        if path.is_file():
            paths.append(path)
    for checkpoint in sorted((runtime_root / "checkpoints").glob("checkpoint_*")):
        paths.extend(sorted(checkpoint.iterdir()))
    artifacts = [
        {
            "path": path.relative_to(repo_root).as_posix(),
            "bytes": path.stat().st_size,
            "sha256": sha256_file(path),
        }
        for path in sorted(paths)
    ]
    return {
        "schema_version": 1,
        "epoch_id": epoch_id,
        "status": status,
        "producer_source_sha": source_sha,
        "closure_source_sha": closure_source_sha or source_sha,
        "base_sha": base_sha,
        "frozen_contract_sha256": frozen_hash,
        "data_cache_identity": identities["raw_cache"],
        "compiler_identity": identities["compiler_identity"],
        "strict_evaluated_count": int(state["strict_evaluated"]),
        "generation_attempts": int(state["generation_attempts"]),
        "active_wall_seconds": float(state["wall_elapsed_seconds"]),
        "workers_final": int(state["workers"]),
        "memory_fallback_used": bool(state["memory_fallback_used"]),
        "sealed_reads": 0,
        "artifacts": artifacts,
        "artifact_bundle_sha256": _payload_sha(artifacts),
        "reproducible": True,
        "continuation": continuation,
    }


def close_budget_exhausted_engine(
    repo_root: Path,
    *,
    runtime_date: str = ECONOMIC_SEARCH_DEFAULT_RUNTIME_DATE,
    expected_producer_source_sha: str | None = None,
    closure_source_sha: str | None = None,
    campaign: str = ECONOMIC_SEARCH_CAMPAIGN,
) -> dict[str, Any]:
    """Finish reports and provenance without generating or evaluating candidates."""

    economic_config = _economic_campaign_config(campaign)
    if runtime_date != economic_config["runtime_date"]:
        raise ValueError("economic search runtime date changed")
    runtime_root = (
        repo_root
        / f"runtime/{economic_config['runtime_prefix']}_{runtime_date}"
    )
    report_path = (
        repo_root
        / f"reports/{economic_config['report_prefix']}_{runtime_date}.md"
    )
    checkpoint = runtime_root / "checkpoints" / "checkpoint_budget_exhausted"
    for path in (
        runtime_root / "frozen_contract.json",
        runtime_root / "embedded_preflight.json",
        runtime_root / "candidate_ledger.parquet",
        runtime_root / "behavior_archive.parquet",
        runtime_root / "behavior_family_summary.json",
        runtime_root / "arm_checkpoint_metrics.parquet",
        runtime_root / "final_decision.json",
        checkpoint / "manifest.json",
        checkpoint / "state.json",
    ):
        if not path.is_file():
            raise FileNotFoundError(f"budget-exhausted closure input missing: {path}")

    frozen = _read_json(runtime_root / "frozen_contract.json")
    original_decision = _read_json(runtime_root / "final_decision.json")
    checkpoint_manifest = _read_json(checkpoint / "manifest.json")
    state = _read_json(checkpoint / "state.json")
    ledger = pd.read_parquet(runtime_root / "candidate_ledger.parquet")
    archive = pd.read_parquet(runtime_root / "behavior_archive.parquet")
    producer_source_sha = str(checkpoint_manifest["source_sha"]).lower()
    if (
        expected_producer_source_sha is not None
        and producer_source_sha != str(expected_producer_source_sha).lower()
    ):
        raise RuntimeError("budget-exhausted producer source SHA changed")
    if original_decision.get("status") != "ENGINE_BUDGET_EXHAUSTED":
        raise RuntimeError("closure is only valid for ENGINE_BUDGET_EXHAUSTED")
    if original_decision.get("reason") not in {
        "RAW_GENERATION_ATTEMPT_LIMIT",
        "WALL_TIME_LIMIT",
    }:
        raise RuntimeError("budget-exhausted reason is not a frozen hard limit")
    if checkpoint_manifest.get("restore_verified") is not True:
        raise RuntimeError("budget-exhausted checkpoint restore was not verified")
    if int(checkpoint_manifest.get("completed_ledger_row_count", -1)) != len(
        ledger
    ):
        raise RuntimeError("budget-exhausted checkpoint row count changed")
    if int(state.get("strict_evaluated", -1)) != len(ledger):
        raise RuntimeError("budget-exhausted state row count changed")
    if len(archive) != len(ledger):
        raise RuntimeError("budget-exhausted archive row count changed")
    if checkpoint_manifest.get("frozen_contract_sha256") != frozen.get(
        "frozen_contract_sha256"
    ):
        raise RuntimeError("budget-exhausted frozen contract changed")
    for record in checkpoint_manifest.get("files", []):
        checkpoint_file = checkpoint / str(record["name"])
        top_level_file = runtime_root / str(record["name"])
        if (
            not checkpoint_file.is_file()
            or checkpoint_file.stat().st_size != int(record["bytes"])
            or sha256_file(checkpoint_file) != str(record["sha256"])
        ):
            raise RuntimeError(
                f"budget-exhausted checkpoint file changed: {record['name']}"
            )
        if top_level_file.is_file() and sha256_file(top_level_file) != str(
            record["sha256"]
        ):
            raise RuntimeError(
                f"budget-exhausted top-level artifact changed: {record['name']}"
            )

    closure_sha = str(closure_source_sha or _git_sha(repo_root)).lower()
    decision = _budget_exhausted_decision(
        decision=original_decision,
        source_sha=producer_source_sha,
        state=state,
        ledger=ledger,
        archive=archive,
        checkpoint_restore_verified=True,
        closure_source_sha=closure_sha,
        campaign=campaign,
    )
    _write_json(runtime_root / "final_decision.json", decision)
    report_path.parent.mkdir(parents=True, exist_ok=True)
    report_path.write_text(
        _budget_exhausted_report_text(decision),
        encoding="utf-8",
        newline="\n",
    )
    identities = {
        "raw_cache": checkpoint_manifest["data_cache_identity"],
        "compiler_identity": checkpoint_manifest["compiler_identity"],
    }
    manifest = _final_manifest(
        repo_root=repo_root,
        runtime_root=runtime_root,
        report_path=report_path,
        source_sha=producer_source_sha,
        frozen_hash=str(frozen["frozen_contract_sha256"]),
        identities=identities,
        state=state,
        epoch_id=economic_config["epoch_id"],
        base_sha=producer_source_sha,
        status="ENGINE_BUDGET_EXHAUSTED",
        closure_source_sha=closure_sha,
        continuation=(
            "python -m alphafactory_crypto.broad_search.search_engine_v1 "
            f"check-{economic_config['cli_suffix']} --runtime-date {runtime_date}"
        ),
    )
    _write_json(runtime_root / "run_manifest.json", manifest)
    return {
        "result": "PASS",
        "status": "ENGINE_BUDGET_EXHAUSTED",
        "producer_source_sha": producer_source_sha,
        "closure_source_sha": closure_sha,
        "strict_evaluated_count": len(ledger),
        "generation_attempts": int(state["generation_attempts"]),
        "checkpoint": checkpoint.name,
        "artifact_bundle_sha256": manifest["artifact_bundle_sha256"],
        "candidate_generation_performed": False,
        "candidate_evaluation_performed": False,
        "rescue_rerun_started": False,
        "sealed_reads": 0,
    }


def close_validation_blocked_engine(
    repo_root: Path,
    *,
    runtime_date: str = ECONOMIC_SEARCH_DEFAULT_RUNTIME_DATE,
    expected_producer_source_sha: str | None = None,
    closure_source_sha: str | None = None,
    campaign: str = ECONOMIC_SEARCH_V2_CAMPAIGN,
    failure_record_name: str | None = None,
) -> dict[str, Any]:
    """Close an already-stopped validation crash without evaluating a candidate."""

    economic_config = _economic_campaign_config(campaign)
    if runtime_date != economic_config["runtime_date"]:
        raise ValueError("economic search runtime date changed")
    runtime_root = (
        repo_root
        / f"runtime/{economic_config['runtime_prefix']}_{runtime_date}"
    )
    report_path = (
        repo_root
        / f"reports/{economic_config['report_prefix']}_{runtime_date}.md"
    )
    checkpoint_count = int(economic_config.get("checkpoint_count", 1))
    checkpoint = runtime_root / "checkpoints" / (
        f"checkpoint_{checkpoint_count - 1:03d}"
    )
    failure_path = runtime_root / (
        failure_record_name or "validation_failure_stderr.log"
    )
    for path in (
        runtime_root / "frozen_contract.json",
        runtime_root / "embedded_preflight.json",
        runtime_root / "candidate_ledger.parquet",
        runtime_root / "behavior_archive.parquet",
        runtime_root / "behavior_family_summary.json",
        runtime_root / "arm_checkpoint_metrics.parquet",
        checkpoint / "manifest.json",
        checkpoint / "state.json",
        failure_path,
    ):
        if not path.is_file():
            raise FileNotFoundError(
                f"validation-blocked closure input missing: {path}"
            )
    for path in (
        runtime_root / "final_decision.json",
        runtime_root / "run_manifest.json",
        runtime_root / "validation_candidate_ledger.parquet",
        runtime_root / "validation_arm_metrics.parquet",
        runtime_root / "validation_decisions.json",
        runtime_root / "checkpoints" / "checkpoint_validation",
    ):
        if path.exists():
            raise RuntimeError(
                f"validation-blocked closure found unexpected artifact: {path}"
            )

    frozen = _read_json(runtime_root / "frozen_contract.json")
    checkpoint_manifest = _read_json(checkpoint / "manifest.json")
    state = _read_json(checkpoint / "state.json")
    ledger = pd.read_parquet(runtime_root / "candidate_ledger.parquet").to_dict(
        "records"
    )
    archive = BehaviorArchive.from_rows(
        pd.read_parquet(runtime_root / "behavior_archive.parquet").to_dict(
            "records"
        )
    )
    producer_source_sha = str(checkpoint_manifest["source_sha"]).lower()
    if (
        expected_producer_source_sha is not None
        and producer_source_sha != str(expected_producer_source_sha).lower()
    ):
        raise RuntimeError("validation-blocked producer source SHA changed")
    if checkpoint_manifest.get("restore_verified") is not True:
        raise RuntimeError("validation-blocked checkpoint restore was not verified")
    if int(checkpoint_manifest.get("completed_ledger_row_count", -1)) != len(
        ledger
    ):
        raise RuntimeError("validation-blocked checkpoint row count changed")
    expected_strict_target = int(
        economic_config.get("strict_target", CHECKPOINT_SIZE)
    )
    if len(ledger) != expected_strict_target:
        raise RuntimeError(
            "validation-blocked closure requires the frozen strict target"
        )
    if int(state.get("next_checkpoint_index", -1)) != checkpoint_count:
        raise RuntimeError("validation-blocked checkpoint progress changed")
    if int(state.get("strict_evaluated", -1)) != len(ledger):
        raise RuntimeError("validation-blocked state row count changed")
    checkpoint_files = {
        str(row["name"]): dict(row)
        for row in checkpoint_manifest.get("files", ())
        if isinstance(row, Mapping)
    }
    for name in (
        "candidate_ledger.parquet",
        "behavior_archive.parquet",
        "arm_checkpoint_metrics.parquet",
    ):
        checkpoint_file = checkpoint / name
        top_level_file = runtime_root / name
        record = checkpoint_files.get(name)
        if (
            not checkpoint_file.is_file()
            or record is None
            or sha256_file(checkpoint_file) != str(record.get("sha256") or "")
            or sha256_file(top_level_file) != sha256_file(checkpoint_file)
        ):
            raise RuntimeError(
                f"validation-blocked checkpoint artifact changed: {name}"
            )
    if failure_record_name is None:
        failure_text = failure_path.read_text(
            encoding="utf-8", errors="replace"
        )
        failure_reason = "CONTROL_BEHAVIOR_EQUALS_PRIMARY"
        if (
            "run_frozen_validation_stage" not in failure_text
            or failure_reason not in failure_text
        ):
            raise RuntimeError("validation-blocked traceback identity changed")
        failure = {
            "reason": failure_reason,
            "arm": "NOT_PERSISTED_BY_PRODUCER",
            "candidate_id": "NOT_PERSISTED_BY_PRODUCER",
            "horizon_hours": -1,
            "selection_rank": -1,
            "producer_traceback_sha256": sha256_file(failure_path),
            "closure_mode": "POST_MORTEM_FROM_VERIFIED_CHECKPOINT",
        }
    else:
        failure_record = _read_json(failure_path)
        expected_message = (
            "validation control path inconsistent for arm: "
            "extensible_mechanism_random_v2:interaction_left"
        )
        if (
            failure_record.get("status") != "PROCESS_EXIT_CAPTURED"
            or failure_record.get("producer_source_sha")
            != producer_source_sha
            or failure_record.get("checkpoint") != checkpoint.name
            or int(failure_record.get("strict_evaluated_at_exit", -1))
            != len(ledger)
            or int(failure_record.get("exit_code", 0)) != 1
            or failure_record.get("exception_type") != "ValueError"
            or failure_record.get("exception_message") != expected_message
            or failure_record.get("traceback_function")
            != "_validation_arm_metrics"
        ):
            raise RuntimeError("validation-blocked failure record changed")
        failure = {
            "reason": "VALIDATION_CONTROL_PATH_SCHEMA_INCONSISTENT",
            "arm": "extensible_mechanism_random_v2",
            "candidate_id": "NOT_APPLICABLE_ARM_AGGREGATION",
            "horizon_hours": -1,
            "selection_rank": -1,
            "producer_traceback_sha256": sha256_file(failure_path),
            "closure_mode": "POST_MORTEM_FROM_VERIFIED_CHECKPOINT",
            "failure_stage": "ARM_AGGREGATION",
            "exception_message": expected_message,
        }

    closure_sha = str(closure_source_sha or _git_sha(repo_root)).lower()
    decision = _validation_blocked_decision(
        source_sha=producer_source_sha,
        state=state,
        ledger=ledger,
        archive=archive,
        checkpoint=checkpoint,
        failure=failure,
        campaign=campaign,
        closure_source_sha=closure_sha,
    )
    _write_json(runtime_root / "final_decision.json", decision)
    report_path.parent.mkdir(parents=True, exist_ok=True)
    report_path.write_text(
        _validation_blocked_report_text(decision),
        encoding="utf-8",
        newline="\n",
    )
    identities = {
        "raw_cache": checkpoint_manifest["data_cache_identity"],
        "compiler_identity": checkpoint_manifest["compiler_identity"],
    }
    manifest = _final_manifest(
        repo_root=repo_root,
        runtime_root=runtime_root,
        report_path=report_path,
        source_sha=producer_source_sha,
        frozen_hash=str(frozen["frozen_contract_sha256"]),
        identities=identities,
        state=state,
        epoch_id=economic_config["epoch_id"],
        base_sha=producer_source_sha,
        status="ENGINE_VALIDATION_BLOCKED",
        closure_source_sha=closure_sha,
        continuation=(
            "python -m alphafactory_crypto.broad_search.search_engine_v1 "
            f"check-{economic_config['cli_suffix']} --runtime-date {runtime_date}"
        ),
    )
    _write_json(runtime_root / "run_manifest.json", manifest)
    return {
        "result": "PASS",
        "status": "ENGINE_VALIDATION_BLOCKED",
        "producer_source_sha": producer_source_sha,
        "closure_source_sha": closure_sha,
        "strict_evaluated_count": len(ledger),
        "generation_attempts": int(state["generation_attempts"]),
        "checkpoint": checkpoint.name,
        "artifact_bundle_sha256": manifest["artifact_bundle_sha256"],
        "candidate_generation_performed": False,
        "candidate_evaluation_performed": False,
        "rescue_rerun_started": False,
        "sealed_reads": 0,
    }


def _carrier_gate_final_decision(
    *,
    source_sha: str,
    carrier_id: str,
    state: Mapping[str, Any],
    ledger: Sequence[Mapping[str, Any]],
    archive: BehaviorArchive,
    metrics: Sequence[Mapping[str, Any]],
    runtime_root: Path,
) -> dict[str, Any]:
    final_metrics = {
        str(row["arm"]): dict(row)
        for row in metrics
        if int(row["checkpoint_index"]) == CARRIER_GATE_CHECKPOINT_COUNT - 1
    }
    random_metrics = final_metrics["canonical_typed_random"]
    comparisons = {}
    for arm in CARRIER_GATE_ARMS[1:]:
        local = final_metrics[arm]
        comparisons[arm] = {
            "mean_search_reward_delta": float(
                local["mean_search_reward_at_matched_count"]
            )
            - float(random_metrics["mean_search_reward_at_matched_count"]),
            "top_decile_search_reward_delta": float(
                local["top_decile_search_reward_at_matched_count"]
            )
            - float(
                random_metrics["top_decile_search_reward_at_matched_count"]
            ),
            "mean_pair_reward_delta": float(
                local["mean_pair_reward_at_matched_count"]
            )
            - float(random_metrics["mean_pair_reward_at_matched_count"]),
            "top_decile_pair_reward_delta": float(
                local["top_decile_pair_reward_at_matched_count"]
            )
            - float(random_metrics["top_decile_pair_reward_at_matched_count"]),
            "new_behavior_families_per_1k_delta": float(
                local["new_behavior_families_per_1k_evaluations"]
            )
            - float(random_metrics["new_behavior_families_per_1k_evaluations"]),
        }
    checkpoints = sorted(
        (runtime_root / "checkpoints").glob("checkpoint_[0-9][0-9][0-9]")
    )
    return {
        "schema_version": 1,
        "status": "PASS_CARRIER_GATE_COMPLETED",
        "producer_source_sha": source_sha,
        "carrier_id": carrier_id,
        "strict_evaluated_count": len(ledger),
        "generation_attempts": int(state["generation_attempts"]),
        "active_wall_seconds": float(state["wall_elapsed_seconds"]),
        "checkpoint_count": len(checkpoints),
        "checkpoint_restore_verified": (
            len(checkpoints) == CARRIER_GATE_CHECKPOINT_COUNT
            and all(
                _read_json(path / "manifest.json").get("restore_verified") is True
                for path in checkpoints
            )
        ),
        "behavior_family_count": len(archive.champion_by_family),
        "arm_comparisons": comparisons,
        "research_decision": "HOLD_DEVELOPMENT_FIXED_RETROSPECTIVE_CARRIER",
        "future_arena_qualification": False,
        "alpha_claim": False,
        "oos": False,
        "promotion": False,
        "sealed_reads": 0,
    }


def _carrier_gate_report_text(decision: Mapping[str, Any]) -> str:
    return f"""# Crypto Search Carrier Gate V1

- Carrier: `{decision['carrier_id']}`
- Strict evaluated: `{decision['strict_evaluated_count']}`
- Checkpoints: `{decision['checkpoint_count']}`, exact restore: `{decision['checkpoint_restore_verified']}`
- Research decision: `{decision['research_decision']}`
- Authority: dual-axis matched controls, incremental behavior identity, arm/seed-local adaptive memory, single-EMA CEM update.
- Boundaries: development-only; no OOS, promotion, sealed reads, or Alpha claim.
"""


def _v13_final_decision(
    *,
    source_sha: str,
    state: Mapping[str, Any],
    ledger: Sequence[Mapping[str, Any]],
    archive: BehaviorArchive,
    metrics: Sequence[Mapping[str, Any]],
    runtime_root: Path,
) -> dict[str, Any]:
    base = _carrier_gate_final_decision(
        source_sha=source_sha,
        carrier_id="BROAD_PANEL_BASELINE_X_AGGTRADES_TOP200_DELIVERED",
        state=state,
        ledger=ledger,
        archive=archive,
        metrics=metrics,
        runtime_root=runtime_root,
    )
    final_metrics = {
        str(row["arm"]): dict(row)
        for row in metrics
        if int(row["checkpoint_index"]) == V13_CHECKPOINT_COUNT - 1
    }
    random_metrics = final_metrics["canonical_typed_random"]
    comparisons = {
        arm: {
            "valid_exact_unique_per_cpu_hour_delta": float(
                final_metrics[arm]["valid_exact_unique_per_cpu_hour"]
            )
            - float(random_metrics["valid_exact_unique_per_cpu_hour"]),
            "new_behavior_families_per_1k_delta": float(
                final_metrics[arm]["new_behavior_families_per_1k_evaluations"]
            )
            - float(
                random_metrics["new_behavior_families_per_1k_evaluations"]
            ),
            "mean_search_reward_delta": float(
                final_metrics[arm]["mean_search_reward_at_matched_count"]
            )
            - float(random_metrics["mean_search_reward_at_matched_count"]),
            "top_decile_search_reward_delta": float(
                final_metrics[arm][
                    "top_decile_search_reward_at_matched_count"
                ]
            )
            - float(
                random_metrics["top_decile_search_reward_at_matched_count"]
            ),
            "mean_pair_reward_delta": float(
                final_metrics[arm]["mean_pair_reward_at_matched_count"]
            )
            - float(random_metrics["mean_pair_reward_at_matched_count"]),
            "top_decile_pair_reward_delta": float(
                final_metrics[arm]["top_decile_pair_reward_at_matched_count"]
            )
            - float(
                random_metrics["top_decile_pair_reward_at_matched_count"]
            ),
        }
        for arm in V13_ARMS[1:]
    }
    positive = sum(bool(row["matched_positive"]) for row in ledger)
    return {
        **base,
        "status": "PASS_SEARCH_ENGINE_V1_3_CROSS_CARRIER_COMPLETED",
        "checkpoint_restore_verified": (
            len(
                sorted(
                    (runtime_root / "checkpoints").glob(
                        "checkpoint_[0-9][0-9][0-9]"
                    )
                )
            )
            == V13_CHECKPOINT_COUNT
        ),
        "cross_carrier_strict_count": sum(
            bool(row.get("cross_carrier_verified")) for row in ledger
        ),
        "positive_matched_discoveries": positive,
        "arm_comparisons": comparisons,
        "research_decision": "HOLD_RESEARCH_FIXED_RETROSPECTIVE_CROSS_CARRIER",
        "future_arena_qualification": False,
        "future_new_data_arena_qualified_arms": [],
        "oi_mark_exclusion": "NO_COMMON_VERIFIED_TARGET_WINDOW",
        "core3_exclusion": "THREE_ASSET_ONLY_NOT_USED_FOR_121_ASSET_ARENA",
        "right_axis_ledger_trace": True,
    }


def _v13_report_text(decision: Mapping[str, Any]) -> str:
    return f"""# Crypto Search Engine V1.3 Cross-Carrier Arena

- Status: `{decision['status']}`
- Producer source: `{decision['producer_source_sha']}`
- Surface: existing aligned Broad39 x aggTrades44 physical carrier.
- Strict evaluated: `{decision['strict_evaluated_count']}`; cross-carrier verified: `{decision['cross_carrier_strict_count']}`.
- Positive matched discoveries: `{decision['positive_matched_discoveries']}`.
- Checkpoints: `{decision['checkpoint_count']}`, exact restore: `{decision['checkpoint_restore_verified']}`.
- Right-axis control and incremental waterfall persisted separately: `{decision['right_axis_ledger_trace']}`.
- Research decision: `{decision['research_decision']}`.
- OI/mark excluded because no verified target window overlaps another active carrier; Core3 excluded from the 121-asset Arena because its verified context has only three assets.
- Boundaries: fixed retrospective development only; no OOS, promotion, sealed reads, liquidation, or Alpha claim.
"""


def _require_bound_authority_preflight(
    repo_root: Path,
    authority_preflight: Mapping[str, Any] | None,
    *,
    economic_receipt_required: bool,
) -> dict[str, Any]:
    if not isinstance(authority_preflight, Mapping):
        raise RuntimeError("ECONOMIC_RECEIPT_PREFLIGHT_REQUIRED")
    from alphafactory_crypto.broad_search.experiment_authority import (
        require_real_experiment_authority,
    )

    receipt_path = None
    receipt_bound_authorization = None
    if economic_receipt_required:
        incoming_receipt = authority_preflight.get("economic_receipt")
        if not isinstance(incoming_receipt, Mapping):
            raise RuntimeError("ECONOMIC_RECEIPT_PREFLIGHT_REQUIRED")
        receipt_path = str(incoming_receipt.get("receipt_path") or "")
    else:
        incoming_authorization = authority_preflight.get(
            "receipt_bound_non_formal_authorization"
        )
        if isinstance(incoming_authorization, Mapping):
            receipt_bound_authorization = dict(incoming_authorization)
    verified = require_real_experiment_authority(
        repo_root,
        evidence_to_add=str(authority_preflight.get("evidence_to_add") or ""),
        decision_to_change=str(
            authority_preflight.get("decision_to_change") or ""
        ),
        economic_receipt_required=economic_receipt_required,
        economic_receipt_path=receipt_path,
        receipt_bound_non_formal_authorization=(
            receipt_bound_authorization
        ),
    )
    if verified != dict(authority_preflight):
        raise RuntimeError("ECONOMIC_RECEIPT_PREFLIGHT_CHANGED")
    return dict(verified)


def _require_bound_economic_run(
    repo_root: Path,
    authority_preflight: Mapping[str, Any] | None,
) -> dict[str, Any]:
    verified = _require_bound_authority_preflight(
        repo_root,
        authority_preflight,
        economic_receipt_required=True,
    )
    receipt = verified.get("economic_receipt")
    if not isinstance(receipt, Mapping) or receipt.get("run_authorized") is not True:
        raise RuntimeError("ECONOMIC_RECEIPT_RUN_NOT_AUTHORIZED")
    execution = dict(receipt.get("execution") or {})
    target_root = repo_root / str(execution.get("target_cache_path") or "")
    target_metadata_path = target_root / "metadata.json"
    if not target_metadata_path.is_file():
        raise RuntimeError("ECONOMIC_RECEIPT_TARGET_CACHE_MISSING")
    target_metadata = _read_json(target_metadata_path)
    for field in (
        "venue",
        "source",
        "price_field",
        "formula",
        "execution_delay_hours",
        "horizons_hours",
        "positive_price_required",
        "missing_value_fill",
        "target_cache_identity_sha256",
    ):
        observed = (
            target_metadata.get("identity_sha256")
            if field == "target_cache_identity_sha256"
            else target_metadata.get(field)
        )
        if observed != execution.get(field):
            raise RuntimeError(f"ECONOMIC_RECEIPT_TARGET_DRIFT:{field}")
    return dict(receipt)


def _bind_economic_receipt(
    frozen: Mapping[str, Any],
    receipt: Mapping[str, Any],
) -> dict[str, Any]:
    payload = {
        key: value
        for key, value in frozen.items()
        if key != "frozen_contract_sha256"
    }
    payload["economic_receipt"] = dict(receipt)
    return {**payload, "frozen_contract_sha256": _payload_sha(payload)}


def _validate_economic_search_surface(
    *,
    receipt: Mapping[str, Any],
    identities: Mapping[str, Any],
    contracts: Sequence[FieldContract],
    expected_campaign: str = ECONOMIC_SEARCH_CAMPAIGN,
    expected_seeds: Sequence[int] = SEEDS,
    expected_strict_target: int = STRICT_TARGET,
    expected_checkpoint_size: int = CHECKPOINT_SIZE,
    expected_checkpoint_count: int = CHECKPOINT_COUNT,
) -> str:
    campaign = dict(receipt.get("search_campaign") or {})
    raw_cache = dict(identities.get("raw_cache") or {})
    carrier_manifest = dict(
        identities.get("aligned_carrier_manifest") or {}
    )
    behavior_window = dict(
        identities.get("behavior_contract_window") or {}
    )
    train_partition = dict(
        dict(receipt.get("evidence_partition") or {}).get("train") or {}
    )
    checks = {
        "runner_campaign": campaign.get("runner_campaign")
        == expected_campaign,
        "carrier_id": campaign.get("carrier_id")
        == "OI_MARK_RANKS51_200_X_AGGTRADES_TOP200_ALIGNED",
        "carrier_cache_identity_sha256": (
            campaign.get("carrier_cache_identity_sha256")
            == raw_cache.get("identity_sha256")
        ),
        "carrier_manifest": (
            campaign.get("carrier_manifest")
            == carrier_manifest.get("path")
        ),
        "field_count": int(campaign.get("field_count", -1))
        == len(contracts),
        "strict_evaluated_target": int(
            campaign.get("strict_evaluated_target", -1)
        )
        == int(expected_strict_target),
        "checkpoint_size": int(campaign.get("checkpoint_size", -1))
        == int(expected_checkpoint_size),
        "checkpoint_count": int(campaign.get("checkpoint_count", -1))
        == int(expected_checkpoint_count),
        "behavior_contract_train_start": behavior_window.get("start")
        == train_partition.get("start"),
        "behavior_contract_train_end": behavior_window.get("end_exclusive")
        == train_partition.get("end_exclusive"),
        "behavior_contract_validation_read": behavior_window.get(
            "validation_read"
        )
        is False,
        "behavior_contract_holdout_read": behavior_window.get("holdout_read")
        is False,
    }
    if tuple(int(value) for value in expected_seeds) != SEEDS:
        checks["campaign_seed_set"] = tuple(
            int(value) for value in campaign.get("seed_set") or ()
        ) == tuple(int(value) for value in expected_seeds)
        expected_seed_derivation = _economic_campaign_config(
            expected_campaign
        ).get("seed_derivation")
        checks["campaign_seed_derivation"] = (
            campaign.get("seed_derivation")
            == expected_seed_derivation
        )
    failed = sorted(key for key, value in checks.items() if not value)
    if failed:
        raise RuntimeError(
            "ECONOMIC_SEARCH_SURFACE_BINDING_CHANGED:" + ",".join(failed)
        )
    return str(campaign["carrier_id"])


def apply_search_validation_kill_line(
    *,
    runtime_root: Path,
    arm_id: str,
    metrics: Mapping[str, Any],
    matched_evaluated_counts: Mapping[str, int],
    economic_receipt: Mapping[str, Any],
) -> dict[str, Any]:
    """Execute the frozen no-feedback validation stop and checkpoint action."""

    validation = dict(economic_receipt.get("validation") or {})
    kill_line = dict(economic_receipt.get("validation_kill_line") or {})
    if any(
        validation.get(field) is not False
        for field in (
            "optimizer_feedback_allowed",
            "policy_memory_write_allowed",
            "candidate_generation_allowed",
        )
    ):
        raise RuntimeError("ECONOMIC_RECEIPT_VALIDATION_WRITE_BOUNDARY_CHANGED")
    counts = {str(key): int(value) for key, value in matched_evaluated_counts.items()}
    if not counts or len(set(counts.values())) != 1:
        raise RuntimeError("VALIDATION_MATCHED_EVALUATED_COUNTS_DIFFER")
    if min(counts.values()) < int(kill_line["minimum_evaluated_per_active_arm"]):
        raise RuntimeError("VALIDATION_MATCHED_EVALUATED_COUNT_TOO_SMALL")
    from alphafactory_crypto.broad_search.experiment_authority import (
        evaluate_search_validation_kill_line,
    )

    decision = evaluate_search_validation_kill_line(metrics)
    result = {
        **decision,
        "arm_id": str(arm_id),
        "matched_evaluated_counts": counts,
        "economic_receipt_sha256": str(
            economic_receipt.get("receipt_sha256") or ""
        ),
        "validation_role": validation.get("role"),
        "holdout_read": False,
        "threshold_tuning_performed": False,
    }
    if not bool(decision["passed"]):
        checkpoint = (
            runtime_root
            / "checkpoints"
            / f"validation_kill_{str(arm_id).lower()}.json"
        )
        result["arm_stopped"] = True
        result["checkpoint_path"] = str(checkpoint)
        _write_json(checkpoint, result)
    else:
        result["arm_stopped"] = False
        result["checkpoint_path"] = None
    return result


def _policy_state_sha256(policies: Mapping[str, PolicyType]) -> str:
    return _payload_sha(
        {
            key: _export_policy(policy)
            for key, policy in sorted(policies.items())
        }
    )


def _equal_weight_path(paths: Sequence[np.ndarray]) -> np.ndarray:
    if not paths:
        raise ValueError("validation ensemble has no paths")
    arrays = [np.asarray(path, dtype=float) for path in paths]
    shapes = {array.shape for array in arrays}
    if len(shapes) != 1:
        raise ValueError("validation ensemble path shapes differ")
    stack = np.stack(arrays, axis=0)
    finite = np.isfinite(stack)
    counts = finite.sum(axis=0)
    sums = np.where(finite, stack, 0.0).sum(axis=0)
    return np.divide(
        sums,
        counts,
        out=np.full(sums.shape, np.nan, dtype=float),
        where=counts > 0,
    )


def _validation_path_summary(
    values: np.ndarray,
    *,
    horizon: int,
) -> tuple[float, float]:
    from scripts.crypto_a7reward1_portfolio_reward_model import (
        nonoverlap_metric,
        sortino,
    )

    path = np.asarray(values, dtype=float)
    finite = path[np.isfinite(path)]
    net_mean = float(np.mean(finite)) if finite.size else float("nan")
    periods_per_year = 24.0 * 365.0 / max(1, int(horizon))
    _, floor = nonoverlap_metric(
        path,
        int(horizon),
        lambda local: sortino(local, periods_per_year),
    )
    return net_mean, float(floor)


def _validation_arm_metrics(
    arm: str,
    records: Sequence[Mapping[str, Any]],
    *,
    required_horizons: Sequence[int],
) -> dict[str, Any]:
    by_horizon: dict[int, list[Mapping[str, Any]]] = defaultdict(list)
    for record in records:
        by_horizon[int(record["horizon_hours"])].append(record)
    if not by_horizon:
        raise ValueError(f"validation arm has no evaluated candidates: {arm}")
    observed_horizons = tuple(sorted(by_horizon))
    expected_horizons = tuple(sorted(int(value) for value in required_horizons))
    if observed_horizons != expected_horizons:
        raise RuntimeError(
            "VALIDATION_REQUIRED_HORIZONS_MISSING:"
            f"{arm}:expected={expected_horizons}:observed={observed_horizons}"
        )
    horizon_rows: list[dict[str, Any]] = []
    for horizon, local in sorted(by_horizon.items()):
        primary_path = _equal_weight_path(
            [
                np.asarray(row["paths"]["primary_net"], dtype=float)
                for row in local
            ]
        )
        matched_path = _equal_weight_path(
            [
                np.asarray(
                    row["paths"]["matched_component_net"][
                        str(row["matched_component"])
                    ],
                    dtype=float,
                )
                for row in local
            ]
        )
        candidate_control_paths: list[np.ndarray] = []
        control_schema_counts: Counter[str] = Counter()
        for row in local:
            controls = dict(row["paths"].get("control_net") or {})
            if not controls:
                raise ValueError(f"validation controls missing for arm: {arm}")
            control_schema_counts["|".join(sorted(str(name) for name in controls))] += 1
            candidate_control_paths.append(
                _equal_weight_path(
                    [
                        np.asarray(values, dtype=float)
                        for _, values in sorted(controls.items())
                    ]
                )
            )
        control_path = _equal_weight_path(candidate_control_paths)
        finite_control = control_path[np.isfinite(control_path)]
        control_mean = (
            float(np.mean(finite_control))
            if finite_control.size
            else float("nan")
        )
        primary_mean, floor_sortino = _validation_path_summary(
            primary_path,
            horizon=horizon,
        )
        finite_matched = matched_path[np.isfinite(matched_path)]
        matched_mean = (
            float(np.mean(finite_matched))
            if finite_matched.size
            else float("nan")
        )
        horizon_rows.append(
            {
                "horizon_hours": int(horizon),
                "candidate_count": len(local),
                "validation_net_mean": primary_mean,
                "validation_nonoverlap_floor_sortino": floor_sortino,
                "validation_matched_increment": matched_mean,
                "validation_control_net_mean": control_mean,
                "validation_control_not_dominant": bool(
                    math.isfinite(primary_mean)
                    and math.isfinite(control_mean)
                    and primary_mean > control_mean
                ),
                "control_schema_counts_json": json.dumps(
                    dict(sorted(control_schema_counts.items())),
                    sort_keys=True,
                    separators=(",", ":"),
                ),
                "control_aggregation": (
                    "EQUAL_WEIGHT_WITHIN_CANDIDATE_THEN_EQUAL_WEIGHT_CANDIDATES"
                ),
            }
        )
    return {
        "arm": str(arm),
        "matched_evaluated_count": len(records),
        "validation_net_mean": min(
            float(row["validation_net_mean"]) for row in horizon_rows
        ),
        "validation_nonoverlap_floor_sortino": min(
            float(row["validation_nonoverlap_floor_sortino"])
            for row in horizon_rows
        ),
        "validation_matched_increment": min(
            float(row["validation_matched_increment"])
            for row in horizon_rows
        ),
        "validation_control_not_dominant": all(
            bool(row["validation_control_not_dominant"])
            for row in horizon_rows
        ),
        "horizon_metrics_json": json.dumps(
            horizon_rows,
            sort_keys=True,
            separators=(",", ":"),
        ),
        "aggregation": (
            "WORST_HORIZON_EQUAL_WEIGHT_FROZEN_CANDIDATE_ENSEMBLE"
        ),
        "required_horizons_hours_json": json.dumps(
            expected_horizons,
            separators=(",", ":"),
        ),
    }


def _write_validation_top_level_artifacts(
    *,
    runtime_root: Path,
    validation_rows: Sequence[Mapping[str, Any]],
    validation_metrics: Sequence[Mapping[str, Any]],
    validation_decisions: Mapping[str, Any],
) -> None:
    _write_parquet(
        runtime_root / "validation_candidate_ledger.parquet",
        validation_rows,
    )
    _write_parquet(
        runtime_root / "validation_arm_metrics.parquet",
        validation_metrics,
    )
    _write_json(
        runtime_root / "validation_decisions.json",
        validation_decisions,
    )


