def _restore_validation_checkpoint(
    *,
    runtime_root: Path,
    checkpoint_path: Path,
    registry: TypedExpressionRegistry,
    expected_source_sha: str,
    expected_frozen_hash: str,
    expected_identities: Mapping[str, Any],
) -> tuple[
    dict[str, Any],
    dict[str, PolicyType],
    list[dict[str, Any]],
    BehaviorArchive,
    list[dict[str, Any]],
    dict[str, Any],
]:
    restored = _load_checkpoint(
        checkpoint_path=checkpoint_path,
        registry=registry,
        expected_source_sha=expected_source_sha,
        expected_frozen_hash=expected_frozen_hash,
        expected_identities=expected_identities,
    )
    validation_rows = pd.read_parquet(
        checkpoint_path / "validation_candidate_ledger.parquet"
    ).to_dict("records")
    validation_metrics = pd.read_parquet(
        checkpoint_path / "validation_arm_metrics.parquet"
    ).to_dict("records")
    validation_decisions = _read_json(
        checkpoint_path / "validation_decisions.json"
    )
    _write_validation_top_level_artifacts(
        runtime_root=runtime_root,
        validation_rows=validation_rows,
        validation_metrics=validation_metrics,
        validation_decisions=validation_decisions,
    )
    return (*restored, {**validation_decisions, "resumed": True})


def run_frozen_validation_stage(
    *,
    runtime_root: Path,
    store: RawPanelStore,
    registry: TypedExpressionRegistry,
    state: Mapping[str, Any],
    policies: Mapping[str, PolicyType],
    train_ledger: Sequence[Mapping[str, Any]],
    archive: BehaviorArchive,
    train_metrics: Sequence[Mapping[str, Any]],
    identities: Mapping[str, Any],
    economic_receipt: Mapping[str, Any],
    evaluation_runner: (
        Callable[[CandidateSpec, float], Mapping[str, Any]] | None
    ) = None,
) -> tuple[
    dict[str, Any],
    dict[str, PolicyType],
    list[dict[str, Any]],
    BehaviorArchive,
    list[dict[str, Any]],
    dict[str, Any],
]:
    """Run or exactly restore the no-feedback validation stage.

    Candidate ranking is frozen from train-only rows.  Known candidate-local
    validation degenerations are persisted and deterministically backfilled
    by that ranking within the same arm and horizon.  Validation cannot
    propose, update a policy/archive, or read the holdout.  Arms that cannot
    fill the frozen equal-count sample are written back as EXITED, so the
    existing checkpoint allocation removes them on continuation.
    """

    runtime_root = Path(runtime_root)
    checkpoint_path = runtime_root / "checkpoints" / "checkpoint_validation"
    expected_source_sha = str(state["source_sha"])
    expected_frozen_hash = str(state["frozen_contract_sha256"])
    incoming_policy_hash = _policy_state_sha256(policies)
    incoming_archive_hash = archive.state_hash()
    incoming_ledger_hash = _payload_sha(
        [str(row["candidate_id"]) for row in train_ledger]
    )
    if checkpoint_path.exists():
        manifest = _read_json(checkpoint_path / "manifest.json")
        if incoming_policy_hash != str(manifest["policy_state_sha256"]):
            raise ValueError("validation resume policy state changed")
        if incoming_archive_hash != str(manifest["archive_state_sha256"]):
            raise ValueError("validation resume archive state changed")
        if incoming_ledger_hash != str(manifest["completed_identity_sha256"]):
            raise ValueError("validation resume train ledger changed")
        restored = _restore_validation_checkpoint(
            runtime_root=runtime_root,
            checkpoint_path=checkpoint_path,
            registry=registry,
            expected_source_sha=expected_source_sha,
            expected_frozen_hash=expected_frozen_hash,
            expected_identities=identities,
        )
        (
            restored_state,
            restored_policies,
            restored_ledger,
            restored_archive,
            restored_metrics,
            validation_result,
        ) = restored
        if _payload_sha(list(train_metrics)) != _payload_sha(restored_metrics):
            raise ValueError("validation resume train metrics changed")
        return (
            restored_state,
            restored_policies,
            restored_ledger,
            restored_archive,
            restored_metrics,
            validation_result,
        )

    validation = dict(economic_receipt.get("validation") or {})
    kill_line = dict(economic_receipt.get("validation_kill_line") or {})
    if any(
        validation.get(field) is not False
        for field in (
            "optimizer_feedback_allowed",
            "policy_memory_write_allowed",
            "candidate_generation_allowed",
        )
    ):
        raise RuntimeError("ECONOMIC_RECEIPT_VALIDATION_WRITE_BOUNDARY_CHANGED")
    evaluated_per_arm = int(kill_line.get("evaluated_per_active_arm", 0))
    evaluated_per_horizon = int(
        kill_line.get("evaluated_per_arm_per_horizon", 0)
    )
    minimum = int(kill_line.get("minimum_evaluated_per_active_arm", 0))
    control_arm_id = str(
        kill_line.get("control_arm_id") or "canonical_typed_random"
    )
    required_horizons = tuple(
        int(value) for value in kill_line.get("required_horizons_hours", ())
    )
    receipt_horizons = tuple(
        int(value)
        for value in dict(economic_receipt.get("execution") or {}).get(
            "horizons_hours",
            (),
        )
    )
    if (
        evaluated_per_arm < minimum
        or minimum <= 0
        or evaluated_per_horizon <= 0
        or len(required_horizons) < 2
        or tuple(sorted(required_horizons))
        != tuple(sorted(receipt_horizons))
        or evaluated_per_horizon * len(required_horizons)
        != evaluated_per_arm
    ):
        raise RuntimeError("VALIDATION_EVALUATED_COUNT_CONTRACT_INVALID")
    if (
        kill_line.get("candidate_selection")
        != (
            "TOP_TRAIN_SEARCH_REWARD_PER_REQUIRED_HORIZON_"
            "THEN_COMPLETION_ORDINAL"
        )
    ):
        raise RuntimeError("VALIDATION_CANDIDATE_SELECTION_CHANGED")
    if (
        kill_line.get("arm_aggregation")
        != "WORST_HORIZON_EQUAL_WEIGHT_FROZEN_CANDIDATE_ENSEMBLE"
    ):
        raise RuntimeError("VALIDATION_ARM_AGGREGATION_CHANGED")

    mutable_state = dict(state)
    mutable_state["arm_states"] = dict(state.get("arm_states", {}))
    by_arm: dict[str, list[Mapping[str, Any]]] = defaultdict(list)
    for row in train_ledger:
        by_arm[str(row["arm"])].append(row)
    if control_arm_id in by_arm:
        mutable_state["arm_states"].setdefault(
            control_arm_id,
            "ACTIVE",
        )
    active_arms = sorted(
        arm
        for arm, arm_state in mutable_state["arm_states"].items()
        if str(arm_state) != "EXITED"
    )
    if not active_arms:
        raise RuntimeError("VALIDATION_HAS_NO_ACTIVE_ARMS")
    if control_arm_id not in active_arms:
        raise RuntimeError("VALIDATION_CONTROL_ARM_NOT_ACTIVE")
    selected: list[
        tuple[str, int, int, Mapping[str, Any], CandidateSpec]
    ] = []
    expected_receipt_hash = str(
        economic_receipt.get("receipt_sha256") or ""
    )
    for arm in active_arms:
        arm_selected: list[tuple[int, int, Mapping[str, Any]]] = []
        for horizon in required_horizons:
            candidates = sorted(
                (
                    row
                    for row in by_arm.get(arm, ())
                    if int(
                        CandidateSpec.from_dict(
                            json.loads(str(row["candidate_spec_json"]))
                        ).horizon_hours
                    )
                    == horizon
                ),
                key=lambda row: (
                    -float(row["search_reward"]),
                    int(row["arm_completion_ordinal"]),
                    str(row["candidate_id"]),
                ),
            )
            arm_selected.extend(
                (horizon, horizon_rank, row)
                for horizon_rank, row in enumerate(
                    candidates,
                    start=1,
                )
            )
        for rank, (horizon, horizon_rank, row) in enumerate(
            arm_selected,
            start=1,
        ):
            if row.get("search_reward_authority") != SEARCH_REWARD_AUTHORITY:
                raise RuntimeError(
                    f"VALIDATION_TRAIN_REWARD_AUTHORITY_CHANGED:{arm}"
                )
            if str(row.get("economic_receipt_sha256") or "") != (
                expected_receipt_hash
            ):
                raise RuntimeError(
                    f"VALIDATION_TRAIN_RECEIPT_IDENTITY_CHANGED:{arm}"
                )
            if (
                row.get("train_orientation_fitted") is not True
                or str(row.get("evaluation_partition") or "") != "train"
            ):
                raise RuntimeError(
                    f"VALIDATION_TRAIN_ORIENTATION_NOT_FROZEN:{arm}"
                )
            candidate = CandidateSpec.from_dict(
                json.loads(str(row["candidate_spec_json"]))
            )
            if candidate.candidate_id != str(row["candidate_id"]):
                raise RuntimeError(
                    f"VALIDATION_CANDIDATE_IDENTITY_CHANGED:{arm}"
                )
            if int(candidate.horizon_hours) != int(horizon):
                raise RuntimeError(
                    f"VALIDATION_CANDIDATE_HORIZON_CHANGED:{arm}"
                )
            selected.append(
                (arm, rank, horizon_rank, row, candidate)
            )

    if evaluation_runner is None:
        def evaluate_selected(
            candidate: CandidateSpec,
            orientation: float,
        ) -> Mapping[str, Any]:
            return evaluate_pair(
                store=store,
                registry=registry,
                candidate=candidate,
                block_start=str(validation["start"]),
                block_end=str(validation["end_exclusive"]),
                block_role=str(validation["role"]),
                behavior_contract=None,
                economic_receipt=economic_receipt,
                frozen_train_orientation=float(orientation),
                include_validation_paths=True,
            )
    else:
        evaluate_selected = evaluation_runner

    policy_hash_before = _policy_state_sha256(policies)
    archive_hash_before = archive.state_hash()
    internal_records: list[dict[str, Any]] = []
    validation_rows: list[dict[str, Any]] = []
    candidate_local_failures: list[dict[str, Any]] = []
    successful_by_arm_horizon: Counter[tuple[str, int]] = Counter()
    attempted_by_arm: Counter[str] = Counter()
    expected_tail_purge = int(
        dict(economic_receipt.get("execution") or {}).get(
            "partition_tail_purge_hours",
            -1,
        )
    )
    for arm, _pool_rank, horizon_rank, train_row, candidate in selected:
        arm_horizon = (arm, int(candidate.horizon_hours))
        if successful_by_arm_horizon[arm_horizon] >= evaluated_per_horizon:
            continue
        attempted_by_arm[arm] += 1
        rank = int(attempted_by_arm[arm])
        orientation = float(train_row["train_orientation"])
        matched_component = str(
            train_row.get("search_reward_matched_limiting_component") or ""
        )
        try:
            evaluation = dict(evaluate_selected(candidate, orientation))
        except ValueError as exc:
            reason = str(exc)
            if reason not in VALIDATION_CANDIDATE_FAIL_CLOSED_ERRORS:
                raise
            failure = {
                "arm": arm,
                "selection_rank": int(rank),
                "horizon_selection_rank": int(horizon_rank),
                "candidate_id": candidate.candidate_id,
                "horizon_hours": int(candidate.horizon_hours),
                "reason": reason,
            }
            candidate_local_failures.append(failure)
            validation_rows.append(
                {
                    "arm": arm,
                    "selection_rank": int(rank),
                    "horizon_selection_rank": int(horizon_rank),
                    "candidate_id": candidate.candidate_id,
                    "horizon_hours": int(candidate.horizon_hours),
                    "train_search_reward": float(train_row["search_reward"]),
                    "frozen_train_orientation": orientation,
                    "frozen_matched_component": matched_component,
                    "effective_block_end_exclusive": None,
                    "partition_tail_purge_hours": expected_tail_purge,
                    "validation_status": "CANDIDATE_LOCAL_FAILURE",
                    "validation_failure_reason": reason,
                    "matched_evaluated": False,
                    "validation_primary_net_mean": float("nan"),
                    "validation_primary_nonoverlap_floor_sortino": float(
                        "nan"
                    ),
                    "validation_matched_increment": float("nan"),
                    "validation_control_net_means_json": "{}",
                    "candidate_generation_performed": False,
                    "optimizer_feedback_written": False,
                    "policy_memory_written": False,
                    "holdout_read": False,
                }
            )
            continue
        if evaluation.get("candidate_id") != candidate.candidate_id:
            raise RuntimeError("VALIDATION_EVALUATION_CANDIDATE_CHANGED")
        if evaluation.get("evaluation_partition") != "validation":
            raise RuntimeError("VALIDATION_EVALUATION_PARTITION_CHANGED")
        if evaluation.get("train_orientation_fitted") is not False:
            raise RuntimeError("VALIDATION_REFIT_TRAIN_ORIENTATION")
        if float(evaluation.get("train_orientation", float("nan"))) != orientation:
            raise RuntimeError("VALIDATION_FROZEN_ORIENTATION_CHANGED")
        if int(evaluation.get("partition_tail_purge_hours", -1)) != (
            expected_tail_purge
        ):
            raise RuntimeError("VALIDATION_PARTITION_TAIL_PURGE_CHANGED")
        paths = evaluation.get("_validation_paths")
        if not isinstance(paths, Mapping):
            raise RuntimeError("VALIDATION_PATHS_MISSING")
        matched_paths = paths.get("matched_component_net")
        if (
            not isinstance(matched_paths, Mapping)
            or matched_component not in matched_paths
        ):
            raise RuntimeError(
                "VALIDATION_FROZEN_MATCHED_COMPONENT_MISSING"
            )
        internal = {
            "arm": arm,
            "selection_rank": int(rank),
            "horizon_selection_rank": int(horizon_rank),
            "candidate_id": candidate.candidate_id,
            "horizon_hours": int(candidate.horizon_hours),
            "matched_component": matched_component,
            "paths": paths,
        }
        internal_records.append(internal)
        successful_by_arm_horizon[arm_horizon] += 1
        primary_mean, floor_sortino = _validation_path_summary(
            np.asarray(paths["primary_net"], dtype=float),
            horizon=int(candidate.horizon_hours),
        )
        matched_path = np.asarray(
            matched_paths[matched_component],
            dtype=float,
        )
        finite_matched = matched_path[np.isfinite(matched_path)]
        control_means = {
            str(name): (
                float(np.mean(finite))
                if (
                    finite := np.asarray(values, dtype=float)[
                        np.isfinite(np.asarray(values, dtype=float))
                    ]
                ).size
                else float("nan")
            )
            for name, values in dict(paths.get("control_net") or {}).items()
        }
        validation_rows.append(
            {
                "arm": arm,
                "selection_rank": int(rank),
                "horizon_selection_rank": int(horizon_rank),
                "candidate_id": candidate.candidate_id,
                "horizon_hours": int(candidate.horizon_hours),
                "train_search_reward": float(train_row["search_reward"]),
                "frozen_train_orientation": orientation,
                "frozen_matched_component": matched_component,
                "effective_block_end_exclusive": evaluation.get(
                    "effective_block_end_exclusive"
                ),
                "partition_tail_purge_hours": expected_tail_purge,
                "validation_status": "EVALUATED",
                "validation_failure_reason": None,
                "matched_evaluated": True,
                "validation_primary_net_mean": primary_mean,
                "validation_primary_nonoverlap_floor_sortino": floor_sortino,
                "validation_matched_increment": (
                    float(np.mean(finite_matched))
                    if finite_matched.size
                    else float("nan")
                ),
                "validation_control_net_means_json": json.dumps(
                    control_means,
                    sort_keys=True,
                    separators=(",", ":"),
                ),
                "candidate_generation_performed": False,
                "optimizer_feedback_written": False,
                "policy_memory_written": False,
                "holdout_read": False,
            }
        )

    failures_by_arm: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for failure in candidate_local_failures:
        failures_by_arm[str(failure["arm"])].append(failure)
    validation_metrics: list[dict[str, Any]] = []
    constructible_arms: set[str] = set()
    for arm in active_arms:
        arm_records = [
            row for row in internal_records if str(row["arm"]) == arm
        ]
        arm_failures = failures_by_arm.get(arm, [])
        horizon_success_counts = {
            int(horizon): int(successful_by_arm_horizon[(arm, int(horizon))])
            for horizon in required_horizons
        }
        constructible = all(
            count == evaluated_per_horizon
            for count in horizon_success_counts.values()
        )
        reason_counts = Counter(
            str(failure["reason"]) for failure in arm_failures
        )
        common = {
            "validation_constructibility_passed": constructible,
            "validation_attempted_count": int(attempted_by_arm[arm]),
            "candidate_local_failure_count": len(arm_failures),
            "candidate_local_failure_reasons_json": json.dumps(
                dict(sorted(reason_counts.items())),
                sort_keys=True,
                separators=(",", ":"),
            ),
            "horizon_success_counts_json": json.dumps(
                horizon_success_counts,
                sort_keys=True,
                separators=(",", ":"),
            ),
        }
        if constructible:
            constructible_arms.add(arm)
            validation_metrics.append(
                {
                    **_validation_arm_metrics(
                        arm,
                        arm_records,
                        required_horizons=required_horizons,
                    ),
                    **common,
                }
            )
            continue
        validation_metrics.append(
            {
                "arm": arm,
                "matched_evaluated_count": len(arm_records),
                "validation_net_mean": float("nan"),
                "validation_nonoverlap_floor_sortino": float("nan"),
                "validation_matched_increment": float("nan"),
                "validation_control_not_dominant": False,
                "horizon_metrics_json": json.dumps(
                    [
                        {
                            "horizon_hours": int(horizon),
                            "candidate_count": horizon_success_counts[
                                int(horizon)
                            ],
                            "required_candidate_count": evaluated_per_horizon,
                        }
                        for horizon in required_horizons
                    ],
                    sort_keys=True,
                    separators=(",", ":"),
                ),
                "aggregation": (
                    "WORST_HORIZON_EQUAL_WEIGHT_FROZEN_CANDIDATE_ENSEMBLE"
                ),
                "required_horizons_hours_json": json.dumps(
                    tuple(sorted(required_horizons)),
                    separators=(",", ":"),
                ),
                **common,
            }
        )
    counts = {
        str(row["arm"]): int(row["matched_evaluated_count"])
        for row in validation_metrics
    }
    comparison_counts = {
        arm: counts[arm] for arm in sorted(constructible_arms)
    }
    control_constructible = control_arm_id in constructible_arms
    random_control_survival_required = bool(
        kill_line.get("random_control_survival_required", True)
    )
    decisions: dict[str, Any] = {}
    control_passed: bool | None = None
    ordered_validation_metrics = sorted(
        validation_metrics,
        key=lambda metric: (
            str(metric["arm"]) != control_arm_id,
            str(metric["arm"]),
        ),
    )
    for metric in ordered_validation_metrics:
        arm = str(metric["arm"])
        before = str(mutable_state["arm_states"][arm])
        constructible = metric["validation_constructibility_passed"] is True
        can_apply_economic_kill_line = constructible and (
            not random_control_survival_required
            or arm == control_arm_id
            or control_passed is True
        )
        if can_apply_economic_kill_line:
            decision = apply_search_validation_kill_line(
                runtime_root=runtime_root,
                arm_id=arm,
                metrics=metric,
                matched_evaluated_counts=comparison_counts,
                economic_receipt=economic_receipt,
            )
        else:
            if not constructible:
                failure_reason = "VALIDATION_ARM_EQUAL_COUNT_UNAVAILABLE"
            elif random_control_survival_required and not control_constructible:
                failure_reason = (
                    "VALIDATION_CONTROL_ARM_EQUAL_COUNT_UNAVAILABLE"
                )
            else:
                failure_reason = "VALIDATION_CONTROL_ARM_FAILED_KILL_LINE"
            checkpoint = (
                runtime_root
                / "checkpoints"
                / f"validation_kill_{arm.lower()}.json"
            )
            decision = {
                "result": "FAIL_STOP_ARM_AND_WRITE_CHECKPOINT",
                "passed": False,
                "conditions": {
                    "validation_equal_count_constructible": constructible,
                    "validation_control_arm_constructible": (
                        control_constructible
                    ),
                    "validation_control_arm_passed": control_passed is True,
                },
                "failure_reason": failure_reason,
                "arm_id": arm,
                "matched_evaluated_counts": counts,
                "equal_count_comparison_counts": comparison_counts,
                "candidate_local_failure_count": int(
                    metric["candidate_local_failure_count"]
                ),
                "economic_receipt_sha256": str(
                    economic_receipt.get("receipt_sha256") or ""
                ),
                "validation_role": validation.get("role"),
                "holdout_read": False,
                "threshold_tuning_performed": False,
                "optimizer_feedback_written": False,
                "policy_memory_written": False,
                "candidate_generation_performed": False,
                "arm_stopped": True,
                "checkpoint_path": str(checkpoint),
            }
            _write_json(checkpoint, decision)
        if arm == control_arm_id:
            control_passed = bool(decision["passed"])
        after = before if bool(decision["passed"]) else "EXITED"
        mutable_state["arm_states"][arm] = after
        decisions[arm] = {
            **decision,
            "state_before": before,
            "state_after": after,
        }

    policy_hash_after = _policy_state_sha256(policies)
    archive_hash_after = archive.state_hash()
    if policy_hash_after != policy_hash_before:
        raise RuntimeError("VALIDATION_MUTATED_POLICY_STATE")
    if archive_hash_after != archive_hash_before:
        raise RuntimeError("VALIDATION_MUTATED_ARCHIVE_STATE")
    validation_decisions = {
        "schema_version": 1,
        "status": "VALIDATION_STAGE_COMPLETE",
        "matched_evaluated_counts": counts,
        "equal_count_comparison_counts": comparison_counts,
        "validation_attempted_counts": {
            arm: int(attempted_by_arm[arm]) for arm in active_arms
        },
        "candidate_local_failure_counts": {
            arm: len(failures_by_arm.get(arm, ())) for arm in active_arms
        },
        "candidate_local_failure_handling": (
            "RECORD_AND_DETERMINISTICALLY_BACKFILL_BY_FROZEN_TRAIN_RANK_"
            "WITHIN_ARM_HORIZON"
        ),
        "candidate_local_failures": candidate_local_failures,
        "orchestration_campaign": kill_line["orchestration_campaign"],
        "trigger_after_train_checkpoint_index": int(
            kill_line["trigger_after_train_checkpoint_index"]
        ),
        "required_horizons_hours": list(required_horizons),
        "evaluated_per_arm_per_horizon": evaluated_per_horizon,
        "candidate_selection": kill_line["candidate_selection"],
        "arm_aggregation": kill_line["arm_aggregation"],
        "random_control_survival_required": random_control_survival_required,
        "control_arm_id": control_arm_id,
        "arm_decisions": decisions,
        "arm_state_after": dict(sorted(mutable_state["arm_states"].items())),
        "policy_state_sha256_before": policy_hash_before,
        "policy_state_sha256_after": policy_hash_after,
        "archive_state_sha256_before": archive_hash_before,
        "archive_state_sha256_after": archive_hash_after,
        "candidate_generation_performed": False,
        "optimizer_feedback_written": False,
        "policy_memory_written": False,
        "holdout_read": False,
        "threshold_tuning_performed": False,
        "economic_receipt_sha256": expected_receipt_hash,
    }
    mutable_state["validation_stage"] = {
        **validation_decisions,
        "validation_candidate_ledger_sha256": _payload_sha(validation_rows),
        "validation_arm_metrics_sha256": _payload_sha(validation_metrics),
    }
    checkpoint_path = _write_checkpoint(
        runtime_root=runtime_root,
        label="checkpoint_validation",
        checkpoint_index=int(mutable_state["next_checkpoint_index"]),
        registry=registry,
        state=mutable_state,
        policies=policies,
        ledger=train_ledger,
        archive=archive,
        metrics=train_metrics,
        identities=identities,
        validation_rows=validation_rows,
        validation_metrics=validation_metrics,
        validation_decisions=validation_decisions,
    )
    (
        restored_state,
        restored_policies,
        restored_ledger,
        restored_archive,
        restored_metrics,
    ) = _load_checkpoint(
        checkpoint_path=checkpoint_path,
        registry=registry,
        expected_source_sha=expected_source_sha,
        expected_frozen_hash=expected_frozen_hash,
        expected_identities=identities,
    )
    _write_validation_top_level_artifacts(
        runtime_root=runtime_root,
        validation_rows=validation_rows,
        validation_metrics=validation_metrics,
        validation_decisions=validation_decisions,
    )
    return (
        restored_state,
        restored_policies,
        restored_ledger,
        restored_archive,
        restored_metrics,
        {**validation_decisions, "resumed": False},
    )


def _v23_candidate_horizon(row: Mapping[str, Any]) -> int:
    return int(
        CandidateSpec.from_dict(
            json.loads(str(row["candidate_spec_json"]))
        ).horizon_hours
    )


def _v23_stratified_candidate_rows(
    rows: Sequence[Mapping[str, Any]],
    *,
    excluded_ids: set[str],
    stratum_count: int,
) -> dict[int, list[Mapping[str, Any]]]:
    ordered = sorted(
        rows,
        key=lambda row: (
            int(row["arm_completion_ordinal"]),
            str(row["candidate_id"]),
        ),
    )
    if len(ordered) < stratum_count:
        raise RuntimeError("V23_VALIDATION_STRATUM_UNDERFILLED")
    output: dict[int, list[Mapping[str, Any]]] = {
        index: [] for index in range(stratum_count)
    }
    for ordinal, row in enumerate(ordered):
        stratum = min(stratum_count - 1, ordinal * stratum_count // len(ordered))
        if str(row["candidate_id"]) not in excluded_ids:
            output[stratum].append(row)
    for stratum, local in output.items():
        local.sort(
            key=lambda row: (
                hashlib.sha256(
                    (
                        f"{MECHANISM_SEARCH_V23_EPOCH_ID}|stratified|{stratum}|"
                        f"{row['candidate_id']}"
                    ).encode()
                ).hexdigest(),
                int(row["arm_completion_ordinal"]),
                str(row["candidate_id"]),
            )
        )
    return output


def _v23_daily_path(values: np.ndarray) -> np.ndarray:
    path = np.asarray(values, dtype=float)
    if path.ndim != 1:
        raise ValueError("V23 validation path must be one-dimensional")
    day_count = int(math.ceil(path.size / 24.0))
    padded = np.full(day_count * 24, np.nan, dtype=float)
    padded[: path.size] = path
    matrix = padded.reshape(day_count, 24)
    finite = np.isfinite(matrix)
    counts = finite.sum(axis=1)
    sums = np.where(finite, matrix, 0.0).sum(axis=1)
    return np.divide(
        sums,
        counts,
        out=np.full(day_count, np.nan, dtype=float),
        where=counts > 0,
    )


def _v23_paired_block_effect(
    left: np.ndarray,
    right: np.ndarray,
    *,
    seed: int,
    horizon: int,
    comparison: str,
    metric: str,
    block_length: int,
    replications: int,
    lower_quantile: float,
) -> dict[str, Any]:
    left_values = np.asarray(left, dtype=float)
    right_values = np.asarray(right, dtype=float)
    if left_values.shape != right_values.shape:
        raise ValueError("V23 paired validation paths differ in shape")
    delta = right_values - left_values
    delta = delta[np.isfinite(delta)]
    if delta.size < block_length:
        raise RuntimeError("V23_PAIRED_DAILY_PATH_TOO_SHORT")
    bootstrap_seed = int.from_bytes(
        hashlib.sha256(
            (
                f"{MECHANISM_SEARCH_V23_EPOCH_ID}|validation-bootstrap|{seed}|"
                f"{horizon}|{comparison}|{metric}"
            ).encode()
        ).digest()[:4],
        "big",
    )
    rng = np.random.default_rng(bootstrap_seed)
    block_count = int(math.ceil(delta.size / block_length))
    sample_means = np.empty(replications, dtype=float)
    offsets = np.arange(block_length, dtype=int)
    for replication in range(replications):
        starts = rng.integers(0, delta.size, size=block_count)
        indexes = (starts[:, None] + offsets[None, :]) % delta.size
        sample_means[replication] = float(
            np.mean(delta[indexes.reshape(-1)[: delta.size]])
        )
    observed = float(np.mean(delta))
    lower = float(np.quantile(sample_means, lower_quantile))
    return {
        "observed_mean_delta": observed,
        "bootstrap_lower_quantile": lower,
        "passed": bool(observed > 0.0 and lower > 0.0),
        "paired_day_count": int(delta.size),
        "block_length_days": int(block_length),
        "replications": int(replications),
        "lower_quantile": float(lower_quantile),
        "bootstrap_seed": bootstrap_seed,
    }


def _v23_attribution_projection(
    relative_cells: Sequence[Mapping[str, Any]],
    absolute_cells: Sequence[Mapping[str, Any]],
) -> tuple[dict[str, bool], bool, bool]:
    component_pass: dict[str, bool] = {}
    for comparison in (
        "proposal_distribution",
        "train_ranker",
        "total_policy",
    ):
        local = [
            row
            for row in relative_cells
            if str(row.get("comparison")) == comparison
        ]
        component_pass[comparison] = len(local) == 4 and all(
            bool(row.get("passed")) for row in local
        )
    absolute_pass = len(absolute_cells) == 4 and all(
        bool(row.get("passed")) for row in absolute_cells
    )
    return component_pass, absolute_pass, bool(
        absolute_pass and all(component_pass.values())
    )


def _v23_cohort_metric_and_paths(
    *,
    cohort: str,
    arm: str,
    seed: int,
    horizon: int,
    records: Sequence[Mapping[str, Any]],
    validation_start: str,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    primary_path = _equal_weight_path(
        [np.asarray(row["paths"]["primary_net"], dtype=float) for row in records]
    )
    matched_path = _equal_weight_path(
        [
            np.asarray(
                row["paths"]["matched_component_net"][row["matched_component"]],
                dtype=float,
            )
            for row in records
        ]
    )
    candidate_controls: list[np.ndarray] = []
    control_schema_counts: Counter[str] = Counter()
    for row in records:
        controls = dict(row["paths"].get("control_net") or {})
        if not controls:
            raise RuntimeError("V23_VALIDATION_CONTROLS_MISSING")
        control_schema_counts["|".join(sorted(str(key) for key in controls))] += 1
        candidate_controls.append(
            _equal_weight_path(
                [np.asarray(values, dtype=float) for _, values in sorted(controls.items())]
            )
        )
    control_path = _equal_weight_path(candidate_controls)
    primary_mean, floor_sortino = _validation_path_summary(
        primary_path,
        horizon=horizon,
    )
    finite_matched = matched_path[np.isfinite(matched_path)]
    finite_control = control_path[np.isfinite(control_path)]
    matched_mean = (
        float(np.mean(finite_matched)) if finite_matched.size else float("nan")
    )
    control_mean = (
        float(np.mean(finite_control)) if finite_control.size else float("nan")
    )
    primary_daily = _v23_daily_path(primary_path)
    matched_daily = _v23_daily_path(matched_path)
    control_daily = _v23_daily_path(control_path)
    start = pd.Timestamp(validation_start)
    path_rows = [
        {
            "cohort": cohort,
            "arm": arm,
            "seed": int(seed),
            "horizon_hours": int(horizon),
            "day_ordinal": int(day),
            "utc_day": (start + pd.Timedelta(days=day)).strftime("%Y-%m-%d"),
            "primary_net": float(primary_daily[day]),
            "matched_increment": float(matched_daily[day]),
            "control_net": float(control_daily[day]),
        }
        for day in range(len(primary_daily))
    ]
    metric = {
        "cohort": cohort,
        "arm": arm,
        "seed": int(seed),
        "horizon_hours": int(horizon),
        "matched_evaluated_count": len(records),
        "validation_net_mean": primary_mean,
        "validation_nonoverlap_floor_sortino": floor_sortino,
        "validation_matched_increment": matched_mean,
        "validation_control_net_mean": control_mean,
        "validation_control_not_dominant": bool(
            math.isfinite(primary_mean)
            and math.isfinite(control_mean)
            and primary_mean > control_mean
        ),
        "control_schema_counts_json": json.dumps(
            dict(sorted(control_schema_counts.items())),
            sort_keys=True,
            separators=(",", ":"),
        ),
        "daily_path_row_count": len(path_rows),
        "aggregation": "EQUAL_WEIGHT_CANDIDATES_WITHIN_SEED_HORIZON_COHORT",
    }
    return metric, path_rows


def _write_v23_validation_top_level_artifacts(
    *,
    runtime_root: Path,
    validation_rows: Sequence[Mapping[str, Any]],
    validation_metrics: Sequence[Mapping[str, Any]],
    validation_paths: Sequence[Mapping[str, Any]],
    validation_decisions: Mapping[str, Any],
) -> None:
    _write_validation_top_level_artifacts(
        runtime_root=runtime_root,
        validation_rows=validation_rows,
        validation_metrics=validation_metrics,
        validation_decisions=validation_decisions,
    )
    _write_parquet(
        runtime_root / "validation_cohort_paths.parquet",
        validation_paths,
    )


def _restore_v23_validation_checkpoint(
    *,
    runtime_root: Path,
    checkpoint_path: Path,
    registry: TypedExpressionRegistry,
    expected_source_sha: str,
    expected_frozen_hash: str,
    expected_identities: Mapping[str, Any],
) -> tuple[
    dict[str, Any],
    dict[str, PolicyType],
    list[dict[str, Any]],
    BehaviorArchive,
    list[dict[str, Any]],
    dict[str, Any],
]:
    restored = _load_checkpoint(
        checkpoint_path=checkpoint_path,
        registry=registry,
        expected_source_sha=expected_source_sha,
        expected_frozen_hash=expected_frozen_hash,
        expected_identities=expected_identities,
    )
    validation_rows = pd.read_parquet(
        checkpoint_path / "validation_candidate_ledger.parquet"
    ).to_dict("records")
    validation_metrics = pd.read_parquet(
        checkpoint_path / "validation_arm_metrics.parquet"
    ).to_dict("records")
    validation_paths = pd.read_parquet(
        checkpoint_path / "validation_cohort_paths.parquet"
    ).to_dict("records")
    validation_decisions = _read_json(checkpoint_path / "validation_decisions.json")
    _write_v23_validation_top_level_artifacts(
        runtime_root=runtime_root,
        validation_rows=validation_rows,
        validation_metrics=validation_metrics,
        validation_paths=validation_paths,
        validation_decisions=validation_decisions,
    )
    return (*restored, {**validation_decisions, "resumed": True})


def run_v23_policy_attribution_validation(
    *,
    repo_root: Path,
    runtime_root: Path,
    store: RawPanelStore,
    registry: TypedExpressionRegistry,
    state: Mapping[str, Any],
    policies: Mapping[str, PolicyType],
    train_ledger: Sequence[Mapping[str, Any]],
    archive: BehaviorArchive,
    train_metrics: Sequence[Mapping[str, Any]],
    identities: Mapping[str, Any],
    economic_receipt: Mapping[str, Any],
    evaluation_runner: Callable[[CandidateSpec, float], Mapping[str, Any]] | None = None,
) -> tuple[
    dict[str, Any],
    dict[str, PolicyType],
    list[dict[str, Any]],
    BehaviorArchive,
    list[dict[str, Any]],
    dict[str, Any],
]:
    config, _, _ = _load_mechanism_v23_contract(repo_root)
    contract = dict(config["validation"])
    checkpoint_path = runtime_root / "checkpoints" / "checkpoint_validation"
    expected_source_sha = str(state["source_sha"])
    expected_frozen_hash = str(state["frozen_contract_sha256"])
    if checkpoint_path.exists():
        return _restore_v23_validation_checkpoint(
            runtime_root=runtime_root,
            checkpoint_path=checkpoint_path,
            registry=registry,
            expected_source_sha=expected_source_sha,
            expected_frozen_hash=expected_frozen_hash,
            expected_identities=identities,
        )
    if len(train_ledger) != MECHANISM_SEARCH_V23_QUALIFICATION_STRICT_COUNT:
        raise RuntimeError("V23_VALIDATION_TRAIN_COUNT_CHANGED")
    validation = dict(economic_receipt.get("validation") or {})
    if any(
        validation.get(field) is not False
        for field in (
            "optimizer_feedback_allowed",
            "policy_memory_write_allowed",
            "candidate_generation_allowed",
        )
    ):
        raise RuntimeError("ECONOMIC_RECEIPT_VALIDATION_WRITE_BOUNDARY_CHANGED")
    expected_receipt_hash = str(economic_receipt.get("receipt_sha256") or "")
    required_horizons = tuple(int(value) for value in contract["required_horizons_hours"])
    cohort_size = int(contract["cohort_size_per_seed_horizon"])
    selection = dict(contract["selection"])
    stratum_count = int(selection["stratum_count"])
    per_stratum = int(selection["successful_candidates_per_stratum"])
    if stratum_count * per_stratum != cohort_size:
        raise RuntimeError("V23_VALIDATION_STRATIFICATION_COUNT_CHANGED")
    arm_by_kind = {
        "random": "expanded_mechanism_random_v2_3",
        "evolution": "mechanism_evolution_v2_3",
    }
    by_cell: dict[tuple[str, int, int], list[Mapping[str, Any]]] = defaultdict(list)
    for row in train_ledger:
        key = (str(row["arm"]), int(row["seed"]), _v23_candidate_horizon(row))
        by_cell[key].append(row)
    if evaluation_runner is None:
        def evaluate_selected(
            candidate: CandidateSpec,
            orientation: float,
        ) -> Mapping[str, Any]:
            return evaluate_pair(
                store=store,
                registry=registry,
                candidate=candidate,
                block_start=str(validation["start"]),
                block_end=str(validation["end_exclusive"]),
                block_role=str(validation["role"]),
                behavior_contract=None,
                economic_receipt=economic_receipt,
                frozen_train_orientation=float(orientation),
                include_validation_paths=True,
            )
    else:
        evaluate_selected = evaluation_runner

    policy_hash_before = _policy_state_sha256(policies)
    archive_hash_before = archive.state_hash()
    validation_rows: list[dict[str, Any]] = []
    internal_records: list[dict[str, Any]] = []
    failure_rows: list[dict[str, Any]] = []
    attempted_by_cell: dict[tuple[str, int, int], set[str]] = defaultdict(set)

    def evaluate_row(
        *,
        cohort: str,
        arm: str,
        seed: int,
        horizon: int,
        selection_rank: int,
        stratum: int | None,
        row: Mapping[str, Any],
    ) -> bool:
        candidate_id = str(row["candidate_id"])
        attempted_by_cell[(arm, seed, horizon)].add(candidate_id)
        if row.get("search_reward_authority") != SEARCH_REWARD_AUTHORITY:
            raise RuntimeError("V23_VALIDATION_TRAIN_REWARD_AUTHORITY_CHANGED")
        if str(row.get("economic_receipt_sha256") or "") != expected_receipt_hash:
            raise RuntimeError("V23_VALIDATION_TRAIN_RECEIPT_IDENTITY_CHANGED")
        if (
            row.get("train_orientation_fitted") is not True
            or str(row.get("evaluation_partition") or "") != "train"
        ):
            raise RuntimeError("V23_VALIDATION_TRAIN_ORIENTATION_NOT_FROZEN")
        candidate = CandidateSpec.from_dict(json.loads(str(row["candidate_spec_json"])))
        if candidate.candidate_id != candidate_id or int(candidate.horizon_hours) != horizon:
            raise RuntimeError("V23_VALIDATION_CANDIDATE_IDENTITY_CHANGED")
        orientation = float(row["train_orientation"])
        matched_component = str(
            row.get("search_reward_matched_limiting_component") or ""
        )
        try:
            evaluation = dict(evaluate_selected(candidate, orientation))
        except ValueError as exc:
            reason = str(exc)
            if reason not in VALIDATION_CANDIDATE_FAIL_CLOSED_ERRORS:
                raise
            failure = {
                "cohort": cohort,
                "arm": arm,
                "seed": int(seed),
                "horizon_hours": int(horizon),
                "selection_rank": int(selection_rank),
                "stratum": stratum,
                "candidate_id": candidate_id,
                "reason": reason,
            }
            failure_rows.append(failure)
            validation_rows.append(
                {
                    **failure,
                    "train_search_reward": float(row["search_reward"]),
                    "frozen_train_orientation": orientation,
                    "frozen_matched_component": matched_component,
                    "validation_status": "CANDIDATE_LOCAL_FAILURE",
                    "matched_evaluated": False,
                    "candidate_generation_performed": False,
                    "optimizer_feedback_written": False,
                    "policy_memory_written": False,
                    "holdout_read": False,
                }
            )
            return False
        if (
            evaluation.get("candidate_id") != candidate_id
            or evaluation.get("evaluation_partition") != "validation"
            or evaluation.get("train_orientation_fitted") is not False
            or float(evaluation.get("train_orientation", float("nan"))) != orientation
        ):
            raise RuntimeError("V23_VALIDATION_EVALUATION_CONTRACT_CHANGED")
        paths = evaluation.get("_validation_paths")
        if not isinstance(paths, Mapping):
            raise RuntimeError("V23_VALIDATION_PATHS_MISSING")
        matched_paths = paths.get("matched_component_net")
        if not isinstance(matched_paths, Mapping) or matched_component not in matched_paths:
            raise RuntimeError("V23_VALIDATION_FROZEN_MATCHED_COMPONENT_MISSING")
        internal_records.append(
            {
                "cohort": cohort,
                "arm": arm,
                "seed": int(seed),
                "horizon_hours": int(horizon),
                "candidate_id": candidate_id,
                "matched_component": matched_component,
                "paths": paths,
            }
        )
        primary_mean, floor_sortino = _validation_path_summary(
            np.asarray(paths["primary_net"], dtype=float),
            horizon=horizon,
        )
        matched_path = np.asarray(matched_paths[matched_component], dtype=float)
        finite_matched = matched_path[np.isfinite(matched_path)]
        validation_rows.append(
            {
                "cohort": cohort,
                "arm": arm,
                "seed": int(seed),
                "horizon_hours": int(horizon),
                "selection_rank": int(selection_rank),
                "stratum": stratum,
                "candidate_id": candidate_id,
                "train_search_reward": float(row["search_reward"]),
                "frozen_train_orientation": orientation,
                "frozen_matched_component": matched_component,
                "effective_block_end_exclusive": evaluation.get(
                    "effective_block_end_exclusive"
                ),
                "validation_status": "EVALUATED",
                "matched_evaluated": True,
                "validation_primary_net_mean": primary_mean,
                "validation_primary_nonoverlap_floor_sortino": floor_sortino,
                "validation_matched_increment": (
                    float(np.mean(finite_matched))
                    if finite_matched.size
                    else float("nan")
                ),
                "candidate_generation_performed": False,
                "optimizer_feedback_written": False,
                "policy_memory_written": False,
                "holdout_read": False,
            }
        )
        return True

    for seed in MECHANISM_SEARCH_V23_SEEDS:
        for horizon in required_horizons:
            for kind, arm in arm_by_kind.items():
                local = list(by_cell.get((arm, seed, horizon), ()))
                if len(local) < cohort_size * 3:
                    raise RuntimeError("V23_VALIDATION_TRAIN_CELL_UNDERFILLED")
                top_cohort = f"{kind}_train_top"
                top_rows = sorted(
                    local,
                    key=lambda row: (
                        -float(row["search_reward"]),
                        int(row["arm_completion_ordinal"]),
                        str(row["candidate_id"]),
                    ),
                )
                top_success = 0
                for rank, row in enumerate(top_rows, start=1):
                    if evaluate_row(
                        cohort=top_cohort,
                        arm=arm,
                        seed=seed,
                        horizon=horizon,
                        selection_rank=rank,
                        stratum=None,
                        row=row,
                    ):
                        top_success += 1
                    if top_success == cohort_size:
                        break
                if top_success != cohort_size:
                    raise RuntimeError("V23_VALIDATION_TOP_COHORT_UNDERFILLED")
                stratified_cohort = f"{kind}_stratified"
                strata = _v23_stratified_candidate_rows(
                    local,
                    excluded_ids=attempted_by_cell[(arm, seed, horizon)],
                    stratum_count=stratum_count,
                )
                for stratum in range(stratum_count):
                    successes = 0
                    for rank, row in enumerate(strata[stratum], start=1):
                        if evaluate_row(
                            cohort=stratified_cohort,
                            arm=arm,
                            seed=seed,
                            horizon=horizon,
                            selection_rank=rank,
                            stratum=stratum,
                            row=row,
                        ):
                            successes += 1
                        if successes == per_stratum:
                            break
                    if successes != per_stratum:
                        raise RuntimeError("V23_VALIDATION_STRATUM_UNDERFILLED")

    validation_metrics: list[dict[str, Any]] = []
    validation_paths: list[dict[str, Any]] = []
    for cohort in contract["cohorts"]:
        arm = arm_by_kind["random" if str(cohort).startswith("random") else "evolution"]
        for seed in MECHANISM_SEARCH_V23_SEEDS:
            for horizon in required_horizons:
                records = [
                    row
                    for row in internal_records
                    if str(row["cohort"]) == str(cohort)
                    and int(row["seed"]) == seed
                    and int(row["horizon_hours"]) == horizon
                ]
                if len(records) != cohort_size:
                    raise RuntimeError("V23_VALIDATION_COHORT_COUNT_CHANGED")
                metric, path_rows = _v23_cohort_metric_and_paths(
                    cohort=str(cohort),
                    arm=arm,
                    seed=seed,
                    horizon=horizon,
                    records=records,
                    validation_start=str(validation["start"]),
                )
                validation_metrics.append(metric)
                validation_paths.extend(path_rows)

    path_lookup: dict[tuple[str, int, int, str], np.ndarray] = {}
    for cohort in contract["cohorts"]:
        for seed in MECHANISM_SEARCH_V23_SEEDS:
            for horizon in required_horizons:
                local = sorted(
                    (
                        row
                        for row in validation_paths
                        if str(row["cohort"]) == str(cohort)
                        and int(row["seed"]) == seed
                        and int(row["horizon_hours"]) == horizon
                    ),
                    key=lambda row: int(row["day_ordinal"]),
                )
                for field in ("primary_net", "matched_increment", "control_net"):
                    path_lookup[(str(cohort), seed, horizon, field)] = np.asarray(
                        [float(row[field]) for row in local],
                        dtype=float,
                    )
    comparisons = {
        "proposal_distribution": ("random_stratified", "evolution_stratified"),
        "train_ranker": ("evolution_stratified", "evolution_train_top"),
        "total_policy": ("random_train_top", "evolution_train_top"),
    }
    bootstrap = dict(contract["paired_block_bootstrap"])
    relative_cells: list[dict[str, Any]] = []
    for comparison, (left, right) in comparisons.items():
        for seed in MECHANISM_SEARCH_V23_SEEDS:
            for horizon in required_horizons:
                effects = {
                    metric: _v23_paired_block_effect(
                        path_lookup[(left, seed, horizon, metric)],
                        path_lookup[(right, seed, horizon, metric)],
                        seed=seed,
                        horizon=horizon,
                        comparison=comparison,
                        metric=metric,
                        block_length=int(bootstrap["block_length_days"]),
                        replications=int(bootstrap["replications"]),
                        lower_quantile=float(bootstrap["lower_quantile"]),
                    )
                    for metric in ("primary_net", "matched_increment")
                }
                relative_cells.append(
                    {
                        "comparison": comparison,
                        "left_cohort": left,
                        "right_cohort": right,
                        "seed": int(seed),
                        "horizon_hours": int(horizon),
                        "effects": effects,
                        "passed": all(row["passed"] for row in effects.values()),
                    }
                )
    from alphafactory_crypto.broad_search.experiment_authority import (
        evaluate_search_validation_kill_line,
    )

    absolute_cells: list[dict[str, Any]] = []
    for metric in validation_metrics:
        if str(metric["cohort"]) != "evolution_train_top":
            continue
        gate = evaluate_search_validation_kill_line(metric)
        absolute_cells.append(
            {
                "seed": int(metric["seed"]),
                "horizon_hours": int(metric["horizon_hours"]),
                **gate,
            }
        )
    component_pass, absolute_pass, full_policy_pass = _v23_attribution_projection(
        relative_cells,
        absolute_cells,
    )
    mutable_state = dict(state)
    mutable_state["arm_states"] = dict(state.get("arm_states") or {})
    mutable_state["arm_states"]["expanded_mechanism_random_v2_3"] = "EXITED"
    mutable_state["arm_states"]["mechanism_evolution_v2_3"] = (
        "ACTIVE" if full_policy_pass else "EXITED"
    )
    if _policy_state_sha256(policies) != policy_hash_before:
        raise RuntimeError("V23_VALIDATION_MUTATED_POLICY_STATE")
    if archive.state_hash() != archive_hash_before:
        raise RuntimeError("V23_VALIDATION_MUTATED_ARCHIVE_STATE")
    evaluated_counts = Counter(
        str(row["cohort"])
        for row in validation_rows
        if row.get("validation_status") == "EVALUATED"
    )
    validation_decisions = {
        "schema_version": 1,
        "status": "VALIDATION_STAGE_COMPLETE",
        "orchestration_campaign": MECHANISM_SEARCH_V23_CAMPAIGN,
        "trigger_after_train_checkpoint_index": 7,
        "cohort_evaluated_counts": dict(sorted(evaluated_counts.items())),
        "strict_candidate_cohort_evaluated_count": sum(evaluated_counts.values()),
        "candidate_local_failure_count": len(failure_rows),
        "candidate_local_failures": failure_rows,
        "random_role": "COMPARATOR_ONLY_NO_PROFITABILITY_SURVIVAL_REQUIREMENT",
        "random_profitability_survival_required": False,
        "absolute_kill_line_applies_to": "evolution_train_top",
        "absolute_cells": absolute_cells,
        "absolute_evolution_top_passed": absolute_pass,
        "relative_cells": relative_cells,
        "component_pass": component_pass,
        "proposal_distribution_qualified": component_pass["proposal_distribution"],
        "train_ranker_qualified": component_pass["train_ranker"],
        "total_policy_relative_qualified": component_pass["total_policy"],
        "full_evolution_policy_pass": full_policy_pass,
        "continuation_authorized": full_policy_pass,
        "arm_state_after": dict(sorted(mutable_state["arm_states"].items())),
        "policy_state_sha256_before": policy_hash_before,
        "policy_state_sha256_after": _policy_state_sha256(policies),
        "archive_state_sha256_before": archive_hash_before,
        "archive_state_sha256_after": archive.state_hash(),
        "candidate_generation_performed": False,
        "optimizer_feedback_written": False,
        "policy_memory_written": False,
        "holdout_read": False,
        "threshold_tuning_performed": False,
        "economic_receipt_sha256": expected_receipt_hash,
    }
    mutable_state["validation_stage"] = {
        **validation_decisions,
        "validation_candidate_ledger_sha256": _payload_sha(validation_rows),
        "validation_arm_metrics_sha256": _payload_sha(validation_metrics),
        "validation_cohort_paths_sha256": _payload_sha(validation_paths),
    }
    checkpoint_path = _write_checkpoint(
        runtime_root=runtime_root,
        label="checkpoint_validation",
        checkpoint_index=int(mutable_state["next_checkpoint_index"]),
        registry=registry,
        state=mutable_state,
        policies=policies,
        ledger=train_ledger,
        archive=archive,
        metrics=train_metrics,
        identities=identities,
        validation_rows=validation_rows,
        validation_metrics=validation_metrics,
        validation_decisions=validation_decisions,
        validation_paths=validation_paths,
    )
    restored = _load_checkpoint(
        checkpoint_path=checkpoint_path,
        registry=registry,
        expected_source_sha=expected_source_sha,
        expected_frozen_hash=expected_frozen_hash,
        expected_identities=identities,
    )
    _write_v23_validation_top_level_artifacts(
        runtime_root=runtime_root,
        validation_rows=validation_rows,
        validation_metrics=validation_metrics,
        validation_paths=validation_paths,
        validation_decisions=validation_decisions,
    )
    return (*restored, {**validation_decisions, "resumed": False})


def _v23_oos_projection_rows(frame: pd.DataFrame) -> list[dict[str, Any]]:
    selected = frame[
        frame["validation_status"].eq("EVALUATED")
        & frame["matched_evaluated"].eq(True)
    ].copy()
    selected = selected.sort_values(
        ["cohort", "seed", "horizon_hours", "selection_rank", "candidate_id"],
        kind="stable",
    )
    columns = (
        "cohort",
        "arm",
        "seed",
        "horizon_hours",
        "selection_rank",
        "stratum",
        "candidate_id",
        "frozen_train_orientation",
        "frozen_matched_component",
    )
    integer_columns = {
        "seed",
        "horizon_hours",
        "selection_rank",
        "stratum",
        "frozen_train_orientation",
    }
    rows: list[dict[str, Any]] = []
    for record in selected[list(columns)].to_dict("records"):
        rows.append(
            {
                key: (
                    None
                    if pd.isna(value)
                    else int(value)
                    if key in integer_columns
                    else str(value)
                )
                for key, value in record.items()
            }
        )
    return rows


def _load_v23_oos_receipt(
    repo_root: Path,
    *,
    require_authorized: bool,
) -> dict[str, Any]:
    path = repo_root / V23_OOS_RECEIPT_PATH
    if not path.is_file():
        raise RuntimeError("V23_OOS_RECEIPT_MISSING")
    receipt = _read_json(path)
    blockers: list[str] = []
    status = str(receipt.get("status") or "")
    allowed_statuses = {
        "RUN_AUTHORIZED_ONE_TIME_FROZEN_OOS_REPLAY",
        "RUN_AUTHORIZATION_CONSUMED_OOS_REPLAY_COMPLETE",
    }
    if receipt.get("schema_version") != 1:
        blockers.append("schema_version")
    if receipt.get("receipt_id") != "CRYPTO_SEARCH_V2_3_FROZEN_OOS_RECEIPT":
        blockers.append("receipt_id")
    if status not in allowed_statuses:
        blockers.append("status")
    expected_authorized = status == "RUN_AUTHORIZED_ONE_TIME_FROZEN_OOS_REPLAY"
    if receipt.get("run_authorized") is not expected_authorized:
        blockers.append("run_authorized")
    if require_authorized and not expected_authorized:
        blockers.append("authorization_consumed")
    expected_authorization = {
        "decision_id": "USER_AUTHORIZED_V23_FROZEN_OOS_REPLAY_20260803",
        "authority": "CURRENT_USER_INSTRUCTION",
        "scope": "ONE_READ_ONLY_FROZEN_V23_1024_COHORT_OOS_REPLAY",
        "candidate_generation_allowed": False,
        "validation_performance_selection_allowed": False,
        "optimizer_feedback_allowed": False,
        "policy_memory_write_allowed": False,
        "archive_write_allowed": False,
        "parameter_tuning_allowed": False,
        "seed_change_allowed": False,
        "rescue_rerun_allowed": False,
        "promotion_allowed": False,
    }
    if dict(receipt.get("run_authorization") or {}) != expected_authorization:
        blockers.append("run_authorization")
    expected_outcome = {
        "status": "PASS_CRYPTO_SEARCH_V2_3_FROZEN_OOS_REPLAY_COMPLETE",
        "reason": "FROZEN_COHORT_OOS_REPLAY_TERMINAL",
        "runtime": f"runtime/{V23_OOS_RUNTIME_PREFIX}_{V23_OOS_DEFAULT_RUNTIME_DATE}",
        "source_candidate_count": V23_OOS_COHORT_COUNT,
        "candidate_generation_performed": False,
        "validation_performance_selection_performed": False,
        "optimizer_feedback_written": False,
        "policy_memory_written": False,
        "archive_written": False,
        "promotion_started": False,
    }
    run_outcome = dict(receipt.get("run_outcome") or {})
    if expected_authorized and run_outcome:
        blockers.append("run_outcome_before_consumption")
    if not expected_authorized and run_outcome != expected_outcome:
        blockers.append("run_outcome")
    source = dict(receipt.get("source_v23") or {})
    expected_source = {
        "runtime": V23_OOS_SOURCE_RUNTIME,
        "producer_source_sha": "06512e01876345d9921d56405d8254a82933a9b7",
        "artifact_bundle_sha256": (
            "A593CAB511326F30ABC426329E71F1451AD73250E5D4FEF4552CFD8F46AEDAF5"
        ),
        "candidate_ledger_path": f"{V23_OOS_SOURCE_RUNTIME}/candidate_ledger.parquet",
        "candidate_ledger_sha256": (
            "B19F0E94B9BB50933E8F6BD6A92754E3D8DC8059968C0D5069E3EF87527456E4"
        ),
        "validation_candidate_ledger_path": (
            f"{V23_OOS_SOURCE_RUNTIME}/validation_candidate_ledger.parquet"
        ),
        "validation_candidate_ledger_sha256": (
            "8D113E8DB68D4E79D99A4717CBB8561CF288784D8260BC08FA9FA732B981208F"
        ),
        "evaluated_cohort_projection_sha256": (
            "78AD6586EFBC54FBFAEA2C81879DDD938CBFB51AA2AB97BC49EF1FA20BF81FAF"
        ),
        "evaluated_candidate_count": V23_OOS_COHORT_COUNT,
        "unique_candidate_count": V23_OOS_COHORT_COUNT,
    }
    if source != expected_source:
        blockers.append("source_v23")
    source_receipt_path = str(receipt.get("source_receipt_path") or "")
    if source_receipt_path != "config/crypto_search_mechanism_v2_3_receipt.json":
        blockers.append("source_receipt_path")
    source_receipt_file = repo_root / source_receipt_path
    if not source_receipt_file.is_file():
        blockers.append("source_receipt_missing")
        base_receipt: dict[str, Any] = {}
    else:
        base_receipt = _read_json(source_receipt_file)
        if _payload_sha(base_receipt) != str(
            receipt.get("source_receipt_sha256") or ""
        ):
            blockers.append("source_receipt_sha256")
        if dict(base_receipt.get("run_outcome") or {}).get(
            "artifact_bundle_sha256"
        ) != expected_source["artifact_bundle_sha256"]:
            blockers.append("source_receipt_outcome")
    holdout = dict(receipt.get("holdout") or {})
    expected_holdout = {
        "role": "READ_ONLY_HOLDOUT_REQUIRES_SEPARATE_AUTHORIZATION",
        "start": "2026-01-01T00:00:00Z",
        "end_exclusive": "2026-07-01T00:00:00Z",
        "read_allowed": True,
        "optimizer_feedback_allowed": False,
        "policy_memory_write_allowed": False,
        "candidate_generation_allowed": False,
    }
    if holdout != expected_holdout:
        blockers.append("holdout")
    replay = dict(receipt.get("replay") or {})
    expected_replay = {
        "cohorts": [
            "random_stratified",
            "random_train_top",
            "evolution_stratified",
            "evolution_train_top",
        ],
        "candidate_count_per_cohort": 256,
        "candidate_count_per_seed_horizon_cohort": 64,
        "seeds": [int(value) for value in MECHANISM_SEARCH_V23_SEEDS],
        "horizons_hours": [1, 4],
        "candidate_local_failure_action": "PERSIST_NO_BACKFILL",
        "orientation": "FROZEN_TRAIN_ORIENTATION",
        "matched_component": "FROZEN_TRAIN_LIMITING_COMPONENT",
        "same_target_mapping_cost": True,
    }
    if replay != expected_replay:
        blockers.append("replay")
    aggregation = dict(receipt.get("aggregation") or {})
    expected_aggregation = {
        "primary_estimand": (
            "EQUAL_WEIGHT_ACROSS_SEED_HORIZON_DAILY_TOTAL_POLICY_EFFECT"
        ),
        "total_policy": "evolution_train_top_minus_random_train_top",
        "proposal_distribution": (
            "evolution_stratified_minus_random_stratified"
        ),
        "train_ranker": "evolution_train_top_minus_evolution_stratified",
        "cell_results_are_heterogeneity_not_kill_gates": True,
        "block_length_days": 7,
        "bootstrap_replications": 4096,
        "reported_quantiles": [0.05, 0.1, 0.25, 0.5, 0.75, 0.9, 0.95],
        "binary_qualification_gate": False,
    }
    if aggregation != expected_aggregation:
        blockers.append("aggregation")
    boundaries = dict(receipt.get("boundaries") or {})
    expected_boundaries = {
        "oos": True,
        "sealed_partition_reads": 1,
        "challenge": False,
        "recent": False,
        "may_stress": False,
        "forward": False,
        "promotion": False,
        "new_search": False,
        "cross_sprint_adaptive_memory": False,
        "a_share_constraints_applied": False,
    }
    if boundaries != expected_boundaries:
        blockers.append("boundaries")
    component_sources = dict(receipt.get("component_sources") or {})
    expected_component_names = {
        "pair_evaluator",
        "oos_runtime",
        "target_store",
        "mapping_and_cost",
        "mechanism_compiler",
        "authority_preflight",
    }
    if set(component_sources) != expected_component_names:
        blockers.append("component_sources.keys")
    frozen_contract_path = (
        repo_root / str(run_outcome.get("runtime") or "") / "frozen_contract.json"
    )
    if frozen_contract_path.is_file():
        producer_source_sha = str(
            _read_json(frozen_contract_path).get("source_sha") or ""
        )
    else:
        producer_source_sha = ""
        blockers.append("run_outcome.frozen_contract")
    for name, component in component_sources.items():
        item = dict(component)
        relative_path = str(item.get("path") or "")
        try:
            observed_sha256 = _git_file_sha256(
                repo_root,
                producer_source_sha,
                relative_path,
            )
        except (OSError, subprocess.CalledProcessError):
            observed_sha256 = ""
        if observed_sha256 != str(item.get("sha256") or ""):
            blockers.append(f"component_sources.{name}")
    for label in (
        expected_source["candidate_ledger_path"],
        expected_source["validation_candidate_ledger_path"],
    ):
        artifact = repo_root / label
        expected_hash = expected_source[
            "candidate_ledger_sha256"
            if label.endswith("/candidate_ledger.parquet")
            and "validation_" not in label
            else "validation_candidate_ledger_sha256"
        ]
        if not artifact.is_file() or sha256_file(artifact) != expected_hash:
            blockers.append(f"source_artifact.{artifact.name}")
    if blockers:
        raise RuntimeError("V23_OOS_RECEIPT_BLOCKED:" + ",".join(sorted(set(blockers))))
    return {
        **receipt,
        "receipt_sha256": _payload_sha(receipt),
        "source_receipt": base_receipt,
    }


def _v23_oos_economic_context(receipt: Mapping[str, Any]) -> dict[str, Any]:
    base = dict(receipt["source_receipt"])
    partitions = {
        key: dict(value)
        for key, value in dict(base.get("evidence_partition") or {}).items()
    }
    partitions["holdout"] = dict(receipt["holdout"])
    context = {
        **base,
        "status": receipt["status"],
        "run_authorized": receipt["run_authorized"],
        "run_authorization": dict(receipt["run_authorization"]),
        "evidence_partition": partitions,
        "train": dict(partitions["train"]),
        "validation": dict(partitions["validation"]),
        "holdout": dict(partitions["holdout"]),
        "boundaries": dict(receipt["boundaries"]),
        "receipt_sha256": str(receipt["receipt_sha256"]),
    }
    return context


def _load_v23_oos_candidates(
    repo_root: Path,
    receipt: Mapping[str, Any],
) -> list[dict[str, Any]]:
    source = dict(receipt["source_v23"])
    validation_frame = pd.read_parquet(
        repo_root / str(source["validation_candidate_ledger_path"])
    )
    projection = _v23_oos_projection_rows(validation_frame)
    if (
        len(projection) != V23_OOS_COHORT_COUNT
        or len({row["candidate_id"] for row in projection})
        != V23_OOS_COHORT_COUNT
        or _payload_sha(projection)
        != str(source["evaluated_cohort_projection_sha256"])
    ):
        raise RuntimeError("V23_OOS_COHORT_PROJECTION_CHANGED")
    if Counter(row["cohort"] for row in projection) != {
        value: 256 for value in receipt["replay"]["cohorts"]
    }:
        raise RuntimeError("V23_OOS_COHORT_BALANCE_CHANGED")
    train_frame = pd.read_parquet(repo_root / str(source["candidate_ledger_path"]))
    if train_frame["candidate_id"].duplicated().any():
        raise RuntimeError("V23_OOS_TRAIN_LEDGER_IDENTITY_DUPLICATED")
    train_lookup = train_frame.set_index("candidate_id").to_dict("index")
    selected: list[dict[str, Any]] = []
    for frozen in projection:
        candidate_id = str(frozen["candidate_id"])
        train = dict(train_lookup.get(candidate_id) or {})
        if not train:
            raise RuntimeError("V23_OOS_TRAIN_CANDIDATE_MISSING")
        candidate = CandidateSpec.from_dict(
            json.loads(str(train["candidate_spec_json"]))
        )
        if (
            candidate.candidate_id != candidate_id
            or int(candidate.horizon_hours) != int(frozen["horizon_hours"])
            or int(float(train["train_orientation"]))
            != int(frozen["frozen_train_orientation"])
            or str(train["search_reward_matched_limiting_component"])
            != str(frozen["frozen_matched_component"])
        ):
            raise RuntimeError("V23_OOS_FROZEN_CANDIDATE_BINDING_CHANGED")
        selected.append({**frozen, "candidate": candidate.to_dict()})
    return selected


def _v23_oos_block_effect(
    delta: np.ndarray,
    *,
    label: str,
    block_length: int,
    replications: int,
    quantiles: Sequence[float],
) -> dict[str, Any]:
    values = np.asarray(delta, dtype=float)
    values = values[np.isfinite(values)]
    if values.size < block_length:
        raise RuntimeError("V23_OOS_PAIRED_DAILY_PATH_TOO_SHORT")
    seed = int.from_bytes(
        hashlib.sha256(f"{V23_OOS_EPOCH_ID}|{label}".encode()).digest()[:4],
        "big",
    )
    rng = np.random.default_rng(seed)
    block_count = int(math.ceil(values.size / block_length))
    offsets = np.arange(block_length, dtype=int)
    sample_means = np.empty(replications, dtype=float)
    for ordinal in range(replications):
        starts = rng.integers(0, values.size, size=block_count)
        indexes = (starts[:, None] + offsets[None, :]) % values.size
        sample_means[ordinal] = float(
            np.mean(values[indexes.reshape(-1)[: values.size]])
        )
    return {
        "observed_mean_delta": float(np.mean(values)),
        "probability_positive": float(np.mean(sample_means > 0.0)),
        "bootstrap_quantiles": {
            f"q{int(round(value * 100)):02d}": float(np.quantile(sample_means, value))
            for value in quantiles
        },
        "paired_day_count": int(values.size),
        "block_length_days": int(block_length),
        "replications": int(replications),
        "bootstrap_seed": seed,
    }


def _v23_oos_aggregate(
    *,
    candidate_rows: Sequence[Mapping[str, Any]],
    candidate_path_rows: Sequence[Mapping[str, Any]],
    receipt: Mapping[str, Any],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]], dict[str, Any]]:
    successful = [row for row in candidate_rows if row["oos_status"] == "EVALUATED"]
    path_frame = pd.DataFrame(list(candidate_path_rows))
    if not successful or path_frame.empty:
        raise RuntimeError("V23_OOS_NO_EVALUATED_PATHS")
    group_keys = ["cohort", "arm", "seed", "horizon_hours", "day_ordinal", "utc_day"]
    cohort_paths = (
        path_frame.groupby(group_keys, as_index=False, sort=True)[
            ["primary_net", "matched_increment", "control_net"]
        ]
        .mean()
        .sort_values(group_keys, kind="stable")
    )
    metrics: list[dict[str, Any]] = []
    for (cohort, arm, seed, horizon), local in cohort_paths.groupby(
        ["cohort", "arm", "seed", "horizon_hours"], sort=True
    ):
        candidate_count = sum(
            row["cohort"] == cohort
            and int(row["seed"]) == int(seed)
            and int(row["horizon_hours"]) == int(horizon)
            and row["oos_status"] == "EVALUATED"
            for row in candidate_rows
        )
        primary = local["primary_net"].to_numpy(dtype=float)
        matched = local["matched_increment"].to_numpy(dtype=float)
        control = local["control_net"].to_numpy(dtype=float)
        from scripts.crypto_a7reward1_portfolio_reward_model import sortino

        metrics.append(
            {
                "cohort": str(cohort),
                "arm": str(arm),
                "seed": int(seed),
                "horizon_hours": int(horizon),
                "matched_evaluated_count": int(candidate_count),
                "oos_primary_net_mean": float(np.nanmean(primary)),
                "oos_primary_daily_sortino": float(sortino(primary, 365.0)),
                "oos_matched_increment": float(np.nanmean(matched)),
                "oos_control_net_mean": float(np.nanmean(control)),
                "oos_control_not_dominant": bool(
                    float(np.nanmean(primary)) > float(np.nanmean(control))
                ),
                "daily_path_row_count": int(len(local)),
            }
        )
    path_lookup: dict[tuple[str, int, int, str], np.ndarray] = {}
    for row in metrics:
        local = cohort_paths[
            cohort_paths["cohort"].eq(row["cohort"])
            & cohort_paths["seed"].eq(row["seed"])
            & cohort_paths["horizon_hours"].eq(row["horizon_hours"])
        ].sort_values("day_ordinal")
        for field in ("primary_net", "matched_increment", "control_net"):
            path_lookup[(row["cohort"], row["seed"], row["horizon_hours"], field)] = (
                local[field].to_numpy(dtype=float)
            )
    comparisons = {
        "proposal_distribution": ("random_stratified", "evolution_stratified"),
        "train_ranker": ("evolution_stratified", "evolution_train_top"),
        "total_policy": ("random_train_top", "evolution_train_top"),
    }
    aggregation = dict(receipt["aggregation"])
    block_length = int(aggregation["block_length_days"])
    replications = int(aggregation["bootstrap_replications"])
    quantiles = tuple(float(value) for value in aggregation["reported_quantiles"])
    cell_effects: list[dict[str, Any]] = []
    pooled_deltas: dict[tuple[str, str], list[np.ndarray]] = defaultdict(list)
    for comparison, (left, right) in comparisons.items():
        for seed in MECHANISM_SEARCH_V23_SEEDS:
            for horizon in (1, 4):
                effects: dict[str, Any] = {}
                for metric in ("primary_net", "matched_increment"):
                    delta = (
                        path_lookup[(right, seed, horizon, metric)]
                        - path_lookup[(left, seed, horizon, metric)]
                    )
                    pooled_deltas[(comparison, metric)].append(delta)
                    effects[metric] = _v23_oos_block_effect(
                        delta,
                        label=f"cell|{comparison}|{seed}|{horizon}|{metric}",
                        block_length=block_length,
                        replications=replications,
                        quantiles=quantiles,
                    )
                cell_effects.append(
                    {
                        "comparison": comparison,
                        "left_cohort": left,
                        "right_cohort": right,
                        "seed": int(seed),
                        "horizon_hours": int(horizon),
                        "effects": effects,
                    }
                )
    pooled_effects: dict[str, Any] = {}
    for comparison in comparisons:
        pooled_effects[comparison] = {}
        for metric in ("primary_net", "matched_increment"):
            values = pooled_deltas[(comparison, metric)]
            shape = {item.shape for item in values}
            if len(shape) != 1:
                raise RuntimeError("V23_OOS_CELL_PATH_SHAPE_CHANGED")
            pooled = np.nanmean(np.stack(values, axis=0), axis=0)
            pooled_effects[comparison][metric] = _v23_oos_block_effect(
                pooled,
                label=f"pooled|{comparison}|{metric}",
                block_length=block_length,
                replications=replications,
                quantiles=quantiles,
            )
    primary_effect = pooled_effects["total_policy"]["primary_net"]
    matched_effect = pooled_effects["total_policy"]["matched_increment"]
    primary_positive = float(primary_effect["observed_mean_delta"]) > 0.0
    matched_positive = float(matched_effect["observed_mean_delta"]) > 0.0
    q10_supported = (
        float(primary_effect["bootstrap_quantiles"]["q10"]) > 0.0
        and float(matched_effect["bootstrap_quantiles"]["q10"]) > 0.0
    )
    if primary_positive and matched_positive:
        classification = (
            "OOS_TOTAL_POLICY_POSITIVE_DIRECTION_Q10_SUPPORTED"
            if q10_supported
            else "OOS_TOTAL_POLICY_POSITIVE_DIRECTION_UNCERTAIN"
        )
    elif not primary_positive and not matched_positive:
        classification = "OOS_TOTAL_POLICY_NEGATIVE_DIRECTION"
    else:
        classification = "OOS_TOTAL_POLICY_MIXED_DIRECTION"
    failures = [row for row in candidate_rows if row["oos_status"] != "EVALUATED"]
    effects = {
        "schema_version": 1,
        "primary_estimand": aggregation["primary_estimand"],
        "classification": classification,
        "binary_qualification_gate_applied": False,
        "cell_results_role": "HETEROGENEITY_ONLY",
        "source_candidate_count": len(candidate_rows),
        "evaluated_candidate_count": len(successful),
        "candidate_local_failure_count": len(failures),
        "candidate_local_failures": [
            {
                "candidate_id": str(row["candidate_id"]),
                "cohort": str(row["cohort"]),
                "seed": int(row["seed"]),
                "horizon_hours": int(row["horizon_hours"]),
                "reason": str(row["reason"]),
            }
            for row in failures
        ],
        "pooled_effects": pooled_effects,
        "cell_effects": cell_effects,
        "promotion_authorized": False,
        "next_search_started": False,
    }
    return metrics, cohort_paths.to_dict("records"), effects


def _write_v23_oos_checkpoint(
    *,
    runtime_root: Path,
    label: str,
    source_sha: str,
    frozen_hash: str,
    selection_hash: str,
    candidate_rows: Sequence[Mapping[str, Any]],
    candidate_path_rows: Sequence[Mapping[str, Any]],
) -> Path:
    checkpoint_root = runtime_root / "checkpoints"
    checkpoint_root.mkdir(parents=True, exist_ok=True)
    target = checkpoint_root / label
    if target.exists():
        raise FileExistsError(target)
    temporary = checkpoint_root / f".{label}.tmp-{os.getpid()}"
    if temporary.exists():
        shutil.rmtree(temporary)
    temporary.mkdir(parents=True)
    completed_ids = [str(row["candidate_id"]) for row in candidate_rows]
    state = {
        "schema_version": 1,
        "source_sha": source_sha,
        "frozen_contract_sha256": frozen_hash,
        "selection_projection_sha256": selection_hash,
        "completed_candidate_ids": completed_ids,
        "completed_candidate_count": len(candidate_rows),
        "candidate_generation_performed": False,
        "optimizer_feedback_written": False,
        "policy_memory_written": False,
        "archive_written": False,
        "holdout_read": True,
        "sealed_partition_reads": 1,
    }
    _write_json(temporary / "state.json", state)
    _write_parquet(temporary / "oos_candidate_ledger.parquet", candidate_rows)
    _write_parquet(
        temporary / "oos_candidate_daily_paths.parquet",
        candidate_path_rows,
    )
    files = [
        {
            "name": path.name,
            "bytes": path.stat().st_size,
            "sha256": sha256_file(path),
        }
        for path in sorted(temporary.iterdir())
    ]
    manifest = {
        "schema_version": 1,
        "checkpoint": label,
        "source_sha": source_sha,
        "frozen_contract_sha256": frozen_hash,
        "selection_projection_sha256": selection_hash,
        "completed_candidate_count": len(candidate_rows),
        "completed_identity_sha256": _payload_sha(completed_ids),
        "candidate_path_row_count": len(candidate_path_rows),
        "state_sha256": _payload_sha(state),
        "files": files,
        "atomic_write": "TEMP_DIRECTORY_THEN_OS_REPLACE",
        "restore_verified": False,
    }
    _write_json(temporary / "manifest.json", manifest)
    restored_state = _read_json(temporary / "state.json")
    restored_rows = pd.read_parquet(
        temporary / "oos_candidate_ledger.parquet"
    ).to_dict("records")
    restored_paths = pd.read_parquet(
        temporary / "oos_candidate_daily_paths.parquet"
    ).to_dict("records")
    if (
        _payload_sha(restored_state) != manifest["state_sha256"]
        or _payload_sha([str(row["candidate_id"]) for row in restored_rows])
        != manifest["completed_identity_sha256"]
        or len(restored_paths) != int(manifest["candidate_path_row_count"])
    ):
        shutil.rmtree(temporary)
        raise RuntimeError("V23_OOS_CHECKPOINT_RESTORE_FAILED")
    manifest["restore_verified"] = True
    _write_json(temporary / "manifest.json", manifest)
    os.replace(temporary, target)
    return target


def _restore_v23_oos_checkpoint(
    *,
    runtime_root: Path,
    source_sha: str,
    frozen_hash: str,
    selection_hash: str,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]] | None:
    checkpoints = sorted(
        path
        for path in (runtime_root / "checkpoints").glob(
            "checkpoint_[0-9][0-9][0-9]"
        )
        if path.is_dir()
    )
    if not checkpoints:
        return None
    path = checkpoints[-1]
    manifest = _read_json(path / "manifest.json")
    if (
        manifest.get("restore_verified") is not True
        or manifest.get("source_sha") != source_sha
        or manifest.get("frozen_contract_sha256") != frozen_hash
        or manifest.get("selection_projection_sha256") != selection_hash
    ):
        raise RuntimeError("V23_OOS_CHECKPOINT_AUTHORITY_CHANGED")
    for item in manifest["files"]:
        local = path / str(item["name"])
        if (
            not local.is_file()
            or local.stat().st_size != int(item["bytes"])
            or sha256_file(local) != str(item["sha256"])
        ):
            raise RuntimeError("V23_OOS_CHECKPOINT_FILE_CHANGED")
    state = _read_json(path / "state.json")
    candidate_rows = pd.read_parquet(
        path / "oos_candidate_ledger.parquet"
    ).to_dict("records")
    candidate_path_rows = pd.read_parquet(
        path / "oos_candidate_daily_paths.parquet"
    ).to_dict("records")
    if (
        _payload_sha(state) != manifest["state_sha256"]
        or len(candidate_rows) != int(manifest["completed_candidate_count"])
        or len(candidate_path_rows) != int(manifest["candidate_path_row_count"])
        or _payload_sha([str(row["candidate_id"]) for row in candidate_rows])
        != manifest["completed_identity_sha256"]
    ):
        raise RuntimeError("V23_OOS_CHECKPOINT_CONTENT_CHANGED")
    return candidate_rows, candidate_path_rows


def _v23_oos_artifact_bundle(
    runtime_root: Path,
    report_path: Path,
) -> tuple[list[dict[str, Any]], str]:
    names = (
        "frozen_contract.json",
        "embedded_preflight.json",
        "producer_status.json",
        "oos_candidate_ledger.parquet",
        "oos_candidate_daily_paths.parquet",
        "oos_cohort_metrics.parquet",
        "oos_cohort_paths.parquet",
        "oos_effects.json",
        "final_decision.json",
    )
    files = []
    for name in names:
        path = runtime_root / name
        files.append(
            {
                "path": name,
                "bytes": path.stat().st_size,
                "sha256": sha256_file(path),
            }
        )
    files.append(
        {
            "path": report_path.relative_to(runtime_root.parents[1]).as_posix(),
            "bytes": report_path.stat().st_size,
            "sha256": sha256_file(report_path),
        }
    )
    return files, _payload_sha(files)


def run_v23_frozen_oos_replay(
    repo_root: Path,
    *,
    runtime_date: str = V23_OOS_DEFAULT_RUNTIME_DATE,
    source_sha: str | None = None,
    authority_preflight: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    if runtime_date != V23_OOS_DEFAULT_RUNTIME_DATE:
        raise ValueError("V2.3 OOS runtime date changed")
    runtime_root = repo_root / f"runtime/{V23_OOS_RUNTIME_PREFIX}_{runtime_date}"
    report_path = repo_root / f"reports/{V23_OOS_REPORT_PREFIX}_{runtime_date}.md"
    verified_preflight = _require_bound_authority_preflight(
        repo_root,
        authority_preflight,
        economic_receipt_required=False,
    )
    observed_source = _git_sha(repo_root)
    producer_source = str(source_sha or observed_source).lower()
    if producer_source != observed_source:
        raise RuntimeError("V23_OOS_SOURCE_SHA_CHANGED")
    if not _source_tree_clean_for_run(
        repo_root,
        allowed_paths=(runtime_root, report_path),
    ):
        raise RuntimeError("V23_OOS_REQUIRES_CLEAN_PRODUCER_TREE")
    receipt = _load_v23_oos_receipt(repo_root, require_authorized=True)
    economic_context = _v23_oos_economic_context(receipt)
    train_partition = dict(economic_context["train"])
    store, contracts, _, identities, _ = _load_v14_inputs(
        repo_root,
        behavior_window=train_partition,
    )
    cache_root = repo_root / str(identities["raw_cache"]["root"])
    target_root = repo_root / str(economic_context["execution"]["target_cache_path"])
    target_metadata = _validate_receipt_target_store_binding(
        store,
        target_root,
        economic_context["execution"],
    )
    selection = _load_v23_oos_candidates(repo_root, receipt)
    selection_projection = [
        {key: value for key, value in row.items() if key != "candidate"}
        for row in selection
    ]
    selection_hash = _payload_sha(selection_projection)
    frozen_payload = {
        "schema_version": 1,
        "epoch_id": V23_OOS_EPOCH_ID,
        "source_sha": producer_source,
        "receipt": {
            key: value for key, value in receipt.items() if key != "source_receipt"
        },
        "authority_preflight": dict(verified_preflight),
        "source_v23": dict(receipt["source_v23"]),
        "selection_projection_sha256": selection_hash,
        "selection_candidate_count": len(selection),
        "input_identities": identities,
        "target_cache_identity_sha256": target_metadata["identity_sha256"],
        "field_count": len(contracts),
        "holdout": dict(receipt["holdout"]),
        "aggregation": dict(receipt["aggregation"]),
        "workers": V23_OOS_WORKERS,
        "checkpoint_size": V23_OOS_CHECKPOINT_SIZE,
        "candidate_generation_performed": False,
        "validation_performance_selection_performed": False,
        "optimizer_feedback_written": False,
        "policy_memory_written": False,
        "archive_written": False,
        "promotion_authorized": False,
    }
    frozen = {
        **frozen_payload,
        "frozen_contract_sha256": _payload_sha(frozen_payload),
    }
    frozen_hash = str(frozen["frozen_contract_sha256"])
    if runtime_root.exists():
        frozen_path = runtime_root / "frozen_contract.json"
        if not frozen_path.is_file() or _read_json(frozen_path) != frozen:
            raise RuntimeError("V23_OOS_EXISTING_RUNTIME_CONTRACT_CHANGED")
        if (runtime_root / "final_decision.json").is_file():
            raise FileExistsError("V2.3 OOS replay already completed")
    else:
        runtime_root.mkdir(parents=True)
        _write_json(runtime_root / "frozen_contract.json", frozen)
        _write_json(
            runtime_root / "embedded_preflight.json",
            {
                "schema_version": 1,
                "status": "READY_ONE_AUTHORIZED_HOLDOUT_PARTITION_READ",
                "producer_source_sha": producer_source,
                "receipt_sha256": receipt["receipt_sha256"],
                "selection_projection_sha256": selection_hash,
                "source_candidate_count": len(selection),
                "workers": V23_OOS_WORKERS,
                "workers_12_forbidden": True,
                "sealed_partition_reads_before_run": 0,
                "candidate_generation_performed": False,
                "validation_performance_selection_performed": False,
            },
        )
    restored = _restore_v23_oos_checkpoint(
        runtime_root=runtime_root,
        source_sha=producer_source,
        frozen_hash=frozen_hash,
        selection_hash=selection_hash,
    )
    if restored is None:
        candidate_rows: list[dict[str, Any]] = []
        candidate_path_rows: list[dict[str, Any]] = []
    else:
        candidate_rows, candidate_path_rows = restored
    completed_ids = {str(row["candidate_id"]) for row in candidate_rows}
    expected_prefix = [str(row["candidate_id"]) for row in selection[: len(candidate_rows)]]
    if [str(row["candidate_id"]) for row in candidate_rows] != expected_prefix:
        raise RuntimeError("V23_OOS_CHECKPOINT_SELECTION_ORDER_CHANGED")
    holdout = dict(receipt["holdout"])
    started = time.perf_counter()

    def write_status(status: str, *, checkpoint: str | None = None) -> None:
        elapsed = time.perf_counter() - started
        _write_json(
            runtime_root / "producer_status.json",
            {
                "schema_version": 1,
                "status": status,
                "producer_pid": os.getpid(),
                "producer_source_sha": producer_source,
                "frozen_contract_sha256": frozen_hash,
                "heartbeat_utc": pd.Timestamp.now(tz="UTC").isoformat(),
                "completed_candidate_count": len(candidate_rows),
                "source_candidate_count": len(selection),
                "candidate_local_failure_count": sum(
                    row["oos_status"] != "EVALUATED" for row in candidate_rows
                ),
                "checkpoint": checkpoint,
                "workers": V23_OOS_WORKERS,
                "active_wall_seconds": elapsed,
                "sealed_partition_reads": 1 if candidate_rows else 0,
                "candidate_generation_performed": False,
                "optimizer_feedback_written": False,
                "policy_memory_written": False,
                "archive_written": False,
            },
        )

    write_status("OOS_REPLAY_STARTING")
    executor = concurrent.futures.ProcessPoolExecutor(
        max_workers=V23_OOS_WORKERS,
        initializer=_worker_initialize,
        initargs=(
            str(cache_root),
            _contracts_payload(contracts),
            {},
            str(holdout["start"]),
            str(holdout["end_exclusive"]),
            str(holdout["role"]),
            economic_context,
        ),
    )
    try:
        while len(candidate_rows) < len(selection):
            batch = selection[
                len(candidate_rows) : len(candidate_rows) + V23_OOS_CHECKPOINT_SIZE
            ]
            futures = [
                executor.submit(
                    _worker_evaluate_frozen_oos,
                    {
                        "candidate": row["candidate"],
                        "frozen_train_orientation": row[
                            "frozen_train_orientation"
                        ],
                        "frozen_matched_component": row[
                            "frozen_matched_component"
                        ],
                    },
                )
                for row in batch
            ]
            results = [future.result() for future in futures]
            for selected, worker in zip(batch, results):
                candidate_id = str(selected["candidate_id"])
                if candidate_id in completed_ids or worker["candidate_id"] != candidate_id:
                    raise RuntimeError("V23_OOS_WORKER_IDENTITY_CHANGED")
                completed_ids.add(candidate_id)
                base_row = {
                    key: value for key, value in selected.items() if key != "candidate"
                }
                candidate_rows.append(
                    {
                        **base_row,
                        "oos_status": str(worker["status"]),
                        "reason": worker.get("reason"),
                        "effective_block_end_exclusive": worker.get(
                            "effective_block_end_exclusive"
                        ),
                        "oos_primary_net_mean": worker.get(
                            "holdout_primary_net_mean"
                        ),
                        "oos_primary_nonoverlap_floor_sortino": worker.get(
                            "holdout_primary_nonoverlap_floor_sortino"
                        ),
                        "oos_matched_increment": worker.get(
                            "holdout_matched_increment"
                        ),
                        "oos_control_net_mean": worker.get(
                            "holdout_control_net_mean"
                        ),
                        "oos_control_not_dominant": worker.get(
                            "control_not_dominant"
                        ),
                        "process_cpu_seconds": float(worker["process_cpu_seconds"]),
                        "wall_seconds": float(worker["wall_seconds"]),
                        "worker_rss_bytes": int(worker["worker_rss_bytes"]),
                        "candidate_generation_performed": False,
                        "validation_performance_selection_performed": False,
                        "optimizer_feedback_written": False,
                        "policy_memory_written": False,
                        "archive_written": False,
                        "holdout_read": True,
                    }
                )
                if worker["status"] == "EVALUATED":
                    daily_count = len(worker["primary_daily"])
                    if not (
                        len(worker["matched_daily"]) == daily_count
                        and len(worker["control_daily"]) == daily_count
                    ):
                        raise RuntimeError("V23_OOS_WORKER_DAILY_PATH_CHANGED")
                    start = pd.Timestamp(str(holdout["start"]))
                    candidate_path_rows.extend(
                        {
                            "candidate_id": candidate_id,
                            "cohort": str(selected["cohort"]),
                            "arm": str(selected["arm"]),
                            "seed": int(selected["seed"]),
                            "horizon_hours": int(selected["horizon_hours"]),
                            "day_ordinal": int(day),
                            "utc_day": (start + pd.Timedelta(days=day)).strftime(
                                "%Y-%m-%d"
                            ),
                            "primary_net": float(worker["primary_daily"][day]),
                            "matched_increment": float(
                                worker["matched_daily"][day]
                            ),
                            "control_net": float(worker["control_daily"][day]),
                        }
                        for day in range(daily_count)
                    )
            checkpoint_index = len(candidate_rows) // V23_OOS_CHECKPOINT_SIZE - 1
            label = f"checkpoint_{checkpoint_index:03d}"
            _write_v23_oos_checkpoint(
                runtime_root=runtime_root,
                label=label,
                source_sha=producer_source,
                frozen_hash=frozen_hash,
                selection_hash=selection_hash,
                candidate_rows=candidate_rows,
                candidate_path_rows=candidate_path_rows,
            )
            write_status("OOS_REPLAY_RUNNING", checkpoint=label)
    except BaseException:
        write_status("OOS_REPLAY_FAILED")
        raise
    finally:
        executor.shutdown(wait=True, cancel_futures=False)
    metrics, cohort_paths, effects = _v23_oos_aggregate(
        candidate_rows=candidate_rows,
        candidate_path_rows=candidate_path_rows,
        receipt=receipt,
    )
    _write_parquet(runtime_root / "oos_candidate_ledger.parquet", candidate_rows)
    _write_parquet(
        runtime_root / "oos_candidate_daily_paths.parquet", candidate_path_rows
    )
    _write_parquet(runtime_root / "oos_cohort_metrics.parquet", metrics)
    _write_parquet(runtime_root / "oos_cohort_paths.parquet", cohort_paths)
    _write_json(runtime_root / "oos_effects.json", effects)
    write_status("OOS_REPLAY_COMPLETE", checkpoint="checkpoint_015")
    decision = {
        "schema_version": 1,
        "status": "PASS_CRYPTO_SEARCH_V2_3_FROZEN_OOS_REPLAY_COMPLETE",
        "reason": "FROZEN_COHORT_OOS_REPLAY_TERMINAL",
        "classification": effects["classification"],
        "producer_source_sha": producer_source,
        "source_candidate_count": len(candidate_rows),
        "evaluated_candidate_count": effects["evaluated_candidate_count"],
        "candidate_local_failure_count": effects["candidate_local_failure_count"],
        "checkpoint_count": 16,
        "checkpoint_restore_verified": True,
        "holdout_read": True,
        "sealed_partition_reads": 1,
        "oos": True,
        "candidate_generation_performed": False,
        "validation_performance_selection_performed": False,
        "optimizer_feedback_written": False,
        "policy_memory_written": False,
        "archive_written": False,
        "binary_qualification_gate_applied": False,
        "promotion_authorized": False,
        "promotion_started": False,
        "next_search_started": False,
        "research_scope": "CONDITIONAL_OOS_POLICY_ATTRIBUTION_NO_PROMOTION",
    }
    _write_json(runtime_root / "final_decision.json", decision)
    total = effects["pooled_effects"]["total_policy"]
    report_path.parent.mkdir(parents=True, exist_ok=True)
    report_lines = [
        f"# Crypto Search V2.3 Frozen OOS Replay ({runtime_date})",
        "",
        (
            f"- Source candidates: `{len(candidate_rows):,}`; evaluated: "
            f"`{effects['evaluated_candidate_count']:,}`; local failures: "
            f"`{effects['candidate_local_failure_count']}`."
        ),
        (
            f"- Holdout: `{holdout['start']}` to `{holdout['end_exclusive']}`; "
            "one sealed partition read."
        ),
        f"- Classification: **{effects['classification']}**.",
        (
            "- Total-policy primary-net delta: "
            f"`{total['primary_net']['observed_mean_delta']:.12f}`; bootstrap "
            f"P(delta>0): `{total['primary_net']['probability_positive']:.4f}`."
        ),
        (
            "- Total-policy matched-increment delta: "
            f"`{total['matched_increment']['observed_mean_delta']:.12f}`; "
            "bootstrap P(delta>0): "
            f"`{total['matched_increment']['probability_positive']:.4f}`."
        ),
        "",
        (
            "All four frozen cohorts were replayed without validation-performance "
            "selection, candidate generation, backfill, optimizer/archive/policy "
            "feedback, parameter tuning, or promotion."
        ),
        (
            "Seed/horizon cells are heterogeneity reports, not kill gates. Results "
            "remain conditional on the frozen Binance USD-M target and 5 bps cost."
        ),
        "",
    ]
    report_path.write_text(
        "\n".join(report_lines),
        encoding="utf-8",
        newline="\n",
    )
    files, bundle = _v23_oos_artifact_bundle(runtime_root, report_path)
    manifest = {
        "schema_version": 1,
        "experiment_id": V23_OOS_EPOCH_ID,
        "producer_source_sha": producer_source,
        "frozen_contract_sha256": frozen_hash,
        "receipt_sha256": receipt["receipt_sha256"],
        "selection_projection_sha256": selection_hash,
        "source_candidate_count": len(candidate_rows),
        "evaluated_candidate_count": effects["evaluated_candidate_count"],
        "checkpoint_count": 16,
        "holdout_read": True,
        "sealed_partition_reads": 1,
        "candidate_generation_performed": False,
        "optimizer_feedback_written": False,
        "policy_memory_written": False,
        "archive_written": False,
        "promotion_started": False,
        "files": files,
        "artifact_bundle_sha256": bundle,
    }
    _write_json(runtime_root / "run_manifest.json", manifest)
    return {**decision, "artifact_bundle_sha256": bundle}


def check_v23_frozen_oos_replay(
    repo_root: Path,
    *,
    runtime_date: str = V23_OOS_DEFAULT_RUNTIME_DATE,
) -> dict[str, Any]:
    runtime_root = repo_root / f"runtime/{V23_OOS_RUNTIME_PREFIX}_{runtime_date}"
    report_path = repo_root / f"reports/{V23_OOS_REPORT_PREFIX}_{runtime_date}.md"
    errors: list[str] = []
    receipt = _load_v23_oos_receipt(repo_root, require_authorized=False)
    selection = _load_v23_oos_candidates(repo_root, receipt)
    selection_hash = _payload_sha(
        [
            {key: value for key, value in row.items() if key != "candidate"}
            for row in selection
        ]
    )
    frozen = _read_json(runtime_root / "frozen_contract.json")
    decision = _read_json(runtime_root / "final_decision.json")
    manifest = _read_json(runtime_root / "run_manifest.json")
    candidate_rows = pd.read_parquet(
        runtime_root / "oos_candidate_ledger.parquet"
    ).to_dict("records")
    candidate_path_rows = pd.read_parquet(
        runtime_root / "oos_candidate_daily_paths.parquet"
    ).to_dict("records")
    observed_metrics = pd.read_parquet(
        runtime_root / "oos_cohort_metrics.parquet"
    ).to_dict("records")
    observed_paths = pd.read_parquet(
        runtime_root / "oos_cohort_paths.parquet"
    ).to_dict("records")
    observed_effects = _read_json(runtime_root / "oos_effects.json")
    recomputed_metrics, recomputed_paths, recomputed_effects = _v23_oos_aggregate(
        candidate_rows=candidate_rows,
        candidate_path_rows=candidate_path_rows,
        receipt=receipt,
    )
    if (
        len(candidate_rows) != V23_OOS_COHORT_COUNT
        or len({str(row["candidate_id"]) for row in candidate_rows})
        != V23_OOS_COHORT_COUNT
        or [str(row["candidate_id"]) for row in candidate_rows]
        != [str(row["candidate_id"]) for row in selection]
    ):
        errors.append("candidate_ledger")
    if _payload_sha(observed_metrics) != _payload_sha(recomputed_metrics):
        errors.append("cohort_metrics")
    if _payload_sha(observed_paths) != _payload_sha(recomputed_paths):
        errors.append("cohort_paths")
    if observed_effects != recomputed_effects:
        errors.append("effects")
    checkpoints = sorted(
        path
        for path in (runtime_root / "checkpoints").glob(
            "checkpoint_[0-9][0-9][0-9]"
        )
        if path.is_dir()
    )
    if len(checkpoints) != 16 or not all(
        _read_json(path / "manifest.json").get("restore_verified") is True
        for path in checkpoints
    ):
        errors.append("checkpoints")
    if frozen.get("selection_projection_sha256") != selection_hash:
        errors.append("frozen_selection")
    if (
        decision.get("status")
        != "PASS_CRYPTO_SEARCH_V2_3_FROZEN_OOS_REPLAY_COMPLETE"
        or decision.get("classification") != observed_effects["classification"]
        or decision.get("holdout_read") is not True
        or decision.get("sealed_partition_reads") != 1
        or decision.get("candidate_generation_performed") is not False
        or decision.get("optimizer_feedback_written") is not False
        or decision.get("policy_memory_written") is not False
        or decision.get("archive_written") is not False
        or decision.get("promotion_started") is not False
    ):
        errors.append("final_decision")
    if (
        manifest.get("producer_source_sha") != frozen.get("source_sha")
        or manifest.get("selection_projection_sha256") != selection_hash
        or manifest.get("source_candidate_count") != V23_OOS_COHORT_COUNT
        or manifest.get("holdout_read") is not True
        or manifest.get("sealed_partition_reads") != 1
    ):
        errors.append("run_manifest")
    for item in manifest.get("files") or []:
        label = str(item["path"])
        path = repo_root / label if label.startswith("reports/") else runtime_root / label
        if (
            not path.is_file()
            or path.stat().st_size != int(item["bytes"])
            or sha256_file(path) != str(item["sha256"])
        ):
            errors.append(f"artifact:{label}")
    if not report_path.is_file():
        errors.append("report")
    bundle = _payload_sha(list(manifest.get("files") or []))
    if bundle != manifest.get("artifact_bundle_sha256"):
        errors.append("artifact_bundle")
    return {
        "status": "PASS" if not errors else "FAIL",
        "errors": sorted(set(errors)),
        "producer_source_sha": manifest.get("producer_source_sha"),
        "source_candidate_count": len(candidate_rows),
        "evaluated_candidate_count": observed_effects["evaluated_candidate_count"],
        "candidate_local_failure_count": observed_effects[
            "candidate_local_failure_count"
        ],
        "classification": observed_effects["classification"],
        "checkpoint_count": len(checkpoints),
        "artifact_bundle_sha256": manifest.get("artifact_bundle_sha256"),
        "sealed_partition_reads": manifest.get("sealed_partition_reads"),
    }


def _frozen_validation_due(
    *,
    campaign: str,
    state: Mapping[str, Any],
    economic_receipt: Mapping[str, Any],
) -> bool:
    kill_line = dict(economic_receipt.get("validation_kill_line") or {})
    expected_campaign = str(kill_line.get("orchestration_campaign") or "")
    if campaign != expected_campaign:
        raise RuntimeError(
            "ECONOMIC_RECEIPT_VALIDATION_CAMPAIGN_CHANGED:"
            f"expected={expected_campaign}:observed={campaign}"
        )
    trigger = int(kill_line.get("trigger_after_train_checkpoint_index", -1))
    if trigger < 0:
        raise RuntimeError("VALIDATION_CHECKPOINT_TRIGGER_INVALID")
    return (
        "validation_stage" not in state
        and int(state.get("next_checkpoint_index", 0)) > trigger
    )


def _validation_resumed_flag(
    validation_result: Mapping[str, Any] | None,
) -> bool:
    return bool((validation_result or {}).get("resumed", False))


def run_engine(
    repo_root: Path,
    *,
    runtime_date: str = DEFAULT_RUNTIME_DATE,
    source_sha: str | None = None,
    campaign: str = "legacy",
    carrier_id: str | None = None,
    authority_preflight: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    if campaign not in {
        "legacy",
        "aggtrades_system_canary",
        "search_engine_v1_1",
        "search_engine_v1_2",
        "carrier_gate_v1",
        "search_engine_v1_3_cross_carrier",
        *ECONOMIC_SEARCH_CAMPAIGNS,
    }:
        raise ValueError(f"unsupported Search Engine V1 campaign: {campaign}")
    is_economic = campaign in ECONOMIC_SEARCH_CAMPAIGNS
    economic_config = (
        _economic_campaign_config(campaign) if is_economic else None
    )
    campaign_seeds = (
        _economic_campaign_seeds(campaign) if is_economic else SEEDS
    )
    is_canary = campaign == "aggtrades_system_canary"
    is_v11 = campaign == "search_engine_v1_1"
    is_v12 = campaign == "search_engine_v1_2"
    is_carrier_gate = campaign == "carrier_gate_v1"
    is_v13 = campaign == "search_engine_v1_3_cross_carrier"
    is_mechanism_v2 = campaign == MECHANISM_SEARCH_V2_CAMPAIGN
    is_mechanism_v21 = campaign == MECHANISM_SEARCH_V21_CAMPAIGN
    is_mechanism_v22 = campaign == MECHANISM_SEARCH_V22_CAMPAIGN
    is_mechanism_v23 = campaign == MECHANISM_SEARCH_V23_CAMPAIGN
    is_search_evidence_v1 = campaign in SEARCH_EVIDENCE_CAMPAIGNS
    is_mechanism_campaign = (
        is_mechanism_v2
        or is_mechanism_v21
        or is_mechanism_v22
        or is_mechanism_v23
        or is_search_evidence_v1
    )
    is_system_campaign = (
        is_canary or is_v11 or is_v12 or is_carrier_gate or is_v13
    )
    if is_economic:
        assert economic_config is not None
        if runtime_date != economic_config["runtime_date"]:
            raise ValueError("economic search runtime date changed")
        runtime_root = (
            repo_root
            / f"runtime/{economic_config['runtime_prefix']}_{runtime_date}"
        )
        report_path = (
            repo_root
            / f"reports/{economic_config['report_prefix']}_{runtime_date}.md"
        )
        strict_target = int(economic_config.get("strict_target", STRICT_TARGET))
        checkpoint_count = int(
            economic_config.get("checkpoint_count", CHECKPOINT_COUNT)
        )
        checkpoint_size = int(
            economic_config.get("checkpoint_size", CHECKPOINT_SIZE)
        )
        raw_attempt_limit = int(
            economic_config.get("raw_attempt_limit", RAW_ATTEMPT_LIMIT)
        )
        wall_time_limit = float(
            economic_config.get(
                "wall_time_limit_seconds", WALL_TIME_LIMIT_SECONDS
            )
        )
        campaign_arms = tuple(economic_config.get("arms", FIRST_CHECKPOINT_ARMS))
        block_role = "FRESH_DEVELOPMENT_TRAIN_ONLY"
    elif is_v13:
        if runtime_date != V13_DEFAULT_RUNTIME_DATE:
            raise ValueError("Search Engine V1.3 runtime date changed")
        runtime_root = (
            repo_root
            / f"runtime/crypto_search_engine_v1_3_cross_carrier_{runtime_date}"
        )
        report_path = (
            repo_root
            / f"reports/CRYPTO_SEARCH_ENGINE_V1_3_CROSS_CARRIER_{runtime_date}.md"
        )
        strict_target = V13_STRICT_TARGET
        checkpoint_count = V13_CHECKPOINT_COUNT
        checkpoint_size = V13_CHECKPOINT_SIZE
        raw_attempt_limit = V13_RAW_ATTEMPT_LIMIT
        wall_time_limit = V13_WALL_TIME_LIMIT_SECONDS
        campaign_arms = V13_ARMS
        block_role = "FRESH_STATE_FIXED_RETROSPECTIVE_BROAD_X_AGGTRADES"
    elif is_carrier_gate:
        if runtime_date != CARRIER_GATE_DEFAULT_RUNTIME_DATE:
            raise ValueError("carrier gate runtime date changed")
        if carrier_id not in CARRIER_GATE_IDS:
            raise ValueError("carrier gate requires one frozen carrier id")
        carrier_slug = str(carrier_id).lower()
        carrier_revision = (
            "r4" if carrier_id == "CORE3_MICROSTRUCTURE_PILOT" else "r3"
        )
        runtime_root = repo_root / (
            f"runtime/crypto_search_carrier_gate_v1_{carrier_revision}_{carrier_slug}_{runtime_date}"
        )
        report_path = repo_root / (
            f"reports/CRYPTO_SEARCH_CARRIER_GATE_V1_{carrier_revision.upper()}_{carrier_slug.upper()}_{runtime_date}.md"
        )
        strict_target = CARRIER_GATE_STRICT_TARGET
        checkpoint_count = CARRIER_GATE_CHECKPOINT_COUNT
        checkpoint_size = CARRIER_GATE_CHECKPOINT_SIZE
        raw_attempt_limit = CARRIER_GATE_RAW_ATTEMPT_LIMIT
        wall_time_limit = CARRIER_GATE_WALL_TIME_LIMIT_SECONDS
        campaign_arms = CARRIER_GATE_ARMS
        block_role = f"FRESH_STATE_CARRIER_LOCAL_DEVELOPMENT_GATE:{carrier_id}"
    elif is_v12:
        if runtime_date != V12_DEFAULT_RUNTIME_DATE:
            raise ValueError(
                "Search Engine V1.2 is authorized only for runtime date "
                f"{V12_DEFAULT_RUNTIME_DATE}"
            )
        runtime_root = (
            repo_root / f"runtime/crypto_search_engine_v1_2_{runtime_date}"
        )
        report_path = (
            repo_root / f"reports/CRYPTO_SEARCH_ENGINE_V1_2_{runtime_date}.md"
        )
        strict_target = V12_STRICT_TARGET
        checkpoint_count = V12_CHECKPOINT_COUNT
        checkpoint_size = V12_CHECKPOINT_SIZE
        raw_attempt_limit = V12_RAW_ATTEMPT_LIMIT
        wall_time_limit = V12_WALL_TIME_LIMIT_SECONDS
        campaign_arms = V12_ARMS
        block_role = "SPENT_DEVELOPMENT_SEARCH_ENGINE_V1_2_SYSTEM_ONLY"
    elif is_v11:
        if runtime_date != V11_DEFAULT_RUNTIME_DATE:
            raise ValueError(
                "Search Engine V1.1 is authorized only for runtime date "
                f"{V11_DEFAULT_RUNTIME_DATE}"
            )
        runtime_root = (
            repo_root / f"runtime/crypto_search_engine_v1_1_{runtime_date}"
        )
        report_path = (
            repo_root / f"reports/CRYPTO_SEARCH_ENGINE_V1_1_{runtime_date}.md"
        )
        strict_target = V11_STRICT_TARGET
        checkpoint_count = V11_CHECKPOINT_COUNT
        checkpoint_size = V11_CHECKPOINT_SIZE
        raw_attempt_limit = V11_RAW_ATTEMPT_LIMIT
        wall_time_limit = V11_WALL_TIME_LIMIT_SECONDS
        campaign_arms = V11_ARMS
        block_role = "SPENT_DEVELOPMENT_SEARCH_ENGINE_V1_1_SYSTEM_ONLY"
    elif is_canary:
        runtime_root = (
            repo_root
            / f"runtime/crypto_aggtrades_system_canary_v1_{runtime_date}"
        )
        report_path = (
            repo_root
            / f"reports/CRYPTO_AGGTRADES_SYSTEM_CANARY_V1_{runtime_date}.md"
        )
        strict_target = AGGTRADES_CANARY_STRICT_TARGET
        checkpoint_count = AGGTRADES_CANARY_CHECKPOINT_COUNT
        checkpoint_size = AGGTRADES_CANARY_CHECKPOINT_SIZE
        raw_attempt_limit = AGGTRADES_CANARY_RAW_ATTEMPT_LIMIT
        wall_time_limit = AGGTRADES_CANARY_WALL_TIME_LIMIT_SECONDS
        campaign_arms = AGGTRADES_CANARY_ARMS
        block_role = "DEVELOPMENT_DIAGNOSTIC_FIXED_COHORT_AGGTRADES_SYSTEM_CANARY"
    else:
        runtime_root = repo_root / f"runtime/crypto_search_engine_v1_{runtime_date}"
        report_path = repo_root / f"reports/CRYPTO_SEARCH_ENGINE_V1_{runtime_date}.md"
        strict_target = STRICT_TARGET
        checkpoint_count = CHECKPOINT_COUNT
        checkpoint_size = CHECKPOINT_SIZE
        raw_attempt_limit = RAW_ATTEMPT_LIMIT
        wall_time_limit = WALL_TIME_LIMIT_SECONDS
        campaign_arms = FIRST_CHECKPOINT_ARMS
        block_role = "SPENT_DEVELOPMENT_BROAD39_SEARCH_ENGINE_V1"
    if is_economic:
        economic_receipt = _require_bound_economic_run(
            repo_root,
            authority_preflight,
        )
        assert economic_receipt is not None
        block_role = str(
            economic_receipt["evidence_partition"]["train"]["role"]
        )
    else:
        _require_bound_authority_preflight(
            repo_root,
            authority_preflight,
            economic_receipt_required=False,
        )
        economic_receipt = None
    observed_source = _git_sha(repo_root)
    source_sha = (source_sha or observed_source).lower()
    if source_sha != observed_source:
        raise ValueError("run must bind the checked-out producer source SHA")
    if not _source_tree_clean_for_run(
        repo_root, allowed_paths=(runtime_root, report_path)
    ):
        raise RuntimeError(
            "Search Engine V1 requires a clean producer tree; only its runtime/report may exist"
        )
    if is_economic:
        assert economic_receipt is not None
        train_partition = dict(
            economic_receipt["evidence_partition"]["train"]
        )
        store, contracts, behavior_contract, input_identities, continuation = (
            _load_v14_inputs(
                repo_root,
                behavior_window=train_partition,
            )
        )
        block_start = str(train_partition["start"])
        block_end = str(train_partition["end_exclusive"])
        carrier_id = _validate_economic_search_surface(
            receipt=economic_receipt,
            identities=input_identities,
            contracts=contracts,
            expected_campaign=campaign,
            expected_seeds=campaign_seeds,
            expected_strict_target=strict_target,
            expected_checkpoint_size=checkpoint_size,
            expected_checkpoint_count=checkpoint_count,
        )
    elif is_v13:
        store, contracts, behavior_contract, input_identities, continuation = (
            _load_v13_inputs(repo_root)
        )
        block_start = str(continuation["window"]["start"])
        block_end = str(continuation["window"]["end_exclusive"])
    elif is_carrier_gate:
        store, contracts, behavior_contract, input_identities, continuation = (
            _load_carrier_gate_inputs(repo_root, str(carrier_id))
        )
        block_start = str(continuation["window"]["start"])
        block_end = str(continuation["window"]["end_exclusive"])
    elif is_v12:
        store, contracts, behavior_contract, input_identities, continuation = (
            _load_v12_inputs(repo_root)
        )
        block_start = str(continuation["window"]["start"])
        block_end = str(continuation["window"]["end_exclusive"])
    elif is_v11:
        store, contracts, behavior_contract, input_identities, continuation = (
            _load_v11_inputs(repo_root)
        )
        block_start = str(continuation["window"]["start"])
        block_end = str(continuation["window"]["end_exclusive"])
    elif is_canary:
        store, contracts, behavior_contract, input_identities, continuation = (
            _load_aggtrades_canary_inputs(repo_root)
        )
        block_start = str(continuation["window"]["start"])
        block_end = str(continuation["window"]["end_exclusive"])
    else:
        store, contracts, behavior_contract, input_identities, continuation = (
            _load_bound_inputs(repo_root)
        )
        block_start = ADAPTIVE_START
        block_end = ADAPTIVE_END
    registry = TypedExpressionRegistry(contracts)
    optimizer_block_contract = (
        dict(
            _load_search_evidence_v1_contract(
                repo_root, campaign=campaign
            )[0]["block_robust_contract"]
        )
        if campaign == BLOCK_ROBUST_GATE_CAMPAIGN
        else None
    )
    proposal_liveness = _proposal_liveness_preflight(
        registry,
        arms=campaign_arms,
        seeds=campaign_seeds,
    )
    compiler_binding = _compiler_binding(repo_root)
    environment = _environment_fingerprint()
    if is_search_evidence_v1:
        frozen = _search_evidence_v1_frozen_contract(
            repo_root=repo_root,
            source_sha=source_sha,
            compiler_binding=compiler_binding,
            behavior_contract=behavior_contract,
            input_identities=input_identities,
            environment=environment,
            contracts=contracts,
            carrier_id=str(carrier_id),
            campaign=campaign,
        )
    elif is_mechanism_v23:
        frozen = _mechanism_v23_frozen_contract(
            repo_root=repo_root,
            source_sha=source_sha,
            compiler_binding=compiler_binding,
            behavior_contract=behavior_contract,
            input_identities=input_identities,
            environment=environment,
            contracts=contracts,
            carrier_id=str(carrier_id),
        )
    elif is_mechanism_v22:
        frozen = _mechanism_v22_frozen_contract(
            repo_root=repo_root,
            source_sha=source_sha,
            compiler_binding=compiler_binding,
            behavior_contract=behavior_contract,
            input_identities=input_identities,
            environment=environment,
            contracts=contracts,
            carrier_id=str(carrier_id),
        )
    elif is_mechanism_v21:
        frozen = _mechanism_v21_frozen_contract(
            repo_root=repo_root,
            source_sha=source_sha,
            compiler_binding=compiler_binding,
            behavior_contract=behavior_contract,
            input_identities=input_identities,
            environment=environment,
            contracts=contracts,
            carrier_id=str(carrier_id),
        )
    elif is_mechanism_v2:
        frozen = _mechanism_v2_frozen_contract(
            repo_root=repo_root,
            source_sha=source_sha,
            compiler_binding=compiler_binding,
            behavior_contract=behavior_contract,
            input_identities=input_identities,
            environment=environment,
            contracts=contracts,
            carrier_id=str(carrier_id),
        )
    elif is_economic:
        frozen = _economic_search_frozen_contract(
            source_sha=source_sha,
            compiler_binding=compiler_binding,
            behavior_contract=behavior_contract,
            input_identities=input_identities,
            environment=environment,
            contracts=contracts,
            carrier_id=str(carrier_id),
            epoch_id=economic_config["epoch_id"],
            seeds=campaign_seeds,
            seed_derivation=economic_config.get("seed_derivation"),
        )
    elif is_v13:
        frozen = _v13_frozen_contract(
            source_sha=source_sha,
            compiler_binding=compiler_binding,
            behavior_contract=behavior_contract,
            input_identities=input_identities,
            environment=environment,
            config=continuation,
            contracts=contracts,
        )
    elif is_carrier_gate:
        frozen = _carrier_gate_frozen_contract(
            source_sha=source_sha,
            compiler_binding=compiler_binding,
            behavior_contract=behavior_contract,
            input_identities=input_identities,
            environment=environment,
            config=continuation,
            contracts=contracts,
        )
    elif is_v12:
        frozen = _v12_frozen_contract(
            source_sha=source_sha,
            compiler_binding=compiler_binding,
            behavior_contract=behavior_contract,
            input_identities=input_identities,
            environment=environment,
            config=continuation,
        )
    elif is_v11:
        frozen = _v11_frozen_contract(
            source_sha=source_sha,
            compiler_binding=compiler_binding,
            behavior_contract=behavior_contract,
            input_identities=input_identities,
            environment=environment,
            config=continuation,
        )
    elif is_canary:
        frozen = _aggtrades_canary_frozen_contract(
            source_sha=source_sha,
            compiler_binding=compiler_binding,
            behavior_contract=behavior_contract,
            input_identities=input_identities,
            environment=environment,
            config=continuation,
        )
    else:
        frozen = _frozen_contract(
            source_sha=source_sha,
            compiler_binding=compiler_binding,
            behavior_contract=behavior_contract,
            input_identities=input_identities,
            environment=environment,
        )
    if is_economic:
        assert economic_receipt is not None
        frozen = _bind_economic_receipt(frozen, economic_receipt)
    frozen_hash = str(frozen["frozen_contract_sha256"])
    identities = {
        **input_identities,
        "compiler_identity": compiler_binding,
    }
    cache_root = (
        repo_root / str(input_identities["raw_cache"]["root"])
        if is_economic
        else repo_root / str(continuation["cache"]["root"])
        if is_system_campaign or is_carrier_gate
        else repo_root / str(continuation["cache_root"])
    )
    v13_origin_sets = (
        {
            key: set(str(value) for value in values)
            for key, values in continuation["field_origins"].items()
        }
        if is_v13
        else {}
    )

    existing_checkpoints: list[Path] = []
    if runtime_root.exists():
        frozen_path = runtime_root / "frozen_contract.json"
        if not frozen_path.is_file() or _read_json(frozen_path) != frozen:
            raise ValueError("existing runtime has a different frozen contract")
        if (runtime_root / "final_decision.json").is_file():
            raise FileExistsError("Search Engine V1 campaign already completed")
        existing_checkpoints = sorted(
            (runtime_root / "checkpoints").glob("checkpoint_[0-9][0-9][0-9]")
        )
        validation_checkpoint = (
            runtime_root / "checkpoints" / "checkpoint_validation"
        )
        if validation_checkpoint.is_dir():
            existing_checkpoints.append(validation_checkpoint)
    else:
        runtime_root.mkdir(parents=True)
        _write_json(runtime_root / "frozen_contract.json", frozen)
        _write_json(
            runtime_root / "embedded_preflight.json",
            {
                "schema_version": 1,
                "status": f"READY_FIRST_STRICT_BATCH_COUNTS_TOWARD_{strict_target}",
                "workers_requested": DEFAULT_WORKERS,
                "workers_12_forbidden": True,
                "memory_gate_bytes": MEMORY_GATE_BYTES,
                "available_memory_bytes": int(psutil.virtual_memory().available),
                "strict_candidates_consumed_outside_campaign": 0,
                "proposal_liveness": proposal_liveness,
            },
        )

    if existing_checkpoints:
        resume_checkpoint = max(
            existing_checkpoints,
            key=_checkpoint_resume_order,
        )
        state, policies, ledger, archive, metrics = _load_checkpoint(
            checkpoint_path=resume_checkpoint,
            registry=registry,
            expected_source_sha=source_sha,
            expected_frozen_hash=frozen_hash,
            expected_identities=identities,
        )
    else:
        state = _new_campaign_state(
            source_sha, frozen_hash, arms=campaign_arms, seeds=campaign_seeds
        )
        policies = _initial_policies(
            registry, arms=campaign_arms, seeds=campaign_seeds
        )
        ledger: list[dict[str, Any]] = []
        archive = BehaviorArchive()
        metrics: list[dict[str, Any]] = []

    attempted_ids = set(str(value) for value in state["attempted_exact_ids"])
    active_started = time.perf_counter()
    prior_active_seconds = float(state["wall_elapsed_seconds"])
    required_pairs_per_hour = strict_target * 3600.0 / wall_time_limit
    preflight_done = _read_json(runtime_root / "embedded_preflight.json").get(
        "status"
    ) not in {
        f"READY_FIRST_STRICT_BATCH_COUNTS_TOWARD_{strict_target}"
    }

    def active_elapsed() -> float:
        return prior_active_seconds + (time.perf_counter() - active_started)

    def write_producer_status(
        status: str,
        *,
        checkpoint_index: int | None = None,
        last_batch: Mapping[str, Any] | None = None,
    ) -> None:
        elapsed = active_elapsed()
        strict_count = len(ledger)
        observed_per_hour = strict_count * 3600.0 / elapsed if elapsed > 0.0 else 0.0
        remaining = max(0, strict_target - strict_count)
        projected_remaining = (
            remaining / observed_per_hour if observed_per_hour > 0.0 else None
        )
        slots = int(state.get("evaluation_slots_submitted", 0))
        available_slots = int(state.get("evaluation_worker_slots_available", 0))
        evaluator_wall = float(state.get("batch_evaluator_wall_seconds", 0.0))
        pair_cpu = float(state.get("pair_process_cpu_seconds", 0.0))
        _write_json(
            runtime_root / "producer_status.json",
            {
                "schema_version": 1,
                "status": str(status),
                "producer_pid": os.getpid(),
                "producer_parent_pid": os.getppid(),
                "producer_source_sha": source_sha,
                "frozen_contract_sha256": frozen_hash,
                "heartbeat_utc": pd.Timestamp.now(tz="UTC").isoformat(),
                "checkpoint_index": checkpoint_index,
                "strict_evaluated": strict_count,
                "strict_target": strict_target,
                "generation_attempts": int(state["generation_attempts"]),
                "active_wall_seconds": elapsed,
                "required_pairs_per_hour": required_pairs_per_hour,
                "observed_pairs_per_hour": observed_per_hour,
                "projected_remaining_hours": projected_remaining,
                "workers": int(state["workers"]),
                "evaluation_batches": int(state.get("evaluation_batches", 0)),
                "worker_slot_fill_ratio": (
                    slots / available_slots if available_slots > 0 else 0.0
                ),
                "evaluator_effective_cores": (
                    pair_cpu / evaluator_wall if evaluator_wall > 0.0 else 0.0
                ),
                "last_batch": dict(last_batch or {}),
            },
        )

    def enforce_budget(reserve_attempts: int = 0) -> None:
        state["wall_elapsed_seconds"] = active_elapsed()
        if (
            int(state["generation_attempts"]) + int(reserve_attempts)
            > raw_attempt_limit
        ):
            raise _EngineBudgetExhausted("RAW_GENERATION_ATTEMPT_LIMIT")
        if float(state["wall_elapsed_seconds"]) >= wall_time_limit:
            raise _EngineBudgetExhausted("ACTIVE_WALL_TIME_LIMIT")

    executor: concurrent.futures.ProcessPoolExecutor | None = None
    process_evidence_root = _process_evidence_root_for_campaign(
        runtime_root,
        campaign,
    )

    def start_executor(workers: int) -> concurrent.futures.ProcessPoolExecutor:
        return concurrent.futures.ProcessPoolExecutor(
            max_workers=workers,
            initializer=_worker_initialize,
            initargs=(
                str(cache_root),
                _contracts_payload(contracts),
                behavior_contract,
                block_start,
                block_end,
                block_role,
                economic_receipt,
                is_search_evidence_v1,
                optimizer_block_contract,
                (
                    str(process_evidence_root)
                    if process_evidence_root is not None
                    else None
                ),
            ),
        )

    def stop_executor() -> None:
        nonlocal executor
        if executor is not None:
            executor.shutdown(wait=True, cancel_futures=False)
            executor = None

    validation_result: dict[str, Any] | None = None
    if isinstance(state.get("validation_stage"), Mapping):
        if is_economic:
            validation_checkpoint = (
                runtime_root / "checkpoints" / "checkpoint_validation"
            )
            if not validation_checkpoint.is_dir():
                raise RuntimeError("VALIDATION_CHECKPOINT_MISSING_ON_RESUME")
            (
                validation_state,
                _validation_policies,
                _validation_ledger,
                _validation_archive,
                _validation_metrics,
                validation_result,
            ) = (
                _restore_v23_validation_checkpoint(
                    runtime_root=runtime_root,
                    checkpoint_path=validation_checkpoint,
                    registry=registry,
                    expected_source_sha=source_sha,
                    expected_frozen_hash=frozen_hash,
                    expected_identities=identities,
                )
                if is_mechanism_v23
                else _restore_validation_checkpoint(
                    runtime_root=runtime_root,
                    checkpoint_path=validation_checkpoint,
                    registry=registry,
                    expected_source_sha=source_sha,
                    expected_frozen_hash=frozen_hash,
                    expected_identities=identities,
                )
            )
            if dict(validation_state.get("validation_stage") or {}) != dict(
                state["validation_stage"]
            ):
                raise RuntimeError("VALIDATION_STAGE_STATE_CHANGED_ON_RESUME")
        else:
            validation_result = {
                **dict(state["validation_stage"]),
                "resumed": True,
            }

    def execute_frozen_validation_if_due() -> bool:
        nonlocal state
        nonlocal policies
        nonlocal ledger
        nonlocal archive
        nonlocal metrics
        nonlocal attempted_ids
        nonlocal validation_result
        if not is_economic:
            return False
        assert economic_receipt is not None
        if not _frozen_validation_due(
            campaign=campaign,
            state=state,
            economic_receipt=economic_receipt,
        ):
            return False
        stop_executor()
        if is_mechanism_v21 or is_mechanism_v22:
            train_gate = (
                _mechanism_v22_train_gate(
                    repo_root=repo_root,
                    ledger=ledger,
                )
                if is_mechanism_v22
                else _mechanism_v21_train_gate(
                    repo_root=repo_root,
                    ledger=ledger,
                )
            )
            _write_json(runtime_root / "train_gate.json", train_gate)
            if train_gate["validation_authorized_by_gate"] is not True:
                validation_result = {
                    "schema_version": 1,
                    "status": "VALIDATION_NOT_RUN_TRAIN_GATE_NEGATIVE",
                    "resumed": False,
                    "arm_decisions": {},
                    "train_gate_sha256": _payload_sha(train_gate),
                    "candidate_generation_performed": False,
                    "optimizer_feedback_written": False,
                    "policy_memory_written": False,
                    "holdout_read": False,
                    "threshold_tuning_performed": False,
                }
                return True
        from alphafactory_crypto.broad_search.replay_v14_binance_target import (
            BinanceTargetStore,
        )

        validation_execution = dict(economic_receipt["execution"])
        validation_target_root = (
            repo_root / str(validation_execution["target_cache_path"])
        )
        _validate_receipt_target_store_binding(
            store,
            validation_target_root,
            validation_execution,
        )
        validation_runner = (
            run_v23_policy_attribution_validation
            if is_mechanism_v23
            else run_frozen_validation_stage
        )
        validation_kwargs = {
            "runtime_root": runtime_root,
            "store": BinanceTargetStore(store, validation_target_root),
            "registry": registry,
            "state": state,
            "policies": policies,
            "train_ledger": ledger,
            "archive": archive,
            "train_metrics": metrics,
            "identities": identities,
            "economic_receipt": economic_receipt,
        }
        if is_mechanism_v23:
            validation_kwargs["repo_root"] = repo_root
        (
            state,
            policies,
            ledger,
            archive,
            metrics,
            validation_result,
        ) = validation_runner(**validation_kwargs)
        attempted_ids = set(
            str(value) for value in state["attempted_exact_ids"]
        )
        return True

    try:
        write_producer_status(
            "RUNNING", checkpoint_index=int(state["next_checkpoint_index"])
        )
        execute_frozen_validation_if_due()
        if _validation_control_arm_stopped(state) and not is_mechanism_campaign:
            raise _ValidationControlArmStopped(
                "VALIDATION_CONTROL_ARM_FAILED_KILL_LINE"
            )
        v22_terminal_after_gate = bool(
            (is_mechanism_v22 or is_mechanism_v23)
            and validation_result is not None
            and not (
                bool(validation_result.get("full_evolution_policy_pass"))
                if is_mechanism_v23
                else _mechanism_v22_validation_allows_expansion(validation_result)
            )
        )
        executor = (
            None
            if v22_terminal_after_gate
            else start_executor(int(state["workers"]))
        )
        for checkpoint_index in range(
            (
                checkpoint_count
                if v22_terminal_after_gate
                else int(state["next_checkpoint_index"])
            ),
            checkpoint_count,
        ):
            allocation = (
                _search_evidence_v1_checkpoint_allocation(
                    checkpoint_index,
                    repo_root=repo_root,
                    seeds=campaign_seeds,
                    campaign=campaign,
                )
                if is_search_evidence_v1
                else _mechanism_v23_checkpoint_allocation(
                    checkpoint_index,
                    repo_root=repo_root,
                    seeds=campaign_seeds,
                )
                if is_mechanism_v23
                else _mechanism_v22_checkpoint_allocation(
                    checkpoint_index,
                    repo_root=repo_root,
                    seeds=campaign_seeds,
                )
                if is_mechanism_v22
                else _mechanism_v21_checkpoint_allocation(
                    checkpoint_index,
                    repo_root=repo_root,
                    seeds=campaign_seeds,
                )
                if is_mechanism_v21
                else _mechanism_v2_checkpoint_allocation(
                    checkpoint_index,
                    repo_root=repo_root,
                    seeds=campaign_seeds,
                )
                if is_mechanism_v2
                else dict(V13_CHECKPOINT_ALLOCATION)
                if is_v13
                else dict(CARRIER_GATE_CHECKPOINT_ALLOCATION)
                if is_carrier_gate
                else dict(V12_CHECKPOINT_ALLOCATION)
                if is_v12
                else dict(V11_CHECKPOINT_ALLOCATION)
                if is_v11
                else dict(AGGTRADES_CANARY_CHECKPOINT_ALLOCATION)
                if is_canary
                else _checkpoint_allocation(
                    checkpoint_index,
                    state["arm_states"],
                    seeds=campaign_seeds,
                )
            )
            checkpoint_existing = Counter(
                str(row["arm"])
                for row in ledger
                if int(row["checkpoint_index"]) == checkpoint_index
            )
            target_by_lane = {
                _policy_key(arm, seed): allocation[arm] // len(campaign_seeds)
                for arm in allocation
                if allocation[arm] > 0
                for seed in campaign_seeds
            }
            lane_completed = Counter(
                _policy_key(str(row["arm"]), int(row["seed"]))
                for row in ledger
                if int(row["checkpoint_index"]) == checkpoint_index
            )
            arm_completion = Counter(str(row["arm"]) for row in ledger)
            lane_order = sorted(target_by_lane)
            checkpoint_start_count = len(ledger)
            checkpoint_target_count = checkpoint_start_count + (
                checkpoint_size - sum(checkpoint_existing.values())
            )
            while len(ledger) < checkpoint_target_count:
                enforce_budget()
                proposals: list[dict[str, Any]] = []
                scans_without_slot = 0
                batch_target_size = (
                    min(int(state["workers"]), len(lane_order))
                    if is_v12
                    else int(state["workers"])
                )
                balanced_batch_index = int(state["balanced_batch_index"])
                while len(proposals) < batch_target_size:
                    enforce_budget()
                    if all(
                        lane_completed[key]
                        + sum(proposal["policy_key"] == key for proposal in proposals)
                        >= target
                        for key, target in target_by_lane.items()
                    ):
                        break
                    if is_v12:
                        policy_key, next_cursor = _balanced_lane_choice(
                            lane_order=lane_order,
                            lane_completed=lane_completed,
                            proposals=proposals,
                            target_by_lane=target_by_lane,
                            scheduler_cursor=int(state["scheduler_cursor"]),
                        )
                        state["scheduler_cursor"] = next_cursor
                        if policy_key is None:
                            break
                    else:
                        policy_key = lane_order[
                            int(state["scheduler_cursor"]) % len(lane_order)
                        ]
                        state["scheduler_cursor"] = (
                            int(state["scheduler_cursor"]) + 1
                        )
                    pending_for_policy = sum(
                        proposal["policy_key"] == policy_key
                        for proposal in proposals
                    )
                    policy = policies[policy_key]
                    inflight_limit = _policy_inflight_limit(
                        campaign=campaign,
                        policy=policy,
                        workers=int(state["workers"]),
                        active_lane_count=len(lane_order),
                    )
                    if pending_for_policy >= inflight_limit:
                        scans_without_slot += 1
                        if scans_without_slot > len(lane_order) * 2:
                            break
                        continue
                    if (
                        lane_completed[policy_key]
                        + sum(
                            proposal["policy_key"] == policy_key
                            for proposal in proposals
                        )
                        >= target_by_lane[policy_key]
                    ):
                        scans_without_slot += 1
                        if scans_without_slot > len(lane_order) * 2:
                            break
                        continue
                    scans_without_slot = 0
                    arm, seed_text = policy_key.rsplit("|", 1)
                    seed = int(seed_text)
                    enforce_budget(MAX_SINGLE_PROPOSAL_RAW_ATTEMPTS)
                    proposal_cpu_started = time.process_time()
                    try:
                        candidate, metadata = _policy_propose(policy, archive)
                    except _ProposalGenerationFailure as failure:
                        proposal_cpu = time.process_time() - proposal_cpu_started
                        failed_raw_attempts = int(
                            getattr(failure, "raw_attempts", 1)
                        )
                        failed_compile_valid_attempts = int(
                            getattr(failure, "compile_valid_attempts", 0)
                        )
                        _increment_counter(
                            state,
                            arm,
                            "generation_attempts",
                            failed_raw_attempts,
                        )
                        _increment_counter(
                            state,
                            arm,
                            "compile_valid",
                            failed_compile_valid_attempts,
                        )
                        state["arm_counters"][arm]["cpu_seconds"] += proposal_cpu
                        _failure(
                            state,
                            arm,
                            "PROPOSAL_" + type(failure).__name__,
                        )
                        continue
                    raw_attempts = int(metadata["raw_attempts"])
                    compile_valid_attempts = int(
                        metadata.get("compile_valid_attempts", raw_attempts)
                    )
                    _increment_counter(
                        state, arm, "generation_attempts", raw_attempts
                    )
                    _increment_counter(
                        state, arm, "compile_valid", compile_valid_attempts
                    )
                    expression_verified = _candidate_rebuild_verified(
                        registry,
                        candidate,
                        field_role_surface(contracts)["roles"],
                    )
                    if not expression_verified:
                        attempted_ids.add(candidate.candidate_id)
                        _policy_reject(policy, candidate)
                        _failure(state, arm, "EXPRESSION_HASH_REPLAY")
                        state["arm_counters"][arm]["cpu_seconds"] += (
                            time.process_time() - proposal_cpu_started
                        )
                        continue
                    if candidate.candidate_id in attempted_ids:
                        _policy_reject(policy, candidate)
                        _failure(state, arm, "GLOBAL_EXACT_DUPLICATE")
                        state["arm_counters"][arm]["cpu_seconds"] += (
                            time.process_time() - proposal_cpu_started
                        )
                        continue
                    attempted_ids.add(candidate.candidate_id)
                    if is_v13:
                        semantic_carriers = list(
                            _candidate_semantic_carriers(
                                candidate, v13_origin_sets
                            )
                        )
                        if set(semantic_carriers) != set(v13_origin_sets):
                            _policy_reject(policy, candidate)
                            _failure(state, arm, "CROSS_CARRIER_INPUT_REQUIRED")
                            state["arm_counters"][arm]["cpu_seconds"] += (
                                time.process_time() - proposal_cpu_started
                            )
                            continue
                    else:
                        semantic_carriers = []
                    if (
                        is_system_campaign
                        and not is_carrier_gate
                        and not is_v13
                        and not (
                        set(candidate.raw_fields)
                        & set(AGGTRADES_SYSTEM_CANARY_FIELDS)
                        )
                    ):
                        _policy_reject(policy, candidate)
                        _failure(state, arm, "AGGTRADES_INPUT_REQUIRED")
                        state["arm_counters"][arm]["cpu_seconds"] += (
                            time.process_time() - proposal_cpu_started
                        )
                        continue
                    _increment_counter(state, arm, "exact_unique", 1)
                    proposal_cpu = time.process_time() - proposal_cpu_started
                    state["arm_counters"][arm]["cpu_seconds"] += proposal_cpu
                    proposals.append(
                        {
                            **metadata,
                            "policy_key": policy_key,
                            "arm": arm,
                            "seed": seed,
                            "candidate": candidate,
                            "semantic_carriers": semantic_carriers,
                            "cross_carrier_verified": (
                                True if is_v13 else None
                            ),
                            "expression_hash_verified": expression_verified,
                            "proposal_cpu_seconds": proposal_cpu,
                            "generation_attempt_ordinal": int(
                                state["generation_attempts"]
                            ),
                            "checkpoint_completion_ordinal": len(ledger)
                            - checkpoint_start_count
                            + len(proposals)
                            + 1,
                            "balanced_batch_index": (
                                balanced_batch_index if is_v12 else None
                            ),
                            "balanced_batch_slot": (
                                len(proposals) if is_v12 else None
                            ),
                            "balanced_batch_size": (
                                batch_target_size if is_v12 else None
                            ),
                            "evaluation_batch_index": int(
                                state.get("evaluation_batch_index", 0)
                            ),
                            "evaluation_batch_slot": len(proposals),
                            "policy_inflight_ordinal": pending_for_policy + 1,
                        }
                    )
                if not proposals:
                    continue
                if is_v12 and len(proposals) != V12_BALANCED_BATCH_SIZE:
                    raise _EngineBudgetExhausted(
                        "V12_BALANCED_BATCH_UNDERFILLED"
                    )
                if is_v12:
                    state["scheduler_cursor"] = (
                        int(state["scheduler_cursor"]) + 1
                    )
                assert executor is not None
                batch_index = int(state.get("evaluation_batch_index", 0))
                if process_evidence_root is not None:
                    state["attempted_exact_ids"] = sorted(attempted_ids)

                def persist_batch_stage(
                    stage: str,
                    *,
                    submitted_count: int,
                    returned_count: int,
                ) -> None:
                    if process_evidence_root is None:
                        return
                    batch_evidence_path = (
                        process_evidence_root
                        / f"producer_batch_{batch_index:06d}.json"
                    )
                    evidence = _write_proposal_batch_process_evidence(
                        evidence_root=process_evidence_root,
                        stage=stage,
                        source_sha=source_sha,
                        frozen_contract_sha256=frozen_hash,
                        checkpoint_index=checkpoint_index,
                        batch_index=batch_index,
                        generation_attempts=int(state["generation_attempts"]),
                        attempted_exact_id_count=len(attempted_ids),
                        proposals=proposals,
                        submitted_count=submitted_count,
                        returned_count=returned_count,
                    )
                    status_row = {
                        "evaluation_batch_index": batch_index,
                        "proposal_count": len(proposals),
                        "submitted_count": submitted_count,
                        "returned_count": returned_count,
                        "process_evidence_path": batch_evidence_path.relative_to(
                            runtime_root
                        ).as_posix(),
                        "process_evidence_sha256": evidence["evidence_sha256"],
                    }
                    write_producer_status(
                        stage,
                        checkpoint_index=checkpoint_index,
                        last_batch=status_row,
                    )

                persist_batch_stage(
                    "PROPOSAL_BATCH_READY_BEFORE_WORKER_SUBMIT",
                    submitted_count=0,
                    returned_count=0,
                )
                batch_wall_started = time.perf_counter()
                future_rows: list[
                    tuple[dict[str, Any], concurrent.futures.Future[dict[str, Any]]]
                ] = []
                try:
                    for proposal in proposals:
                        future_rows.append(
                            (
                                proposal,
                                executor.submit(
                                    _worker_evaluate,
                                    proposal["candidate"].to_dict(),
                                ),
                            )
                        )
                except BaseException:
                    persist_batch_stage(
                        "WORKER_SUBMISSION_FAILED",
                        submitted_count=len(future_rows),
                        returned_count=0,
                    )
                    raise
                persist_batch_stage(
                    "WORKERS_SUBMITTED",
                    submitted_count=len(future_rows),
                    returned_count=0,
                )
                worker_results = [
                    (proposal, future.result()) for proposal, future in future_rows
                ]
                persist_batch_stage(
                    "WORKER_RESULTS_RETURNED",
                    submitted_count=len(future_rows),
                    returned_count=len(worker_results),
                )
                batch_evaluator_wall = time.perf_counter() - batch_wall_started
                batch_pair_cpu = sum(
                    float(worker["process_cpu_seconds"])
                    for _, worker in worker_results
                )
                state["evaluation_batch_index"] = int(
                    state.get("evaluation_batch_index", 0)
                ) + 1
                state["evaluation_batches"] = int(
                    state.get("evaluation_batches", 0)
                ) + 1
                state["evaluation_slots_submitted"] = int(
                    state.get("evaluation_slots_submitted", 0)
                ) + len(proposals)
                state["evaluation_worker_slots_available"] = int(
                    state.get("evaluation_worker_slots_available", 0)
                ) + int(state["workers"])
                state["pair_process_cpu_seconds"] = float(
                    state.get("pair_process_cpu_seconds", 0.0)
                ) + batch_pair_cpu
                state["batch_evaluator_wall_seconds"] = float(
                    state.get("batch_evaluator_wall_seconds", 0.0)
                ) + batch_evaluator_wall
                last_batch_telemetry = {
                    "evaluation_batch_index": int(state["evaluation_batch_index"])
                    - 1,
                    "submitted": len(proposals),
                    "workers": int(state["workers"]),
                    "slot_fill_ratio": len(proposals)
                    / max(1, int(state["workers"])),
                    "pair_process_cpu_seconds": batch_pair_cpu,
                    "evaluator_wall_seconds": batch_evaluator_wall,
                    "effective_cores": (
                        batch_pair_cpu / batch_evaluator_wall
                        if batch_evaluator_wall > 0.0
                        else 0.0
                    ),
                }
                memory_failure = False
                batch_peak_rss = 0
                for proposal, worker in worker_results:
                    arm = str(proposal["arm"])
                    policy = policies[str(proposal["policy_key"])]
                    candidate = proposal["candidate"]
                    state["arm_counters"][arm]["cpu_seconds"] += float(
                        worker["process_cpu_seconds"]
                    )
                    completion_cpu_started = time.process_time()
                    batch_peak_rss = max(
                        batch_peak_rss, int(worker["worker_rss_bytes"])
                    )
                    evaluation = worker["evaluation"]
                    if evaluation is None:
                        _policy_reject(policy, candidate)
                        reason = str(worker["error"] or "PAIR_EVALUATION_FAILED")
                        degeneracy_evidence = worker.get("degeneracy_evidence")
                        if is_search_evidence_v1 and isinstance(
                            degeneracy_evidence, Mapping
                        ):
                            control_provenance = degeneracy_evidence.get(
                                "control_degeneracy_provenance"
                            )
                            realization = degeneracy_evidence.get(
                                "mechanism_realization_provenance"
                            )
                            state.setdefault("search_failure_evidence", []).append(
                                {
                                    "generation_attempt_ordinal": int(
                                        proposal["generation_attempt_ordinal"]
                                    ),
                                    "checkpoint_index": int(checkpoint_index),
                                    "candidate_id": candidate.candidate_id,
                                    "candidate_spec_sha256": _payload_sha(
                                        candidate.to_dict()
                                    ),
                                    "candidate_spec_json": json.dumps(
                                        candidate.to_dict(), sort_keys=True
                                    ),
                                    "arm": arm,
                                    "seed": int(proposal["seed"]),
                                    "skeleton_id": candidate.skeleton_id,
                                    "mechanism_family": candidate.mechanism_family,
                                    "operator_path": candidate.operator_path,
                                    "mapping_family": candidate.mapping_id,
                                    "horizon_hours": int(candidate.horizon_hours),
                                    "operation": str(proposal["operation"]),
                                    "parent_ids_json": json.dumps(
                                        list(proposal["parent_ids"])
                                    ),
                                    "failure_reason": reason.split(":", 1)[-1],
                                    "control_degeneracy_provenance_sha256": (
                                        control_provenance.get("provenance_sha256")
                                        if isinstance(control_provenance, Mapping)
                                        else None
                                    ),
                                    "control_degeneracy_provenance_json": (
                                        json.dumps(
                                            control_provenance,
                                            sort_keys=True,
                                            separators=(",", ":"),
                                            ensure_ascii=True,
                                        )
                                        if isinstance(control_provenance, Mapping)
                                        else None
                                    ),
                                    "mechanism_realization_sha256": (
                                        realization.get("provenance_sha256")
                                        if isinstance(realization, Mapping)
                                        else None
                                    ),
                                    "mechanism_realization_json": (
                                        json.dumps(
                                            realization,
                                            sort_keys=True,
                                            separators=(",", ":"),
                                            ensure_ascii=True,
                                        )
                                        if isinstance(realization, Mapping)
                                        else None
                                    ),
                                    "declared_axis_count": (
                                        realization.get("declared_axis_count")
                                        if isinstance(realization, Mapping)
                                        else None
                                    ),
                                    "active_axis_count": (
                                        realization.get("active_axis_count")
                                        if isinstance(realization, Mapping)
                                        else None
                                    ),
                                    "mechanism_realization_status": (
                                        realization.get("status")
                                        if isinstance(realization, Mapping)
                                        else None
                                    ),
                                    "condition_effect_rate": (
                                        realization.get("condition_effect_rate")
                                        if isinstance(realization, Mapping)
                                        else None
                                    ),
                                    "proposal_compile_cpu_seconds": float(
                                        proposal["proposal_cpu_seconds"]
                                    ),
                                    "pair_process_cpu_seconds": float(
                                        worker["process_cpu_seconds"]
                                    ),
                                    "pair_wall_seconds": float(worker["wall_seconds"]),
                                    "strict_evaluated": False,
                                    "matched_positive": False,
                                }
                            )
                        _failure(state, arm, reason.split(":", 1)[0])
                        memory_failure = memory_failure or bool(
                            worker["memory_error"]
                        )
                        state["arm_counters"][arm]["cpu_seconds"] += (
                            time.process_time() - completion_cpu_started
                        )
                        continue
                    completion_ordinal = len(ledger) + 1
                    arm_completion[arm] += 1
                    archive_row, new_family = archive.observe(
                        candidate=candidate,
                        evaluation=evaluation,
                        arm=arm,
                        seed=int(proposal["seed"]),
                        completion_ordinal=completion_ordinal,
                        checkpoint_index=checkpoint_index,
                    )
                    proposal["family_member_count_at_completion"] = int(
                        archive.family_counts[
                            str(archive_row["behavior_family_id"])
                        ]
                    )
                    policy_family_counts = state.setdefault(
                        "policy_local_family_counts", {}
                    ).setdefault(str(proposal["policy_key"]), {})
                    local_family_id = str(archive_row["behavior_family_id"])
                    local_family_count = int(
                        policy_family_counts.get(local_family_id, 0)
                    ) + 1
                    policy_family_counts[local_family_id] = local_family_count
                    proposal[
                        "new_policy_local_behavior_family_at_completion"
                    ] = local_family_count == 1
                    proposal[
                        "policy_local_family_count_at_completion"
                    ] = local_family_count
                    policy_archive_row = {
                        **archive_row,
                        "operation": proposal["operation"],
                        "parent_ids": list(proposal["parent_ids"]),
                        "transition_key": proposal.get("transition_key"),
                        "new_policy_local_behavior_family_at_completion": bool(
                            proposal[
                                "new_policy_local_behavior_family_at_completion"
                            ]
                        ),
                        "policy_local_family_count_at_completion": int(
                            proposal[
                                "policy_local_family_count_at_completion"
                            ]
                        ),
                        "block_robust_ordering": evaluation.get(
                            "block_robust_ordering"
                        ),
                    }
                    if (
                        isinstance(policy, TypedEvolutionV2)
                        and policy.parameters.get(
                            "campaign_local_transition_collision_control"
                        )
                        is True
                        and str(proposal["operation"])
                        == "COMPATIBLE_SKELETON_VARIANT_MUTATION"
                    ):
                        policy.observe_transition(
                            transition_key=str(
                                proposal.get("transition_key") or ""
                            ),
                            new_family=bool(
                                proposal[
                                    "new_policy_local_behavior_family_at_completion"
                                ]
                            ),
                            block_after_collisions=int(
                                policy.parameters[
                                    "transition_block_after_collisions"
                                ]
                            ),
                        )
                    _policy_observe(
                        policy,
                        candidate=candidate,
                        reward=_search_ordering_reward(evaluation),
                        archive_row=policy_archive_row,
                    )
                    _increment_counter(state, arm, "matched_control_valid", 1)
                    _increment_counter(state, arm, "strict_evaluated", 1)
                    lane_completed[str(proposal["policy_key"])] += 1
                    ledger_row = _ledger_row(
                        candidate=candidate,
                        evaluation=evaluation,
                        proposal=proposal,
                        archive_row=archive_row,
                        new_family=new_family,
                        state_hash_after=(
                            str(proposal["policy_state_hash_after_proposal"])
                            if type(policy) is MechanismRandomV2
                            else policy.state_hash()
                        ),
                        checkpoint_index=checkpoint_index,
                        completion_ordinal=completion_ordinal,
                        arm_completion_ordinal=arm_completion[arm],
                        worker=worker,
                        require_evidence_provenance=is_search_evidence_v1,
                    )
                    completion_cpu = time.process_time() - completion_cpu_started
                    state["arm_counters"][arm]["cpu_seconds"] += completion_cpu
                    ledger_row["archive_completion_cpu_seconds"] = completion_cpu
                    ledger.append(ledger_row)
                    if is_v13 and len(ledger) == V13_CANARY_STRICT_COUNT:
                        _write_json(
                            runtime_root / "constructibility_canary.json",
                            {
                                "schema_version": 1,
                                "status": "PASS_PENDING_CHECKPOINT_RESTORE",
                                "strict_evaluated_count": len(ledger),
                                "all_cross_carrier": all(
                                    bool(row.get("cross_carrier_verified"))
                                    for row in ledger
                                ),
                                "all_dual_axis_traced": all(
                                    row.get("right_delta_weight_sha256")
                                    and row.get("right_axis_feedback_json")
                                    for row in ledger
                                ),
                                "compiler_validation": True,
                                "matched_controls": [
                                    "left_only",
                                    "right_only",
                                ],
                                "receipt_and_hash_replay": all(
                                    bool(row["expression_hash_verified"])
                                    and (
                                        row.get("receipt_json") is None
                                        or bool(row.get("receipt_verified"))
                                    )
                                    for row in ledger
                                ),
                                "checkpoint_restore": "PENDING_CHECKPOINT_000",
                                "sealed_reads": 0,
                            },
                        )
                if not preflight_done:
                    available_memory = int(psutil.virtual_memory().available)
                    projected = (
                        batch_peak_rss * DEFAULT_WORKERS
                        + int(psutil.Process(os.getpid()).memory_info().rss)
                    )
                    fallback = bool(
                        memory_failure
                        or projected > MEMORY_GATE_BYTES
                        or available_memory < MEMORY_GATE_BYTES
                    )
                    preflight = {
                        **_read_json(runtime_root / "embedded_preflight.json"),
                        "schema_version": 1,
                        "status": "PASS_10_WORKERS"
                        if not fallback
                        else "MEMORY_FAIL_CLOSED_FALLBACK_8",
                        "workers_requested": DEFAULT_WORKERS,
                        "workers_selected": FALLBACK_WORKERS
                        if fallback
                        else DEFAULT_WORKERS,
                        "workers_12_forbidden": True,
                        "strict_candidates_consumed_outside_campaign": 0,
                        "first_batch_candidates": len(proposals),
                        "first_batch_strict_completed": sum(
                            worker["evaluation"] is not None
                            for _, worker in worker_results
                        ),
                        "peak_worker_rss_bytes": batch_peak_rss,
                        "projected_10_worker_plus_parent_rss_bytes": projected,
                        "available_memory_bytes": available_memory,
                        "memory_gate_bytes": MEMORY_GATE_BYTES,
                    }
                    _write_json(runtime_root / "embedded_preflight.json", preflight)
                    preflight_done = True
                    if fallback:
                        stop_executor()
                        state["workers"] = FALLBACK_WORKERS
                        state["memory_fallback_used"] = True
                        executor = start_executor(FALLBACK_WORKERS)
                elif memory_failure:
                    if int(state["workers"]) == DEFAULT_WORKERS:
                        stop_executor()
                        state["workers"] = FALLBACK_WORKERS
                        state["memory_fallback_used"] = True
                        executor = start_executor(FALLBACK_WORKERS)
                    else:
                        raise _EngineBudgetExhausted(
                            "MEMORY_ERROR_RECURRED_AT_8_WORKERS"
                        )
                if is_v12:
                    state["balanced_batch_index"] = balanced_batch_index + 1
                state["attempted_exact_ids"] = sorted(attempted_ids)
                state["wall_elapsed_seconds"] = active_elapsed()
                if (
                    int(state["generation_attempts"]) > raw_attempt_limit
                    or float(state["wall_elapsed_seconds"]) > wall_time_limit
                ):
                    raise _EngineBudgetExhausted(
                        "RAW_OR_WALL_BUDGET_EXCEEDED_AFTER_WORKER_BATCH"
                    )
                if len(ledger) % 100 == 0:
                    write_producer_status(
                        "RUNNING",
                        checkpoint_index=checkpoint_index,
                        last_batch=last_batch_telemetry,
                    )
                    print(
                        json.dumps(
                            {
                                "event": "search_engine_v1_progress",
                                "checkpoint_index": checkpoint_index,
                                "strict_evaluated": len(ledger),
                                "generation_attempts": state[
                                    "generation_attempts"
                                ],
                                "behavior_families": len(
                                    archive.champion_by_family
                                ),
                                "workers": state["workers"],
                                "required_pairs_per_hour": required_pairs_per_hour,
                                "observed_pairs_per_hour": (
                                    len(ledger) * 3600.0 / active_elapsed()
                                ),
                                "worker_slot_fill_ratio": (
                                    int(state["evaluation_slots_submitted"])
                                    / max(
                                        1,
                                        int(
                                            state[
                                                "evaluation_worker_slots_available"
                                            ]
                                        ),
                                    )
                                ),
                            },
                            sort_keys=True,
                        ),
                        flush=True,
                    )

            checkpoint_rows = [
                row
                for row in ledger
                if int(row["checkpoint_index"]) == checkpoint_index
            ]
            cem_arms = tuple(
                arm
                for arm in campaign_arms
                if arm
                in {
                    "hierarchical_typed_cem_v2",
                    "behavior_niched_cem_v2_1",
                    "mechanism_level_cem_v2",
                }
            )
            evolution_adaptation_arms = tuple(
                arm
                for arm in campaign_arms
                if arm
                in {
                    "behavior_niched_evolution_v2_1",
                    "collision_controlled_evolution_v2_2",
                }
            )
            for seed in campaign_seeds:
                for arm in cem_arms:
                    policy = policies[_policy_key(arm, seed)]
                    assert isinstance(
                        policy, (HierarchicalTypedCEMV2, MechanismCEMV2)
                    )
                    policy.update(
                        [
                            row
                            for row in checkpoint_rows
                            if row["arm"] == arm
                            and int(row["seed"]) == seed
                        ]
                    )
                for arm in evolution_adaptation_arms:
                    policy = policies[_policy_key(arm, seed)]
                    assert isinstance(policy, TypedEvolutionV2)
                    policy.update_operator_productivity(
                        [
                            row
                            for row in checkpoint_rows
                            if row["arm"] == arm
                            and int(row["seed"]) == seed
                        ]
                    )
            state["next_checkpoint_index"] = checkpoint_index + 1
            state["wall_elapsed_seconds"] = active_elapsed()
            checkpoint_metrics = _metrics_rows(
                checkpoint_index=checkpoint_index,
                ledger=ledger,
                archive=archive,
                state=state,
                policies=policies,
                comparison_arms=(
                    tuple(economic_config["arms"])
                    if is_search_evidence_v1
                    else MECHANISM_SEARCH_V23_ARMS
                    if is_mechanism_v23
                    else MECHANISM_SEARCH_V22_ARMS
                    if is_mechanism_v22
                    else MECHANISM_SEARCH_V21_ARMS
                    if is_mechanism_v21
                    else MECHANISM_SEARCH_V2_ARMS
                    if is_mechanism_v2
                    else V13_ARMS
                    if is_v13
                    else CARRIER_GATE_ARMS
                    if is_carrier_gate
                    else V12_ARMS
                    if is_v12
                    else V11_ARMS
                    if is_v11
                    else AGGTRADES_CANARY_ARMS
                    if is_canary
                    else None
                ),
            )
            gates = (
                {}
                if is_system_campaign or is_mechanism_campaign
                else _apply_exit_gate(
                    checkpoint_index=checkpoint_index,
                    checkpoint_metrics=checkpoint_metrics,
                    state=state,
                )
            )
            metrics.extend(checkpoint_metrics)
            _write_top_level_artifacts(
                runtime_root=runtime_root,
                ledger=ledger,
                archive=archive,
                metrics=metrics,
                failure_evidence=(
                    state.get("search_failure_evidence", [])
                    if is_search_evidence_v1
                    else None
                ),
            )
            checkpoint_path = _write_checkpoint(
                runtime_root=runtime_root,
                label=f"checkpoint_{checkpoint_index:03d}",
                checkpoint_index=checkpoint_index,
                registry=registry,
                state=state,
                policies=policies,
                ledger=ledger,
                archive=archive,
                metrics=metrics,
                identities=identities,
            )
            state, policies, ledger, archive, metrics = _load_checkpoint(
                checkpoint_path=checkpoint_path,
                registry=registry,
                expected_source_sha=source_sha,
                expected_frozen_hash=frozen_hash,
                expected_identities=identities,
            )
            validation_ran = execute_frozen_validation_if_due()
            if _validation_control_arm_stopped(state) and not is_mechanism_campaign:
                raise _ValidationControlArmStopped(
                    "VALIDATION_CONTROL_ARM_FAILED_KILL_LINE"
                )
            v22_terminal_after_gate = bool(
                (is_mechanism_v22 or is_mechanism_v23)
                and validation_ran
                and validation_result is not None
                and not (
                    bool(validation_result.get("full_evolution_policy_pass"))
                    if is_mechanism_v23
                    else _mechanism_v22_validation_allows_expansion(validation_result)
                )
            )
            if (
                validation_ran
                and int(state["next_checkpoint_index"]) < checkpoint_count
                and not v22_terminal_after_gate
            ):
                executor = start_executor(int(state["workers"]))
            if is_v13 and checkpoint_index == 0:
                canary_path = runtime_root / "constructibility_canary.json"
                canary = _read_json(canary_path)
                canary.update(
                    {
                        "status": "PASS",
                        "checkpoint_restore": "VERIFIED_AT_CHECKPOINT_000",
                        "checkpoint_manifest_sha256": sha256_file(
                            checkpoint_path / "manifest.json"
                        ),
                    }
                )
                _write_json(canary_path, canary)
            attempted_ids = set(str(value) for value in state["attempted_exact_ids"])
            write_producer_status(
                "CHECKPOINT_COMPLETE",
                checkpoint_index=checkpoint_index,
            )
            print(
                json.dumps(
                    {
                        "event": "search_engine_v1_checkpoint_complete",
                        "checkpoint": checkpoint_path.name,
                        "strict_evaluated": len(ledger),
                        "behavior_families": len(archive.champion_by_family),
                        "arm_states": state["arm_states"],
                        "exit_gates": gates,
                        "restore_verified": True,
                    },
                    sort_keys=True,
                ),
                flush=True,
            )
            if v22_terminal_after_gate:
                break
        stop_executor()
    except _ValidationControlArmStopped as failure:
        stop_executor()
        if not is_economic or economic_config is None:
            raise
        validation_stage = dict(state.get("validation_stage") or {})
        arm_decisions = dict(validation_stage.get("arm_decisions") or {})
        control_decision = dict(
            arm_decisions.get("canonical_typed_random") or {}
        )
        if control_decision.get("passed") is not False:
            raise RuntimeError(
                "VALIDATION_CONTROL_ARM_STOP_STATE_INCONSISTENT"
            ) from failure
        validation_checkpoint = (
            runtime_root / "checkpoints" / "checkpoint_validation"
        )
        if not validation_checkpoint.is_dir():
            raise RuntimeError(
                "VALIDATION_CONTROL_ARM_STOP_CHECKPOINT_MISSING"
            ) from failure
        state["attempted_exact_ids"] = sorted(attempted_ids)
        state["wall_elapsed_seconds"] = active_elapsed()
        _write_top_level_artifacts(
            runtime_root=runtime_root,
            ledger=ledger,
            archive=archive,
            metrics=metrics,
        )
        decision = _validation_blocked_decision(
            source_sha=source_sha,
            state=state,
            ledger=ledger,
            archive=archive,
            checkpoint=validation_checkpoint,
            failure={
                "reason": str(failure),
                "arm": "canonical_typed_random",
                "candidate_id": "EQUAL_COUNT_ARM_ENSEMBLE",
                "horizon_hours": -1,
                "selection_rank": -1,
            },
            campaign=campaign,
        )
        decision["validation_stage"] = {
            key: value
            for key, value in validation_stage.items()
            if key != "arm_decisions"
        }
        decision["validation_arm_decisions"] = arm_decisions
        _write_json(runtime_root / "final_decision.json", decision)
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _validation_control_arm_stopped_report_text(decision),
            encoding="utf-8",
            newline="\n",
        )
        manifest = _final_manifest(
            repo_root=repo_root,
            runtime_root=runtime_root,
            report_path=report_path,
            source_sha=source_sha,
            frozen_hash=frozen_hash,
            identities=identities,
            state=state,
            epoch_id=economic_config["epoch_id"],
            base_sha=source_sha,
            status="ENGINE_VALIDATION_BLOCKED",
            continuation=(
                "python -m alphafactory_crypto.broad_search.search_engine_v1 "
                f"check-{economic_config['cli_suffix']} "
                f"--runtime-date {runtime_date}"
            ),
        )
        _write_json(runtime_root / "run_manifest.json", manifest)
        print(
            json.dumps(
                {
                    "event": "search_engine_v1_validation_control_arm_stopped",
                    "checkpoint": validation_checkpoint.name,
                    "strict_evaluated": len(ledger),
                    "reason": str(failure),
                },
                sort_keys=True,
            ),
            flush=True,
        )
        return {"result": "ENGINE_VALIDATION_BLOCKED", **decision}
    except _ValidationStageBlocked as failure:
        stop_executor()
        if not is_economic or economic_config is None:
            raise
        failure_payload = failure.to_dict()
        state["validation_stage"] = {
            "status": "BLOCKED_BEFORE_COMPLETE_EQUAL_COUNT",
            **failure_payload,
            "candidate_generation_performed": False,
            "optimizer_feedback_written": False,
            "policy_memory_written": False,
            "holdout_read": False,
        }
        state["attempted_exact_ids"] = sorted(attempted_ids)
        state["wall_elapsed_seconds"] = active_elapsed()
        _write_top_level_artifacts(
            runtime_root=runtime_root,
            ledger=ledger,
            archive=archive,
            metrics=metrics,
        )
        blocked_checkpoint = _write_checkpoint(
            runtime_root=runtime_root,
            label="checkpoint_validation_blocked",
            checkpoint_index=int(state["next_checkpoint_index"]),
            registry=registry,
            state=state,
            policies=policies,
            ledger=ledger,
            archive=archive,
            metrics=metrics,
            identities=identities,
        )
        decision = _validation_blocked_decision(
            source_sha=source_sha,
            state=state,
            ledger=ledger,
            archive=archive,
            checkpoint=blocked_checkpoint,
            failure=failure_payload,
            campaign=campaign,
        )
        _write_json(runtime_root / "final_decision.json", decision)
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _validation_blocked_report_text(decision),
            encoding="utf-8",
            newline="\n",
        )
        manifest = _final_manifest(
            repo_root=repo_root,
            runtime_root=runtime_root,
            report_path=report_path,
            source_sha=source_sha,
            frozen_hash=frozen_hash,
            identities=identities,
            state=state,
            epoch_id=economic_config["epoch_id"],
            base_sha=source_sha,
            status="ENGINE_VALIDATION_BLOCKED",
            continuation=(
                "python -m alphafactory_crypto.broad_search.search_engine_v1 "
                f"check-{economic_config['cli_suffix']} "
                f"--runtime-date {runtime_date}"
            ),
        )
        _write_json(runtime_root / "run_manifest.json", manifest)
        print(
            json.dumps(
                {
                    "event": "search_engine_v1_validation_blocked",
                    "checkpoint": blocked_checkpoint.name,
                    "strict_evaluated": len(ledger),
                    **failure_payload,
                },
                sort_keys=True,
            ),
            flush=True,
        )
        return {"result": "ENGINE_VALIDATION_BLOCKED", **decision}
    except _EngineBudgetExhausted as failure:
        stop_executor()
        state["attempted_exact_ids"] = sorted(attempted_ids)
        state["wall_elapsed_seconds"] = active_elapsed()
        _write_top_level_artifacts(
            runtime_root=runtime_root,
            ledger=ledger,
            archive=archive,
            metrics=metrics,
        )
        partial = _write_checkpoint(
            runtime_root=runtime_root,
            label="checkpoint_budget_exhausted",
            checkpoint_index=int(state["next_checkpoint_index"]),
            registry=registry,
            state=state,
            policies=policies,
            ledger=ledger,
            archive=archive,
            metrics=metrics,
            identities=identities,
        )
        decision = {
            "schema_version": 1,
            "status": "ENGINE_BUDGET_EXHAUSTED",
            "reason": str(failure),
            "strict_evaluated_count": len(ledger),
            "generation_attempts": int(state["generation_attempts"]),
            "active_wall_seconds": float(state["wall_elapsed_seconds"]),
            "checkpoint": partial.name,
            "parameters_changed": False,
            "seed_changed": False,
            "rescue_rerun_started": False,
            "sealed_reads": 0,
        }
        _write_json(runtime_root / "final_decision.json", decision)
        write_producer_status(
            "ENGINE_BUDGET_EXHAUSTED",
            checkpoint_index=int(state["next_checkpoint_index"]),
        )
        return {"result": "ENGINE_BUDGET_EXHAUSTED", **decision}
    except Exception as failure:
        stop_executor()
        state["attempted_exact_ids"] = sorted(attempted_ids)
        state["wall_elapsed_seconds"] = active_elapsed()
        failure_payload = {
            "schema_version": 1,
            "status": "PRODUCER_FAILED",
            "failure_type": type(failure).__name__,
            "failure_message": str(failure),
            "traceback": traceback.format_exc(),
            "producer_source_sha": source_sha,
            "frozen_contract_sha256": frozen_hash,
            "strict_evaluated_count": len(ledger),
            "generation_attempts": int(state["generation_attempts"]),
            "active_wall_seconds": float(state["wall_elapsed_seconds"]),
            "checkpoint_index": int(state["next_checkpoint_index"]),
            "sealed_reads": 0,
        }
        _write_json(runtime_root / "producer_failure.json", failure_payload)
        write_producer_status(
            "PRODUCER_FAILED",
            checkpoint_index=int(state["next_checkpoint_index"]),
        )
        print(json.dumps(failure_payload, sort_keys=True), file=sys.stderr, flush=True)
        raise
    finally:
        stop_executor()

    v22_terminal_count = (
        MECHANISM_SEARCH_V23_STRICT_TARGET
        if (
            is_mechanism_v23
            and validation_result is not None
            and bool(validation_result.get("full_evolution_policy_pass"))
        )
        else MECHANISM_SEARCH_V23_QUALIFICATION_STRICT_COUNT
        if is_mechanism_v23
        else MECHANISM_SEARCH_V22_STRICT_TARGET
        if (
            is_mechanism_v22
            and validation_result is not None
            and _mechanism_v22_validation_allows_expansion(validation_result)
        )
        else MECHANISM_SEARCH_V22_QUALIFICATION_STRICT_COUNT
        if is_mechanism_v22
        else strict_target
    )
    if len(ledger) != v22_terminal_count:
        raise AssertionError(
            "Search Engine V1 ended without exactly "
            f"{v22_terminal_count:,} terminal strict candidates"
        )
    if is_search_evidence_v1 and validation_result is None:
        validation_result = {
            "schema_version": 1,
            "status": "NOT_AUTHORIZED",
            "candidate_generation_performed": False,
            "optimizer_feedback_written": False,
            "policy_memory_written": False,
            "holdout_read": False,
            "arm_decisions": {},
        }
    if is_economic and validation_result is None:
        raise RuntimeError(
            "VALIDATION_STAGE_NOT_COMPLETED_BEFORE_ADDITIONAL_BUDGET"
        )
    state["wall_elapsed_seconds"] = active_elapsed()
    evidence_summary = (
        _write_search_evidence_v1_artifacts(
            runtime_root=runtime_root,
            ledger=ledger,
            state=state,
            economic_receipt=economic_receipt or {},
            config=_load_search_evidence_v1_contract(
                repo_root, campaign=campaign
            )[0],
            campaign=campaign,
        )
        if is_search_evidence_v1
        else None
    )
    decision = (
        _search_evidence_v1_final_decision(
            repo_root=repo_root,
            source_sha=source_sha,
            state=state,
            ledger=ledger,
            archive=archive,
            runtime_root=runtime_root,
            evidence_summary=evidence_summary or {},
            campaign=campaign,
        )
        if is_search_evidence_v1
        else _mechanism_v23_final_decision(
            repo_root=repo_root,
            source_sha=source_sha,
            state=state,
            ledger=ledger,
            archive=archive,
            runtime_root=runtime_root,
            validation_result=validation_result or {},
        )
        if is_mechanism_v23
        else _mechanism_v22_final_decision(
            repo_root=repo_root,
            source_sha=source_sha,
            state=state,
            ledger=ledger,
            archive=archive,
            runtime_root=runtime_root,
            validation_result=validation_result or {},
        )
        if is_mechanism_v22
        else _mechanism_v21_final_decision(
            repo_root=repo_root,
            source_sha=source_sha,
            state=state,
            ledger=ledger,
            archive=archive,
            metrics=metrics,
            runtime_root=runtime_root,
            validation_result=validation_result or {},
        )
        if is_mechanism_v21
        else _mechanism_v2_final_decision(
            repo_root=repo_root,
            source_sha=source_sha,
            state=state,
            ledger=ledger,
            archive=archive,
            metrics=metrics,
            runtime_root=runtime_root,
            validation_result=validation_result or {},
        )
        if is_mechanism_v2
        else _v13_final_decision(
            source_sha=source_sha,
            state=state,
            ledger=ledger,
            archive=archive,
            metrics=metrics,
            runtime_root=runtime_root,
        )
        if is_v13
        else _carrier_gate_final_decision(
            source_sha=source_sha,
            carrier_id=str(carrier_id),
            state=state,
            ledger=ledger,
            archive=archive,
            metrics=metrics,
            runtime_root=runtime_root,
        )
        if is_carrier_gate
        else _v12_final_decision(
            source_sha=source_sha,
            state=state,
            ledger=ledger,
            archive=archive,
            metrics=metrics,
            runtime_root=runtime_root,
        )
        if is_v12
        else _v11_final_decision(
            source_sha=source_sha,
            state=state,
            ledger=ledger,
            archive=archive,
            metrics=metrics,
            runtime_root=runtime_root,
        )
        if is_v11
        else _aggtrades_canary_final_decision(
            source_sha=source_sha,
            state=state,
            ledger=ledger,
            archive=archive,
            metrics=metrics,
            runtime_root=runtime_root,
        )
        if is_canary
        else _final_decision(
            source_sha=source_sha,
            state=state,
            ledger=ledger,
            archive=archive,
            metrics=metrics,
            runtime_root=runtime_root,
            seeds=campaign_seeds,
        )
    )
    if is_economic:
        assert economic_config is not None
        assert validation_result is not None
        decision["validation_stage"] = {
            key: value
            for key, value in validation_result.items()
            if key != "arm_decisions"
        }
        decision["validation_arm_decisions"] = dict(
            validation_result.get("arm_decisions") or {}
        )
        decision.update(
            {
                "epoch_id": economic_config["epoch_id"],
                "report_title": economic_config["report_title"],
                "surface_description": (
                    "existing 115-field OI/mark x aggTrades aligned carrier; "
                    "receipt-bound Binance USD-M target"
                ),
                "search_campaign": campaign,
            }
        )
    if is_mechanism_campaign:
        _write_mechanism_v2_knowledge(
            repo_root=repo_root,
            runtime_root=runtime_root,
            ledger=ledger,
            validation_result=validation_result or {},
            campaign=campaign,
        )
    _write_json(runtime_root / "final_decision.json", decision)
    report_path.parent.mkdir(parents=True, exist_ok=True)
    report_path.write_text(
        (
            _search_evidence_v1_report_text(decision)
            if is_search_evidence_v1
            else _mechanism_v23_report_text(decision)
            if is_mechanism_v23
            else _mechanism_v22_report_text(decision)
            if is_mechanism_v22
            else _mechanism_v21_report_text(decision)
            if is_mechanism_v21
            else _mechanism_v2_report_text(decision)
            if is_mechanism_v2
            else _report_text(decision)
            if is_economic
            else _v13_report_text(decision)
            if is_v13
            else _carrier_gate_report_text(decision)
            if is_carrier_gate
            else _v12_report_text(decision)
            if is_v12
            else _v11_report_text(decision)
            if is_v11
            else _aggtrades_canary_report_text(decision)
            if is_canary
            else _report_text(decision)
        ),
        encoding="utf-8",
        newline="\n",
    )
    manifest = _final_manifest(
        repo_root=repo_root,
        runtime_root=runtime_root,
        report_path=report_path,
        source_sha=source_sha,
        frozen_hash=frozen_hash,
        identities=identities,
        state=state,
        epoch_id=(
            economic_config["epoch_id"]
            if is_economic
            else V13_EPOCH_ID
            if is_v13
            else CARRIER_GATE_EPOCH_ID
            if is_carrier_gate
            else V12_EPOCH_ID
            if is_v12
            else V11_EPOCH_ID
            if is_v11
            else AGGTRADES_CANARY_EPOCH_ID
            if is_canary
            else EPOCH_ID
        ),
        base_sha=(
            source_sha
            if is_system_campaign or is_economic
            else BASE_SHA
        ),
        continuation=(
            "python -m alphafactory_crypto.broad_search.search_engine_v1 "
            f"check-{economic_config['cli_suffix']} --runtime-date {runtime_date}"
            if is_economic
            else "python -m alphafactory_crypto.broad_search.search_engine_v1 "
            f"check-v13 --runtime-date {runtime_date}"
            if is_v13
            else "python -m alphafactory_crypto.broad_search.search_engine_v1 "
            f"check-carrier-gate --carrier-id {carrier_id} --runtime-date {runtime_date}"
            if is_carrier_gate
            else "python -m alphafactory_crypto.broad_search.search_engine_v1 "
            f"check-v12 --runtime-date {runtime_date}"
            if is_v12
            else "python -m alphafactory_crypto.broad_search.search_engine_v1 "
            f"check-v11 --runtime-date {runtime_date}"
            if is_v11
            else "python -m alphafactory_crypto.broad_search.search_engine_v1 "
            f"check-canary --runtime-date {runtime_date}"
            if is_canary
            else "python -m alphafactory_crypto.broad_search.search_engine_v1 "
            f"check --runtime-date {runtime_date}"
        ),
    )
    _write_json(runtime_root / "run_manifest.json", manifest)
    run_result = (
        "PASS"
        if is_v13
        or is_carrier_gate
        or (not is_v11 and not is_v12)
        or decision["status"]
        in {
            "PASS_SEARCH_ENGINE_V1_1_COMPLETED",
            "PASS_SEARCH_ENGINE_V1_2_COMPLETED",
        }
        else "ENGINE_BUDGET_EXHAUSTED"
        if decision["status"] == "ENGINE_BUDGET_EXHAUSTED"
        else "FAIL"
    )
    return {
        "result": run_result,
        "status": decision["status"],
        "producer_source_sha": source_sha,
        "strict_evaluated_count": len(ledger),
        "generation_attempts": int(state["generation_attempts"]),
        "checkpoint_count": checkpoint_count,
        "behavior_family_count": len(archive.champion_by_family),
        "validation_status": (
            validation_result["status"]
            if validation_result is not None
            else "NOT_APPLICABLE"
        ),
        "validation_resumed": _validation_resumed_flag(validation_result),
        "artifact_bundle_sha256": manifest["artifact_bundle_sha256"],
        "sealed_reads": 0,
    }


def check_engine(
    repo_root: Path,
    *,
    runtime_date: str = DEFAULT_RUNTIME_DATE,
    campaign: str = "legacy",
) -> dict[str, Any]:
    is_economic = campaign in ECONOMIC_SEARCH_CAMPAIGNS
    if campaign not in {"legacy", *ECONOMIC_SEARCH_CAMPAIGNS}:
        raise ValueError(f"unsupported check campaign: {campaign}")
    if is_economic:
        economic_config = _economic_campaign_config(campaign)
        if runtime_date != economic_config["runtime_date"]:
            raise ValueError("economic search runtime date changed")
        runtime_root = (
            repo_root
            / f"runtime/{economic_config['runtime_prefix']}_{runtime_date}"
        )
        report_path = (
            repo_root
            / f"reports/{economic_config['report_prefix']}_{runtime_date}.md"
        )
    else:
        runtime_root = (
            repo_root / f"runtime/crypto_search_engine_v1_{runtime_date}"
        )
        report_path = (
            repo_root / f"reports/CRYPTO_SEARCH_ENGINE_V1_{runtime_date}.md"
        )
    errors: list[str] = []
    required = (
        "frozen_contract.json",
        "embedded_preflight.json",
        "candidate_ledger.parquet",
        "behavior_archive.parquet",
        "behavior_family_summary.json",
        "arm_checkpoint_metrics.parquet",
        "final_decision.json",
        "run_manifest.json",
    )
    for name in required:
        if not (runtime_root / name).is_file():
            errors.append(f"missing:{name}")
    if not report_path.is_file():
        errors.append("missing:report")
    if errors:
        return {"result": "FAIL", "errors": errors}

    frozen = _read_json(runtime_root / "frozen_contract.json")
    decision = _read_json(runtime_root / "final_decision.json")
    manifest = _read_json(runtime_root / "run_manifest.json")
    budget_exhausted = (
        decision.get("status") == "ENGINE_BUDGET_EXHAUSTED"
    )
    validation_blocked = (
        decision.get("status") == "ENGINE_VALIDATION_BLOCKED"
    )
    validation_status = str(
        dict(decision.get("validation_stage") or {}).get("status") or ""
    )
    validation_complete = validation_status == "VALIDATION_STAGE_COMPLETE"
    completed_validation_control_stop = _completed_validation_control_stop(
        decision
    )
    preflight = _read_json(runtime_root / "embedded_preflight.json")
    ledger = pd.read_parquet(runtime_root / "candidate_ledger.parquet")
    archive = pd.read_parquet(runtime_root / "behavior_archive.parquet")
    metrics = pd.read_parquet(runtime_root / "arm_checkpoint_metrics.parquet")
    family_summary = _read_json(runtime_root / "behavior_family_summary.json")
    expected_campaign_seeds = (
        _economic_campaign_seeds(campaign) if is_economic else SEEDS
    )
    if tuple(int(value) for value in frozen.get("seeds") or ()) != tuple(
        expected_campaign_seeds
    ):
        errors.append("frozen_seed_set")
    if "seed" in ledger.columns and not set(
        int(value) for value in ledger["seed"].dropna().unique()
    ).issubset(set(expected_campaign_seeds)):
        errors.append("ledger_seed_set")
    if campaign == ECONOMIC_SEARCH_V6_CAMPAIGN:
        expected_seed_contract = {
            "derivation": ECONOMIC_SEARCH_V6_SEED_DERIVATION,
            "pre_registered_before_candidate_one": True,
            "prior_v1_v5_seed_set_reused": False,
            "within_campaign_seed_change_allowed": False,
            "additional_seed_campaign_allowed": False,
            "evidence_role": "DEVELOPMENT_SEED_ROBUSTNESS_ONLY",
        }
        if dict(frozen.get("seed_contract") or {}) != expected_seed_contract:
            errors.append("frozen_seed_contract")
        errors.extend(
            f"v6_seed_balance:{item}"
            for item in _completed_checkpoint_seed_balance_errors(
                ledger,
                expected_seeds=expected_campaign_seeds,
            )
        )
    if (
        is_economic
        and validation_complete
        and not budget_exhausted
        and (not validation_blocked or completed_validation_control_stop)
    ):
        validation_rows = pd.read_parquet(
            runtime_root / "validation_candidate_ledger.parquet"
        )
        validation_metrics = pd.read_parquet(
            runtime_root / "validation_arm_metrics.parquet"
        )
        validation_decisions = _read_json(
            runtime_root / "validation_decisions.json"
        )
        if campaign == ECONOMIC_SEARCH_V6_CAMPAIGN:
            if "candidate_id" not in validation_rows.columns:
                errors.append("validation_candidate_provenance")
            elif not set(validation_rows["candidate_id"].astype(str)).issubset(
                set(ledger["candidate_id"].astype(str))
            ):
                errors.append("validation_candidate_provenance")
        validation_checkpoint = (
            runtime_root / "checkpoints" / "checkpoint_validation"
        )
        if not validation_checkpoint.is_dir():
            errors.append("validation_checkpoint")
        if "validation_status" not in validation_rows.columns:
            errors.append("validation_candidate_status")
            evaluated_validation_rows = validation_rows.iloc[0:0]
        else:
            observed_statuses = set(
                validation_rows["validation_status"].astype(str).unique()
            )
            if not observed_statuses.issubset(
                {"EVALUATED", "CANDIDATE_LOCAL_FAILURE"}
            ):
                errors.append("validation_candidate_status")
            evaluated_validation_rows = validation_rows[
                validation_rows["validation_status"] == "EVALUATED"
            ]
        failure_validation_rows = validation_rows[
            validation_rows.get(
                "validation_status",
                pd.Series(index=validation_rows.index, dtype=str),
            )
            == "CANDIDATE_LOCAL_FAILURE"
        ]
        expected_validation_counts = {
            str(arm): int(count)
            for arm, count in dict(
                validation_decisions.get("matched_evaluated_counts") or {}
            ).items()
        }
        if len(expected_validation_counts) != 3:
            errors.append("validation_arm_count")
        observed_validation_counts_raw = {
            str(arm): int(count)
            for arm, count in evaluated_validation_rows.groupby("arm").size().items()
        }
        observed_validation_counts = {
            arm: observed_validation_counts_raw.get(arm, 0)
            for arm in expected_validation_counts
        }
        if (
            set(observed_validation_counts_raw) - set(expected_validation_counts)
            or observed_validation_counts != expected_validation_counts
        ):
            errors.append("validation_candidate_count")
        horizon_counts = (
            evaluated_validation_rows.groupby(["arm", "horizon_hours"])
            .size()
            .to_dict()
        )
        if len(validation_metrics) != 3:
            errors.append("validation_arm_count")
        else:
            metric_by_arm = {
                str(row["arm"]): row
                for row in validation_metrics.to_dict("records")
            }
            arm_decisions = dict(
                validation_decisions.get("arm_decisions") or {}
            )
            for arm, expected_count in expected_validation_counts.items():
                metric = metric_by_arm.get(arm)
                if metric is None:
                    errors.append(f"validation_metric_missing:{arm}")
                    continue
                constructible = bool(
                    metric.get("validation_constructibility_passed", False)
                )
                local_horizon_counts = {
                    int(horizon): int(count)
                    for (local_arm, horizon), count in horizon_counts.items()
                    if str(local_arm) == arm
                }
                if constructible:
                    if expected_count != 128 or local_horizon_counts != {
                        1: 64,
                        4: 64,
                    }:
                        errors.append(
                            f"validation_horizon_allocation:{arm}"
                        )
                else:
                    decision_row = dict(arm_decisions.get(arm) or {})
                    if (
                        expected_count >= 128
                        or decision_row.get("passed") is not False
                        or decision_row.get("state_after") != "EXITED"
                    ):
                        errors.append(
                            f"validation_constructibility_decision:{arm}"
                        )
        expected_failure_counts = {
            str(arm): int(count)
            for arm, count in dict(
                validation_decisions.get("candidate_local_failure_counts")
                or {}
            ).items()
        }
        observed_failure_counts = {
            str(arm): int(count)
            for arm, count in failure_validation_rows.groupby("arm").size().items()
        }
        expected_nonzero_failure_counts = {
            arm: count
            for arm, count in expected_failure_counts.items()
            if count > 0
        }
        if observed_failure_counts != expected_nonzero_failure_counts:
            errors.append("validation_candidate_failure_count")
        if (
            not failure_validation_rows.empty
            and (
                failure_validation_rows["validation_failure_reason"]
                .fillna("")
                .eq("")
                .any()
                or failure_validation_rows["matched_evaluated"].astype(bool).any()
            )
        ):
            errors.append("validation_candidate_failure_evidence")
        if validation_decisions.get("status") != "VALIDATION_STAGE_COMPLETE":
            errors.append("validation_decision")
    elif is_economic and budget_exhausted:
        validation_status = decision.get("validation_stage", {}).get("status")
        if validation_status not in {
            "NOT_RUN_BUDGET_EXHAUSTED_BEFORE_CHECKPOINT_000",
            "VALIDATION_STAGE_COMPLETE",
        }:
            errors.append("budget_exhausted_validation_status")
        validation_artifacts = (
            "validation_candidate_ledger.parquet",
            "validation_arm_metrics.parquet",
            "validation_decisions.json",
        )
        for name in validation_artifacts:
            exists = (runtime_root / name).exists()
            if (
                validation_status
                == "NOT_RUN_BUDGET_EXHAUSTED_BEFORE_CHECKPOINT_000"
                and exists
            ):
                errors.append(f"budget_exhausted_unexpected_validation:{name}")
            if validation_status == "VALIDATION_STAGE_COMPLETE" and not exists:
                errors.append(f"budget_exhausted_missing_validation:{name}")
    elif is_economic:
        if validation_status != "BLOCKED_BEFORE_COMPLETE_EQUAL_COUNT":
            errors.append("validation_blocked_status")
        for name in (
            "validation_candidate_ledger.parquet",
            "validation_arm_metrics.parquet",
            "validation_decisions.json",
        ):
            if (runtime_root / name).exists():
                errors.append(f"validation_blocked_unexpected_artifact:{name}")

    frozen_without_hash = {
        key: value for key, value in frozen.items() if key != "frozen_contract_sha256"
    }
    if _payload_sha(frozen_without_hash) != frozen.get("frozen_contract_sha256"):
        errors.append("frozen_contract_sha256")
    if is_economic:
        surface = dict(frozen.get("surface") or {})
        if (
            surface.get("context_id")
            != "OI_MARK_RANKS51_200_X_AGGTRADES_TOP200_ALIGNED"
            or surface.get("fields") != 115
            or len(surface.get("field_ids") or []) != 115
            or surface.get("carrier_reused") is not True
            or surface.get("new_materializer") is not False
        ):
            errors.append("economic_search_surface")
    elif frozen.get("surface") != {
        "context_id": "BROAD_PANEL_BASELINE",
        "fields": 39,
        "core3_fields": 0,
        "joint_120_channel_panel": False,
    }:
        errors.append("broad39_surface")
    boundaries = frozen.get("boundaries", {})
    if (
        boundaries.get("sealed_reads") != 0
        or any(
            bool(boundaries.get(key))
            for key in (
                "report_only_feedback",
                "challenge",
                "recent",
                "may_stress",
                "forward",
                "promotion",
                "cross_sprint_adaptive_memory",
            )
        )
    ):
        errors.append("sealed_boundary")
    if frozen.get("behavior_descriptor", {}).get("outcome_fields_in_identity") != []:
        errors.append("behavior_outcome_identity")
    post_audit_holds: list[str] = []
    if frozen.get("behavior_descriptor", {}).get(
        "pit_regime_source_validation"
    ) != "CROSS_SECTION_CONSTANT_AND_EQUAL_TO_FINITE_ASSET_SUPPORT":
        post_audit_holds.append("LEGACY_UNVALIDATED_ACTIVE_UNIVERSE_REGIME")
    if frozen.get("evaluator_contract", {}).get("lcb_contract", {}).get(
        "authority"
    ) != "NEWEY_WEST_BARTLETT":
        post_audit_holds.append("LEGACY_IID_LCB_ON_OVERLAPPING_HORIZON")
    if "primary_month_metrics_json" not in ledger.columns:
        post_audit_holds.append("LEGACY_MATCHED_WATERFALL_NOT_PERSISTED")
    if preflight.get("strict_candidates_consumed_outside_campaign") != 0:
        errors.append("preflight_external_budget")
    if preflight.get("workers_selected") not in {DEFAULT_WORKERS, FALLBACK_WORKERS}:
        errors.append("worker_selection")

    if budget_exhausted or validation_blocked:
        if not 0 < len(ledger) < STRICT_TARGET:
            errors.append("partial_terminal_strict_count")
        if int(decision.get("strict_evaluated_count", -1)) != len(ledger):
            errors.append("partial_terminal_decision_count")
    elif len(ledger) != STRICT_TARGET:
        errors.append("strict_count")
    expected_strict_count = (
        len(ledger)
        if budget_exhausted or validation_blocked
        else STRICT_TARGET
    )
    if ledger["candidate_id"].nunique() != expected_strict_count:
        errors.append("exact_unique")
    for column in (
        "compile_valid",
        "exact_unique",
        "matched_control_valid",
        "strict_cost_evaluated",
        "expression_hash_verified",
    ):
        if column not in ledger or not bool(ledger[column].fillna(False).all()):
            errors.append(f"ledger_gate:{column}")
    receipt_rows = ledger[ledger["receipt_json"].notna()]
    if receipt_rows.empty or not bool(receipt_rows["receipt_verified"].eq(True).all()):
        errors.append("receipt_verification")
    for operation in (
        "EFFECTIVE_GENE_MUTATION_1_TO_3",
        "COMPATIBLE_SKELETON_VARIANT_MUTATION",
        "ONE_POINT_HOMOLOGOUS_GENE_BUNDLE_CROSSOVER",
    ):
        if not bool((ledger["operation"] == operation).any()):
            errors.append(f"operation_not_executed:{operation}")
    if ledger["behavior_family_id"].isna().any():
        errors.append("behavior_identity")
    if len(archive) != expected_strict_count:
        errors.append("archive_row_count")
    champions = archive[archive["is_family_champion"].fillna(False)]
    if champions["behavior_family_id"].nunique() != archive[
        "behavior_family_id"
    ].nunique():
        errors.append("archive_family_champion")
    if family_summary.get("family_count") != int(
        archive["behavior_family_id"].nunique()
    ):
        errors.append("family_summary_count")

    checkpoints = sorted(
        (runtime_root / "checkpoints").glob("checkpoint_[0-9][0-9][0-9]")
    )
    if budget_exhausted:
        completed_checkpoint_count = int(decision.get("checkpoint_count", 0))
        if len(checkpoints) != completed_checkpoint_count:
            errors.append("budget_exhausted_numeric_checkpoint")
        emergency_checkpoint = (
            runtime_root / "checkpoints" / "checkpoint_budget_exhausted"
        )
        if not emergency_checkpoint.is_dir():
            errors.append("budget_exhausted_checkpoint")
        else:
            emergency_manifest = _read_json(
                emergency_checkpoint / "manifest.json"
            )
            if int(
                emergency_manifest.get("completed_ledger_row_count", -1)
            ) != len(ledger):
                errors.append("budget_exhausted_checkpoint_rows")
            if emergency_manifest.get("restore_verified") is not True:
                errors.append("budget_exhausted_checkpoint_restore")
            if emergency_manifest.get("source_sha") != manifest.get(
                "producer_source_sha"
            ):
                errors.append("budget_exhausted_checkpoint_source")
            for record in emergency_manifest.get("files", []):
                path = emergency_checkpoint / str(record["name"])
                if (
                    not path.is_file()
                    or path.stat().st_size != int(record["bytes"])
                    or sha256_file(path) != str(record["sha256"])
                ):
                    errors.append(
                        "budget_exhausted_checkpoint_file:"
                        + str(record["name"])
                    )
    elif validation_blocked:
        if len(checkpoints) != 1:
            errors.append("validation_blocked_numeric_checkpoint")
        validation_stage = dict(decision.get("validation_stage") or {})
        if completed_validation_control_stop:
            completed_checkpoint = (
                runtime_root / "checkpoints" / "checkpoint_validation"
            )
            if not completed_checkpoint.is_dir():
                errors.append("validation_blocked_checkpoint")
            else:
                completed_manifest = _read_json(
                    completed_checkpoint / "manifest.json"
                )
                if completed_manifest.get("restore_verified") is not True:
                    errors.append("validation_blocked_checkpoint_restore")
                if int(
                    completed_manifest.get("completed_ledger_row_count", -1)
                ) != len(ledger):
                    errors.append("validation_blocked_checkpoint_rows")
                if completed_manifest.get("source_sha") != manifest.get(
                    "producer_source_sha"
                ):
                    errors.append("validation_blocked_checkpoint_source")
            arm_decisions = dict(
                decision.get("validation_arm_decisions") or {}
            )
            control_decision = dict(
                arm_decisions.get("canonical_typed_random") or {}
            )
            if (
                decision.get("reason")
                != "VALIDATION_CONTROL_ARM_FAILED_KILL_LINE"
                or decision.get("checkpoint") != "checkpoint_validation"
                or control_decision.get("passed") is not False
                or control_decision.get("state_after") != "EXITED"
                or validation_stage.get("arm_state_after")
                != {
                    "canonical_typed_random": "EXITED",
                    "hierarchical_typed_cem_v2": "EXITED",
                    "typed_evolution_v2": "EXITED",
                }
            ):
                errors.append("validation_blocked_control_arm_terminal")
        else:
            blocked_checkpoint = (
                runtime_root / "checkpoints" / "checkpoint_validation_blocked"
            )
            if blocked_checkpoint.is_dir():
                blocked_manifest = _read_json(
                    blocked_checkpoint / "manifest.json"
                )
                if blocked_manifest.get("restore_verified") is not True:
                    errors.append("validation_blocked_checkpoint_restore")
                if int(
                    blocked_manifest.get("completed_ledger_row_count", -1)
                ) != len(ledger):
                    errors.append("validation_blocked_checkpoint_rows")
            elif (
                validation_stage.get("closure_mode")
                == "POST_MORTEM_FROM_VERIFIED_CHECKPOINT"
                and decision.get("checkpoint") == "checkpoint_000"
            ):
                checkpoint_manifest = _read_json(
                    runtime_root
                    / "checkpoints"
                    / "checkpoint_000"
                    / "manifest.json"
                )
                if checkpoint_manifest.get("restore_verified") is not True:
                    errors.append("validation_blocked_checkpoint_restore")
                if int(
                    checkpoint_manifest.get("completed_ledger_row_count", -1)
                ) != len(ledger):
                    errors.append("validation_blocked_checkpoint_rows")
            else:
                errors.append("validation_blocked_checkpoint")
    elif len(checkpoints) != CHECKPOINT_COUNT:
        errors.append("checkpoint_count")
    for index, checkpoint in enumerate(checkpoints):
        checkpoint_manifest = _read_json(checkpoint / "manifest.json")
        if int(checkpoint_manifest.get("completed_ledger_row_count", -1)) != (
            index + 1
        ) * CHECKPOINT_SIZE:
            errors.append(f"checkpoint_rows:{index}")
        if checkpoint_manifest.get("source_sha") != manifest.get(
            "producer_source_sha"
        ):
            errors.append(f"checkpoint_source:{index}")
        if checkpoint_manifest.get("frozen_contract_sha256") != frozen.get(
            "frozen_contract_sha256"
        ):
            errors.append(f"checkpoint_contract:{index}")
        if checkpoint_manifest.get("restore_verified") is not True:
            errors.append(f"checkpoint_restore:{index}")
        for record in checkpoint_manifest.get("files", []):
            path = checkpoint / str(record["name"])
            if (
                not path.is_file()
                or path.stat().st_size != int(record["bytes"])
                or sha256_file(path) != str(record["sha256"])
            ):
                errors.append(f"checkpoint_file:{index}:{record['name']}")

    if budget_exhausted:
        completed_checkpoint_count = int(decision.get("checkpoint_count", 0))
        if not bool(
            ledger["checkpoint_index"]
            .astype(int)
            .le(completed_checkpoint_count)
            .all()
        ):
            errors.append("budget_exhausted_checkpoint_index")
        metric_indices = (
            set(metrics["checkpoint_index"].astype(int).unique())
            if not metrics.empty
            else set()
        )
        if metric_indices != set(range(completed_checkpoint_count)):
            errors.append("budget_exhausted_checkpoint_metrics")
        if decision.get("research_decision") != (
            "HOLD_INCOMPLETE_IMBALANCED_CAMPAIGN"
        ):
            errors.append("budget_exhausted_research_decision")
        if decision.get("future_new_data_arena_qualified_arms") != []:
            errors.append("budget_exhausted_arm_qualification")
    elif validation_blocked:
        if len(ledger) != CHECKPOINT_SIZE:
            errors.append("validation_blocked_checkpoint_count")
        if set(metrics["checkpoint_index"].astype(int).unique()) != {0}:
            errors.append("validation_blocked_checkpoint_metrics")
        if decision.get("research_decision") != (
            "HOLD_ENGINE_VALIDATION_BLOCKED"
        ):
            errors.append("validation_blocked_research_decision")
        if decision.get("future_new_data_arena_qualified_arms") != []:
            errors.append("validation_blocked_arm_qualification")
    else:
        initial = (
            ledger[ledger["checkpoint_index"] == 0]
            .groupby("arm")
            .size()
            .to_dict()
        )
        if initial != {arm: 400 for arm in FIRST_CHECKPOINT_ARMS}:
            errors.append("checkpoint_000_arm_contract")
        if bool(
            ledger[
                (ledger["checkpoint_index"] > 0)
                & ledger["arm"].isin(
                    ["cem_distribution_v1", "evolutionary_typed_v1"]
                )
            ].shape[0]
        ):
            errors.append("v1_control_did_not_exit")
        if set(metrics["checkpoint_index"].astype(int).unique()) != set(
            range(CHECKPOINT_COUNT)
        ):
            errors.append("checkpoint_metrics")
    if int(decision.get("generation_attempts", RAW_ATTEMPT_LIMIT + 1)) > RAW_ATTEMPT_LIMIT:
        errors.append("raw_attempt_budget")
    if float(decision.get("active_wall_seconds", WALL_TIME_LIMIT_SECONDS + 1)) > WALL_TIME_LIMIT_SECONDS:
        errors.append("wall_time_budget")
    if budget_exhausted:
        if (
            decision.get("reason")
            not in {"RAW_GENERATION_ATTEMPT_LIMIT", "WALL_TIME_LIMIT"}
            or decision.get("sealed_reads") != 0
            or decision.get("rescue_rerun_started") is not False
        ):
            errors.append("budget_exhausted_final_decision")
    elif (
        not validation_blocked
        and decision.get("status") != "PASS"
    ) or decision.get("sealed_reads") != 0:
        errors.append("final_decision")
    if decision.get("next_arena_started") is not False:
        errors.append("next_arena_boundary")
    if (
        not budget_exhausted
        and not validation_blocked
        and decision.get("success_questions", {}).get(
            "continuous_checkpoint_resume"
        )
        != "YES_EXACT_RESTORE_VERIFIED"
    ):
        errors.append("resume_answer")

    if manifest.get("strict_evaluated_count") != expected_strict_count:
        errors.append("manifest_strict_count")
    expected_manifest_status = (
        "ENGINE_BUDGET_EXHAUSTED"
        if budget_exhausted
        else "ENGINE_VALIDATION_BLOCKED"
        if validation_blocked
        else "COMPLETED"
    )
    if manifest.get("status") != expected_manifest_status:
        errors.append("manifest_status")
    if manifest.get("frozen_contract_sha256") != frozen.get(
        "frozen_contract_sha256"
    ):
        errors.append("manifest_contract")
    if manifest.get("sealed_reads") != 0:
        errors.append("manifest_sealed_reads")
    if _payload_sha(manifest.get("artifacts", [])) != manifest.get(
        "artifact_bundle_sha256"
    ):
        errors.append("manifest_bundle")
    for record in manifest.get("artifacts", []):
        path = repo_root / str(record["path"])
        if (
            not path.is_file()
            or path.stat().st_size != int(record["bytes"])
            or sha256_file(path) != str(record["sha256"])
        ):
            errors.append(f"manifest_artifact:{record['path']}")
    try:
        subprocess.check_call(
            [
                "git",
                "cat-file",
                "-e",
                f"{manifest['producer_source_sha']}^{{commit}}",
            ],
            cwd=repo_root,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
    except subprocess.CalledProcessError:
        errors.append("producer_source_commit")
    engineering_result = "PASS" if not errors else "FAIL"
    return {
        "result": engineering_result,
        "errors": errors,
        "engineering_integrity": engineering_result,
        "component_qualification": (
            "HOLD_ENGINE_BUDGET_EXHAUSTED_BEFORE_CHECKPOINT_000"
            if budget_exhausted
            else
            "HOLD_ENGINE_VALIDATION_BLOCKED"
            if validation_blocked
            else
            "HOLD_POST_AUDIT_REMEDIATION_REQUIRED"
            if post_audit_holds
            else "HOLD_SEPARATE_FRESH_STATE_REQUALIFICATION_REQUIRED"
        ),
        "post_audit_holds": post_audit_holds,
        "future_new_data_arena_qualified_arms": [],
        "historical_diagnostic_qualification_only": decision.get(
            "future_new_data_arena_qualified_arms", []
        ),
        "producer_source_sha": manifest.get("producer_source_sha"),
        "strict_evaluated_count": len(ledger),
        "generation_attempts": decision.get("generation_attempts"),
        "checkpoint_count": len(checkpoints),
        "behavior_family_count": int(archive["behavior_family_id"].nunique()),
        "artifact_bundle_sha256": manifest.get("artifact_bundle_sha256"),
        "sealed_reads": decision.get("sealed_reads"),
    }


def check_aggtrades_canary(
    repo_root: Path,
    *,
    runtime_date: str = AGGTRADES_CANARY_DEFAULT_RUNTIME_DATE,
) -> dict[str, Any]:
    runtime_root = (
        repo_root / f"runtime/crypto_aggtrades_system_canary_v1_{runtime_date}"
    )
    report_path = (
        repo_root / f"reports/CRYPTO_AGGTRADES_SYSTEM_CANARY_V1_{runtime_date}.md"
    )
    errors: list[str] = []
    required = (
        "frozen_contract.json",
        "embedded_preflight.json",
        "candidate_ledger.parquet",
        "behavior_archive.parquet",
        "behavior_family_summary.json",
        "arm_checkpoint_metrics.parquet",
        "final_decision.json",
        "run_manifest.json",
    )
    for name in required:
        if not (runtime_root / name).is_file():
            errors.append(f"missing:{name}")
    if not report_path.is_file():
        errors.append("missing:report")
    if errors:
        return {"result": "FAIL", "errors": errors}
    frozen = _read_json(runtime_root / "frozen_contract.json")
    decision = _read_json(runtime_root / "final_decision.json")
    manifest = _read_json(runtime_root / "run_manifest.json")
    preflight = _read_json(runtime_root / "embedded_preflight.json")
    ledger = pd.read_parquet(runtime_root / "candidate_ledger.parquet")
    archive = pd.read_parquet(runtime_root / "behavior_archive.parquet")
    metrics = pd.read_parquet(runtime_root / "arm_checkpoint_metrics.parquet")
    family_summary = _read_json(runtime_root / "behavior_family_summary.json")
    frozen_without_hash = {
        key: value
        for key, value in frozen.items()
        if key != "frozen_contract_sha256"
    }
    if _payload_sha(frozen_without_hash) != frozen.get("frozen_contract_sha256"):
        errors.append("frozen_contract_sha256")
    if frozen.get("authorization") != (
        "ONE_FRESH_STATE_2000_AGGTRADES_SYSTEM_CANARY"
    ):
        errors.append("authorization")
    if frozen.get("surface", {}).get(
        "every_candidate_requires_aggtrades_input"
    ) is not True:
        errors.append("aggtrades_candidate_gate")
    boundaries = frozen.get("boundaries", {})
    if boundaries.get("sealed_reads") != 0 or any(
        bool(boundaries.get(key))
        for key in (
            "challenge",
            "recent",
            "may_stress",
            "forward",
            "promotion",
            "cross_sprint_adaptive_memory",
            "latent_priority",
            "relational_training",
        )
    ):
        errors.append("sealed_boundary")
    if preflight.get("workers_selected") not in {
        DEFAULT_WORKERS,
        FALLBACK_WORKERS,
    }:
        errors.append("worker_selection")
    if preflight.get("strict_candidates_consumed_outside_campaign") != 0:
        errors.append("preflight_external_budget")
    if len(ledger) != AGGTRADES_CANARY_STRICT_TARGET:
        errors.append("strict_count")
    if ledger["candidate_id"].nunique() != AGGTRADES_CANARY_STRICT_TARGET:
        errors.append("exact_unique")
    for column in (
        "compile_valid",
        "exact_unique",
        "matched_control_valid",
        "strict_cost_evaluated",
        "expression_hash_verified",
    ):
        if column not in ledger or not bool(ledger[column].fillna(False).all()):
            errors.append(f"ledger_gate:{column}")
    if not all(
        bool(
            set(json.loads(str(value)))
            & set(AGGTRADES_SYSTEM_CANARY_FIELDS)
        )
        for value in ledger["raw_fields_json"]
    ):
        errors.append("candidate_without_aggtrades")
    arm_counts = ledger.groupby("arm").size().to_dict()
    expected_arm_counts = {
        arm: count * AGGTRADES_CANARY_CHECKPOINT_COUNT
        for arm, count in AGGTRADES_CANARY_CHECKPOINT_ALLOCATION.items()
    }
    if arm_counts != expected_arm_counts:
        errors.append("arm_counts")
    for checkpoint_index in range(AGGTRADES_CANARY_CHECKPOINT_COUNT):
        local = (
            ledger[ledger["checkpoint_index"].astype(int).eq(checkpoint_index)]
            .groupby("arm")
            .size()
            .to_dict()
        )
        if local != AGGTRADES_CANARY_CHECKPOINT_ALLOCATION:
            errors.append(f"checkpoint_arm_counts:{checkpoint_index}")
    receipt_rows = ledger[ledger["receipt_json"].notna()]
    if receipt_rows.empty or not bool(
        receipt_rows["receipt_verified"].eq(True).all()
    ):
        errors.append("receipt_verification")
    for operation in (
        "EFFECTIVE_GENE_MUTATION_1_TO_3",
        "COMPATIBLE_SKELETON_VARIANT_MUTATION",
        "ONE_POINT_HOMOLOGOUS_GENE_BUNDLE_CROSSOVER",
    ):
        if not bool(ledger["operation"].eq(operation).any()):
            errors.append(f"operation_not_executed:{operation}")
    if len(archive) != AGGTRADES_CANARY_STRICT_TARGET:
        errors.append("archive_row_count")
    champions = archive[archive["is_family_champion"].fillna(False)]
    if champions["behavior_family_id"].nunique() != archive[
        "behavior_family_id"
    ].nunique():
        errors.append("archive_family_champion")
    if family_summary.get("family_count") != int(
        archive["behavior_family_id"].nunique()
    ):
        errors.append("family_summary_count")
    checkpoints = sorted(
        (runtime_root / "checkpoints").glob("checkpoint_[0-9][0-9][0-9]")
    )
    if len(checkpoints) != AGGTRADES_CANARY_CHECKPOINT_COUNT:
        errors.append("checkpoint_count")
    for index, checkpoint in enumerate(checkpoints):
        checkpoint_manifest = _read_json(checkpoint / "manifest.json")
        if int(checkpoint_manifest.get("completed_ledger_row_count", -1)) != (
            index + 1
        ) * AGGTRADES_CANARY_CHECKPOINT_SIZE:
            errors.append(f"checkpoint_rows:{index}")
        if checkpoint_manifest.get("restore_verified") is not True:
            errors.append(f"checkpoint_restore:{index}")
        for record in checkpoint_manifest.get("files", []):
            path = checkpoint / str(record["name"])
            if (
                not path.is_file()
                or path.stat().st_size != int(record["bytes"])
                or sha256_file(path) != str(record["sha256"])
            ):
                errors.append(f"checkpoint_file:{index}:{record['name']}")
    if set(metrics["checkpoint_index"].astype(int).unique()) != set(
        range(AGGTRADES_CANARY_CHECKPOINT_COUNT)
    ):
        errors.append("checkpoint_metrics")
    if int(
        decision.get(
            "generation_attempts", AGGTRADES_CANARY_RAW_ATTEMPT_LIMIT + 1
        )
    ) > AGGTRADES_CANARY_RAW_ATTEMPT_LIMIT:
        errors.append("raw_attempt_budget")
    if float(
        decision.get(
            "active_wall_seconds",
            AGGTRADES_CANARY_WALL_TIME_LIMIT_SECONDS + 1,
        )
    ) > AGGTRADES_CANARY_WALL_TIME_LIMIT_SECONDS:
        errors.append("wall_time_budget")
    if decision.get("status") != "PASS_SYSTEM_CANARY_COMPLETED":
        errors.append("final_decision")
    if decision.get("research_decision") != (
        "HOLD_RESEARCH_FIXED_RETROSPECTIVE_COHORT"
    ):
        errors.append("research_boundary")
    if decision.get("future_new_data_arena_qualified_arms") != []:
        errors.append("future_arm_qualification")
    if decision.get("sealed_reads") != 0:
        errors.append("sealed_reads")
    if manifest.get("strict_evaluated_count") != AGGTRADES_CANARY_STRICT_TARGET:
        errors.append("manifest_strict_count")
    if manifest.get("frozen_contract_sha256") != frozen.get(
        "frozen_contract_sha256"
    ):
        errors.append("manifest_contract")
    if _payload_sha(manifest.get("artifacts", [])) != manifest.get(
        "artifact_bundle_sha256"
    ):
        errors.append("manifest_bundle")
    for record in manifest.get("artifacts", []):
        path = repo_root / str(record["path"])
        if (
            not path.is_file()
            or path.stat().st_size != int(record["bytes"])
            or sha256_file(path) != str(record["sha256"])
        ):
            errors.append(f"manifest_artifact:{record['path']}")
    try:
        subprocess.check_call(
            [
                "git",
                "cat-file",
                "-e",
                f"{manifest['producer_source_sha']}^{{commit}}",
            ],
            cwd=repo_root,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
    except subprocess.CalledProcessError:
        errors.append("producer_source_commit")
    result = "PASS" if not errors else "FAIL"
    return {
        "result": result,
        "errors": errors,
        "engineering_integrity": result,
        "research_decision": decision.get("research_decision"),
        "producer_source_sha": manifest.get("producer_source_sha"),
        "strict_evaluated_count": len(ledger),
        "generation_attempts": decision.get("generation_attempts"),
        "checkpoint_count": len(checkpoints),
        "behavior_family_count": int(archive["behavior_family_id"].nunique()),
        "artifact_bundle_sha256": manifest.get("artifact_bundle_sha256"),
        "future_new_data_arena_qualified_arms": [],
        "sealed_reads": decision.get("sealed_reads"),
    }


def check_v11(
    repo_root: Path,
    *,
    runtime_date: str = V11_DEFAULT_RUNTIME_DATE,
) -> dict[str, Any]:
    runtime_root = repo_root / f"runtime/crypto_search_engine_v1_1_{runtime_date}"
    report_path = repo_root / f"reports/CRYPTO_SEARCH_ENGINE_V1_1_{runtime_date}.md"
    errors: list[str] = []
    required = (
        "frozen_contract.json",
        "embedded_preflight.json",
        "candidate_ledger.parquet",
        "behavior_archive.parquet",
        "behavior_family_summary.json",
        "arm_checkpoint_metrics.parquet",
        "final_decision.json",
        "run_manifest.json",
    )
    for name in required:
        if not (runtime_root / name).is_file():
            errors.append(f"missing:{name}")
    if not report_path.is_file():
        errors.append("missing:report")
    if errors:
        return {"result": "FAIL", "errors": errors}
    frozen = _read_json(runtime_root / "frozen_contract.json")
    decision = _read_json(runtime_root / "final_decision.json")
    manifest = _read_json(runtime_root / "run_manifest.json")
    preflight = _read_json(runtime_root / "embedded_preflight.json")
    ledger = pd.read_parquet(runtime_root / "candidate_ledger.parquet")
    archive = pd.read_parquet(runtime_root / "behavior_archive.parquet")
    metrics = pd.read_parquet(runtime_root / "arm_checkpoint_metrics.parquet")
    family_summary = _read_json(runtime_root / "behavior_family_summary.json")
    frozen_without_hash = {
        key: value
        for key, value in frozen.items()
        if key != "frozen_contract_sha256"
    }
    if _payload_sha(frozen_without_hash) != frozen.get("frozen_contract_sha256"):
        errors.append("frozen_contract_sha256")
    if frozen.get("authorization") != (
        "ONE_FRESH_STATE_3000_SPENT_DEVELOPMENT_SEARCH_ENGINE_V1_1"
    ):
        errors.append("authorization")
    if frozen.get("surface", {}).get(
        "every_candidate_requires_aggtrades_input"
    ) is not True:
        errors.append("aggtrades_candidate_gate")
    fresh_state = frozen.get("fresh_state", {})
    if any(bool(value) for value in fresh_state.values()):
        errors.append("fresh_state_import")
    boundaries = frozen.get("boundaries", {})
    if boundaries.get("sealed_reads") != 0 or any(
        bool(boundaries.get(key))
        for key in (
            "challenge",
            "recent",
            "may_stress",
            "forward",
            "promotion",
            "cross_sprint_adaptive_memory",
            "latent_priority",
            "relational_training",
        )
    ):
        errors.append("sealed_boundary")
    if preflight.get("workers_selected") not in {
        DEFAULT_WORKERS,
        FALLBACK_WORKERS,
    }:
        errors.append("worker_selection")
    if preflight.get("strict_candidates_consumed_outside_campaign") != 0:
        errors.append("preflight_external_budget")
    if len(ledger) != V11_STRICT_TARGET:
        errors.append("strict_count")
    if ledger["candidate_id"].nunique() != V11_STRICT_TARGET:
        errors.append("exact_unique")
    for column in (
        "compile_valid",
        "exact_unique",
        "matched_control_valid",
        "strict_cost_evaluated",
        "expression_hash_verified",
    ):
        if column not in ledger or not bool(ledger[column].fillna(False).all()):
            errors.append(f"ledger_gate:{column}")
    if not all(
        bool(
            set(json.loads(str(value)))
            & set(AGGTRADES_SYSTEM_CANARY_FIELDS)
        )
        for value in ledger["raw_fields_json"]
    ):
        errors.append("candidate_without_aggtrades")
    arm_counts = ledger.groupby("arm").size().to_dict()
    expected_arm_counts = {
        arm: count * V11_CHECKPOINT_COUNT
        for arm, count in V11_CHECKPOINT_ALLOCATION.items()
    }
    if arm_counts != expected_arm_counts:
        errors.append("arm_counts")
    expected_lane_count = next(iter(V11_CHECKPOINT_ALLOCATION.values())) // len(
        SEEDS
    )
    for checkpoint_index in range(V11_CHECKPOINT_COUNT):
        local = (
            ledger[ledger["checkpoint_index"].astype(int).eq(checkpoint_index)]
            .groupby("arm")
            .size()
            .to_dict()
        )
        if local != V11_CHECKPOINT_ALLOCATION:
            errors.append(f"checkpoint_arm_counts:{checkpoint_index}")
        lane_counts = (
            ledger[
                ledger["checkpoint_index"].astype(int).eq(checkpoint_index)
            ]
            .groupby(["arm", "seed"])
            .size()
            .to_dict()
        )
        expected_lanes = {
            (arm, seed): expected_lane_count
            for arm in V11_ARMS
            for seed in SEEDS
        }
        if lane_counts != expected_lanes:
            errors.append(f"checkpoint_arm_seed_counts:{checkpoint_index}")
    broad_contracts, _, _ = _broad39_registry_contracts(repo_root)
    replay_registry = TypedExpressionRegistry(
        tuple((*broad_contracts, *_aggtrades_canary_contracts()))
    )
    replay_policy = TypedEvolutionV2(
        0,
        replay_registry,
        V21_PARAMETERS["behavior_niched_evolution_v2_1"],
    )
    candidates_by_id = {
        str(row["candidate_id"]): CandidateSpec.from_dict(
            json.loads(str(row["candidate_spec_json"]))
        )
        for row in ledger.to_dict("records")
    }
    receipt_rows = ledger[ledger["receipt_json"].notna()]
    if receipt_rows.empty or not bool(
        receipt_rows["receipt_verified"].eq(True).all()
    ):
        errors.append("receipt_verification")
    for row in receipt_rows.to_dict("records"):
        try:
            child = candidates_by_id[str(row["candidate_id"])]
            parent_ids = json.loads(str(row["parent_ids_json"]))
            parents = tuple(
                candidates_by_id[str(parent_id)] for parent_id in parent_ids
            )
            receipt = json.loads(str(row["receipt_json"]))
            if not replay_policy.verify_receipt(parents, child, receipt):
                errors.append(f"receipt_replay:{row['candidate_id']}")
        except (KeyError, TypeError, ValueError, json.JSONDecodeError):
            errors.append(f"receipt_replay:{row['candidate_id']}")
    for operation in EVOLUTION_OPERATIONS:
        if not bool(ledger["operation"].eq(operation).any()):
            errors.append(f"operation_not_executed:{operation}")
    if len(archive) != V11_STRICT_TARGET:
        errors.append("archive_row_count")
    champions = archive[archive["is_family_champion"].fillna(False)]
    if champions["behavior_family_id"].nunique() != archive[
        "behavior_family_id"
    ].nunique():
        errors.append("archive_family_champion")
    if family_summary.get("family_count") != int(
        archive["behavior_family_id"].nunique()
    ):
        errors.append("family_summary_count")
    checkpoints = sorted(
        (runtime_root / "checkpoints").glob("checkpoint_[0-9][0-9][0-9]")
    )
    if len(checkpoints) != V11_CHECKPOINT_COUNT:
        errors.append("checkpoint_count")
    checkpoint_policy_frontier_verified = True
    for index, checkpoint in enumerate(checkpoints):
        checkpoint_manifest = _read_json(checkpoint / "manifest.json")
        if int(checkpoint_manifest.get("completed_ledger_row_count", -1)) != (
            index + 1
        ) * V11_CHECKPOINT_SIZE:
            errors.append(f"checkpoint_rows:{index}")
        if checkpoint_manifest.get("restore_verified") is not True:
            errors.append(f"checkpoint_restore:{index}")
        for record in checkpoint_manifest.get("files", []):
            path = checkpoint / str(record["name"])
            if (
                not path.is_file()
                or path.stat().st_size != int(record["bytes"])
                or sha256_file(path) != str(record["sha256"])
            ):
                errors.append(f"checkpoint_file:{index}:{record['name']}")
        try:
            _, restored_policies, _, _, _ = _load_checkpoint(
                checkpoint_path=checkpoint,
                registry=replay_registry,
                expected_source_sha=str(frozen["source_sha"]),
                expected_frozen_hash=str(
                    frozen["frozen_contract_sha256"]
                ),
                expected_identities={
                    **dict(frozen["input_identities"]),
                    "compiler_identity": dict(frozen["compiler_identity"]),
                },
            )
            cem_policies = [
                policy
                for key, policy in restored_policies.items()
                if key.startswith("behavior_niched_cem_v2_1|")
                and isinstance(policy, HierarchicalTypedCEMV2)
            ]
            checkpoint_policy_frontier_verified = bool(
                checkpoint_policy_frontier_verified
                and len(cem_policies) == len(SEEDS)
                and all(
                    policy.parameters.get(
                        "mechanism_stratified_elites"
                    )
                    is True
                    and policy.parameters.get(
                        "skeleton_stratified_elites"
                    )
                    is True
                    and policy.last_elite_mechanism_count > 0
                    and policy.last_elite_skeleton_count > 0
                    for policy in cem_policies
                )
            )
        except (KeyError, TypeError, ValueError):
            errors.append(f"checkpoint_state_replay:{index}")
            checkpoint_policy_frontier_verified = False
    if not checkpoint_policy_frontier_verified:
        errors.append("cem_checkpoint_frontier_state")
    if set(metrics["checkpoint_index"].astype(int).unique()) != set(
        range(V11_CHECKPOINT_COUNT)
    ):
        errors.append("checkpoint_metrics")
    final_evolution = metrics[
        metrics["checkpoint_index"].astype(int).eq(V11_CHECKPOINT_COUNT - 1)
        & metrics["arm"].eq("behavior_niched_evolution_v2_1")
    ]
    final_cem = metrics[
        metrics["checkpoint_index"].astype(int).eq(V11_CHECKPOINT_COUNT - 1)
        & metrics["arm"].eq("behavior_niched_cem_v2_1")
    ]
    if (
        len(final_evolution) != 1
        or int(final_evolution.iloc[0]["operator_update_count"]) <= 0
        or json.loads(
            str(final_evolution.iloc[0]["operator_probabilities_json"])
        )
        == {}
    ):
        errors.append("operator_productivity_update")
    if (
        len(final_cem) != 1
        or int(final_cem.iloc[0]["cem_elite_family_count"]) <= 0
        or int(final_cem.iloc[0]["cem_elite_mechanism_count"]) <= 0
        or int(final_cem.iloc[0]["cem_elite_skeleton_count"]) <= 0
    ):
        errors.append("cem_behavior_niche_update")
    if int(
        decision.get("generation_attempts", V11_RAW_ATTEMPT_LIMIT + 1)
    ) > V11_RAW_ATTEMPT_LIMIT:
        errors.append("raw_attempt_budget")
    if float(
        decision.get(
            "active_wall_seconds", V11_WALL_TIME_LIMIT_SECONDS + 1
        )
    ) > V11_WALL_TIME_LIMIT_SECONDS:
        errors.append("wall_time_budget")
    if decision.get("status") != "PASS_SEARCH_ENGINE_V1_1_COMPLETED":
        errors.append("final_decision")
    if decision.get("research_decision") != (
        "HOLD_RESEARCH_SPENT_FIXED_RETROSPECTIVE_COHORT"
    ):
        errors.append("research_boundary")
    if decision.get("future_new_data_arena_qualified_arms") != []:
        errors.append("future_arm_qualification")
    if decision.get("sealed_reads") != 0:
        errors.append("sealed_reads")
    if manifest.get("strict_evaluated_count") != V11_STRICT_TARGET:
        errors.append("manifest_strict_count")
    if manifest.get("frozen_contract_sha256") != frozen.get(
        "frozen_contract_sha256"
    ):
        errors.append("manifest_contract")
    if _payload_sha(manifest.get("artifacts", [])) != manifest.get(
        "artifact_bundle_sha256"
    ):
        errors.append("manifest_bundle")
    for record in manifest.get("artifacts", []):
        path = repo_root / str(record["path"])
        if (
            not path.is_file()
            or path.stat().st_size != int(record["bytes"])
            or sha256_file(path) != str(record["sha256"])
        ):
            errors.append(f"manifest_artifact:{record['path']}")
    try:
        subprocess.check_call(
            [
                "git",
                "cat-file",
                "-e",
                f"{manifest['producer_source_sha']}^{{commit}}",
            ],
            cwd=repo_root,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
    except subprocess.CalledProcessError:
        errors.append("producer_source_commit")
    result = "PASS" if not errors else "FAIL"
    return {
        "result": result,
        "errors": errors,
        "engineering_integrity": result,
        "research_decision": decision.get("research_decision"),
        "producer_source_sha": manifest.get("producer_source_sha"),
        "strict_evaluated_count": len(ledger),
        "generation_attempts": decision.get("generation_attempts"),
        "checkpoint_count": len(checkpoints),
        "behavior_family_count": int(archive["behavior_family_id"].nunique()),
        "artifact_bundle_sha256": manifest.get("artifact_bundle_sha256"),
        "search_iteration_decision": decision.get(
            "search_iteration_decision", {}
        ),
        "future_new_data_arena_qualified_arms": [],
        "sealed_reads": decision.get("sealed_reads"),
    }


def check_v12(
    repo_root: Path,
    *,
    runtime_date: str = V12_DEFAULT_RUNTIME_DATE,
) -> dict[str, Any]:
    runtime_root = repo_root / f"runtime/crypto_search_engine_v1_2_{runtime_date}"
    report_path = repo_root / f"reports/CRYPTO_SEARCH_ENGINE_V1_2_{runtime_date}.md"
    errors: list[str] = []
    required = (
        "frozen_contract.json",
        "embedded_preflight.json",
        "candidate_ledger.parquet",
        "behavior_archive.parquet",
        "behavior_family_summary.json",
        "arm_checkpoint_metrics.parquet",
        "final_decision.json",
        "run_manifest.json",
    )
    for name in required:
        if not (runtime_root / name).is_file():
            errors.append(f"missing:{name}")
    if not report_path.is_file():
        errors.append("missing:report")
    if errors:
        return {"result": "FAIL", "errors": errors}
    frozen = _read_json(runtime_root / "frozen_contract.json")
    decision = _read_json(runtime_root / "final_decision.json")
    manifest = _read_json(runtime_root / "run_manifest.json")
    preflight = _read_json(runtime_root / "embedded_preflight.json")
    ledger = pd.read_parquet(runtime_root / "candidate_ledger.parquet")
    archive = pd.read_parquet(runtime_root / "behavior_archive.parquet")
    metrics = pd.read_parquet(runtime_root / "arm_checkpoint_metrics.parquet")
    family_summary = _read_json(runtime_root / "behavior_family_summary.json")
    frozen_without_hash = {
        key: value
        for key, value in frozen.items()
        if key != "frozen_contract_sha256"
    }
    if _payload_sha(frozen_without_hash) != frozen.get("frozen_contract_sha256"):
        errors.append("frozen_contract_sha256")
    if frozen.get("authorization") != (
        "ONE_FRESH_STATE_2000_SPENT_DEVELOPMENT_SEARCH_ENGINE_V1_2"
    ):
        errors.append("authorization")
    if frozen.get("surface", {}).get(
        "every_candidate_requires_aggtrades_input"
    ) is not True:
        errors.append("aggtrades_candidate_gate")
    fresh_state = frozen.get("fresh_state", {})
    if any(bool(value) for value in fresh_state.values()):
        errors.append("fresh_state_import")
    capability_delta = frozen.get("search_capability_delta", {})
    if (
        capability_delta.get("existing_lane_scheduler_balanced") is not True
        or int(capability_delta.get("balanced_micro_batch_size", -1))
        != V12_BALANCED_BATCH_SIZE
        or capability_delta.get("rotating_seed_lane_submission_order")
        is not True
        or capability_delta.get(
            "campaign_local_transition_collision_control"
        )
        is not True
        or capability_delta.get("new_scheduler_system") is not False
    ):
        errors.append("v12_capability_contract")
    boundaries = frozen.get("boundaries", {})
    if boundaries.get("sealed_reads") != 0 or any(
        bool(boundaries.get(key))
        for key in (
            "challenge",
            "recent",
            "may_stress",
            "forward",
            "promotion",
            "cross_sprint_adaptive_memory",
            "latent_priority",
            "relational_training",
        )
    ):
        errors.append("sealed_boundary")
    if preflight.get("workers_selected") not in {
        DEFAULT_WORKERS,
        FALLBACK_WORKERS,
    }:
        errors.append("worker_selection")
    if preflight.get("strict_candidates_consumed_outside_campaign") != 0:
        errors.append("preflight_external_budget")
    if len(ledger) != V12_STRICT_TARGET:
        errors.append("strict_count")
    if ledger["candidate_id"].nunique() != V12_STRICT_TARGET:
        errors.append("exact_unique")
    for column in (
        "compile_valid",
        "exact_unique",
        "matched_control_valid",
        "strict_cost_evaluated",
        "expression_hash_verified",
    ):
        if column not in ledger or not bool(ledger[column].fillna(False).all()):
            errors.append(f"ledger_gate:{column}")
    if not all(
        bool(set(json.loads(str(value))) & set(AGGTRADES_SYSTEM_CANARY_FIELDS))
        for value in ledger["raw_fields_json"]
    ):
        errors.append("candidate_without_aggtrades")
    expected_arm_counts = {
        arm: count * V12_CHECKPOINT_COUNT
        for arm, count in V12_CHECKPOINT_ALLOCATION.items()
    }
    if ledger.groupby("arm").size().to_dict() != expected_arm_counts:
        errors.append("arm_counts")
    expected_lane_count = next(
        iter(V12_CHECKPOINT_ALLOCATION.values())
    ) // len(SEEDS)
    for checkpoint_index in range(V12_CHECKPOINT_COUNT):
        local = ledger[
            ledger["checkpoint_index"].astype(int).eq(checkpoint_index)
        ]
        if local.groupby("arm").size().to_dict() != V12_CHECKPOINT_ALLOCATION:
            errors.append(f"checkpoint_arm_counts:{checkpoint_index}")
        expected_lanes = {
            (arm, seed): expected_lane_count
            for arm in V12_ARMS
            for seed in SEEDS
        }
        if local.groupby(["arm", "seed"]).size().to_dict() != expected_lanes:
            errors.append(f"checkpoint_arm_seed_counts:{checkpoint_index}")
    if any(
        column not in ledger
        for column in (
            "balanced_batch_index",
            "balanced_batch_slot",
            "balanced_batch_size",
        )
    ):
        errors.append("balanced_batch_columns")
    else:
        batches = list(ledger.groupby("balanced_batch_index", dropna=False))
        lanes_by_slot: dict[int, set[tuple[str, int]]] = defaultdict(set)
        if len(batches) != V12_STRICT_TARGET // V12_BALANCED_BATCH_SIZE:
            errors.append("balanced_batch_count")
        for batch_id, rows in batches:
            if pd.isna(batch_id):
                errors.append("balanced_batch_null")
                continue
            if (
                len(rows) != V12_BALANCED_BATCH_SIZE
                or not rows["balanced_batch_size"]
                .astype(int)
                .eq(V12_BALANCED_BATCH_SIZE)
                .all()
                or sorted(rows["balanced_batch_slot"].astype(int).tolist())
                != list(range(V12_BALANCED_BATCH_SIZE))
                or rows.groupby("arm").size().to_dict()
                != {
                    "canonical_typed_random": len(SEEDS),
                    "collision_controlled_evolution_v2_2": len(SEEDS),
                }
                or len(rows[["arm", "seed"]].drop_duplicates())
                != V12_BALANCED_BATCH_SIZE
            ):
                errors.append(f"balanced_batch:{int(batch_id)}")
            for row in rows.to_dict("records"):
                lanes_by_slot[int(row["balanced_batch_slot"])].add(
                    (str(row["arm"]), int(row["seed"]))
                )
        expected_rotating_lanes = {
            (arm, seed) for arm in V12_ARMS for seed in SEEDS
        }
        if (
            set(lanes_by_slot) != set(range(V12_BALANCED_BATCH_SIZE))
            or any(
                lanes != expected_rotating_lanes
                for lanes in lanes_by_slot.values()
            )
        ):
            errors.append("rotating_submission_order")
    broad_contracts, _, _ = _broad39_registry_contracts(repo_root)
    replay_registry = TypedExpressionRegistry(
        tuple((*broad_contracts, *_aggtrades_canary_contracts()))
    )
    replay_policy = TypedEvolutionV2(
        0,
        replay_registry,
        V22_PARAMETERS["collision_controlled_evolution_v2_2"],
    )
    candidates_by_id = {
        str(row["candidate_id"]): CandidateSpec.from_dict(
            json.loads(str(row["candidate_spec_json"]))
        )
        for row in ledger.to_dict("records")
    }
    receipt_rows = ledger[ledger["receipt_json"].notna()]
    if receipt_rows.empty or not bool(
        receipt_rows["receipt_verified"].eq(True).all()
    ):
        errors.append("receipt_verification")
    for row in receipt_rows.to_dict("records"):
        try:
            child = candidates_by_id[str(row["candidate_id"])]
            parents = tuple(
                candidates_by_id[str(parent_id)]
                for parent_id in json.loads(str(row["parent_ids_json"]))
            )
            receipt = json.loads(str(row["receipt_json"]))
            if not replay_policy.verify_receipt(parents, child, receipt):
                errors.append(f"receipt_replay:{row['candidate_id']}")
        except (KeyError, TypeError, ValueError, json.JSONDecodeError):
            errors.append(f"receipt_replay:{row['candidate_id']}")
    for operation in EVOLUTION_OPERATIONS:
        if not bool(ledger["operation"].eq(operation).any()):
            errors.append(f"operation_not_executed:{operation}")
    skeleton_rows = ledger[
        ledger["operation"].eq("COMPATIBLE_SKELETON_VARIANT_MUTATION")
    ]
    if skeleton_rows.empty or not bool(
        skeleton_rows["transition_key"].notna().all()
    ):
        errors.append("transition_key")
    ledger_by_id = {
        str(row["candidate_id"]): row for row in ledger.to_dict("records")
    }
    for row in skeleton_rows.to_dict("records"):
        try:
            parent_ids = json.loads(str(row["parent_ids_json"]))
            if len(parent_ids) != 1:
                raise ValueError("skeleton mutation requires one parent")
            parent_row = ledger_by_id[str(parent_ids[0])]
            parent = candidates_by_id[str(parent_ids[0])]
            child = candidates_by_id[str(row["candidate_id"])]
            expected_transition_key = TypedEvolutionV2._skeleton_transition_key(
                parent_behavior_family_id=str(
                    parent_row["behavior_family_id"]
                ),
                source_skeleton_id=parent.skeleton_id,
                target_skeleton_id=child.skeleton_id,
                remapped_genome_sha256=_payload_sha(
                    child.generation_genes
                ),
            )
            if str(row["transition_key"]) != expected_transition_key:
                errors.append(f"transition_key_replay:{row['candidate_id']}")
        except (KeyError, TypeError, ValueError, json.JSONDecodeError):
            errors.append(f"transition_key_replay:{row['candidate_id']}")
    if len(archive) != V12_STRICT_TARGET:
        errors.append("archive_row_count")
    champions = archive[archive["is_family_champion"].fillna(False)]
    if champions["behavior_family_id"].nunique() != archive[
        "behavior_family_id"
    ].nunique():
        errors.append("archive_family_champion")
    if family_summary.get("family_count") != int(
        archive["behavior_family_id"].nunique()
    ):
        errors.append("family_summary_count")
    checkpoints = sorted(
        (runtime_root / "checkpoints").glob("checkpoint_[0-9][0-9][0-9]")
    )
    if len(checkpoints) != V12_CHECKPOINT_COUNT:
        errors.append("checkpoint_count")
    for index, checkpoint in enumerate(checkpoints):
        checkpoint_manifest = _read_json(checkpoint / "manifest.json")
        if int(checkpoint_manifest.get("completed_ledger_row_count", -1)) != (
            index + 1
        ) * V12_CHECKPOINT_SIZE:
            errors.append(f"checkpoint_rows:{index}")
        if checkpoint_manifest.get("restore_verified") is not True:
            errors.append(f"checkpoint_restore:{index}")
        for record in checkpoint_manifest.get("files", []):
            path = checkpoint / str(record["name"])
            if (
                not path.is_file()
                or path.stat().st_size != int(record["bytes"])
                or sha256_file(path) != str(record["sha256"])
            ):
                errors.append(f"checkpoint_file:{index}:{record['name']}")
        try:
            _, restored_policies, _, _, _ = _load_checkpoint(
                checkpoint_path=checkpoint,
                registry=replay_registry,
                expected_source_sha=str(frozen["source_sha"]),
                expected_frozen_hash=str(
                    frozen["frozen_contract_sha256"]
                ),
                expected_identities={
                    **dict(frozen["input_identities"]),
                    "compiler_identity": dict(frozen["compiler_identity"]),
                },
            )
            evolution_policies = [
                policy
                for key, policy in restored_policies.items()
                if key.startswith("collision_controlled_evolution_v2_2|")
                and isinstance(policy, TypedEvolutionV2)
            ]
            if len(evolution_policies) != len(SEEDS) or not all(
                policy.parameters.get(
                    "campaign_local_transition_collision_control"
                )
                is True
                for policy in evolution_policies
            ):
                errors.append(f"checkpoint_transition_state:{index}")
        except (KeyError, TypeError, ValueError):
            errors.append(f"checkpoint_state_replay:{index}")
    if set(metrics["checkpoint_index"].astype(int).unique()) != set(
        range(V12_CHECKPOINT_COUNT)
    ):
        errors.append("checkpoint_metrics")
    final_evolution = metrics[
        metrics["checkpoint_index"].astype(int).eq(V12_CHECKPOINT_COUNT - 1)
        & metrics["arm"].eq("collision_controlled_evolution_v2_2")
    ]
    if (
        len(final_evolution) != 1
        or int(final_evolution.iloc[0]["operator_update_count"]) <= 0
        or json.loads(
            str(final_evolution.iloc[0]["operator_probabilities_json"])
        )
        == {}
        or json.loads(
            str(final_evolution.iloc[0]["transition_productivity_json"])
        )
        == {}
    ):
        errors.append("v12_policy_update")
    if int(
        decision.get("generation_attempts", V12_RAW_ATTEMPT_LIMIT + 1)
    ) > V12_RAW_ATTEMPT_LIMIT:
        errors.append("raw_attempt_budget")
    if float(
        decision.get(
            "active_wall_seconds", V12_WALL_TIME_LIMIT_SECONDS + 1
        )
    ) > V12_WALL_TIME_LIMIT_SECONDS:
        errors.append("wall_time_budget")
    if decision.get("status") != "PASS_SEARCH_ENGINE_V1_2_COMPLETED":
        errors.append("final_decision")
    if decision.get("balanced_batch_integrity") is not True:
        errors.append("final_balanced_batch_integrity")
    if decision.get("rotating_submission_integrity") is not True:
        errors.append("final_rotating_submission_integrity")
    if decision.get("research_decision") != (
        "HOLD_RESEARCH_SPENT_FIXED_RETROSPECTIVE_COHORT"
    ):
        errors.append("research_boundary")
    if decision.get("future_new_data_arena_qualified_arms") != []:
        errors.append("future_arm_qualification")
    if decision.get("sealed_reads") != 0:
        errors.append("sealed_reads")
    if manifest.get("strict_evaluated_count") != V12_STRICT_TARGET:
        errors.append("manifest_strict_count")
    if manifest.get("frozen_contract_sha256") != frozen.get(
        "frozen_contract_sha256"
    ):
        errors.append("manifest_contract")
    if _payload_sha(manifest.get("artifacts", [])) != manifest.get(
        "artifact_bundle_sha256"
    ):
        errors.append("manifest_bundle")
    for record in manifest.get("artifacts", []):
        path = repo_root / str(record["path"])
        if (
            not path.is_file()
            or path.stat().st_size != int(record["bytes"])
            or sha256_file(path) != str(record["sha256"])
        ):
            errors.append(f"manifest_artifact:{record['path']}")
    try:
        subprocess.check_call(
            [
                "git",
                "cat-file",
                "-e",
                f"{manifest['producer_source_sha']}^{{commit}}",
            ],
            cwd=repo_root,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
    except subprocess.CalledProcessError:
        errors.append("producer_source_commit")
    result = "PASS" if not errors else "FAIL"
    return {
        "result": result,
        "errors": errors,
        "engineering_integrity": result,
        "research_decision": decision.get("research_decision"),
        "producer_source_sha": manifest.get("producer_source_sha"),
        "strict_evaluated_count": len(ledger),
        "generation_attempts": decision.get("generation_attempts"),
        "checkpoint_count": len(checkpoints),
        "balanced_batch_count": decision.get("balanced_batch_count"),
        "behavior_family_count": int(archive["behavior_family_id"].nunique()),
        "artifact_bundle_sha256": manifest.get("artifact_bundle_sha256"),
        "search_iteration_decision": decision.get(
            "search_iteration_decision", {}
        ),
        "future_new_data_arena_qualified_arms": [],
        "sealed_reads": decision.get("sealed_reads"),
    }


def _load_v14_config(repo_root: Path) -> tuple[dict[str, Any], Path]:
    path = repo_root / V14_CONFIG
    config = _read_json(path)
    if config.get("authorization") != (
        "ONE_FRESH_STATE_OI_FLOW_CONDITIONAL_MECHANISM_GATE"
    ):
        raise PermissionError("Search Engine V1.4 authorization changed")
    if any(bool(value) for value in config.get("fresh_state", {}).values()):
        raise PermissionError("Search Engine V1.4 imported prior state")
    forbidden = (
        "alpha_claim",
        "oos",
        "challenge",
        "recent",
        "may_stress",
        "forward",
        "promotion",
        "latent_priority",
        "relational_training",
        "cross_sprint_adaptive_memory",
    )
    if any(bool(config["boundaries"].get(key)) for key in forbidden):
        raise PermissionError("Search Engine V1.4 research boundary opened")
    if tuple(config["semantic_tuples"]) != CONDITIONAL_SEMANTIC_TUPLES:
        raise ValueError("Search Engine V1.4 semantic tuples changed")
    if int(config["stage_a"]["constructibility_canary_strict_count"]) != (
        V14_STAGE_A_COUNT
    ):
        raise ValueError("Search Engine V1.4 Stage A budget changed")
    if int(config["stage_b"]["typed_random_strict_count"]) != V14_STAGE_B_COUNT:
        raise ValueError("Search Engine V1.4 Stage B budget changed")
    if int(config["stage_c"]["strict_count"]) != V14_STAGE_C_COUNT:
        raise ValueError("Search Engine V1.4 Stage C budget changed")
    return config, path


def _v14_carrier_contracts(
    repo_root: Path, config: Mapping[str, Any]
) -> tuple[tuple[FieldContract, ...], tuple[FieldContract, ...], Path, Path]:
    manifest_path = repo_root / str(config["source_carrier_manifest"])
    manifest = _read_json(manifest_path)
    oi_id = str(config["source_carriers"]["oi_mark"])
    agg_id = str(config["source_carriers"]["aggtrades"])
    oi_contracts = _contracts_from_payload(
        manifest["carriers"][oi_id]["contracts"]
    )
    agg_contracts = _contracts_from_payload(
        manifest["carriers"][agg_id]["contracts"]
    )
    if len(oi_contracts) != 71 or len(agg_contracts) != 44:
        raise ValueError("V1.4 source carrier field counts changed")
    if set(item.field_id for item in oi_contracts) & set(
        item.field_id for item in agg_contracts
    ):
        raise ValueError("V1.4 source carrier field identities overlap")
    oi_cache = repo_root / str(manifest["carriers"][oi_id]["cache_root"])
    output_cache = repo_root / str(config["aligned_carrier"]["cache_root"])
    return oi_contracts, agg_contracts, oi_cache, output_cache


def build_v14_aligned_carrier(
    repo_root: Path, *, source_sha: str
) -> dict[str, Any]:
    config, config_path = _load_v14_config(repo_root)
    oi_contracts, agg_contracts, oi_cache, output_cache = (
        _v14_carrier_contracts(repo_root, config)
    )
    aligned = config["aligned_carrier"]
    metadata = build_aggtrades_search_surface_cache(
        source_cache_root=oi_cache,
        top100_tar=Path(str(config["inputs"]["aggtrades_top100_tar"])),
        ranks101_200_tar=Path(
            str(config["inputs"]["aggtrades_ranks101_200_tar"])
        ),
        output_cache_root=output_cache,
        broad_field_ids=[item.field_id for item in oi_contracts],
        start=str(aligned["start"]),
        end_exclusive=str(aligned["end_exclusive"]),
        producer_source_sha=source_sha,
        verify_tar_sha256=bool(aligned["verify_full_tar_sha256"]),
    )
    contracts = tuple((*oi_contracts, *agg_contracts))
    if len(contracts) != int(aligned["field_count"]):
        raise ValueError("V1.4 aligned contract field count changed")
    runtime_root = (
        repo_root
        / f"runtime/crypto_search_engine_v1_4_oi_flow_{V14_DEFAULT_RUNTIME_DATE}"
    )
    runtime_root.mkdir(parents=True, exist_ok=True)
    contract_rows = _contracts_payload(contracts)
    carrier_manifest = {
        "schema_version": 1,
        "source_sha": source_sha,
        "config_sha256": sha256_file(config_path),
        "carrier_id": "OI_MARK_RANKS51_200_X_AGGTRADES_TOP200_ALIGNED",
        "cache_root": output_cache.relative_to(repo_root).as_posix(),
        "cache_identity_sha256": metadata["identity_sha256"],
        "directory_bundle": _directory_bundle(output_cache),
        "contracts": contract_rows,
        "contracts_sha256": _payload_sha(contract_rows),
        "field_origins": {
            "OI_MARK_RANKS51_200_DELIVERED": [
                item.field_id for item in oi_contracts
            ],
            "AGGTRADES_TOP200_DELIVERED": [
                item.field_id for item in agg_contracts
            ],
        },
    }
    _write_json(runtime_root / "aligned_carrier_manifest.json", carrier_manifest)
    return carrier_manifest


def _v14_domains(
    contracts: Sequence[FieldContract],
) -> dict[str, dict[str, tuple[Any, ...]]]:
    fields = tuple(item.field_id for item in contracts)

    def values(predicate: Callable[[str], bool]) -> tuple[str, ...]:
        return tuple(sorted(field_id for field_id in fields if predicate(field_id)))

    oi_level = values(
        lambda value: "__open_interest_" in value
        and "__open_interest_value_" not in value
        and not value.endswith("__oi_n")
    )
    oi_notional = values(lambda value: "__open_interest_value_" in value)
    funding = values(lambda value: "__funding_rate_" in value)
    mark = values(lambda value: "__mark_price_" in value)
    index = values(lambda value: "__index_price_" in value)
    flow = values(
        lambda value: value
        in {
            "signed_aggressor_quantity",
            "signed_aggressor_notional",
            "volume_imbalance",
            "buy_sell_notional_ratio",
        }
    )
    price_response = values(
        lambda value: value in {"price_range_bps", "close_to_open_bps"}
    )
    large_trade = values(
        lambda value: value.startswith("large_")
        or value == "max_trade_notional"
    )
    intensity = values(
        lambda value: value
        in {
            "agg_trade_count",
            "underlying_trade_count",
            "buy_agg_trade_count",
            "sell_agg_trade_count",
            "buy_underlying_trade_count",
            "sell_underlying_trade_count",
        }
        or value.startswith("trade_count_")
    )
    basis_pairs = tuple(
        sorted(
            (left, right)
            for left in mark
            for right in index
            if left.split("__", 1)[0] == right.split("__", 1)[0]
            and left.rsplit("_", 1)[-1] == right.rsplit("_", 1)[-1]
        )
    )
    cross_oi_pairs = tuple(
        sorted(
            (left, right)
            for left in oi_level
            for right in oi_level
            if left < right
            and left.split("__", 1)[0] != right.split("__", 1)[0]
            and left.split("__", 1)[1] == right.split("__", 1)[1]
        )
    )
    domains = {
        CONDITIONAL_SEMANTIC_TUPLES[0]: {
            "left": oi_level,
            "right": flow,
            "condition_bundle": basis_pairs,
        },
        CONDITIONAL_SEMANTIC_TUPLES[1]: {
            "left": price_response,
            "right": large_trade,
            "condition": oi_level,
        },
        CONDITIONAL_SEMANTIC_TUPLES[2]: {
            "left_bundle": cross_oi_pairs,
            "right": flow,
            "condition": funding,
        },
        CONDITIONAL_SEMANTIC_TUPLES[3]: {
            "left": oi_notional,
            "right": price_response,
            "condition": intensity,
        },
    }
    if any(
        not all(values for values in domain.values())
        for domain in domains.values()
    ):
        raise ValueError("V1.4 conditional typed domain is empty")
    return domains


def _v14_sample_conditional(
    *,
    registry: TypedExpressionRegistry,
    domains: Mapping[str, Mapping[str, Sequence[Any]]],
    semantic_tuple: str,
    rng: random.Random,
) -> CandidateSpec:
    domain = domains[semantic_tuple]
    auxiliary = ""
    if "left_bundle" in domain:
        left, auxiliary = rng.choice(tuple(domain["left_bundle"]))
    else:
        left = rng.choice(tuple(domain["left"]))
    right = rng.choice(tuple(domain["right"]))
    if "condition_bundle" in domain:
        condition, auxiliary = rng.choice(tuple(domain["condition_bundle"]))
    else:
        condition = rng.choice(tuple(domain["condition"]))
    genes = {
        "semantic_tuple": semantic_tuple,
        "left_field": left,
        "right_field": right,
        "condition_field": condition,
        "auxiliary_field": auxiliary,
        "left_window": rng.choice(WINDOWS),
        "right_window": rng.choice(WINDOWS),
        "condition_window": rng.choice(WINDOWS),
        "left_normalizer": rng.choice(NORMALIZERS),
        "right_normalizer": rng.choice(NORMALIZERS),
        "condition_normalizer": rng.choice(NORMALIZERS),
        "horizon_hours": rng.choice(HORIZONS),
    }
    return conditional_candidate_from_genes(registry, genes=genes)


def _v14_replay_verified(
    registry: TypedExpressionRegistry, candidate: CandidateSpec
) -> bool:
    try:
        if candidate.mechanism_family.startswith("CONDITIONAL_"):
            replay = conditional_candidate_from_genes(
                registry, genes=candidate.generation_genes
            )
        else:
            replay = candidate_from_genes(
                registry,
                skeleton=_skeleton_by_id(candidate.skeleton_id),
                genes=candidate.generation_genes,
                roles=field_role_surface(
                    tuple(registry.fields.values())
                )["roles"],
            )
        return bool(
            replay.candidate_id == candidate.candidate_id
            and replay.expression.expression_id
            == candidate.expression.expression_id
            and replay.control.expression_id == candidate.control.expression_id
        )
    except (KeyError, TypeError, ValueError):
        return False


def qualify_v14_aligned_carrier(
    repo_root: Path, *, source_sha: str
) -> dict[str, Any]:
    config, _ = _load_v14_config(repo_root)
    runtime_root = (
        repo_root
        / f"runtime/crypto_search_engine_v1_4_oi_flow_{V14_DEFAULT_RUNTIME_DATE}"
    )
    manifest_path = runtime_root / "aligned_carrier_manifest.json"
    if not manifest_path.is_file():
        build_v14_aligned_carrier(repo_root, source_sha=source_sha)
    manifest = _read_json(manifest_path)
    if manifest.get("source_sha") != source_sha:
        raise ValueError("V1.4 aligned carrier producer SHA changed")
    cache_root = repo_root / str(manifest["cache_root"])
    store = RawPanelStore.open(cache_root)
    contracts = _contracts_from_payload(manifest["contracts"])
    registry = TypedExpressionRegistry(contracts)
    oi_fields = set(manifest["field_origins"][
        "OI_MARK_RANKS51_200_DELIVERED"
    ])
    agg_fields = set(
        manifest["field_origins"]["AGGTRADES_TOP200_DELIVERED"]
    )
    field_finite = {
        item.field_id: int(np.isfinite(store.field(item.field_id)).sum())
        for item in contracts
    }
    base = np.asarray(store.base_eligible(), dtype=bool)
    observed = np.asarray(store.observed(), dtype=bool)
    target_support = {
        str(horizon): int(
            np.isfinite(store.target_return(horizon))[base].sum()
        )
        for horizon in HORIZONS
    }
    timestamp_ns = np.asarray(store.timestamp_ns, dtype=np.int64)
    hourly_contiguous = bool(
        len(timestamp_ns) > 1
        and np.diff(timestamp_ns).min()
        == np.diff(timestamp_ns).max()
        == 3_600_000_000_000
    )
    active_assets = base.sum(axis=0)
    minimum_assets = int(
        config["aligned_carrier"]["minimum_assets_per_timestamp"]
    )
    nonempty = active_assets >= minimum_assets
    runs: list[tuple[int, int]] = []
    run_start: int | None = None
    for index, value in enumerate(nonempty.tolist()):
        if value and run_start is None:
            run_start = index
        if run_start is not None and (
            not value or index == len(nonempty) - 1
        ):
            run_end = (
                index
                if value and index == len(nonempty) - 1
                else index - 1
            )
            runs.append((run_start, run_end))
            run_start = None
    if not runs:
        raise ValueError("V1.4 aligned carrier has no continuous eligible block")
    qualified_start, qualified_end = max(
        runs,
        key=lambda value: (value[1] - value[0] + 1, -value[0]),
    )
    qualified_end_exclusive_ns = (
        int(timestamp_ns[qualified_end]) + 3_600_000_000_000
    )
    qualified_window = {
        "selection_rule": (
            "LONGEST_CONTIGUOUS_PRE_REWARD_BLOCK_WITH_AT_LEAST_3_ELIGIBLE_ASSETS"
        ),
        "start": pd.Timestamp(
            int(timestamp_ns[qualified_start]), unit="ns", tz="UTC"
        ).isoformat(),
        "end_exclusive": pd.Timestamp(
            qualified_end_exclusive_ns, unit="ns", tz="UTC"
        ).isoformat(),
        "hours": int(qualified_end - qualified_start + 1),
        "excluded_empty_hours": int((~nonempty).sum()),
    }
    domains = _v14_domains(contracts)
    gates = {
        "source_sha_bound": manifest.get("source_sha") == source_sha,
        "field_count_115": len(contracts) == 115,
        "oi_mark_count_71": len(oi_fields) == 71,
        "aggtrades_count_44": len(agg_fields) == 44,
        "all_fields_have_finite_support": all(
            value > 0 for value in field_finite.values()
        ),
        "hourly_timestamp_grid_contiguous": hourly_contiguous,
        "qualified_target_window_contiguous": bool(
            qualified_window["hours"] >= 24 * 180
            and nonempty[qualified_start : qualified_end + 1].all()
        ),
        "real_overlapping_assets": int((base.any(axis=1)).sum()) >= 3,
        "dynamic_eligible_intersection": bool(
            np.all(~base | observed)
            and np.any(active_assets >= int(
                config["aligned_carrier"]["minimum_assets_per_timestamp"]
            ))
        ),
        "no_fill": config["aligned_carrier"]["missing_value_fill"] is None,
        "pit_lag": all(item.observable_lag_hours >= 1 for item in contracts),
        "target_support": all(value > 0 for value in target_support.values()),
        "target_formula_unchanged": (
            store.metadata.get("target_formula")
            == "engineering-only log(priority_venue_mark[t+2+h] / priority_venue_mark[t+2])"
            and config["aligned_carrier"]["target_formula_change"] is False
        ),
        "semantic_domains_nonempty": all(
            all(values for values in domain.values())
            for domain in domains.values()
        ),
    }
    decision = {
        "schema_version": 1,
        "stage": "A_CARRIER_QUALIFICATION",
        "status": "PASS" if all(gates.values()) else "FAIL_CLOSED",
        "source_sha": source_sha,
        "cache_identity_sha256": store.metadata["identity_sha256"],
        "window": {
            "start": store.metadata["start_utc"],
            "end_exclusive": store.metadata["end_exclusive_utc"],
            "timestamps": int(store.shape[1]),
        },
        "assets": {
            "physical": int(store.shape[0]),
            "ever_eligible": int(base.any(axis=1).sum()),
            "minimum_active": int(active_assets[active_assets > 0].min()),
            "maximum_active": int(active_assets.max()),
        },
        "field_finite_counts": field_finite,
        "target_finite_on_base": target_support,
        "qualified_continuous_window": qualified_window,
        "gates": gates,
        "sealed_reads": 0,
    }
    _write_json(runtime_root / "stage_a_carrier_qualification.json", decision)
    return decision


def _load_v14_inputs(
    repo_root: Path,
    *,
    behavior_window: Mapping[str, Any] | None = None,
) -> tuple[
    RawPanelStore,
    tuple[FieldContract, ...],
    dict[str, Any],
    dict[str, Any],
    dict[str, Any],
]:
    config, config_path = _load_v14_config(repo_root)
    runtime_root = (
        repo_root
        / f"runtime/crypto_search_engine_v1_4_oi_flow_{V14_DEFAULT_RUNTIME_DATE}"
    )
    manifest_path = runtime_root / "aligned_carrier_manifest.json"
    manifest = _read_json(manifest_path)
    cache_root = repo_root / str(manifest["cache_root"])
    metadata = _read_json(cache_root / "metadata.json")
    if metadata["identity_sha256"] != manifest["cache_identity_sha256"]:
        raise ValueError("V1.4 aligned carrier identity changed")
    contracts = _contracts_from_payload(manifest["contracts"])
    store = RawPanelStore.open(cache_root)
    if tuple(store.metadata["field_ids"]) != tuple(
        item.field_id for item in contracts
    ):
        raise ValueError("V1.4 aligned field order changed")
    qualification = _read_json(
        runtime_root / "stage_a_carrier_qualification.json"
    )
    qualified_window = qualification["qualified_continuous_window"]
    contract_window = (
        {
            "start": str(behavior_window["start"]),
            "end_exclusive": str(behavior_window["end_exclusive"]),
        }
        if behavior_window is not None
        else {
            "start": str(qualified_window["start"]),
            "end_exclusive": str(qualified_window["end_exclusive"]),
        }
    )
    qualified_start = pd.Timestamp(str(qualified_window["start"]))
    qualified_end = pd.Timestamp(str(qualified_window["end_exclusive"]))
    contract_start = pd.Timestamp(contract_window["start"])
    contract_end = pd.Timestamp(contract_window["end_exclusive"])
    if (
        contract_start < qualified_start
        or contract_end > qualified_end
        or contract_start >= contract_end
    ):
        raise ValueError("V1.4 behavior contract window is outside qualification")
    block = store.block_slice(
        contract_window["start"],
        contract_window["end_exclusive"],
    )
    base = np.asarray(store.base_eligible()[:, block], dtype=bool)
    counts = base.sum(axis=0, dtype=np.int64).astype(float)
    regime = np.broadcast_to(counts, base.shape).copy()
    regime[~base] = np.nan
    behavior_contract = freeze_search_behavior_contract(
        regime,
        base,
        pit_regime_source="__BASE_ELIGIBLE_COUNT__",
    )
    identities = {
        "v14_config": {
            "path": V14_CONFIG,
            "sha256": sha256_file(config_path),
        },
        "aligned_carrier_manifest": {
            "path": manifest_path.relative_to(repo_root).as_posix(),
            "sha256": sha256_file(manifest_path),
        },
        "raw_cache": {
            "root": str(manifest["cache_root"]),
            "identity_sha256": metadata["identity_sha256"],
            "directory_bundle": manifest["directory_bundle"],
        },
        "compiler_identity": _compiler_binding(repo_root),
        "qualified_continuous_window": dict(qualified_window),
    }
    if behavior_window is not None:
        identities["behavior_contract_window"] = {
            **contract_window,
            "authority": "ECONOMIC_RECEIPT_TRAIN_ONLY",
            "validation_read": False,
            "holdout_read": False,
        }
    return (
        store,
        contracts,
        behavior_contract,
        identities,
        {**config, "qualified_continuous_window": dict(qualified_window)},
    )


def _v14_frozen_contract(
    *,
    source_sha: str,
    contracts: Sequence[FieldContract],
    behavior_contract: Mapping[str, Any],
    identities: Mapping[str, Any],
    config: Mapping[str, Any],
) -> dict[str, Any]:
    payload = {
        "schema_version": 1,
        "epoch_id": V14_EPOCH_ID,
        "experiment_id": config["experiment_id"],
        "source_sha": source_sha,
        "authorization": config["authorization"],
        "input_identities": dict(identities),
        "compiler_identity": dict(identities["compiler_identity"]),
        "evaluator_contract": pair_contract_payload(),
        "behavior_descriptor": dict(behavior_contract),
        "surface": {
            "field_count": len(contracts),
            "field_ids": [item.field_id for item in contracts],
            "semantic_tuples": list(CONDITIONAL_SEMANTIC_TUPLES),
            "binary_skeleton_registry_count": len(skeleton_registry()),
            "new_ast": False,
            "new_compiler": False,
            "new_evaluator": False,
            "target_formula_changed": False,
        },
        "stages": {
            "A": dict(config["stage_a"]),
            "B": dict(config["stage_b"]),
            "C": dict(config["stage_c"]),
        },
        "budget": dict(config["budget"]),
        "fresh_state": dict(config["fresh_state"]),
        "memory": "CAMPAIGN_LOCAL_PER_RUN_MEMORY_ONLY",
        "boundaries": {**dict(config["boundaries"]), "sealed_reads": 0},
    }
    return {**payload, "frozen_contract_sha256": _payload_sha(payload)}


def _v14_sample_binary(
    *,
    registry: TypedExpressionRegistry,
    contracts: Sequence[FieldContract],
    origin_sets: Mapping[str, set[str]],
    rng: random.Random,
) -> tuple[CandidateSpec, int]:
    surface = field_role_surface(contracts)
    compatible = [
        item
        for item in skeleton_registry()
        if item.skeleton_id in surface["compatible_skeleton_ids"]
    ]
    if not compatible:
        raise ValueError("V1.4 binary baseline has no compatible skeleton")
    for attempt in range(1, 4_226):
        candidate = generate_effective_candidate(
            registry,
            skeleton=rng.choice(compatible),
            rng=rng,
            roles=surface["roles"],
        )
        if all(set(candidate.raw_fields) & fields for fields in origin_sets.values()):
            return candidate, attempt
    raise _ProposalGenerationFailure(
        "V1.4 binary cross-origin proposal exhausted",
        raw_attempts=4_225,
    )


def _v14_candidate_row(
    *,
    registry: TypedExpressionRegistry,
    candidate: CandidateSpec,
    evaluation: Mapping[str, Any],
    stage: str,
    arm: str,
    completion_ordinal: int,
    stage_completion_ordinal: int,
    generation_attempt_ordinal: int,
    checkpoint_index: int,
    worker: Mapping[str, Any],
    archive: BehaviorArchive,
    seed: int,
    operation: str,
    receipt: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    archive_row, new_family = archive.observe(
        candidate=candidate,
        evaluation=evaluation,
        arm=arm,
        seed=seed,
        completion_ordinal=completion_ordinal,
        checkpoint_index=checkpoint_index,
    )
    feedback = evaluation["feedback"]
    semantic_tuple = candidate.generation_genes.get("semantic_tuple")
    return {
        "completion_ordinal": completion_ordinal,
        "stage_completion_ordinal": stage_completion_ordinal,
        "checkpoint_index": checkpoint_index,
        "stage": stage,
        "arm": arm,
        "seed": seed,
        "generation_attempt_ordinal": generation_attempt_ordinal,
        "candidate_id": candidate.candidate_id,
        "exact_expression_id": candidate.candidate_id,
        "canonical_expression_id": candidate.expression.expression_id,
        "behavior_family_id": evaluation["behavior"]["behavior_family_id"],
        "new_behavior_family_at_completion": bool(new_family),
        "is_family_champion_at_completion": bool(
            archive_row["is_family_champion"]
        ),
        "skeleton_id": candidate.skeleton_id,
        "mechanism_family": candidate.mechanism_family,
        "semantic_tuple": semantic_tuple,
        "hierarchical_three_axis": bool(
            evaluation.get("hierarchical_three_axis")
        ),
        "raw_fields_json": json.dumps(list(candidate.raw_fields)),
        "candidate_spec_json": json.dumps(candidate.to_dict(), sort_keys=True),
        "candidate_spec_sha256": _payload_sha(candidate.to_dict()),
        "operation": operation,
        "receipt_json": (
            json.dumps(receipt, sort_keys=True) if receipt is not None else None
        ),
        "receipt_verified": (
            _payload_sha(
                {key: value for key, value in receipt.items() if key != "receipt_sha256"}
            )
            == receipt.get("receipt_sha256")
            if receipt is not None
            else None
        ),
        "compile_valid": True,
        "exact_unique": True,
        "matched_control_valid": True,
        "strict_cost_evaluated": True,
        "expression_hash_verified": _v14_replay_verified(registry, candidate),
        "pair_reward": float(evaluation["pair_reward"]),
        "matched_positive": bool(evaluation["matched_positive"]),
        "control_degeneracy_provenance_sha256": (
            control_provenance.get("provenance_sha256")
            if isinstance(control_provenance, Mapping)
            else None
        ),
        "control_degeneracy_provenance_json": (
            json.dumps(
                control_provenance,
                sort_keys=True,
                separators=(",", ":"),
                ensure_ascii=True,
            )
            if isinstance(control_provenance, Mapping)
            else None
        ),
        "mechanism_realization_sha256": (
            mechanism_realization.get("provenance_sha256")
            if isinstance(mechanism_realization, Mapping)
            else None
        ),
        "mechanism_realization_json": (
            json.dumps(
                mechanism_realization,
                sort_keys=True,
                separators=(",", ":"),
                ensure_ascii=True,
            )
            if isinstance(mechanism_realization, Mapping)
            else None
        ),
        "declared_axis_count": (
            mechanism_realization.get("declared_axis_count")
            if isinstance(mechanism_realization, Mapping)
            else None
        ),
        "active_axis_count": (
            mechanism_realization.get("active_axis_count")
            if isinstance(mechanism_realization, Mapping)
            else None
        ),
        "mechanism_realization_status": (
            mechanism_realization.get("status")
            if isinstance(mechanism_realization, Mapping)
            else None
        ),
        "condition_effect_rate": (
            mechanism_realization.get("condition_effect_rate")
            if isinstance(mechanism_realization, Mapping)
            else None
        ),
        "interaction_matched_positive": feedback.get(
            "interaction_matched_positive"
        ),
        "conditional_matched_positive": feedback.get(
            "conditional_matched_positive"
        ),
        "interaction_left_distance": (
            feedback.get("interaction_left_axis") or {}
        ).get("distance"),
        "interaction_right_distance": (
            feedback.get("interaction_right_axis") or {}
        ).get("distance"),
        "conditional_distance": (
            feedback.get("conditional_axis") or {}
        ).get("distance"),
        "net_mean": evaluation["incremental"].get("net_mean"),
        "turnover_mean": evaluation["incremental"].get("turnover_mean"),
        "cost_mean": evaluation["incremental"].get("cost_mean"),
        "support": evaluation["incremental"].get("support"),
        "left_delta_weight_sha256": evaluation.get(
            "left_delta_weight_sha256"
        ),
        "right_delta_weight_sha256": evaluation.get(
            "right_delta_weight_sha256"
        ),
        "interaction_left_delta_weight_sha256": evaluation.get(
            "interaction_left_delta_weight_sha256"
        ),
        "process_cpu_seconds": float(worker["process_cpu_seconds"]),
        "wall_seconds": float(worker["wall_seconds"]),
        "worker_rss_bytes": int(worker["worker_rss_bytes"]),
    }


def _v14_write_checkpoint(
    *,
    runtime_root: Path,
    label: str,
    source_sha: str,
    frozen_hash: str,
    cache_identity: str,
    stage: str,
    rng: random.Random,
    generation_attempts: int,
    ledger: Sequence[Mapping[str, Any]],
    archive: BehaviorArchive,
    policy_state: Mapping[str, Any] | None = None,
) -> Path:
    root = runtime_root / "checkpoints"
    root.mkdir(parents=True, exist_ok=True)
    target = root / label
    if target.exists():
        raise FileExistsError(target)
    temporary = root / f".{label}.tmp-{os.getpid()}"
    if temporary.exists():
        shutil.rmtree(temporary)
    temporary.mkdir(parents=True)
    state = {
        "schema_version": 1,
        "source_sha": source_sha,
        "frozen_contract_sha256": frozen_hash,
        "cache_identity_sha256": cache_identity,
        "stage": stage,
        "rng_state": _json_rng_state(rng.getstate()),
        "generation_attempts": int(generation_attempts),
        "completed_candidate_ids": [
            str(row["candidate_id"]) for row in ledger
        ],
        "policy_state": dict(policy_state or {}),
        "archive_state_sha256": archive.state_hash(),
        "archive_duplicate_replacements": archive.duplicate_replacements,
    }
    _write_json(temporary / "state.json", state)
    _write_parquet(temporary / "candidate_ledger.parquet", ledger)
    _write_parquet(temporary / "behavior_archive.parquet", archive.rows)
    files = [
        {
            "name": path.name,
            "bytes": path.stat().st_size,
            "sha256": sha256_file(path),
        }
        for path in sorted(temporary.iterdir())
    ]
    manifest = {
        "schema_version": 1,
        "checkpoint": label,
        "source_sha": source_sha,
        "frozen_contract_sha256": frozen_hash,
        "cache_identity_sha256": cache_identity,
        "stage": stage,
        "completed_ledger_row_count": len(ledger),
        "completed_identity_sha256": _payload_sha(
            [str(row["candidate_id"]) for row in ledger]
        ),
        "state_sha256": _payload_sha(state),
        "archive_state_sha256": archive.state_hash(),
        "files": files,
        "atomic_write": "TEMP_DIRECTORY_THEN_OS_REPLACE",
        "restore_verified": False,
    }
    _write_json(temporary / "manifest.json", manifest)
    restored_state = _read_json(temporary / "state.json")
    restored_ledger = pd.read_parquet(
        temporary / "candidate_ledger.parquet"
    ).to_dict("records")
    restored_archive = BehaviorArchive.from_rows(
        pd.read_parquet(temporary / "behavior_archive.parquet").to_dict(
            "records"
        )
    )
    restored_archive.duplicate_replacements = int(
        restored_state["archive_duplicate_replacements"]
    )
    restored_rng = random.Random()
    restored_rng.setstate(_tuple_rng_state(restored_state["rng_state"]))
    if (
        _payload_sha(restored_state) != manifest["state_sha256"]
        or _payload_sha(
            [str(row["candidate_id"]) for row in restored_ledger]
        )
        != manifest["completed_identity_sha256"]
        or restored_archive.state_hash() != manifest["archive_state_sha256"]
        or _json_rng_state(restored_rng.getstate()) != restored_state["rng_state"]
    ):
        shutil.rmtree(temporary)
        raise ValueError("V1.4 checkpoint restore verification failed")
    manifest["restore_verified"] = True
    _write_json(temporary / "manifest.json", manifest)
    os.replace(temporary, target)
    return target


def _v14_restore_latest_checkpoint(
    *,
    runtime_root: Path,
    source_sha: str,
    frozen_hash: str,
    cache_identity: str,
) -> tuple[
    random.Random,
    int,
    list[dict[str, Any]],
    BehaviorArchive,
] | None:
    checkpoints = sorted(
        path
        for path in (runtime_root / "checkpoints").glob("checkpoint_*")
        if path.is_dir()
    )
    if not checkpoints:
        return None
    path = checkpoints[-1]
    manifest = _read_json(path / "manifest.json")
    if (
        manifest.get("restore_verified") is not True
        or manifest.get("source_sha") != source_sha
        or manifest.get("frozen_contract_sha256") != frozen_hash
        or manifest.get("cache_identity_sha256") != cache_identity
    ):
        raise ValueError("V1.4 checkpoint authority changed")
    for record in manifest["files"]:
        local = path / str(record["name"])
        if (
            not local.is_file()
            or local.stat().st_size != int(record["bytes"])
            or sha256_file(local) != str(record["sha256"])
        ):
            raise ValueError("V1.4 checkpoint file identity changed")
    state = _read_json(path / "state.json")
    if _payload_sha(state) != manifest["state_sha256"]:
        raise ValueError("V1.4 checkpoint state identity changed")
    ledger = pd.read_parquet(path / "candidate_ledger.parquet").to_dict(
        "records"
    )
    archive = BehaviorArchive.from_rows(
        pd.read_parquet(path / "behavior_archive.parquet").to_dict("records")
    )
    archive.duplicate_replacements = int(
        state["archive_duplicate_replacements"]
    )
    if (
        len(ledger) != int(manifest["completed_ledger_row_count"])
        or archive.state_hash() != manifest["archive_state_sha256"]
    ):
        raise ValueError("V1.4 checkpoint restore content changed")
    rng = random.Random()
    rng.setstate(_tuple_rng_state(state["rng_state"]))
    return rng, int(state["generation_attempts"]), ledger, archive


def _v14_stage_metrics(
    ledger: Sequence[Mapping[str, Any]], *, stage: str
) -> dict[str, Any]:
    rows = [row for row in ledger if str(row["stage"]) == stage]
    frame = pd.DataFrame(rows)
    if frame.empty:
        return {
            "stage": stage,
            "strict_evaluated_count": 0,
        }
    hierarchical = frame.loc[
        frame["hierarchical_three_axis"].fillna(False).astype(bool)
    ]
    return {
        "stage": stage,
        "strict_evaluated_count": len(frame),
        "exact_unique_count": int(frame["candidate_id"].nunique()),
        "behavior_family_count": int(frame["behavior_family_id"].nunique()),
        "behavior_duplicate_rate": float(
            1.0 - frame["behavior_family_id"].nunique() / len(frame)
        ),
        "matched_positive_count": int(
            frame["matched_positive"].fillna(False).sum()
        ),
        "hierarchical_count": len(hierarchical),
        "hierarchical_matched_positive_count": int(
            hierarchical["matched_positive"].fillna(False).sum()
        ),
        "interaction_positive_count": int(
            hierarchical["interaction_matched_positive"].fillna(False).sum()
        ),
        "conditional_positive_count": int(
            hierarchical["conditional_matched_positive"].fillna(False).sum()
        ),
        "hierarchical_behavior_duplicate_rate": (
            float(
                1.0
                - hierarchical["behavior_family_id"].nunique()
                / len(hierarchical)
            )
            if len(hierarchical)
            else None
        ),
        "mean_pair_reward": float(frame["pair_reward"].mean()),
        "top_decile_pair_reward": float(
            frame["pair_reward"]
            .nlargest(max(1, int(math.ceil(len(frame) * 0.1))))
            .mean()
        ),
        "semantic_tuple_counts": {
            str(key): int(value)
            for key, value in hierarchical.groupby(
                "semantic_tuple", dropna=False
            ).size().to_dict().items()
        },
        "verified_receipts": int(frame["receipt_verified"].fillna(False).sum()),
    }


def _v14_run_fixed_stage(
    *,
    runtime_root: Path,
    source_sha: str,
    frozen_hash: str,
    cache_root: Path,
    cache_identity: str,
    block_start: str,
    block_end: str,
    contracts: Sequence[FieldContract],
    behavior_contract: Mapping[str, Any],
    stage: str,
    target_sequence: Sequence[str],
    rng: random.Random,
    ledger: list[dict[str, Any]],
    archive: BehaviorArchive,
    completed_ids: set[str],
    generation_attempts: int,
    checkpoint_size: int,
    raw_attempt_limit: int,
    wall_deadline: float,
    economic_receipt: Mapping[str, Any],
) -> tuple[int, int, bool]:
    registry = TypedExpressionRegistry(contracts)
    domains = _v14_domains(contracts)
    contract_fields = set(item.field_id for item in contracts)
    oi_fields = {
        value for value in contract_fields if "__" in value
    }
    agg_fields = contract_fields - oi_fields
    origin_sets = {"oi_mark": oi_fields, "aggtrades": agg_fields}
    stage_existing = sum(str(row["stage"]) == stage for row in ledger)
    if stage_existing > len(target_sequence):
        raise ValueError("V1.4 stage ledger exceeds its frozen target")
    target_counts = Counter(str(value) for value in target_sequence)
    mode_order = tuple(dict.fromkeys(str(value) for value in target_sequence))
    completed_counts: Counter[str] = Counter()
    for row in ledger:
        if str(row["stage"]) != stage:
            continue
        completed_counts[
            str(row["semantic_tuple"])
            if bool(row["hierarchical_three_axis"])
            else "BINARY_BASELINE"
        ] += 1
    workers = DEFAULT_WORKERS
    memory_fallback = False
    executor = concurrent.futures.ProcessPoolExecutor(
        max_workers=workers,
        initializer=_worker_initialize,
        initargs=(
            str(cache_root),
            _contracts_payload(contracts),
            behavior_contract,
            block_start,
            block_end,
            f"FRESH_STATE_V14_{stage}",
            economic_receipt,
        ),
    )
    try:
        while stage_existing < len(target_sequence):
            if generation_attempts >= raw_attempt_limit:
                raise _EngineBudgetExhausted("RAW_GENERATION_ATTEMPT_LIMIT")
            if time.perf_counter() >= wall_deadline:
                raise _EngineBudgetExhausted("ACTIVE_WALL_TIME_LIMIT")
            proposals: list[tuple[CandidateSpec, int, str]] = []
            while (
                len(proposals) < workers
                and stage_existing + len(proposals) < len(target_sequence)
            ):
                pending_counts = Counter(
                    (
                        str(value[0].generation_genes.get("semantic_tuple"))
                        if value[0].mechanism_family.startswith("CONDITIONAL_")
                        else "BINARY_BASELINE"
                    )
                    for value in proposals
                )
                start = (stage_existing + len(proposals)) % len(mode_order)
                rotated = (
                    *mode_order[start:],
                    *mode_order[:start],
                )
                mode = next(
                    (
                        value
                        for value in rotated
                        if completed_counts[value] + pending_counts[value]
                        < target_counts[value]
                    ),
                    None,
                )
                if mode is None:
                    break
                generation_attempts += 1
                if mode == "BINARY_BASELINE":
                    candidate, attempts = _v14_sample_binary(
                        registry=registry,
                        contracts=contracts,
                        origin_sets=origin_sets,
                        rng=rng,
                    )
                    generation_attempts += attempts - 1
                    operation = "CANONICAL_TYPED_RANDOM_BINARY_BASELINE"
                else:
                    candidate = _v14_sample_conditional(
                        registry=registry,
                        domains=domains,
                        semantic_tuple=mode,
                        rng=rng,
                    )
                    operation = "CANONICAL_TYPED_RANDOM_THREE_AXIS"
                if (
                    candidate.candidate_id in completed_ids
                    or any(
                        candidate.candidate_id == value[0].candidate_id
                        for value in proposals
                    )
                ):
                    continue
                if not _v14_replay_verified(registry, candidate):
                    raise ValueError("V1.4 proposal replay/hash verification failed")
                if not all(
                    set(candidate.raw_fields) & values
                    for values in origin_sets.values()
                ):
                    raise ValueError("V1.4 candidate escaped OI/flow origin gate")
                proposals.append((candidate, generation_attempts, operation))
            futures = [
                executor.submit(_worker_evaluate, candidate.to_dict())
                for candidate, _, _ in proposals
            ]
            worker_rows = [future.result() for future in futures]
            peak_rss = max(
                (int(row["worker_rss_bytes"]) for row in worker_rows),
                default=0,
            )
            if (
                not memory_fallback
                and workers == DEFAULT_WORKERS
                and (
                    any(bool(row["memory_error"]) for row in worker_rows)
                    or peak_rss * DEFAULT_WORKERS > MEMORY_GATE_BYTES
                )
            ):
                executor.shutdown(wait=True)
                workers = FALLBACK_WORKERS
                memory_fallback = True
                executor = concurrent.futures.ProcessPoolExecutor(
                    max_workers=workers,
                    initializer=_worker_initialize,
                    initargs=(
                        str(cache_root),
                        _contracts_payload(contracts),
                        behavior_contract,
                        block_start,
                        block_end,
                        f"FRESH_STATE_V14_{stage}",
                        economic_receipt,
                    ),
                )
            for (candidate, attempt_ordinal, operation), worker in zip(
                proposals, worker_rows
            ):
                evaluation = worker["evaluation"]
                if evaluation is None:
                    continue
                completed_ids.add(candidate.candidate_id)
                stage_existing += 1
                completed_counts[
                    str(candidate.generation_genes.get("semantic_tuple"))
                    if candidate.mechanism_family.startswith("CONDITIONAL_")
                    else "BINARY_BASELINE"
                ] += 1
                checkpoint_index = (stage_existing - 1) // checkpoint_size
                row = _v14_candidate_row(
                    registry=registry,
                    candidate=candidate,
                    evaluation=evaluation,
                    stage=stage,
                    arm="canonical_typed_random",
                    completion_ordinal=len(ledger) + 1,
                    stage_completion_ordinal=stage_existing,
                    generation_attempt_ordinal=attempt_ordinal,
                    checkpoint_index=checkpoint_index,
                    worker=worker,
                    archive=archive,
                    seed=20260728,
                    operation=operation,
                )
                ledger.append(row)
                if stage_existing % checkpoint_size == 0:
                    label = (
                        f"checkpoint_{stage.lower()}_"
                        f"{checkpoint_index:03d}"
                    )
                    _v14_write_checkpoint(
                        runtime_root=runtime_root,
                        label=label,
                        source_sha=source_sha,
                        frozen_hash=frozen_hash,
                        cache_identity=cache_identity,
                        stage=stage,
                        rng=rng,
                        generation_attempts=generation_attempts,
                        ledger=ledger,
                        archive=archive,
                    )
                if stage_existing >= len(target_sequence):
                    break
    finally:
        executor.shutdown(wait=True)
    return generation_attempts, workers, memory_fallback


def _v14_artifact_manifest(
    *,
    repo_root: Path,
    runtime_root: Path,
    report_path: Path,
    source_sha: str,
    frozen_hash: str,
) -> dict[str, Any]:
    artifacts = []
    for path in sorted(
        (
            *[
                value
                for value in runtime_root.rglob("*")
                if value.is_file()
                and value.name != "run_manifest.json"
            ],
            report_path,
        ),
        key=lambda value: str(value),
    ):
        artifacts.append(
            {
                "path": path.relative_to(repo_root).as_posix(),
                "bytes": path.stat().st_size,
                "sha256": sha256_file(path),
            }
        )
    return {
        "schema_version": 1,
        "epoch_id": V14_EPOCH_ID,
        "producer_source_sha": source_sha,
        "frozen_contract_sha256": frozen_hash,
        "artifacts": artifacts,
        "artifact_bundle_sha256": _payload_sha(artifacts),
        "continuation": (
            "python -m alphafactory_crypto.broad_search.search_engine_v1 "
            "check-v14 --runtime-date 20260728"
        ),
        "reproducible": True,
        "sealed_reads": 0,
    }


def run_v14(
    repo_root: Path,
    *,
    runtime_date: str = V14_DEFAULT_RUNTIME_DATE,
    source_sha: str | None = None,
    authority_preflight: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    if runtime_date != V14_DEFAULT_RUNTIME_DATE:
        raise ValueError("Search Engine V1.4 runtime date changed")
    _require_bound_authority_preflight(
        repo_root,
        authority_preflight,
        economic_receipt_required=False,
    )
    source_sha = str(source_sha or _git_sha(repo_root)).lower()
    if source_sha != _git_sha(repo_root).lower():
        raise ValueError("Search Engine V1.4 source SHA must equal checkout HEAD")
    config, _ = _load_v14_config(repo_root)
    runtime_root = (
        repo_root / f"runtime/crypto_search_engine_v1_4_oi_flow_{runtime_date}"
    )
    report_path = (
        repo_root
        / f"reports/CRYPTO_SEARCH_ENGINE_V1_4_OI_FLOW_{runtime_date}.md"
    )
    cache_root = repo_root / str(config["aligned_carrier"]["cache_root"])
    if not _source_tree_clean_for_run(
        repo_root,
        allowed_paths=(runtime_root, report_path, cache_root),
    ):
        raise PermissionError("Search Engine V1.4 requires a clean source tree")
    runtime_root.mkdir(parents=True, exist_ok=True)
    if not (runtime_root / "aligned_carrier_manifest.json").is_file():
        build_v14_aligned_carrier(repo_root, source_sha=source_sha)
    qualification = qualify_v14_aligned_carrier(
        repo_root, source_sha=source_sha
    )
    if qualification["status"] != "PASS":
        decision = {
            "schema_version": 1,
            "status": "FAIL_CLOSED_STAGE_A_CARRIER_QUALIFICATION",
            "research_decision": "HOLD_RESEARCH",
            "stage_c": "NOT_RUN",
            "source_sha": source_sha,
            "sealed_reads": 0,
        }
        _write_json(runtime_root / "final_decision.json", decision)
        return {"result": "FAIL", **decision}
    (
        store,
        contracts,
        behavior_contract,
        identities,
        config,
    ) = _load_v14_inputs(repo_root)
    frozen = _v14_frozen_contract(
        source_sha=source_sha,
        contracts=contracts,
        behavior_contract=behavior_contract,
        identities=identities,
        config=config,
    )
    frozen_hash = str(frozen["frozen_contract_sha256"])
    frozen_path = runtime_root / "frozen_contract.json"
    if frozen_path.is_file() and _read_json(frozen_path) != frozen:
        raise ValueError("Search Engine V1.4 frozen contract changed")
    _write_json(frozen_path, frozen)
    embedded_preflight = {
        "schema_version": 1,
        "status": "PASS_READY_STAGE_A_CANARY",
        "source_sha": source_sha,
        "cache_identity_sha256": store.metadata["identity_sha256"],
        "field_count": len(contracts),
        "assets": store.shape[0],
        "timestamps": store.shape[1],
        "workers_requested": DEFAULT_WORKERS,
        "workers_memory_fallback": FALLBACK_WORKERS,
        "workers_12_forbidden": True,
        "sealed_reads": 0,
    }
    _write_json(runtime_root / "embedded_preflight.json", embedded_preflight)
    restored = _v14_restore_latest_checkpoint(
        runtime_root=runtime_root,
        source_sha=source_sha,
        frozen_hash=frozen_hash,
        cache_identity=store.metadata["identity_sha256"],
    )
    if restored is None:
        rng = random.Random(20260728)
        generation_attempts = 0
        ledger: list[dict[str, Any]] = []
        archive = BehaviorArchive()
    else:
        rng, generation_attempts, ledger, archive = restored
    completed_ids = {str(row["candidate_id"]) for row in ledger}
    started = time.perf_counter()
    wall_deadline = started + float(
        config["budget"]["wall_time_seconds_maximum"]
    )
    raw_attempt_limit = int(
        config["budget"]["raw_generation_attempts_maximum"]
    )
    stage_a_sequence = ["BINARY_BASELINE"] * 32 + [
        semantic_tuple
        for semantic_tuple in CONDITIONAL_SEMANTIC_TUPLES
        for _ in range(8)
    ]
    random.Random(2026072801).shuffle(stage_a_sequence)
    stage_b_sequence = ["BINARY_BASELINE"] * 600 + [
        semantic_tuple
        for semantic_tuple in CONDITIONAL_SEMANTIC_TUPLES
        for _ in range(150)
    ]
    random.Random(2026072802).shuffle(stage_b_sequence)
    workers_selected = DEFAULT_WORKERS
    memory_fallback = False
    try:
        if sum(row["stage"] == "STAGE_A" for row in ledger) < V14_STAGE_A_COUNT:
            (
                generation_attempts,
                workers_selected,
                memory_fallback,
            ) = _v14_run_fixed_stage(
                runtime_root=runtime_root,
                source_sha=source_sha,
                frozen_hash=frozen_hash,
                cache_root=repo_root / str(identities["raw_cache"]["root"]),
                cache_identity=store.metadata["identity_sha256"],
                block_start=str(
                    config["qualified_continuous_window"]["start"]
                ),
                block_end=str(
                    config["qualified_continuous_window"]["end_exclusive"]
                ),
                contracts=contracts,
                behavior_contract=behavior_contract,
                stage="STAGE_A",
                target_sequence=stage_a_sequence,
                rng=rng,
                ledger=ledger,
                archive=archive,
                completed_ids=completed_ids,
                generation_attempts=generation_attempts,
                checkpoint_size=V14_STAGE_A_COUNT,
                raw_attempt_limit=raw_attempt_limit,
                wall_deadline=wall_deadline,
                economic_receipt=None,
            )
        stage_a_metrics = _v14_stage_metrics(ledger, stage="STAGE_A")
        stage_a_rows = [
            row for row in ledger if row["stage"] == "STAGE_A"
        ]
        stage_a_canary = {
            "schema_version": 1,
            "status": "PASS"
            if (
                stage_a_metrics["strict_evaluated_count"] == V14_STAGE_A_COUNT
                and stage_a_metrics["exact_unique_count"] == V14_STAGE_A_COUNT
                and sum(
                    not bool(row["hierarchical_three_axis"])
                    for row in stage_a_rows
                )
                == 32
                and all(
                    int(
                        stage_a_metrics["semantic_tuple_counts"].get(
                            value, 0
                        )
                    )
                    == 8
                    for value in CONDITIONAL_SEMANTIC_TUPLES
                )
                and all(
                    bool(row["expression_hash_verified"])
                    and bool(row["strict_cost_evaluated"])
                    for row in stage_a_rows
                )
            )
            else "FAIL_CLOSED",
            "metrics": stage_a_metrics,
            "binary_baseline_count": sum(
                not bool(row["hierarchical_three_axis"])
                for row in stage_a_rows
            ),
            "hierarchical_three_axis_count": sum(
                bool(row["hierarchical_three_axis"])
                for row in stage_a_rows
            ),
            "controls": ["A", "B", "AB", "ABC"],
            "checkpoint_restore": "VERIFIED",
            "pit_lag": qualification["gates"]["pit_lag"],
            "sealed_reads": 0,
        }
        _write_json(
            runtime_root / "stage_a_constructibility_canary.json",
            stage_a_canary,
        )
        if stage_a_canary["status"] != "PASS":
            raise _EngineBudgetExhausted("STAGE_A_CONSTRUCTIBILITY_GATE")
        if sum(row["stage"] == "STAGE_B" for row in ledger) < V14_STAGE_B_COUNT:
            (
                generation_attempts,
                workers_selected,
                local_fallback,
            ) = _v14_run_fixed_stage(
                runtime_root=runtime_root,
                source_sha=source_sha,
                frozen_hash=frozen_hash,
                cache_root=repo_root / str(identities["raw_cache"]["root"]),
                cache_identity=store.metadata["identity_sha256"],
                block_start=str(
                    config["qualified_continuous_window"]["start"]
                ),
                block_end=str(
                    config["qualified_continuous_window"]["end_exclusive"]
                ),
                contracts=contracts,
                behavior_contract=behavior_contract,
                stage="STAGE_B",
                target_sequence=stage_b_sequence,
                rng=rng,
                ledger=ledger,
                archive=archive,
                completed_ids=completed_ids,
                generation_attempts=generation_attempts,
                checkpoint_size=V14_STAGE_B_CHECKPOINT_SIZE,
                raw_attempt_limit=raw_attempt_limit,
                wall_deadline=wall_deadline,
                economic_receipt=None,
            )
            memory_fallback = memory_fallback or local_fallback
    except _EngineBudgetExhausted as failure:
        _write_parquet(runtime_root / "candidate_ledger.parquet", ledger)
        _write_parquet(runtime_root / "behavior_archive.parquet", archive.rows)
        decision = {
            "schema_version": 1,
            "status": "ENGINE_BUDGET_EXHAUSTED",
            "reason": str(failure),
            "source_sha": source_sha,
            "generation_attempts": generation_attempts,
            "strict_evaluated_count": len(ledger),
            "stage_c": "NOT_RUN",
            "parameters_changed": False,
            "seed_changed": False,
            "rescue_rerun_started": False,
            "sealed_reads": 0,
        }
        _write_json(runtime_root / "final_decision.json", decision)
        if is_economic:
            closure = close_budget_exhausted_engine(
                repo_root,
                runtime_date=runtime_date,
                expected_producer_source_sha=source_sha,
                closure_source_sha=source_sha,
            )
            return {**decision, **closure, "result": "ENGINE_BUDGET_EXHAUSTED"}
        return {"result": "ENGINE_BUDGET_EXHAUSTED", **decision}

    stage_b_metrics = _v14_stage_metrics(ledger, stage="STAGE_B")
    tuple_counts = stage_b_metrics["semantic_tuple_counts"]
    gate_contract = config["stage_b"]["adaptive_gate"]
    stage_b_gate = {
        "hierarchical_matched_positive_minimum": (
            stage_b_metrics["hierarchical_matched_positive_count"]
            >= int(gate_contract["hierarchical_matched_positive_minimum"])
        ),
        "hierarchical_strict_completion_rate_minimum": (
            stage_b_metrics["hierarchical_count"] / 600.0
            >= float(
                gate_contract[
                    "hierarchical_strict_completion_rate_minimum"
                ]
            )
        ),
        "hierarchical_behavior_duplicate_rate_maximum": (
            float(stage_b_metrics["hierarchical_behavior_duplicate_rate"])
            <= float(
                gate_contract[
                    "hierarchical_behavior_duplicate_rate_maximum"
                ]
            )
        ),
        "all_semantic_tuple_quotas_complete": all(
            int(tuple_counts.get(value, 0))
            >= int(config["stage_b"]["minimum_tuple_count"])
            for value in CONDITIONAL_SEMANTIC_TUPLES
        ),
    }
    stage_b_decision = {
        "schema_version": 1,
        "status": "PASS_ADAPTIVE_GATE"
        if all(stage_b_gate.values())
        else "HOLD_ADAPTIVE_GATE",
        "metrics": stage_b_metrics,
        "gates": stage_b_gate,
        "parameters_changed": False,
        "seed_changed": False,
        "sealed_reads": 0,
    }
    _write_json(runtime_root / "stage_b_semantic_gate.json", stage_b_decision)
    # Stage C is deliberately called only through the frozen gate.  The
    # adaptive implementation is kept separate below so a semantic-space
    # failure cannot consume policy budget.
    stage_c_status = "NOT_RUN_STAGE_B_GATE"
    if stage_b_decision["status"] == "PASS_ADAPTIVE_GATE":
        stage_c_status = "AUTHORIZED_PENDING_ADAPTIVE_EXECUTION"

    _write_parquet(runtime_root / "candidate_ledger.parquet", ledger)
    _write_parquet(runtime_root / "behavior_archive.parquet", archive.rows)
    _write_json(
        runtime_root / "behavior_family_summary.json",
        {
            "schema_version": 1,
            "family_count": len(archive.champion_by_family),
            "candidate_count": len(archive.rows),
            "duplicate_replacements": archive.duplicate_replacements,
            "families": archive.summary_rows(),
            "archive_state_sha256": archive.state_hash(),
        },
    )
    metrics_rows = [
        _v14_stage_metrics(ledger, stage=value)
        for value in ("STAGE_A", "STAGE_B", "STAGE_C")
    ]
    _write_parquet(runtime_root / "arm_checkpoint_metrics.parquet", metrics_rows)
    decision = {
        "schema_version": 1,
        "status": "PASS_SEARCH_ENGINE_V1_4_SEMANTIC_GATE_COMPLETED",
        "source_sha": source_sha,
        "engineering_integrity": "PASS",
        "research_decision": "HOLD_RESEARCH",
        "stage_a": "PASS",
        "stage_b": stage_b_decision["status"],
        "stage_c": stage_c_status,
        "generation_attempts": generation_attempts,
        "strict_evaluated_count": len(ledger),
        "workers_selected": workers_selected,
        "memory_fallback_used": memory_fallback,
        "future_new_data_arena_qualified_arms": [],
        "alpha_claim": False,
        "oos": False,
        "promotion": False,
        "sealed_reads": 0,
    }
    _write_json(runtime_root / "final_decision.json", decision)
    report_path.write_text(
        "\n".join(
            [
                "# Crypto Search Engine V1.4 OI/Flow",
                "",
                f"- Source: `{source_sha}`",
                f"- Aligned carrier: `71 OI/mark + 44 aggTrades`; window `{qualification['window']['start']}` to `{qualification['window']['end_exclusive']}`.",
                f"- Eligible assets: `{qualification['assets']['ever_eligible']}`; strict candidates: `{len(ledger)}`.",
                f"- Stage A: `{decision['stage_a']}`; Stage B: `{decision['stage_b']}`; Stage C: `{decision['stage_c']}`.",
                f"- Hierarchical matched positives: `{stage_b_metrics['hierarchical_matched_positive_count']}`.",
                f"- Stage-B behavior duplicate rate: `{stage_b_metrics['behavior_duplicate_rate']:.6f}`.",
                "- A/B/AB/ABC share target, support, eligibility, horizon, mapping, and 5 bps cost.",
                "- Development-only result; no OOS, promotion, challenge, recent, forward, or sealed reads.",
                "",
            ]
        ),
        encoding="utf-8",
        newline="\n",
    )
    manifest = _v14_artifact_manifest(
        repo_root=repo_root,
        runtime_root=runtime_root,
        report_path=report_path,
        source_sha=source_sha,
        frozen_hash=frozen_hash,
    )
    _write_json(runtime_root / "run_manifest.json", manifest)
    return {
        "result": "PASS",
        **decision,
        "artifact_bundle_sha256": manifest["artifact_bundle_sha256"],
    }


def check_v13(
    repo_root: Path,
    *,
    runtime_date: str = V13_DEFAULT_RUNTIME_DATE,
) -> dict[str, Any]:
    runtime_root = (
        repo_root
        / f"runtime/crypto_search_engine_v1_3_cross_carrier_{runtime_date}"
    )
    report_path = (
        repo_root
        / f"reports/CRYPTO_SEARCH_ENGINE_V1_3_CROSS_CARRIER_{runtime_date}.md"
    )
    errors: list[str] = []
    required = [
        "frozen_contract.json",
        "embedded_preflight.json",
        "constructibility_canary.json",
        "candidate_ledger.parquet",
        "behavior_archive.parquet",
        "behavior_family_summary.json",
        "arm_checkpoint_metrics.parquet",
        "final_decision.json",
        "run_manifest.json",
    ]
    if is_economic:
        required.extend(
            [
                "validation_candidate_ledger.parquet",
                "validation_arm_metrics.parquet",
                "validation_decisions.json",
            ]
        )
    for name in required:
        if not (runtime_root / name).is_file():
            errors.append(f"missing:{name}")
    if not report_path.is_file():
        errors.append("missing:report")
    if errors:
        return {"result": "FAIL", "errors": errors}
    frozen = _read_json(runtime_root / "frozen_contract.json")
    decision = _read_json(runtime_root / "final_decision.json")
    manifest = _read_json(runtime_root / "run_manifest.json")
    canary = _read_json(runtime_root / "constructibility_canary.json")
    ledger = pd.read_parquet(runtime_root / "candidate_ledger.parquet")
    archive = pd.read_parquet(runtime_root / "behavior_archive.parquet")
    if _payload_sha(
        {
            key: value
            for key, value in frozen.items()
            if key != "frozen_contract_sha256"
        }
    ) != frozen.get("frozen_contract_sha256"):
        errors.append("frozen_contract_sha256")
    if frozen.get("authorization") != (
        "ONE_FRESH_STATE_4000_FIXED_RETROSPECTIVE_CROSS_CARRIER_ARENA"
    ):
        errors.append("authorization")
    if any(bool(value) for value in frozen.get("fresh_state", {}).values()):
        errors.append("fresh_state_import")
    if len(ledger) != V13_STRICT_TARGET or ledger["candidate_id"].nunique() != len(
        ledger
    ):
        errors.append("strict_exact_unique_count")
    for column in (
        "compile_valid",
        "exact_unique",
        "matched_control_valid",
        "strict_cost_evaluated",
        "expression_hash_verified",
        "cross_carrier_verified",
    ):
        if column not in ledger or not bool(ledger[column].fillna(False).all()):
            errors.append(f"ledger_gate:{column}")
    right_axis_columns = (
        "right_control_net_mean",
        "right_incremental_net_mean",
        "right_delta_weight_sha256",
        "right_axis_feedback_json",
        "right_control_behavior_id",
        "right_incremental_behavior_id",
    )
    if any(column not in ledger for column in right_axis_columns):
        errors.append("right_axis_trace_columns")
    elif (
        ledger[list(right_axis_columns)].isna().any().any()
        or ledger["right_delta_weight_sha256"].astype(str).str.len().ne(64).any()
    ):
        errors.append("right_axis_trace_values")
    origin_sets = {
        key: set(values)
        for key, values in frozen["surface"]["field_origins"].items()
    }
    if not all(
        all(set(json.loads(value)) & fields for fields in origin_sets.values())
        for value in ledger["raw_fields_json"].astype(str)
    ):
        errors.append("cross_carrier_origin_gate")
    expected_arm_counts = {
        arm: count * V13_CHECKPOINT_COUNT
        for arm, count in V13_CHECKPOINT_ALLOCATION.items()
    }
    if ledger.groupby("arm").size().to_dict() != expected_arm_counts:
        errors.append("arm_counts")
    checkpoints = sorted(
        (runtime_root / "checkpoints").glob("checkpoint_[0-9][0-9][0-9]")
    )
    if (
        len(checkpoints) != V13_CHECKPOINT_COUNT
        or not all(
            _read_json(path / "manifest.json").get("restore_verified") is True
            for path in checkpoints
        )
    ):
        errors.append("checkpoint_restore")
    if (
        canary.get("status") != "PASS"
        or canary.get("strict_evaluated_count") != V13_CANARY_STRICT_COUNT
        or canary.get("checkpoint_restore") != "VERIFIED_AT_CHECKPOINT_000"
    ):
        errors.append("constructibility_canary")
    boundaries = frozen.get("boundaries", {})
    if boundaries.get("sealed_reads") != 0 or any(
        bool(boundaries.get(key))
        for key in (
            "alpha_claim",
            "oos",
            "challenge",
            "recent",
            "may_stress",
            "forward",
            "promotion",
            "latent_priority",
            "relational_training",
            "cross_sprint_adaptive_memory",
        )
    ):
        errors.append("research_boundary")
    if decision.get("status") != "PASS_SEARCH_ENGINE_V1_3_CROSS_CARRIER_COMPLETED":
        errors.append("final_decision")
    if decision.get("future_new_data_arena_qualified_arms") != []:
        errors.append("future_arena_qualification")
    if _payload_sha(manifest.get("artifacts", [])) != manifest.get(
        "artifact_bundle_sha256"
    ):
        errors.append("manifest_bundle")
    for record in manifest.get("artifacts", []):
        path = repo_root / str(record["path"])
        if (
            not path.is_file()
            or path.stat().st_size != int(record["bytes"])
            or sha256_file(path) != str(record["sha256"])
        ):
            errors.append(f"manifest_artifact:{record['path']}")
    result = "PASS" if not errors else "FAIL"
    return {
        "result": result,
        "errors": errors,
        "engineering_integrity": result,
        "research_decision": decision.get("research_decision"),
        "producer_source_sha": manifest.get("producer_source_sha"),
        "strict_evaluated_count": len(ledger),
        "generation_attempts": decision.get("generation_attempts"),
        "checkpoint_count": len(checkpoints),
        "behavior_family_count": int(archive["behavior_family_id"].nunique()),
        "positive_matched_discoveries": int(
            ledger["matched_positive"].fillna(False).sum()
        ),
        "artifact_bundle_sha256": manifest.get("artifact_bundle_sha256"),
        "future_new_data_arena_qualified_arms": [],
        "sealed_reads": decision.get("sealed_reads"),
    }


def check_v14(
    repo_root: Path,
    *,
    runtime_date: str = V14_DEFAULT_RUNTIME_DATE,
) -> dict[str, Any]:
    runtime_root = (
        repo_root / f"runtime/crypto_search_engine_v1_4_oi_flow_{runtime_date}"
    )
    report_path = (
        repo_root
        / f"reports/CRYPTO_SEARCH_ENGINE_V1_4_OI_FLOW_{runtime_date}.md"
    )
    errors: list[str] = []
    required = (
        "aligned_carrier_manifest.json",
        "stage_a_carrier_qualification.json",
        "frozen_contract.json",
        "embedded_preflight.json",
        "stage_a_constructibility_canary.json",
        "stage_b_semantic_gate.json",
        "candidate_ledger.parquet",
        "behavior_archive.parquet",
        "behavior_family_summary.json",
        "arm_checkpoint_metrics.parquet",
        "final_decision.json",
        "run_manifest.json",
    )
    if campaign == BLOCK_ROBUST_GATE_CAMPAIGN:
        required = (
            *required,
            "block_robust_gate_summary.json",
            "block_robust_template_metrics.parquet",
        )
    for name in required:
        if not (runtime_root / name).is_file():
            errors.append(f"missing:{name}")
    if not report_path.is_file():
        errors.append("missing:report")
    if errors:
        return {"result": "FAIL", "errors": errors}
    frozen = _read_json(runtime_root / "frozen_contract.json")
    qualification = _read_json(
        runtime_root / "stage_a_carrier_qualification.json"
    )
    canary = _read_json(
        runtime_root / "stage_a_constructibility_canary.json"
    )
    stage_b = _read_json(runtime_root / "stage_b_semantic_gate.json")
    decision = _read_json(runtime_root / "final_decision.json")
    manifest = _read_json(runtime_root / "run_manifest.json")
    ledger = pd.read_parquet(runtime_root / "candidate_ledger.parquet")
    archive = pd.read_parquet(runtime_root / "behavior_archive.parquet")
    if _payload_sha(
        {
            key: value
            for key, value in frozen.items()
            if key != "frozen_contract_sha256"
        }
    ) != frozen.get("frozen_contract_sha256"):
        errors.append("frozen_contract_sha256")
    if qualification.get("status") != "PASS":
        errors.append("carrier_qualification")
    if canary.get("status") != "PASS":
        errors.append("constructibility_canary")
    stage_a_count = int(ledger["stage"].eq("STAGE_A").sum())
    stage_b_count = int(ledger["stage"].eq("STAGE_B").sum())
    if stage_a_count != V14_STAGE_A_COUNT or stage_b_count != V14_STAGE_B_COUNT:
        errors.append("stage_strict_counts")
    if ledger["candidate_id"].nunique() != len(ledger):
        errors.append("exact_unique")
    for column in (
        "compile_valid",
        "exact_unique",
        "matched_control_valid",
        "strict_cost_evaluated",
        "expression_hash_verified",
    ):
        if column not in ledger or not bool(ledger[column].fillna(False).all()):
            errors.append(f"ledger_gate:{column}")
    hierarchical = ledger.loc[
        ledger["hierarchical_three_axis"].fillna(False).astype(bool)
    ]
    if hierarchical.empty or not hierarchical["semantic_tuple"].isin(
        CONDITIONAL_SEMANTIC_TUPLES
    ).all():
        errors.append("hierarchical_semantic_tuple")
    if (
        hierarchical["interaction_left_delta_weight_sha256"]
        .astype(str)
        .str.len()
        .ne(64)
        .any()
    ):
        errors.append("hierarchical_delta_hash")
    checkpoints = sorted(
        path
        for path in (runtime_root / "checkpoints").glob("checkpoint_*")
        if path.is_dir()
    )
    if len(checkpoints) != 5 or not all(
        _read_json(path / "manifest.json").get("restore_verified") is True
        for path in checkpoints
    ):
        errors.append("checkpoint_restore")
    if (
        stage_b.get("status") == "PASS_ADAPTIVE_GATE"
        and decision.get("stage_c")
        == "AUTHORIZED_PENDING_ADAPTIVE_EXECUTION"
    ):
        errors.append("stage_c_not_automatically_executed")
    if decision.get("future_new_data_arena_qualified_arms") != []:
        errors.append("future_arena_qualification")
    if decision.get("sealed_reads") != 0:
        errors.append("sealed_reads")
    if len(archive) != len(ledger):
        errors.append("archive_ledger_count")
    if _payload_sha(manifest.get("artifacts", [])) != manifest.get(
        "artifact_bundle_sha256"
    ):
        errors.append("artifact_bundle")
    for record in manifest.get("artifacts", []):
        path = repo_root / str(record["path"])
        if (
            not path.is_file()
            or path.stat().st_size != int(record["bytes"])
            or sha256_file(path) != str(record["sha256"])
        ):
            errors.append(f"manifest_artifact:{record['path']}")
    result = "PASS" if not errors else "FAIL"
    return {
        "result": result,
        "errors": errors,
        "engineering_integrity": result,
        "producer_source_sha": manifest.get("producer_source_sha"),
        "strict_evaluated_count": len(ledger),
        "stage_a_count": stage_a_count,
        "stage_b_count": stage_b_count,
        "stage_c": decision.get("stage_c"),
        "behavior_family_count": int(
            archive["behavior_family_id"].nunique()
        ),
        "hierarchical_matched_positive_count": int(
            hierarchical["matched_positive"].fillna(False).sum()
        ),
        "artifact_bundle_sha256": manifest.get("artifact_bundle_sha256"),
        "future_new_data_arena_qualified_arms": [],
        "sealed_reads": decision.get("sealed_reads"),
    }


def check_mechanism_v2(
    repo_root: Path,
    *,
    runtime_date: str = "20260801",
) -> dict[str, Any]:
    config = _economic_campaign_config(MECHANISM_SEARCH_V2_CAMPAIGN)
    runtime_root = repo_root / (
        f"runtime/{config['runtime_prefix']}_{runtime_date}"
    )
    report_path = repo_root / f"reports/{config['report_prefix']}_{runtime_date}.md"
    errors: list[str] = []
    required = [
        "frozen_contract.json",
        "embedded_preflight.json",
        "candidate_ledger.parquet",
        "behavior_archive.parquet",
        "behavior_family_summary.json",
        "arm_checkpoint_metrics.parquet",
        "final_decision.json",
        "run_manifest.json",
    ]
    for name in required:
        if not (runtime_root / name).is_file():
            errors.append(f"missing:{name}")
    if not report_path.is_file():
        errors.append("missing:report")
    if errors:
        return {"result": "FAIL", "errors": errors}

    decision = _read_json(runtime_root / "final_decision.json")
    validation_blocked = (
        decision.get("status") == "ENGINE_VALIDATION_BLOCKED"
    )
    required_outcome_artifacts = (
        ("validation_failure.json",)
        if validation_blocked
        else (
            "validation_candidate_ledger.parquet",
            "validation_arm_metrics.parquet",
            "validation_decisions.json",
            "mechanism_knowledge.parquet",
            "mechanism_knowledge_summary.json",
        )
    )
    for name in required_outcome_artifacts:
        if not (runtime_root / name).is_file():
            errors.append(f"missing:{name}")
    if errors:
        return {"result": "FAIL", "errors": errors}

    frozen = _read_json(runtime_root / "frozen_contract.json")
    preflight = _read_json(runtime_root / "embedded_preflight.json")
    manifest = _read_json(runtime_root / "run_manifest.json")
    validation = (
        None
        if validation_blocked
        else _read_json(runtime_root / "validation_decisions.json")
    )
    knowledge_summary = (
        None
        if validation_blocked
        else _read_json(runtime_root / "mechanism_knowledge_summary.json")
    )
    ledger = pd.read_parquet(runtime_root / "candidate_ledger.parquet")
    archive = pd.read_parquet(runtime_root / "behavior_archive.parquet")
    metrics = pd.read_parquet(runtime_root / "arm_checkpoint_metrics.parquet")
    validation_rows = (
        None
        if validation_blocked
        else pd.read_parquet(runtime_root / "validation_candidate_ledger.parquet")
    )
    validation_metrics = (
        None
        if validation_blocked
        else pd.read_parquet(runtime_root / "validation_arm_metrics.parquet")
    )
    knowledge = (
        None
        if validation_blocked
        else pd.read_parquet(runtime_root / "mechanism_knowledge.parquet")
    )
    _, catalog = _load_mechanism_v2_contract(repo_root)

    frozen_body = {
        key: value for key, value in frozen.items() if key != "frozen_contract_sha256"
    }
    if _payload_sha(frozen_body) != frozen.get("frozen_contract_sha256"):
        errors.append("frozen_contract_sha256")
    grammar = dict(frozen.get("mechanism_grammar") or {})
    if (
        frozen.get("source_sha") != manifest.get("producer_source_sha")
        or frozen.get("authorization")
        != "ONE_FRESH_STATE_12000_STRICT_MECHANISM_CAMPAIGN"
        or grammar.get("compiled_mechanism_count") != len(catalog)
        or grammar.get("compiled_catalog_sha256")
        != _mechanism_catalog_sha(catalog)
        or grammar.get("second_ast_or_compiler_created") is not False
    ):
        errors.append("frozen_mechanism_contract")
    if tuple(int(value) for value in frozen.get("seeds") or ()) != (
        MECHANISM_SEARCH_V2_SEEDS
    ):
        errors.append("frozen_seed_set")
    if dict(frozen.get("fresh_state") or {}) != dict(
        _read_json(repo_root / MECHANISM_SEARCH_V2_CONFIG)["fresh_state"]
    ):
        errors.append("fresh_state_contract")
    if preflight.get("strict_candidates_consumed_outside_campaign") != 0:
        errors.append("preflight_external_budget")

    if len(ledger) != MECHANISM_SEARCH_V2_STRICT_TARGET:
        errors.append("strict_count")
    if ledger["candidate_id"].nunique() != MECHANISM_SEARCH_V2_STRICT_TARGET:
        errors.append("exact_unique")
    if set(ledger["arm"].astype(str).unique()) != set(MECHANISM_SEARCH_V2_ARMS):
        errors.append("arm_set")
    if not set(int(value) for value in ledger["seed"].unique()).issubset(
        set(MECHANISM_SEARCH_V2_SEEDS)
    ):
        errors.append("ledger_seed_set")
    for column in (
        "compile_valid",
        "exact_unique",
        "matched_control_valid",
        "strict_cost_evaluated",
        "expression_hash_verified",
    ):
        if column not in ledger or not bool(ledger[column].fillna(False).all()):
            errors.append(f"ledger_gate:{column}")
    expected_allocations = {
        0: {"canonical_typed_random": 2_000},
        1: {"extensible_mechanism_random_v2": 2_000},
        2: {"extensible_mechanism_random_v2": 2_000},
        3: {"mechanism_level_cem_v2": 1_000, "mechanism_evolution_v2": 1_000},
        4: {"mechanism_level_cem_v2": 1_000, "mechanism_evolution_v2": 1_000},
        5: {"mechanism_level_cem_v2": 1_000, "mechanism_evolution_v2": 1_000},
    }
    for checkpoint_index, expected in expected_allocations.items():
        observed = {
            str(arm): int(count)
            for arm, count in ledger.loc[
                ledger["checkpoint_index"].astype(int) == checkpoint_index
            ].groupby("arm").size().items()
        }
        if observed != expected:
            errors.append(f"checkpoint_allocation:{checkpoint_index}")
    if set(metrics["checkpoint_index"].astype(int).unique()) != set(range(6)):
        errors.append("checkpoint_metrics")
    for operation in MECHANISM_EVOLUTION_OPERATIONS:
        operation_rows = ledger.loc[ledger["operation"].astype(str) == operation]
        if operation_rows.empty or not bool(
            operation_rows["receipt_verified"]
            .astype("boolean")
            .fillna(False)
            .all()
        ):
            errors.append(f"operation_not_verified:{operation}")

    if len(archive) != len(ledger):
        errors.append("archive_row_count")
    champions = archive.loc[archive["is_family_champion"].fillna(False)]
    if champions["behavior_family_id"].nunique() != archive[
        "behavior_family_id"
    ].nunique():
        errors.append("archive_family_champion")

    checkpoints = sorted(
        (runtime_root / "checkpoints").glob("checkpoint_[0-9][0-9][0-9]")
    )
    if len(checkpoints) != MECHANISM_SEARCH_V2_CHECKPOINT_COUNT:
        errors.append("checkpoint_count")
    try:
        _, contracts, _, _, _ = _load_v14_inputs(repo_root)
        registry = TypedExpressionRegistry(contracts)
        identities = {
            "raw_cache": manifest["data_cache_identity"],
            "compiler_identity": manifest["compiler_identity"],
        }
        for index, checkpoint in enumerate(checkpoints):
            checkpoint_manifest = _read_json(checkpoint / "manifest.json")
            if int(checkpoint_manifest["completed_ledger_row_count"]) != (
                index + 1
            ) * MECHANISM_SEARCH_V2_CHECKPOINT_SIZE:
                errors.append(f"checkpoint_rows:{index}")
            _load_checkpoint(
                checkpoint_path=checkpoint,
                registry=registry,
                expected_source_sha=str(manifest["producer_source_sha"]),
                expected_frozen_hash=str(frozen["frozen_contract_sha256"]),
                expected_identities=identities,
            )
    except (KeyError, OSError, ValueError) as exc:
        errors.append(f"checkpoint_exact_restore:{type(exc).__name__}:{exc}")

    qualified: list[str] = []
    if validation_blocked:
        failure_record = _read_json(runtime_root / "validation_failure.json")
        if (
            failure_record.get("status") != "PROCESS_EXIT_CAPTURED"
            or failure_record.get("producer_source_sha")
            != manifest.get("producer_source_sha")
            or failure_record.get("checkpoint") != "checkpoint_005"
            or failure_record.get("exception_type") != "ValueError"
            or failure_record.get("traceback_function")
            != "_validation_arm_metrics"
        ):
            errors.append("validation_failure_record")
        if any(
            (runtime_root / name).exists()
            for name in (
                "validation_candidate_ledger.parquet",
                "validation_arm_metrics.parquet",
                "validation_decisions.json",
                "mechanism_knowledge.parquet",
                "mechanism_knowledge_summary.json",
            )
        ):
            errors.append("blocked_outcome_has_success_artifacts")
        if (
            decision.get("reason")
            != "VALIDATION_CONTROL_PATH_SCHEMA_INCONSISTENT"
            or decision.get("checkpoint") != "checkpoint_005"
            or decision.get("research_decision")
            != "HOLD_ENGINE_VALIDATION_BLOCKED"
            or decision.get("future_new_data_arena_qualified_arms") != []
            or decision.get("rescue_rerun_started") is not False
        ):
            errors.append("validation_blocked_decision")
    else:
        validation_checkpoint = (
            runtime_root / "checkpoints" / "checkpoint_validation"
        )
        if not validation_checkpoint.is_dir() or _read_json(
            validation_checkpoint / "manifest.json"
        ).get("restore_verified") is not True:
            errors.append("validation_checkpoint_restore")
        if (
            validation.get("status") != "VALIDATION_STAGE_COMPLETE"
            or validation.get("random_control_survival_required") is not False
            or set(dict(validation.get("arm_decisions") or {}))
            != set(MECHANISM_SEARCH_V2_ARMS)
            or set(validation_metrics["arm"].astype(str))
            != set(MECHANISM_SEARCH_V2_ARMS)
        ):
            errors.append("independent_validation_contract")
        evaluated_counts = (
            validation_rows.loc[
                validation_rows["validation_status"].astype(str)
                == "EVALUATED"
            ]
            .groupby("arm")
            .size()
            .to_dict()
        )
        recorded_counts = {
            str(key): int(value)
            for key, value in dict(
                validation.get("matched_evaluated_counts") or {}
            ).items()
        }
        if {
            str(key): int(value) for key, value in evaluated_counts.items()
        } != recorded_counts:
            errors.append("validation_evaluated_counts")
        qualified = sorted(
            arm
            for arm, row in dict(validation.get("arm_decisions") or {}).items()
            if bool(dict(row).get("passed"))
        )
        if (
            decision.get("future_development_data_arena_qualified_arms")
            != qualified
        ):
            errors.append("validation_qualification_projection")
        if (
            len(knowledge) != len(catalog)
            or knowledge["mechanism_id"].nunique() != len(catalog)
            or knowledge_summary.get("declared_mechanism_count")
            != len(catalog)
            or knowledge_summary.get("individual_candidate_reward_persisted")
            is not False
            or knowledge_summary.get("population_or_distribution_persisted")
            is not False
            or knowledge["individual_candidate_state_persisted"]
            .fillna(True)
            .any()
        ):
            errors.append("mechanism_knowledge_boundary")
        if (
            decision.get("status")
            != "PASS_SEARCH_ENGINE_V2_MECHANISM_CAMPAIGN_COMPLETED"
        ):
            errors.append("final_decision_status")
    if (
        decision.get("strict_evaluated_count")
        != MECHANISM_SEARCH_V2_STRICT_TARGET
        or decision.get("checkpoint_restore_verified") is not True
        or decision.get("sealed_reads") != 0
        or decision.get("next_arena_started") is not False
    ):
        errors.append("final_decision")
    if int(decision.get("generation_attempts", MECHANISM_SEARCH_V2_RAW_ATTEMPT_LIMIT + 1)) > (
        MECHANISM_SEARCH_V2_RAW_ATTEMPT_LIMIT
    ):
        errors.append("raw_attempt_budget")
    if float(
        decision.get(
            "active_wall_seconds", MECHANISM_SEARCH_V2_WALL_TIME_LIMIT_SECONDS + 1
        )
    ) > MECHANISM_SEARCH_V2_WALL_TIME_LIMIT_SECONDS:
        errors.append("wall_time_budget")

    if (
        manifest.get("producer_source_sha") != frozen.get("source_sha")
        or manifest.get("strict_evaluated_count")
        != MECHANISM_SEARCH_V2_STRICT_TARGET
        or manifest.get("frozen_contract_sha256")
        != frozen.get("frozen_contract_sha256")
        or manifest.get("sealed_reads") != 0
        or _payload_sha(manifest.get("artifacts", []))
        != manifest.get("artifact_bundle_sha256")
    ):
        errors.append("run_manifest")
    for record in manifest.get("artifacts", []):
        path = repo_root / str(record["path"])
        if (
            not path.is_file()
            or path.stat().st_size != int(record["bytes"])
            or sha256_file(path) != str(record["sha256"])
        ):
            errors.append(f"manifest_artifact:{record['path']}")
    try:
        subprocess.check_call(
            [
                "git",
                "cat-file",
                "-e",
                f"{manifest['producer_source_sha']}^{{commit}}",
            ],
            cwd=repo_root,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
    except (KeyError, subprocess.CalledProcessError):
        errors.append("producer_source_commit")
    result = "PASS" if not errors else "FAIL"
    return {
        "result": result,
        "errors": errors,
        "engineering_integrity": result,
        "producer_source_sha": manifest.get("producer_source_sha"),
        "strict_evaluated_count": len(ledger),
        "generation_attempts": decision.get("generation_attempts"),
        "checkpoint_count": len(checkpoints),
        "compiled_mechanism_count": len(catalog),
        "behavior_family_count": int(archive["behavior_family_id"].nunique()),
        "validation_qualified_arms": qualified,
        "artifact_bundle_sha256": manifest.get("artifact_bundle_sha256"),
        "sealed_reads": decision.get("sealed_reads"),
    }


def check_mechanism_v21(
    repo_root: Path,
    *,
    runtime_date: str = "20260801",
) -> dict[str, Any]:
    config = _economic_campaign_config(MECHANISM_SEARCH_V21_CAMPAIGN)
    runtime_root = repo_root / f"runtime/{config['runtime_prefix']}_{runtime_date}"
    report_path = repo_root / f"reports/{config['report_prefix']}_{runtime_date}.md"
    errors: list[str] = []
    required = (
        "frozen_contract.json",
        "embedded_preflight.json",
        "candidate_ledger.parquet",
        "behavior_archive.parquet",
        "behavior_family_summary.json",
        "arm_checkpoint_metrics.parquet",
        "train_gate.json",
        "mechanism_knowledge.parquet",
        "mechanism_knowledge_summary.json",
        "final_decision.json",
        "run_manifest.json",
    )
    for name in required:
        if not (runtime_root / name).is_file():
            errors.append(f"missing:{name}")
    if not report_path.is_file():
        errors.append("missing:report")
    if errors:
        return {"result": "FAIL", "errors": errors}

    frozen = _read_json(runtime_root / "frozen_contract.json")
    preflight = _read_json(runtime_root / "embedded_preflight.json")
    train_gate = _read_json(runtime_root / "train_gate.json")
    decision = _read_json(runtime_root / "final_decision.json")
    manifest = _read_json(runtime_root / "run_manifest.json")
    knowledge_summary = _read_json(
        runtime_root / "mechanism_knowledge_summary.json"
    )
    ledger = pd.read_parquet(runtime_root / "candidate_ledger.parquet")
    archive = pd.read_parquet(runtime_root / "behavior_archive.parquet")
    metrics = pd.read_parquet(runtime_root / "arm_checkpoint_metrics.parquet")
    knowledge = pd.read_parquet(runtime_root / "mechanism_knowledge.parquet")
    _, legacy_catalog, expanded_catalog, _ = _load_mechanism_v21_contract(
        repo_root
    )

    frozen_body = {
        key: value for key, value in frozen.items() if key != "frozen_contract_sha256"
    }
    grammar = dict(frozen.get("mechanism_grammar") or {})
    if _payload_sha(frozen_body) != frozen.get("frozen_contract_sha256"):
        errors.append("frozen_contract_sha256")
    if (
        frozen.get("source_sha") != manifest.get("producer_source_sha")
        or frozen.get("authorization")
        != "ONE_FRESH_STATE_10000_STRICT_MECHANISM_BASIS_CAMPAIGN"
        or grammar.get("legacy_compiled_mechanism_count") != len(legacy_catalog)
        or grammar.get("expanded_compiled_mechanism_count")
        != len(expanded_catalog)
        or grammar.get("expanded_compiled_catalog_sha256")
        != _mechanism_catalog_sha(expanded_catalog)
        or grammar.get("second_ast_or_compiler_created") is not False
    ):
        errors.append("frozen_mechanism_contract")
    if tuple(int(value) for value in frozen.get("seeds") or ()) != (
        MECHANISM_SEARCH_V21_SEEDS
    ):
        errors.append("frozen_seed_set")
    if preflight.get("strict_candidates_consumed_outside_campaign") != 0:
        errors.append("preflight_external_budget")

    if len(ledger) != MECHANISM_SEARCH_V21_STRICT_TARGET:
        errors.append("strict_count")
    if ledger["candidate_id"].nunique() != MECHANISM_SEARCH_V21_STRICT_TARGET:
        errors.append("exact_unique")
    if set(ledger["arm"].astype(str).unique()) != set(MECHANISM_SEARCH_V21_ARMS):
        errors.append("arm_set")
    if set(int(value) for value in ledger["seed"].unique()) != set(
        MECHANISM_SEARCH_V21_SEEDS
    ):
        errors.append("ledger_seed_set")
    for column in (
        "compile_valid",
        "exact_unique",
        "matched_control_valid",
        "strict_cost_evaluated",
        "expression_hash_verified",
    ):
        if column not in ledger or not bool(ledger[column].fillna(False).all()):
            errors.append(f"ledger_gate:{column}")
    try:
        expected_allocations = _mechanism_v21_expected_checkpoint_allocations(
            stages=tuple(frozen.get("stages") or ()),
            seeds=MECHANISM_SEARCH_V21_SEEDS,
        )
    except (KeyError, TypeError, ValueError, ZeroDivisionError):
        errors.append("frozen_stage_contract")
        expected_allocations = {}
    for checkpoint_index, expected in expected_allocations.items():
        local = ledger.loc[
            ledger["checkpoint_index"].astype(int) == checkpoint_index
        ]
        observed = {
            str(arm): int(count)
            for arm, count in local.groupby("arm").size().items()
        }
        if observed != expected:
            errors.append(f"checkpoint_allocation:{checkpoint_index}")
    if set(metrics["checkpoint_index"].astype(int).unique()) != set(range(5)):
        errors.append("checkpoint_metrics")
    evolution_rows = ledger.loc[
        ledger["arm"].astype(str) == "mechanism_evolution_v2_1"
    ]
    for operation in MECHANISM_EVOLUTION_OPERATIONS:
        operation_rows = evolution_rows.loc[
            evolution_rows["operation"].astype(str) == operation
        ]
        if operation_rows.empty or not bool(
            operation_rows["receipt_verified"]
            .astype("boolean")
            .fillna(False)
            .all()
        ):
            errors.append(f"operation_not_verified:{operation}")

    if len(archive) != len(ledger):
        errors.append("archive_row_count")
    champions = archive.loc[archive["is_family_champion"].fillna(False)]
    if champions["behavior_family_id"].nunique() != archive[
        "behavior_family_id"
    ].nunique():
        errors.append("archive_family_champion")
    if (
        len(knowledge) != len(expanded_catalog)
        or knowledge["mechanism_id"].nunique() != len(expanded_catalog)
        or knowledge_summary.get("declared_mechanism_count")
        != len(expanded_catalog)
        or knowledge_summary.get("individual_candidate_reward_persisted")
        is not False
        or knowledge_summary.get("population_or_distribution_persisted")
        is not False
    ):
        errors.append("mechanism_knowledge_boundary")

    checkpoints = sorted(
        (runtime_root / "checkpoints").glob("checkpoint_[0-9][0-9][0-9]")
    )
    if len(checkpoints) != MECHANISM_SEARCH_V21_CHECKPOINT_COUNT:
        errors.append("checkpoint_count")
    try:
        _, contracts, _, _, _ = _load_v14_inputs(repo_root)
        registry = TypedExpressionRegistry(contracts)
        identities = {
            "raw_cache": manifest["data_cache_identity"],
            "compiler_identity": manifest["compiler_identity"],
        }
        for index, checkpoint in enumerate(checkpoints):
            checkpoint_manifest = _read_json(checkpoint / "manifest.json")
            if int(checkpoint_manifest["completed_ledger_row_count"]) != (
                index + 1
            ) * MECHANISM_SEARCH_V21_CHECKPOINT_SIZE:
                errors.append(f"checkpoint_rows:{index}")
            _load_checkpoint(
                checkpoint_path=checkpoint,
                registry=registry,
                expected_source_sha=str(manifest["producer_source_sha"]),
                expected_frozen_hash=str(frozen["frozen_contract_sha256"]),
                expected_identities=identities,
            )
    except (KeyError, OSError, ValueError) as exc:
        errors.append(f"checkpoint_exact_restore:{type(exc).__name__}:{exc}")

    validation_authorized = bool(train_gate.get("validation_authorized_by_gate"))
    qualified: list[str] = []
    validation_names = (
        "validation_candidate_ledger.parquet",
        "validation_arm_metrics.parquet",
        "validation_decisions.json",
    )
    if validation_authorized:
        for name in validation_names:
            if not (runtime_root / name).is_file():
                errors.append(f"missing:{name}")
        validation_checkpoint = runtime_root / "checkpoints/checkpoint_validation"
        if not validation_checkpoint.is_dir() or _read_json(
            validation_checkpoint / "manifest.json"
        ).get("restore_verified") is not True:
            errors.append("validation_checkpoint_restore")
        if not errors:
            validation = _read_json(runtime_root / "validation_decisions.json")
            if (
                validation.get("status") != "VALIDATION_STAGE_COMPLETE"
                or set(dict(validation.get("arm_decisions") or {}))
                != set(MECHANISM_SEARCH_V21_ARMS)
            ):
                errors.append("validation_contract")
            qualified = sorted(
                arm
                for arm, row in dict(
                    validation.get("arm_decisions") or {}
                ).items()
                if bool(dict(row).get("passed"))
            )
    else:
        if any((runtime_root / name).exists() for name in validation_names):
            errors.append("train_gate_negative_has_validation_artifacts")
        if decision.get("validation_status") != (
            "VALIDATION_NOT_RUN_TRAIN_GATE_NEGATIVE"
        ):
            errors.append("train_gate_negative_status")

    if (
        decision.get("strict_evaluated_count") != MECHANISM_SEARCH_V21_STRICT_TARGET
        or decision.get("checkpoint_restore_verified") is not True
        or decision.get("future_development_data_arena_qualified_arms")
        != qualified
        or decision.get("sealed_reads") != 0
        or decision.get("next_arena_started") is not False
    ):
        errors.append("final_decision")
    if int(
        decision.get(
            "generation_attempts", MECHANISM_SEARCH_V21_RAW_ATTEMPT_LIMIT + 1
        )
    ) > MECHANISM_SEARCH_V21_RAW_ATTEMPT_LIMIT:
        errors.append("raw_attempt_budget")
    if float(
        decision.get(
            "active_wall_seconds",
            MECHANISM_SEARCH_V21_WALL_TIME_LIMIT_SECONDS + 1,
        )
    ) > MECHANISM_SEARCH_V21_WALL_TIME_LIMIT_SECONDS:
        errors.append("wall_time_budget")

    if (
        manifest.get("producer_source_sha") != frozen.get("source_sha")
        or manifest.get("strict_evaluated_count")
        != MECHANISM_SEARCH_V21_STRICT_TARGET
        or manifest.get("frozen_contract_sha256")
        != frozen.get("frozen_contract_sha256")
        or manifest.get("sealed_reads") != 0
        or _payload_sha(manifest.get("artifacts", []))
        != manifest.get("artifact_bundle_sha256")
    ):
        errors.append("run_manifest")
    for record in manifest.get("artifacts", []):
        path = repo_root / str(record["path"])
        if (
            not path.is_file()
            or path.stat().st_size != int(record["bytes"])
            or sha256_file(path) != str(record["sha256"])
        ):
            errors.append(f"manifest_artifact:{record['path']}")
    result = "PASS" if not errors else "FAIL"
    return {
        "result": result,
        "errors": errors,
        "engineering_integrity": result,
        "producer_source_sha": manifest.get("producer_source_sha"),
        "strict_evaluated_count": len(ledger),
        "generation_attempts": decision.get("generation_attempts"),
        "checkpoint_count": len(checkpoints),
        "legacy_compiled_mechanism_count": len(legacy_catalog),
        "expanded_compiled_mechanism_count": len(expanded_catalog),
        "behavior_family_count": int(archive["behavior_family_id"].nunique()),
        "train_gate_status": train_gate.get("status"),
        "validation_qualified_arms": qualified,
        "artifact_bundle_sha256": manifest.get("artifact_bundle_sha256"),
        "sealed_reads": decision.get("sealed_reads"),
    }


def check_mechanism_v22(
    repo_root: Path,
    *,
    runtime_date: str = "20260802",
) -> dict[str, Any]:
    config = _economic_campaign_config(MECHANISM_SEARCH_V22_CAMPAIGN)
    runtime_root = repo_root / f"runtime/{config['runtime_prefix']}_{runtime_date}"
    report_path = repo_root / f"reports/{config['report_prefix']}_{runtime_date}.md"
    errors: list[str] = []
    required = (
        "frozen_contract.json",
        "embedded_preflight.json",
        "candidate_ledger.parquet",
        "behavior_archive.parquet",
        "behavior_family_summary.json",
        "arm_checkpoint_metrics.parquet",
        "train_gate.json",
        "mechanism_knowledge.parquet",
        "mechanism_knowledge_summary.json",
        "final_decision.json",
        "run_manifest.json",
    )
    for name in required:
        if not (runtime_root / name).is_file():
            errors.append(f"missing:{name}")
    if not report_path.is_file():
        errors.append("missing:report")
    if errors:
        return {"result": "FAIL", "errors": errors}

    frozen = _read_json(runtime_root / "frozen_contract.json")
    preflight = _read_json(runtime_root / "embedded_preflight.json")
    train_gate = _read_json(runtime_root / "train_gate.json")
    decision = _read_json(runtime_root / "final_decision.json")
    manifest = _read_json(runtime_root / "run_manifest.json")
    knowledge_summary = _read_json(
        runtime_root / "mechanism_knowledge_summary.json"
    )
    ledger = pd.read_parquet(runtime_root / "candidate_ledger.parquet")
    archive = pd.read_parquet(runtime_root / "behavior_archive.parquet")
    metrics = pd.read_parquet(runtime_root / "arm_checkpoint_metrics.parquet")
    knowledge = pd.read_parquet(runtime_root / "mechanism_knowledge.parquet")
    campaign_config, catalog, _ = _load_mechanism_v22_contract(repo_root)

    frozen_body = {
        key: value for key, value in frozen.items() if key != "frozen_contract_sha256"
    }
    grammar = dict(frozen.get("mechanism_grammar") or {})
    if _payload_sha(frozen_body) != frozen.get("frozen_contract_sha256"):
        errors.append("frozen_contract_sha256")
    if (
        frozen.get("source_sha") != manifest.get("producer_source_sha")
        or frozen.get("authorization")
        != "ONE_FRESH_STATE_UP_TO_20000_STRICT_EVOLUTION_QUALIFICATION_CAMPAIGN"
        or grammar.get("compiled_mechanism_count") != len(catalog)
        or grammar.get("compiled_catalog_sha256")
        != _mechanism_catalog_sha(catalog)
        or grammar.get("v21_catalog_reused_unchanged") is not True
        or grammar.get("second_ast_or_compiler_created") is not False
    ):
        errors.append("frozen_mechanism_contract")
    if tuple(int(value) for value in frozen.get("seeds") or ()) != (
        MECHANISM_SEARCH_V22_SEEDS
    ):
        errors.append("frozen_seed_set")
    if dict(frozen.get("fresh_state") or {}) != dict(
        campaign_config["fresh_state"]
    ):
        errors.append("fresh_state_contract")
    if preflight.get("strict_candidates_consumed_outside_campaign") != 0:
        errors.append("preflight_external_budget")

    validation_allowed = bool(
        decision.get("validation_allows_continuous_expansion")
    )
    expected_strict = (
        MECHANISM_SEARCH_V22_STRICT_TARGET
        if validation_allowed
        else MECHANISM_SEARCH_V22_QUALIFICATION_STRICT_COUNT
    )
    expected_checkpoint_count = 10 if validation_allowed else 4
    if len(ledger) != expected_strict:
        errors.append("strict_count")
    if ledger["candidate_id"].nunique() != expected_strict:
        errors.append("exact_unique")
    if set(ledger["arm"].astype(str).unique()) != set(MECHANISM_SEARCH_V22_ARMS):
        errors.append("arm_set")
    if set(int(value) for value in ledger["seed"].unique()) != set(
        MECHANISM_SEARCH_V22_SEEDS
    ):
        errors.append("ledger_seed_set")
    for column in (
        "compile_valid",
        "exact_unique",
        "matched_control_valid",
        "strict_cost_evaluated",
        "expression_hash_verified",
    ):
        if column not in ledger or not bool(ledger[column].fillna(False).all()):
            errors.append(f"ledger_gate:{column}")
    try:
        expected_allocations = _mechanism_v22_expected_checkpoint_allocations(
            stages=tuple(frozen.get("stages") or ()),
            seeds=MECHANISM_SEARCH_V22_SEEDS,
        )
    except (KeyError, TypeError, ValueError, ZeroDivisionError):
        errors.append("frozen_stage_contract")
        expected_allocations = {}
    for checkpoint_index in range(expected_checkpoint_count):
        local = ledger.loc[
            ledger["checkpoint_index"].astype(int) == checkpoint_index
        ]
        observed = {
            str(arm): int(count)
            for arm, count in local.groupby("arm").size().items()
        }
        if observed != expected_allocations.get(checkpoint_index):
            errors.append(f"checkpoint_allocation:{checkpoint_index}")
    if set(metrics["checkpoint_index"].astype(int).unique()) != set(
        range(expected_checkpoint_count)
    ):
        errors.append("checkpoint_metrics")
    evolution_rows = ledger.loc[
        ledger["arm"].astype(str) == "mechanism_evolution_v2_2"
    ]
    for operation in MECHANISM_EVOLUTION_OPERATIONS:
        operation_rows = evolution_rows.loc[
            evolution_rows["operation"].astype(str) == operation
        ]
        if operation_rows.empty or not bool(
            operation_rows["receipt_verified"]
            .astype("boolean")
            .fillna(False)
            .all()
        ):
            errors.append(f"operation_not_verified:{operation}")

    if len(archive) != len(ledger):
        errors.append("archive_row_count")
    champions = archive.loc[archive["is_family_champion"].fillna(False)]
    if champions["behavior_family_id"].nunique() != archive[
        "behavior_family_id"
    ].nunique():
        errors.append("archive_family_champion")
    if (
        len(knowledge) != len(catalog)
        or knowledge["mechanism_id"].nunique() != len(catalog)
        or knowledge_summary.get("declared_mechanism_count") != len(catalog)
        or knowledge_summary.get("individual_candidate_reward_persisted") is not False
        or knowledge_summary.get("population_or_distribution_persisted") is not False
    ):
        errors.append("mechanism_knowledge_boundary")

    checkpoints = sorted(
        (runtime_root / "checkpoints").glob("checkpoint_[0-9][0-9][0-9]")
    )
    if len(checkpoints) != expected_checkpoint_count:
        errors.append("checkpoint_count")
    try:
        _, contracts, _, _, _ = _load_v14_inputs(repo_root)
        registry = TypedExpressionRegistry(contracts)
        identities = {
            "raw_cache": manifest["data_cache_identity"],
            "compiler_identity": manifest["compiler_identity"],
        }
        for index, checkpoint in enumerate(checkpoints):
            checkpoint_manifest = _read_json(checkpoint / "manifest.json")
            if int(checkpoint_manifest["completed_ledger_row_count"]) != (
                index + 1
            ) * MECHANISM_SEARCH_V22_CHECKPOINT_SIZE:
                errors.append(f"checkpoint_rows:{index}")
            _load_checkpoint(
                checkpoint_path=checkpoint,
                registry=registry,
                expected_source_sha=str(manifest["producer_source_sha"]),
                expected_frozen_hash=str(frozen["frozen_contract_sha256"]),
                expected_identities=identities,
            )
    except (KeyError, OSError, ValueError) as exc:
        errors.append(f"checkpoint_exact_restore:{type(exc).__name__}:{exc}")

    validation_names = (
        "validation_candidate_ledger.parquet",
        "validation_arm_metrics.parquet",
        "validation_decisions.json",
    )
    train_passed = bool(train_gate.get("validation_authorized_by_gate"))
    if train_passed:
        for name in validation_names:
            if not (runtime_root / name).is_file():
                errors.append(f"missing:{name}")
        if all((runtime_root / name).is_file() for name in validation_names):
            validation = _read_json(runtime_root / "validation_decisions.json")
            validation_rows = pd.read_parquet(
                runtime_root / "validation_candidate_ledger.parquet"
            )
            validation_metrics = pd.read_parquet(
                runtime_root / "validation_arm_metrics.parquet"
            )
            if (
                validation.get("status") != "VALIDATION_STAGE_COMPLETE"
                or validation.get("control_arm_id")
                != "expanded_mechanism_random_v2_2"
                or validation.get("random_control_survival_required") is not True
                or set(dict(validation.get("arm_decisions") or {}))
                != set(MECHANISM_SEARCH_V22_ARMS)
                or set(validation_metrics["arm"].astype(str))
                != set(MECHANISM_SEARCH_V22_ARMS)
            ):
                errors.append("validation_contract")
            evaluated_counts = (
                validation_rows.loc[
                    validation_rows["validation_status"].astype(str) == "EVALUATED"
                ]
                .groupby("arm")
                .size()
                .to_dict()
            )
            if any(int(evaluated_counts.get(arm, 0)) != 128 for arm in MECHANISM_SEARCH_V22_ARMS):
                errors.append("validation_equal_count")
            if _mechanism_v22_validation_allows_expansion(validation) != validation_allowed:
                errors.append("validation_projection")
    else:
        if any((runtime_root / name).exists() for name in validation_names):
            errors.append("train_negative_has_validation_artifacts")
        if decision.get("validation_status") != "VALIDATION_NOT_RUN_TRAIN_GATE_NEGATIVE":
            errors.append("train_negative_validation_status")

    expected_status = (
        "PASS_SEARCH_ENGINE_V2_2_CONTINUOUS_EXPANSION_COMPLETE"
        if validation_allowed
        else "PASS_SEARCH_ENGINE_V2_2_VALIDATION_GATE_NEGATIVE"
        if train_passed
        else "PASS_SEARCH_ENGINE_V2_2_TRAIN_GATE_NEGATIVE"
    )
    if (
        decision.get("status") != expected_status
        or decision.get("strict_evaluated_count") != expected_strict
        or decision.get("checkpoint_restore_verified") is not True
        or decision.get("sealed_reads") != 0
        or decision.get("next_arena_started") is not False
    ):
        errors.append("final_decision")
    if int(decision.get("generation_attempts", MECHANISM_SEARCH_V22_RAW_ATTEMPT_LIMIT + 1)) > (
        MECHANISM_SEARCH_V22_RAW_ATTEMPT_LIMIT
    ):
        errors.append("raw_attempt_budget")
    if float(
        decision.get(
            "active_wall_seconds", MECHANISM_SEARCH_V22_WALL_TIME_LIMIT_SECONDS + 1
        )
    ) > MECHANISM_SEARCH_V22_WALL_TIME_LIMIT_SECONDS:
        errors.append("wall_time_budget")
    if (
        manifest.get("producer_source_sha") != frozen.get("source_sha")
        or manifest.get("strict_evaluated_count") != expected_strict
        or manifest.get("frozen_contract_sha256")
        != frozen.get("frozen_contract_sha256")
        or manifest.get("sealed_reads") != 0
        or _payload_sha(manifest.get("artifacts", []))
        != manifest.get("artifact_bundle_sha256")
    ):
        errors.append("run_manifest")
    for record in manifest.get("artifacts", []):
        path = repo_root / str(record["path"])
        if (
            not path.is_file()
            or path.stat().st_size != int(record["bytes"])
            or sha256_file(path) != str(record["sha256"])
        ):
            errors.append(f"manifest_artifact:{record['path']}")
    try:
        subprocess.check_call(
            ["git", "cat-file", "-e", f"{manifest['producer_source_sha']}^{{commit}}"],
            cwd=repo_root,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
    except (KeyError, subprocess.CalledProcessError):
        errors.append("producer_source_commit")
    result = "PASS" if not errors else "FAIL"
    return {
        "result": result,
        "errors": errors,
        "engineering_integrity": result,
        "producer_source_sha": manifest.get("producer_source_sha"),
        "strict_evaluated_count": len(ledger),
        "generation_attempts": decision.get("generation_attempts"),
        "checkpoint_count": len(checkpoints),
        "compiled_mechanism_count": len(catalog),
        "behavior_family_count": int(archive["behavior_family_id"].nunique()),
        "train_gate_status": train_gate.get("status"),
        "validation_allows_continuous_expansion": validation_allowed,
        "validation_qualified_arms": decision.get(
            "future_development_data_arena_qualified_arms"
        ),
        "artifact_bundle_sha256": manifest.get("artifact_bundle_sha256"),
        "sealed_reads": decision.get("sealed_reads"),
    }


def check_mechanism_v23(
    repo_root: Path,
    *,
    runtime_date: str = "20260802",
) -> dict[str, Any]:
    config = _economic_campaign_config(MECHANISM_SEARCH_V23_CAMPAIGN)
    runtime_root = repo_root / f"runtime/{config['runtime_prefix']}_{runtime_date}"
    report_path = repo_root / f"reports/{config['report_prefix']}_{runtime_date}.md"
    errors: list[str] = []
    required = (
        "frozen_contract.json",
        "embedded_preflight.json",
        "candidate_ledger.parquet",
        "behavior_archive.parquet",
        "behavior_family_summary.json",
        "arm_checkpoint_metrics.parquet",
        "mechanism_knowledge.parquet",
        "mechanism_knowledge_summary.json",
        "validation_candidate_ledger.parquet",
        "validation_arm_metrics.parquet",
        "validation_cohort_paths.parquet",
        "validation_decisions.json",
        "final_decision.json",
        "run_manifest.json",
    )
    for name in required:
        if not (runtime_root / name).is_file():
            errors.append(f"missing:{name}")
    if not report_path.is_file():
        errors.append("missing:report")
    if errors:
        return {"result": "FAIL", "errors": errors}
    frozen = _read_json(runtime_root / "frozen_contract.json")
    preflight = _read_json(runtime_root / "embedded_preflight.json")
    decision = _read_json(runtime_root / "final_decision.json")
    manifest = _read_json(runtime_root / "run_manifest.json")
    validation = _read_json(runtime_root / "validation_decisions.json")
    knowledge_summary = _read_json(runtime_root / "mechanism_knowledge_summary.json")
    ledger = pd.read_parquet(runtime_root / "candidate_ledger.parquet")
    archive = pd.read_parquet(runtime_root / "behavior_archive.parquet")
    metrics = pd.read_parquet(runtime_root / "arm_checkpoint_metrics.parquet")
    knowledge = pd.read_parquet(runtime_root / "mechanism_knowledge.parquet")
    validation_rows = pd.read_parquet(
        runtime_root / "validation_candidate_ledger.parquet"
    )
    validation_metrics = pd.read_parquet(runtime_root / "validation_arm_metrics.parquet")
    validation_paths = pd.read_parquet(runtime_root / "validation_cohort_paths.parquet")
    campaign_contract, catalog, _ = _load_mechanism_v23_contract(repo_root)
    frozen_body = {
        key: value for key, value in frozen.items() if key != "frozen_contract_sha256"
    }
    grammar = dict(frozen.get("mechanism_grammar") or {})
    if _payload_sha(frozen_body) != frozen.get("frozen_contract_sha256"):
        errors.append("frozen_contract_sha256")
    if (
        frozen.get("source_sha") != manifest.get("producer_source_sha")
        or frozen.get("authorization") != campaign_contract["authorization"]
        or grammar.get("compiled_mechanism_count") != len(catalog)
        or grammar.get("compiled_catalog_sha256") != _mechanism_catalog_sha(catalog)
        or grammar.get("v21_catalog_reused_unchanged") is not True
        or grammar.get("second_ast_or_compiler_created") is not False
        or tuple(int(value) for value in frozen.get("seeds") or ())
        != MECHANISM_SEARCH_V23_SEEDS
        or dict(frozen.get("fresh_state") or {})
        != dict(campaign_contract["fresh_state"])
    ):
        errors.append("frozen_contract")
    if preflight.get("strict_candidates_consumed_outside_campaign") != 0:
        errors.append("preflight_external_budget")
    full_policy_pass = bool(validation.get("full_evolution_policy_pass"))
    expected_strict = (
        MECHANISM_SEARCH_V23_STRICT_TARGET
        if full_policy_pass
        else MECHANISM_SEARCH_V23_QUALIFICATION_STRICT_COUNT
    )
    expected_checkpoint_count = 10 if full_policy_pass else 8
    if len(ledger) != expected_strict or ledger["candidate_id"].nunique() != expected_strict:
        errors.append("strict_exact_unique_count")
    if set(ledger["arm"].astype(str).unique()) != set(MECHANISM_SEARCH_V23_ARMS):
        errors.append("arm_set")
    if set(int(value) for value in ledger["seed"].unique()) != set(
        MECHANISM_SEARCH_V23_SEEDS
    ):
        errors.append("ledger_seed_set")
    for column in (
        "compile_valid",
        "exact_unique",
        "matched_control_valid",
        "strict_cost_evaluated",
        "expression_hash_verified",
    ):
        if column not in ledger or not bool(ledger[column].fillna(False).all()):
            errors.append(f"ledger_gate:{column}")
    try:
        expected_allocations = _mechanism_v23_expected_checkpoint_allocations(
            stages=tuple(frozen.get("stages") or ()),
            seeds=MECHANISM_SEARCH_V23_SEEDS,
        )
    except (KeyError, TypeError, ValueError, ZeroDivisionError):
        expected_allocations = {}
        errors.append("frozen_stage_contract")
    for checkpoint_index in range(expected_checkpoint_count):
        local = ledger.loc[
            ledger["checkpoint_index"].astype(int) == checkpoint_index
        ]
        observed = {
            str(arm): int(count)
            for arm, count in local.groupby("arm").size().items()
        }
        if observed != expected_allocations.get(checkpoint_index):
            errors.append(f"checkpoint_allocation:{checkpoint_index}")
        seed_counts = local.groupby(["arm", "seed"]).size().to_dict()
        for arm, count in observed.items():
            expected_per_seed = count // len(MECHANISM_SEARCH_V23_SEEDS)
            if any(
                int(seed_counts.get((arm, seed), 0)) != expected_per_seed
                for seed in MECHANISM_SEARCH_V23_SEEDS
            ):
                errors.append(f"checkpoint_seed_balance:{checkpoint_index}:{arm}")
    if set(metrics["checkpoint_index"].astype(int).unique()) != set(
        range(expected_checkpoint_count)
    ):
        errors.append("checkpoint_metrics")
    evolution_rows = ledger.loc[
        ledger["arm"].astype(str) == "mechanism_evolution_v2_3"
    ]
    for operation in MECHANISM_EVOLUTION_OPERATIONS:
        local = evolution_rows.loc[evolution_rows["operation"].astype(str) == operation]
        if local.empty or not bool(
            local["receipt_verified"].astype("boolean").fillna(False).all()
        ):
            errors.append(f"operation_not_verified:{operation}")
    if len(archive) != len(ledger):
        errors.append("archive_row_count")
    champions = archive.loc[archive["is_family_champion"].fillna(False)]
    if champions["behavior_family_id"].nunique() != archive[
        "behavior_family_id"
    ].nunique():
        errors.append("archive_family_champion")
    if (
        len(knowledge) != len(catalog)
        or knowledge["mechanism_id"].nunique() != len(catalog)
        or knowledge_summary.get("declared_mechanism_count") != len(catalog)
        or knowledge_summary.get("individual_candidate_reward_persisted") is not False
        or knowledge_summary.get("population_or_distribution_persisted") is not False
    ):
        errors.append("mechanism_knowledge_boundary")
    checkpoints = sorted(
        (runtime_root / "checkpoints").glob("checkpoint_[0-9][0-9][0-9]")
    )
    if len(checkpoints) != expected_checkpoint_count:
        errors.append("checkpoint_count")
    try:
        _, contracts, _, _, _ = _load_v14_inputs(repo_root)
        registry = TypedExpressionRegistry(contracts)
        identities = {
            "raw_cache": manifest["data_cache_identity"],
            "compiler_identity": manifest["compiler_identity"],
        }
        for index, checkpoint in enumerate(checkpoints):
            checkpoint_manifest = _read_json(checkpoint / "manifest.json")
            if int(checkpoint_manifest["completed_ledger_row_count"]) != (
                index + 1
            ) * MECHANISM_SEARCH_V23_CHECKPOINT_SIZE:
                errors.append(f"checkpoint_rows:{index}")
            _load_checkpoint(
                checkpoint_path=checkpoint,
                registry=registry,
                expected_source_sha=str(manifest["producer_source_sha"]),
                expected_frozen_hash=str(frozen["frozen_contract_sha256"]),
                expected_identities=identities,
            )
        _load_checkpoint(
            checkpoint_path=runtime_root / "checkpoints" / "checkpoint_validation",
            registry=registry,
            expected_source_sha=str(manifest["producer_source_sha"]),
            expected_frozen_hash=str(frozen["frozen_contract_sha256"]),
            expected_identities=identities,
        )
    except (KeyError, OSError, ValueError) as exc:
        errors.append(f"checkpoint_exact_restore:{type(exc).__name__}:{exc}")
    evaluated = validation_rows.loc[
        validation_rows["validation_status"].astype(str) == "EVALUATED"
    ]
    expected_cohorts = set(campaign_contract["validation"]["cohorts"])
    cohort_counts = {
        str(key): int(value)
        for key, value in evaluated.groupby("cohort").size().to_dict().items()
    }
    if cohort_counts != {cohort: 256 for cohort in expected_cohorts}:
        errors.append("validation_cohort_counts")
    cell_counts = evaluated.groupby(
        ["cohort", "seed", "horizon_hours"]
    ).size()
    if len(cell_counts) != 16 or any(int(value) != 64 for value in cell_counts):
        errors.append("validation_cell_counts")
    if evaluated["candidate_id"].nunique() != 1024:
        errors.append("validation_cohort_overlap")
    if len(validation_metrics) != 16 or set(
        validation_metrics["cohort"].astype(str)
    ) != expected_cohorts:
        errors.append("validation_metrics")
    path_keys = validation_paths[
        ["cohort", "seed", "horizon_hours", "day_ordinal"]
    ]
    if (
        validation_paths.empty
        or path_keys.duplicated().any()
        or set(validation_paths["cohort"].astype(str)) != expected_cohorts
    ):
        errors.append("validation_cohort_paths")
    absolute_cells = list(validation.get("absolute_cells") or ())
    component_pass, absolute_pass, projected_full = _v23_attribution_projection(
        list(validation.get("relative_cells") or ()),
        absolute_cells,
    )
    if (
        validation.get("status") != "VALIDATION_STAGE_COMPLETE"
        or validation.get("random_profitability_survival_required") is not False
        or validation.get("random_role")
        != "COMPARATOR_ONLY_NO_PROFITABILITY_SURVIVAL_REQUIREMENT"
        or dict(validation.get("component_pass") or {}) != component_pass
        or bool(validation.get("absolute_evolution_top_passed")) != absolute_pass
        or full_policy_pass != projected_full
        or bool(validation.get("continuation_authorized")) != projected_full
        or validation.get("policy_state_sha256_before")
        != validation.get("policy_state_sha256_after")
        or validation.get("archive_state_sha256_before")
        != validation.get("archive_state_sha256_after")
        or validation.get("holdout_read") is not False
    ):
        errors.append("validation_decision_projection")
    expected_status = (
        "PASS_SEARCH_ENGINE_V2_3_POLICY_ATTRIBUTION_AND_CONTINUATION_COMPLETE"
        if full_policy_pass
        else "PASS_SEARCH_ENGINE_V2_3_POLICY_ATTRIBUTION_GATE_NEGATIVE"
    )
    if (
        decision.get("status") != expected_status
        or decision.get("strict_evaluated_count") != expected_strict
        or decision.get("checkpoint_restore_verified") is not True
        or decision.get("full_evolution_policy_pass") != full_policy_pass
        or decision.get("sealed_reads") != 0
        or decision.get("next_arena_started") is not False
    ):
        errors.append("final_decision")
    if int(
        decision.get("generation_attempts", MECHANISM_SEARCH_V23_RAW_ATTEMPT_LIMIT + 1)
    ) > MECHANISM_SEARCH_V23_RAW_ATTEMPT_LIMIT:
        errors.append("raw_attempt_budget")
    if float(
        decision.get(
            "active_wall_seconds", MECHANISM_SEARCH_V23_WALL_TIME_LIMIT_SECONDS + 1
        )
    ) > MECHANISM_SEARCH_V23_WALL_TIME_LIMIT_SECONDS:
        errors.append("wall_time_budget")
    if (
        manifest.get("producer_source_sha") != frozen.get("source_sha")
        or manifest.get("strict_evaluated_count") != expected_strict
        or manifest.get("frozen_contract_sha256")
        != frozen.get("frozen_contract_sha256")
        or manifest.get("sealed_reads") != 0
        or _payload_sha(manifest.get("artifacts", []))
        != manifest.get("artifact_bundle_sha256")
    ):
        errors.append("run_manifest")
    for record in manifest.get("artifacts", []):
        path = repo_root / str(record["path"])
        if (
            not path.is_file()
            or path.stat().st_size != int(record["bytes"])
            or sha256_file(path) != str(record["sha256"])
        ):
            errors.append(f"manifest_artifact:{record['path']}")
    try:
        subprocess.check_call(
            ["git", "cat-file", "-e", f"{manifest['producer_source_sha']}^{{commit}}"],
            cwd=repo_root,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
    except (KeyError, subprocess.CalledProcessError):
        errors.append("producer_source_commit")
    result = "PASS" if not errors else "FAIL"
    return {
        "result": result,
        "errors": errors,
        "engineering_integrity": result,
        "producer_source_sha": manifest.get("producer_source_sha"),
        "strict_evaluated_count": len(ledger),
        "generation_attempts": decision.get("generation_attempts"),
        "checkpoint_count": len(checkpoints),
        "validation_candidate_cohort_evaluated_count": len(evaluated),
        "proposal_distribution_qualified": component_pass["proposal_distribution"],
        "train_ranker_qualified": component_pass["train_ranker"],
        "full_evolution_policy_pass": full_policy_pass,
        "artifact_bundle_sha256": manifest.get("artifact_bundle_sha256"),
        "sealed_reads": decision.get("sealed_reads"),
    }


def _search_evidence_provenance_observed_mask(
    frame: pd.DataFrame,
) -> pd.Series:
    return pd.Series(
        [
            not _search_evidence_provenance_row_errors(
                row,
                require_strict_non_degenerate=(
                    bool(row.get("strict_evaluated"))
                    or str(row.get("proposal_status") or "")
                    == "STRICT_EVALUATED"
                ),
            )
            for row in frame.to_dict(orient="records")
        ],
        index=frame.index,
        dtype=bool,
    )


def _search_evidence_provenance_row_errors(
    row: Mapping[str, Any],
    *,
    require_strict_non_degenerate: bool = False,
) -> set[str]:
    errors: set[str] = set()
    for column in SEARCH_EVIDENCE_V1_PROVENANCE_COLUMNS:
        value = row.get(column)
        if value is None or bool(pd.isna(value)):
            errors.add(f"ledger_evidence:{column}")
    if errors:
        return errors
    if str(row["mechanism_realization_status"]) not in (
        SEARCH_EVIDENCE_V1_REALIZATION_STATUSES
    ):
        errors.add("ledger_evidence:mechanism_realization_status_value")
    candidate_spec: dict[str, Any] = {}
    try:
        candidate_spec = json.loads(str(row["candidate_spec_json"]))
        candidate_spec_sha256 = _payload_sha(candidate_spec)
    except (KeyError, TypeError, ValueError, json.JSONDecodeError):
        candidate_spec_sha256 = ""
        errors.add("ledger_evidence:candidate_spec_json")
    if candidate_spec_sha256 != str(row.get("candidate_spec_sha256") or ""):
        errors.add("ledger_evidence:candidate_spec_hash")
    if candidate_spec_sha256:
        candidate_projection = {
            "candidate_id": row.get("candidate_id"),
            "skeleton_id": row.get("skeleton_id"),
            "mechanism_family": row.get("mechanism_family"),
            "operator_path": row.get("operator_path"),
            "mapping_id": row.get("mapping_family"),
            "horizon_hours": row.get("horizon_hours"),
        }
        if any(
            str(candidate_spec.get(key)) != str(value)
            for key, value in candidate_projection.items()
        ):
            errors.add("ledger_evidence:candidate_spec_projection")
    try:
        control = json.loads(str(row["control_degeneracy_provenance_json"]))
        realization = json.loads(str(row["mechanism_realization_json"]))
    except (TypeError, ValueError, json.JSONDecodeError):
        errors.add("ledger_evidence:provenance_json")
        return errors
    if not isinstance(control, Mapping) or not isinstance(realization, Mapping):
        errors.add("ledger_evidence:provenance_json")
        return errors
    control = dict(control)
    realization = dict(realization)
    control_body = {
        key: value for key, value in control.items() if key != "provenance_sha256"
    }
    realization_body = {
        key: value
        for key, value in realization.items()
        if key != "provenance_sha256"
    }
    control_hash = str(control.get("provenance_sha256") or "")
    realization_hash = str(realization.get("provenance_sha256") or "")
    if (
        str(row["control_degeneracy_provenance_sha256"]) != control_hash
        or _payload_sha(control_body) != control_hash
    ):
        errors.add("ledger_evidence:control_provenance_hash")
    if (
        str(row["mechanism_realization_sha256"]) != realization_hash
        or _payload_sha(realization_body) != realization_hash
    ):
        errors.add("ledger_evidence:mechanism_realization_hash")
    if (
        control.get("schema_version") != "CRYPTO_PAIR_CONTROL_PROVENANCE_V1"
        or realization.get("schema_version")
        != "CRYPTO_MECHANISM_REALIZATION_PROVENANCE_V1"
    ):
        errors.add("ledger_evidence:provenance_schema")
    candidate_id = str(row.get("candidate_id") or "")
    if (
        str(control.get("candidate_id") or "") != candidate_id
        or str(realization.get("candidate_id") or "") != candidate_id
        or str(control.get("candidate_spec_sha256") or "")
        != candidate_spec_sha256
    ):
        errors.add("ledger_evidence:candidate_binding")
    if (
        str(realization.get("control_degeneracy_provenance_sha256") or "")
        != control_hash
    ):
        errors.add("ledger_evidence:provenance_cross_binding")
    if (
        str(realization.get("mechanism_family") or "")
        != str(candidate_spec.get("mechanism_family") or "")
        or str(realization.get("skeleton_id") or "")
        != str(candidate_spec.get("skeleton_id") or "")
        or str(realization.get("operator_path") or "")
        != str(candidate_spec.get("operator_path") or "")
        or realization.get("authority")
        != (
            "OUTCOME_FREE_SIGNAL_ABLATION_COMPARISONS_ON_SHARED_SUPPORT_MAPPING_"
            "HORIZON_AND_EXECUTION"
        )
    ):
        errors.add("ledger_evidence:mechanism_realization_binding")
    if type(realization.get("hierarchical_three_axis")) is not bool:
        errors.add("ledger_evidence:mechanism_realization_schema")
    hierarchical = bool(realization.get("hierarchical_three_axis"))
    required_comparisons = {
        "primary_vs_left_control",
        "primary_vs_right_control",
        *(
            {
                "ab_vs_interaction_left_control",
                "ab_vs_interaction_right_control",
            }
            if hierarchical
            else set()
        ),
    }
    comparison_labels = {
        "primary_vs_left_control": ("primary", "left_control"),
        "primary_vs_right_control": ("primary", "right_control"),
        "ab_vs_interaction_left_control": (
            "ab_control",
            "interaction_left_control",
        ),
        "ab_vs_interaction_right_control": (
            "ab_control",
            "interaction_right_control",
        ),
    }
    comparisons = control.get("comparisons")
    if not isinstance(comparisons, Mapping) or set(comparisons) != required_comparisons:
        errors.add("ledger_evidence:control_comparison_set")
    else:
        for comparison_id, comparison in comparisons.items():
            if not isinstance(comparison, Mapping):
                errors.add("ledger_evidence:control_comparison_schema")
                continue
            comparison = dict(comparison)
            comparison_body = {
                key: value
                for key, value in comparison.items()
                if key != "provenance_sha256"
            }
            stage_order = comparison.get("stage_order")
            stages = comparison.get("stages")
            expected_stage_order = SEARCH_EVIDENCE_V1_CONTROL_STAGE_ORDERS.get(
                str(candidate_spec.get("mapping_id") or "")
            )
            expected_primary_label, expected_control_label = comparison_labels[
                comparison_id
            ]
            if (
                comparison.get("schema_version")
                != "CRYPTO_CONTROL_DEGENERACY_PROVENANCE_V1"
                or expected_stage_order is None
                or tuple(stage_order or ()) != expected_stage_order
                or not isinstance(stages, Mapping)
                or set(stages) != set(stage_order)
                or type(comparison.get("final_behavior_equal")) is not bool
                or str(comparison.get("mapping_id") or "")
                != str(candidate_spec.get("mapping_id") or "")
                or comparison.get("primary_label") != expected_primary_label
                or comparison.get("control_label") != expected_control_label
            ):
                errors.add("ledger_evidence:control_comparison_schema")
            else:
                stage_equalities: list[bool] = []
                for stage in stage_order:
                    stage_row = dict(stages[stage])
                    if (
                        set(stage_row)
                        != {
                            "primary_identity_sha256",
                            "control_identity_sha256",
                            "equal",
                        }
                        or len(str(stage_row.get("primary_identity_sha256") or ""))
                        != 64
                        or len(str(stage_row.get("control_identity_sha256") or ""))
                        != 64
                        or type(stage_row.get("equal")) is not bool
                        or bool(stage_row.get("equal"))
                        != (
                            str(stage_row.get("primary_identity_sha256"))
                            == str(stage_row.get("control_identity_sha256"))
                        )
                    ):
                        errors.add("ledger_evidence:control_stage_schema")
                        break
                    stage_equalities.append(bool(stage_row["equal"]))
                if len(stage_equalities) == len(stage_order):
                    final_equal = stage_equalities[-1]
                    first_equal = None
                    if final_equal:
                        first_equal = next(
                            (
                                stage
                                for index, stage in enumerate(stage_order)
                                if all(stage_equalities[index:])
                            ),
                            None,
                        )
                    first_divergent = next(
                        (
                            stage
                            for stage, equal in zip(stage_order, stage_equalities)
                            if not equal
                        ),
                        None,
                    )
                    first_reconverged = (
                        first_equal if first_divergent is not None else None
                    )
                    if (
                        type(comparison.get("final_weight_equal")) is not bool
                        or type(comparison.get("final_behavior_equal")) is not bool
                        or bool(comparison.get("final_weight_equal")) != final_equal
                        or bool(comparison.get("final_behavior_equal"))
                        != final_equal
                        or comparison.get("first_equal_stage") != first_equal
                        or comparison.get("first_divergent_stage")
                        != first_divergent
                        or comparison.get("first_reconverged_stage")
                        != first_reconverged
                    ):
                        errors.add("ledger_evidence:control_stage_projection")
                    required_non_degenerate = {
                        "primary_vs_left_control",
                        "primary_vs_right_control",
                        *(
                            {"ab_vs_interaction_left_control"}
                            if hierarchical
                            else set()
                        ),
                    }
                    if (
                        require_strict_non_degenerate
                        and comparison_id in required_non_degenerate
                        and (
                            final_equal
                            or comparison.get("first_equal_stage") is not None
                        )
                    ):
                        errors.add("ledger_evidence:strict_control_degenerate")
            if _payload_sha(comparison_body) != str(
                comparison.get("provenance_sha256") or ""
            ):
                errors.add("ledger_evidence:control_comparison_hash")
    axes = realization.get("axes")
    expected_axes = (
        (
            ("A", "ab_vs_interaction_right_control"),
            ("B", "ab_vs_interaction_left_control"),
            ("C", "primary_vs_left_control"),
        )
        if hierarchical
        else (
            ("A", "primary_vs_right_control"),
            ("B", "primary_vs_left_control"),
        )
    )
    try:
        axis_rows = [dict(axis) for axis in axes]
        axis_projection_matches = all(
            str(axis["axis_id"]) == axis_id
            and str(axis["evidence_comparison"]) == comparison_id
            and type(axis.get("active")) is bool
            and bool(axis["active"])
            == (not bool(
                dict(dict(comparisons[comparison_id])["stages"])["SIGNAL"][
                    "equal"
                ]
            ))
            and axis.get("signal_difference_fraction")
            == dict(comparisons[comparison_id]).get("signal_difference_fraction")
            for axis, (axis_id, comparison_id) in zip(axis_rows, expected_axes)
        ) and len(axis_rows) == len(expected_axes)
        active_axis_count = sum(bool(axis["active"]) for axis in axis_rows)
        declared_axis_count = len(axes)
        expected_status = (
            "ALL_DECLARED_AXES_ACTIVE"
            if active_axis_count == declared_axis_count
            else "NO_DECLARED_AXIS_ACTIVE"
            if active_axis_count == 0
            else "PARTIAL_DECLARED_AXES_ACTIVE"
        )
        projection_matches = (
            declared_axis_count == (3 if hierarchical else 2)
            and int(row["declared_axis_count"]) == declared_axis_count
            and int(realization["declared_axis_count"]) == declared_axis_count
            and int(row["active_axis_count"]) == active_axis_count
            and int(realization["active_axis_count"]) == active_axis_count
            and str(row["mechanism_realization_status"]) == expected_status
            and str(realization["status"]) == expected_status
            and axis_projection_matches
            and realization.get("condition_effect_rate")
            == (
                axis_rows[-1].get("signal_difference_fraction")
                if hierarchical
                else None
            )
        )
    except (KeyError, TypeError, ValueError):
        projection_matches = False
    if not projection_matches:
        errors.add("ledger_evidence:mechanism_realization_projection")
    return errors


def _search_evidence_provenance_errors(ledger: pd.DataFrame) -> list[str]:
    errors: set[str] = set()
    for column in SEARCH_EVIDENCE_V1_PROVENANCE_COLUMNS:
        if column not in ledger or bool(ledger[column].isna().any()):
            errors.add(f"ledger_evidence:{column}")
    if errors:
        return sorted(errors)
    for row in ledger.to_dict(orient="records"):
        errors.update(
            _search_evidence_provenance_row_errors(
                row, require_strict_non_degenerate=True
            )
        )
    return sorted(errors)


def _search_evidence_repair_assessment(
    ledger: pd.DataFrame,
    evidence: pd.DataFrame,
    failures: pd.DataFrame,
) -> dict[str, Any]:
    strict = (
        evidence.loc[evidence["proposal_status"].astype(str).eq("STRICT_EVALUATED")]
        if "proposal_status" in evidence
        else evidence.iloc[0:0]
    )
    ledger_candidate_ids = ledger.get("candidate_id", pd.Series(dtype=str))
    strict_candidate_ids = strict.get("candidate_id", pd.Series(dtype=str))
    ledger_ids = set(ledger_candidate_ids.astype(str))
    strict_ids = set(strict_candidate_ids.astype(str))
    strict_observed = _search_evidence_provenance_observed_mask(strict)
    failure_observed = _search_evidence_provenance_observed_mask(failures)
    ledger_observed = _search_evidence_provenance_observed_mask(ledger)
    observed_strict_ids = set(
        strict.loc[strict_observed, "candidate_id"].astype(str)
        if "candidate_id" in strict
        else ()
    )
    exact_strict_identity = (
        len(ledger) == len(strict)
        and len(ledger) > 0
        and not bool(ledger_candidate_ids.isna().any())
        and not bool(strict_candidate_ids.isna().any())
        and int(ledger_candidate_ids.astype(str).nunique()) == len(ledger)
        and int(strict_candidate_ids.astype(str).nunique()) == len(strict)
        and ledger_ids == strict_ids
    )
    strict_observed_count = int(strict_observed.sum())
    ledger_observed_count = int(ledger_observed.sum())
    fully_joined = len(ledger_ids & observed_strict_ids)
    if ledger_observed_count == len(ledger) and len(ledger) > 0:
        repair_status = "MARKET_FREE_REPAIR_NOT_REQUIRED"
        reason = "STRICT_LEDGER_ALREADY_CONTAINS_OBSERVED_PROVENANCE"
    elif exact_strict_identity and strict_observed_count == len(ledger) and len(ledger) > 0:
        repair_status = "MARKET_FREE_REPAIR_POSSIBLE"
        reason = "STRICT_PROVENANCE_AVAILABLE_IN_EXISTING_EVIDENCE_ROWS"
    else:
        repair_status = "MARKET_FREE_REPAIR_NOT_POSSIBLE"
        reason = "STRICT_SUCCESS_PROVENANCE_WAS_NOT_PERSISTED"
    missing_strict_count = max(0, len(ledger) - fully_joined)
    return {
        "schema_version": 1,
        "repair_status": repair_status,
        "reason": reason,
        "candidate_ledger_row_count": int(len(ledger)),
        "strict_evaluated_count": int(len(strict)),
        "strict_candidate_identity_exact": bool(exact_strict_identity),
        "strict_provenance_observed_count": strict_observed_count,
        "ledger_provenance_observed_count": ledger_observed_count,
        "control_degenerate_row_count": int(len(failures)),
        "control_degenerate_provenance_observed_count": int(
            failure_observed.sum()
        ),
        "fully_joined_strict_observation_count": int(fully_joined),
        "missing_strict_provenance_count": int(missing_strict_count),
        "market_reevaluation_required_for_missing_rows": bool(
            repair_status == "MARKET_FREE_REPAIR_NOT_POSSIBLE"
            and missing_strict_count > 0
        ),
    }


def assess_search_evidence_v1_repair(
    repo_root: Path,
    *,
    runtime_date: str = "20260804",
) -> dict[str, Any]:
    component_paths = (
        "alphafactory_crypto/broad_search/search_engine_v1.py",
        "alphafactory_crypto/broad_search/pair18m.py",
    )
    source_components_clean = (
        subprocess.run(
            ["git", "diff", "--quiet", "HEAD", "--", *component_paths],
            cwd=repo_root,
            check=False,
        ).returncode
        == 0
    )
    if not source_components_clean:
        return {
            "result": "FAIL",
            "errors": ["assessment_source_components_dirty"],
            "market_data_read": False,
            "candidate_evaluation_performed": False,
        }
    config = _economic_campaign_config(SEARCH_EVIDENCE_V1_CAMPAIGN)
    runtime_root = repo_root / f"runtime/{config['runtime_prefix']}_{runtime_date}"
    paths = {
        "candidate_ledger": runtime_root / "candidate_ledger.parquet",
        "search_run_evidence": runtime_root / "search_run_evidence.parquet",
        "search_failure_evidence": runtime_root / "search_failure_evidence.parquet",
        "run_manifest": runtime_root / "run_manifest.json",
    }
    missing = [name for name, path in paths.items() if not path.is_file()]
    if missing:
        return {
            "result": "FAIL",
            "errors": [f"missing:{name}" for name in missing],
            "market_data_read": False,
            "candidate_evaluation_performed": False,
        }
    ledger = pd.read_parquet(paths["candidate_ledger"])
    evidence = pd.read_parquet(paths["search_run_evidence"])
    failures = pd.read_parquet(paths["search_failure_evidence"])
    manifest = _read_json(paths["run_manifest"])
    manifest_records = {
        str(record.get("path") or ""): dict(record)
        for record in manifest.get("artifacts", [])
    }
    manifest_verified = (
        _payload_sha(manifest.get("artifacts") or [])
        == manifest.get("artifact_bundle_sha256")
    )
    for name in (
        "candidate_ledger",
        "search_run_evidence",
        "search_failure_evidence",
    ):
        path = paths[name]
        record = manifest_records.get(path.relative_to(repo_root).as_posix())
        if (
            record is None
            or int(record.get("bytes", -1)) != path.stat().st_size
            or str(record.get("sha256") or "") != sha256_file(path)
        ):
            manifest_verified = False
    assessment = _search_evidence_repair_assessment(ledger, evidence, failures)
    assessment_source_sha = _git_sha(repo_root)
    output = {
        "schema_version": 1,
        "result": "PASS" if manifest_verified else "FAIL",
        "errors": [] if manifest_verified else ["producer_manifest_artifact_binding"],
        "assessment_authority": "IMMUTABLE_EXISTING_ARTIFACT_SCHEMA_AND_IDENTITY_JOIN",
        "runtime_root": runtime_root.relative_to(repo_root).as_posix(),
        "assessment_source_sha": assessment_source_sha,
        "assessment_component_git_blobs": {
            path: _git_blob_sha(repo_root, path)
            for path in component_paths
        },
        "producer_source_sha": manifest.get("producer_source_sha"),
        "producer_artifact_bundle_sha256": manifest.get(
            "artifact_bundle_sha256"
        ),
        "original_artifact_manifest_verified": bool(manifest_verified),
        "input_artifacts": {
            name: {
                "path": path.relative_to(repo_root).as_posix(),
                "sha256": sha256_file(path),
                "bytes": path.stat().st_size,
            }
            for name, path in paths.items()
        },
        **assessment,
        "market_data_read": False,
        "candidate_evaluation_performed": False,
        "historical_inference_performed": False,
        "original_artifacts_modified": False,
        "authorization_consumed_or_changed": False,
    }
    output_path = runtime_root / "closure_repair_assessment.json"
    _write_json(output_path, output)
    return output


def check_search_evidence_v1(
    repo_root: Path,
    *,
    runtime_date: str = "20260804",
    campaign: str = SEARCH_EVIDENCE_V1_CAMPAIGN,
) -> dict[str, Any]:
    config = _economic_campaign_config(campaign)
    campaign_seeds = _economic_campaign_seeds(campaign)
    runtime_root = repo_root / f"runtime/{config['runtime_prefix']}_{runtime_date}"
    report_path = repo_root / f"reports/{config['report_prefix']}_{runtime_date}.md"
    required = (
        "frozen_contract.json",
        "embedded_preflight.json",
        "candidate_ledger.parquet",
        "behavior_archive.parquet",
        "behavior_family_summary.json",
        "arm_checkpoint_metrics.parquet",
        "search_failure_evidence.parquet",
        "search_run_evidence.parquet",
        "search_exposure_strata.parquet",
        "search_run_evidence_summary.json",
        "mechanism_knowledge.parquet",
        "mechanism_knowledge_summary.json",
        "final_decision.json",
        "run_manifest.json",
    )
    errors = [name for name in required if not (runtime_root / name).is_file()]
    if not report_path.is_file():
        errors.append("report")
    if errors:
        return {"result": "FAIL", "errors": [f"missing:{name}" for name in errors]}
    frozen = _read_json(runtime_root / "frozen_contract.json")
    decision = _read_json(runtime_root / "final_decision.json")
    manifest = _read_json(runtime_root / "run_manifest.json")
    summary = _read_json(runtime_root / "search_run_evidence_summary.json")
    ledger = pd.read_parquet(runtime_root / "candidate_ledger.parquet")
    failures = pd.read_parquet(runtime_root / "search_failure_evidence.parquet")
    evidence = pd.read_parquet(runtime_root / "search_run_evidence.parquet")
    exposure = pd.read_parquet(runtime_root / "search_exposure_strata.parquet")
    campaign_contract, catalog, _ = _load_search_evidence_v1_contract(
        repo_root, campaign=campaign
    )
    frozen_body = {
        key: value for key, value in frozen.items() if key != "frozen_contract_sha256"
    }
    if _payload_sha(frozen_body) != frozen.get("frozen_contract_sha256"):
        errors.append("frozen_contract_sha256")
    if (
        frozen.get("epoch_id") != config["epoch_id"]
        or frozen.get("source_sha") != manifest.get("producer_source_sha")
        or frozen.get("authorization") != campaign_contract["authorization"]
        or tuple(int(value) for value in frozen.get("seeds") or ())
        != campaign_seeds
        or dict(frozen.get("policies") or {})
        != dict(campaign_contract["policy_parameters"])
        or dict(frozen.get("evidence_contract") or {})
        != dict(campaign_contract["evidence_contract"])
    ):
        errors.append("frozen_contract")
    if (
        len(ledger) != int(config["strict_target"])
        or ledger["candidate_id"].astype(str).nunique() != len(ledger)
        or set(ledger["arm"].astype(str).unique()) != set(config["arms"])
        or set(int(value) for value in ledger["seed"].unique())
        != set(campaign_seeds)
    ):
        errors.append("strict_ledger_identity")
    errors.extend(_search_evidence_provenance_errors(ledger))
    required_ledger_columns = (
        "primary_gross_mean",
        "primary_net_mean",
        "gross_mean",
        "net_mean",
        "search_reward",
        "pair_reward",
    )
    for column in required_ledger_columns:
        if column not in ledger or bool(ledger[column].isna().any()):
            errors.append(f"ledger_evidence:{column}")
    for column in (
        "compile_valid",
        "exact_unique",
        "matched_control_valid",
        "strict_cost_evaluated",
        "expression_hash_verified",
    ):
        if column not in ledger or not bool(ledger[column].fillna(False).all()):
            errors.append(f"ledger_gate:{column}")
    if len(evidence) != len(ledger) + len(failures):
        errors.append("joined_evidence_row_count")
    elif evidence["candidate_id"].astype(str).duplicated().any():
        errors.append("joined_evidence_candidate_identity")
    if exposure.empty or summary.get("status") != "PASS_SEARCH_RUN_EVIDENCE_V1_NONEMPTY":
        errors.append("evidence_consumer")
    if (
        int(summary.get("strict_evaluated_count", -1)) != len(ledger)
        or int(summary.get("behavior_attributed_proposal_count", -1)) != len(evidence)
        or int(summary.get("control_degenerate_count", -1)) != len(failures)
        or summary.get("diagnostics_used_by_optimizer")
        != (
            "BLOCK_ROBUST_EVOLUTION_ARM_ONLY"
            if campaign == BLOCK_ROBUST_GATE_CAMPAIGN
            else False
        )
        or summary.get("diagnostics_used_by_reward") is not False
        or summary.get("diagnostics_used_by_archive_identity") is not False
        or summary.get("historical_inference_performed") is not False
    ):
        errors.append("evidence_summary")
    if campaign in {
        SEARCH_EVIDENCE_V11_CAMPAIGN,
        BLOCK_ROBUST_GATE_CAMPAIGN,
    } and int(
        summary.get("joined_strict_provenance_count", -1)
    ) != len(ledger):
        errors.append("joined_strict_provenance_count")
    if campaign == BLOCK_ROBUST_GATE_CAMPAIGN:
        block_summary = _read_json(runtime_root / "block_robust_gate_summary.json")
        template_metrics = pd.read_parquet(
            runtime_root / "block_robust_template_metrics.parquet"
        )
        expected_block, expected_templates = _block_robust_gate_summary(
            ledger=ledger,
            state={
                "arm_counters": {
                    arm: {
                        **dict(summary["arm_funnel"][arm]),
                        "cpu_seconds": float(
                            dict(block_summary["arms"][arm])[
                                "total_process_cpu_seconds"
                            ]
                        ),
                    }
                    for arm in BLOCK_ROBUST_GATE_ARMS
                }
            },
            config=campaign_contract,
        )
        if block_summary != expected_block:
            errors.append("block_robust_gate_summary")
        expected_template_frame = pd.DataFrame(expected_templates).sort_values(
            ["mechanism_template", "arm"], kind="mergesort"
        ).reset_index(drop=True)
        observed_template_frame = template_metrics.sort_values(
            ["mechanism_template", "arm"], kind="mergesort"
        ).reset_index(drop=True)
        if not observed_template_frame.equals(expected_template_frame):
            errors.append("block_robust_template_metrics")
        for column in (
            "block_robust_ordering_json",
            "block_robust_ordering_sha256",
            "replicated_positive_block_count",
            "replicated_candidate",
            "all_three_blocks_positive",
        ):
            if column not in ledger or bool(ledger[column].isna().any()):
                errors.append(f"block_robust_ledger:{column}")
    try:
        expected_allocations = _search_evidence_v1_expected_checkpoint_allocations(
            stages=frozen.get("stages") or (),
            seeds=campaign_seeds,
            arms=tuple(config["arms"]),
            checkpoint_size=int(config["checkpoint_size"]),
            checkpoint_count=int(config["checkpoint_count"]),
        )
    except (KeyError, TypeError, ValueError, ZeroDivisionError):
        expected_allocations = {}
        errors.append("frozen_stage_contract")
    for checkpoint_index in range(int(config["checkpoint_count"])):
        local = ledger.loc[ledger["checkpoint_index"].astype(int) == checkpoint_index]
        observed = {
            str(arm): int(count) for arm, count in local.groupby("arm").size().items()
        }
        if observed != expected_allocations.get(checkpoint_index):
            errors.append(f"checkpoint_allocation:{checkpoint_index}")
    checkpoints = sorted(
        (runtime_root / "checkpoints").glob("checkpoint_[0-9][0-9][0-9]")
    )
    if len(checkpoints) != int(config["checkpoint_count"]):
        errors.append("checkpoint_count")
    elif not all(
        bool(_read_json(path / "manifest.json").get("restore_verified"))
        for path in checkpoints
    ):
        errors.append("checkpoint_restore")
    if (
        decision.get("status") != config["decision_status"]
        or decision.get("validation_status") != "NOT_AUTHORIZED"
        or decision.get("alpha_claim") is not False
        or decision.get("oos") is not False
        or decision.get("promotion") != "FORBIDDEN"
        or decision.get("parameters_changed") is not False
        or decision.get("rescue_rerun_started") is not False
    ):
        errors.append("final_decision")
    if int(decision.get("generation_attempts", int(config["raw_attempt_limit"]) + 1)) > (
        int(config["raw_attempt_limit"])
    ):
        errors.append("raw_attempt_budget")
    if float(decision.get("active_wall_seconds", int(config["wall_time_limit_seconds"]) + 1)) > (
        int(config["wall_time_limit_seconds"])
    ):
        errors.append("wall_time_budget")
    manifest_paths = {str(item.get("path") or "") for item in manifest.get("artifacts", [])}
    for name in (
        "search_failure_evidence.parquet",
        "search_run_evidence.parquet",
        "search_exposure_strata.parquet",
        "search_run_evidence_summary.json",
        *(
            (
                "block_robust_gate_summary.json",
                "block_robust_template_metrics.parquet",
            )
            if campaign == BLOCK_ROBUST_GATE_CAMPAIGN
            else ()
        ),
    ):
        if (runtime_root / name).relative_to(repo_root).as_posix() not in manifest_paths:
            errors.append(f"manifest:{name}")
    try:
        subprocess.run(
            ["git", "cat-file", "-e", f"{manifest['producer_source_sha']}^{{commit}}"],
            cwd=repo_root,
            check=True,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
    except (KeyError, subprocess.CalledProcessError):
        errors.append("producer_source_commit")
    result = "PASS" if not errors else "FAIL"
    return {
        "result": result,
        "errors": errors,
        "engineering_integrity": result,
        "producer_source_sha": manifest.get("producer_source_sha"),
        "strict_evaluated_count": len(ledger),
        "behavior_attributed_proposal_count": len(evidence),
        "control_degenerate_count": len(failures),
        "checkpoint_count": len(checkpoints),
        "compiled_mechanism_count": len(catalog),
        "artifact_bundle_sha256": manifest.get("artifact_bundle_sha256"),
        "sealed_reads": decision.get("sealed_reads"),
    }


def _cli_result_is_success(result: Mapping[str, Any]) -> bool:
    return result.get("result") == "PASS" or result.get("status") in {
        "PASS_SEARCH_RUN_EVIDENCE_V1_COMPLETE",
        "PASS_SEARCH_RUN_EVIDENCE_V1_1_COMPLETE",
        "PASS_REPLICATION_AWARE_SEARCH_GATE_V1_COMPLETE",
    }


